INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86970, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "代词，指说话人和听话人双方，相当于“咱们”；有时也指“我”。", "primary_collocate": null, "pronunciation": "zán", "ipa": "tsan³⁵", "syllable_count": 1, "sentences": [{"text": "天不早了，咱回家吧。", "target_word": "咱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下雨了，咱别出去了。", "target_word": "咱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你累了就歇歇，咱慢慢走。", "target_word": "咱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱都是一家人，别客气。", "target_word": "咱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来，咱先吃饭，吃完再说。", "target_word": "咱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间还早，咱再坐一会儿。", "target_word": "咱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题，咱明天再商量。", "target_word": "咱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱老百姓就想过个平安日子。", "target_word": "咱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这活儿咱干不了，你找别人吧。", "target_word": "咱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王，咱俩可不懂这些，你问问小李。", "target_word": "咱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "咱们", "label": "复合"}], "register": "口语", "sense_fingerprint": "口语里指说话人和听话人双方，也可指我", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bb5dbd0-8999-44e2-b7a7-f670f6a1f680') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86970, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "咱", "is_correct": true, "explanation": "咱（zán）：口语代词，指说话人和听话人双方，即“咱们”。"}, {"text": "赞", "is_correct": false, "explanation": "赞（zàn）与“咱”声调不同（第四声），意思是称赞。"}, {"text": "蚕", "is_correct": false, "explanation": "蚕（cán）与“咱”声母不同（c 与 z），意思是吐丝的虫子。"}, {"text": "攒", "is_correct": false, "explanation": "攒（zǎn）与“咱”声调不同（第三声），意思是积聚、存钱。"}, {"text": "簪", "is_correct": false, "explanation": "簪（zān）与“咱”声调不同（第一声），意思是别头发的簪子。"}], "explanations": {"咱": "咱（zán）：口语代词，指说话人和听话人双方，即“咱们”。", "赞": "赞（zàn）与“咱”声调不同（第四声），意思是称赞。", "蚕": "蚕（cán）与“咱”声母不同（c 与 z），意思是吐丝的虫子。", "攒": "攒（zǎn）与“咱”声调不同（第三声），意思是积聚、存钱。", "簪": "簪（zān）与“咱”声调不同（第一声），意思是别头发的簪子。"}, "sentence_index": null, "correct_answer": "咱"}, "level_3": {"options": [{"text": "咱", "is_correct": true, "explanation": "正确：“咱”指说话人和听话人双方，与“回家吧”的劝说语气相符。"}, {"text": "它", "is_correct": false, "explanation": "语义：“它”指事物或动物，不能用来指劝大家回家的人。"}, {"text": "什么", "is_correct": false, "explanation": "语法：“什么”是疑问代词，不能作“回家吧”的主语。"}, {"text": "那里", "is_correct": false, "explanation": "语义：“那里”指地方，不能作“回家”的主语。"}], "explanations": {"咱": "正确：“咱”指说话人和听话人双方，与“回家吧”的劝说语气相符。", "它": "语义：“它”指事物或动物，不能用来指劝大家回家的人。", "什么": "语法：“什么”是疑问代词，不能作“回家吧”的主语。", "那里": "语义：“那里”指地方，不能作“回家”的主语。"}, "sentence_index": 0, "correct_answer": "咱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小王和小李吵了一架，咱俩都不理对方了。", "explanation": "这里应该用〈他俩〉。“咱俩”必须包括说话人，这句说的是小王和小李，应该用“他俩”。"}, {"text": "通知上写着：咱要按时到场。", "explanation": "这里应该用〈大家〉。“咱”是口语，书面通知中要用“大家”。"}, {"text": "尊敬的老师，咱想请假一天。", "explanation": "这里应该用〈我〉。“咱”是口语，写给老师的信中要用“我”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86970, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "咱", "is_correct": true, "explanation": "咱（zán）：口语代词，指说话人和听话人双方，即“咱们”。"}, {"text": "暂", "is_correct": false, "explanation": "暂（zàn）与“咱”声调不同（第四声），意思是暂时。"}, {"text": "残", "is_correct": false, "explanation": "残（cán）与“咱”声母不同（c 与 z），意思是残缺。"}, {"text": "攒", "is_correct": false, "explanation": "攒（zǎn）与“咱”声调不同（第三声），意思是积聚、存钱。"}, {"text": "簪", "is_correct": false, "explanation": "簪（zān）与“咱”声调不同（第一声），意思是别头发的簪子。"}], "explanations": {"咱": "咱（zán）：口语代词，指说话人和听话人双方，即“咱们”。", "暂": "暂（zàn）与“咱”声调不同（第四声），意思是暂时。", "残": "残（cán）与“咱”声母不同（c 与 z），意思是残缺。", "攒": "攒（zǎn）与“咱”声调不同（第三声），意思是积聚、存钱。", "簪": "簪（zān）与“咱”声调不同（第一声），意思是别头发的簪子。"}, "sentence_index": null, "correct_answer": "咱"}, "level_3": {"options": [{"text": "咱", "is_correct": true, "explanation": "正确：“咱”指说话人和听话人双方，与“商量”相符。"}, {"text": "它们", "is_correct": false, "explanation": "语义：“它们”指事物，而“商量”需要人参与。"}, {"text": "自己", "is_correct": false, "explanation": "配价：“商量”需要两方以上参与，“自己”只指一方，不能单独进行商量。"}, {"text": "这个", "is_correct": false, "explanation": "语义：“这个”指事物或事情，不能指参与商量的人。"}], "explanations": {"咱": "正确：“咱”指说话人和听话人双方，与“商量”相符。", "它们": "语义：“它们”指事物，而“商量”需要人参与。", "自己": "配价：“商量”需要两方以上参与，“自己”只指一方，不能单独进行商量。", "这个": "语义：“这个”指事物或事情，不能指参与商量的人。"}, "sentence_index": 6, "correct_answer": "咱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议强调：咱的利益必须坚决维护。", "explanation": "这里应该用〈人民〉。“咱”是口语，不用于庄重的政治表述。"}, {"text": "咱俩都不用去了，你去吧。", "explanation": "这里应该用〈他俩〉。“咱俩”包括听话人，这句又让听话人去，应该用“他俩”。"}, {"text": "咱们三个都保证按时完成任务，你别来凑热闹了。", "explanation": "这里应该用〈他们〉。“咱们三个”包括听话人，这句又让听话人别来，应该用“他们”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86970, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "俩咱都是老同学，别见外。", "corrected_sentence": "咱俩都是老同学，别见外。", "error_description": "“咱俩”是固定的词序，“俩咱”语序错误，应说“咱俩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86970, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "不咱去了，在家歇着吧。", "corrected_sentence": "咱不去了，在家歇着吧。", "error_description": "“不”应放在“咱”之后，应说“咱不去了”；“不咱去了”语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
