INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86971, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "费是用掉的钱。做一件事，买一样东西，都要给出去一些钱，这些钱就是费。", "primary_collocate": null, "pronunciation": "fèi", "ipa": "fei˥˩", "syllable_count": 1, "sentences": [{"text": "明天要交费，我带了两百块。", "target_word": "费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月请你按时交费，别忘了。", "target_word": "费", "complexity_tier": "T3", "furigana": "zhè ge yuè qǐng nǐ àn shí jiāo fèi, bié wàng le.", "sentence_source": "generated"}, {"text": "妈妈说，交费一定要按时，不能拖。", "target_word": "费", "complexity_tier": "T3", "furigana": "mā ma shuō, jiāo fèi yí dìng yào àn shí, bù néng tuō.", "sentence_source": "generated"}, {"text": "他替我付了费。", "target_word": "费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月我已经交完费了。", "target_word": "费", "complexity_tier": "T3", "furigana": "zhè ge yuè wǒ yǐ jīng jiāo wán fèi le.", "sentence_source": "generated"}, {"text": "朋友聚会，大家每人交费五十块。", "target_word": "费", "complexity_tier": "T3", "furigana": "péng you jù huì, dà jiā měi rén jiāo fèi wǔ shí kuài.", "sentence_source": "generated"}, {"text": "你先交费，然后才能进去。", "target_word": "费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没交费的同学，请去办公室。", "target_word": "费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次要交的费太多了，我一个人付不起。", "target_word": "费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上网要付费吗？", "target_word": "费", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "费用", "label": "复合"}, {"form": "笔", "label": "量词"}, {"form": "費", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做事买东西时付出去的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10a82993-50d4-4381-a959-52d6505f63fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86971, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "费", "is_correct": true, "explanation": "费（fèi）：做事或买东西时付出的钱，即本题要辨认的词。"}, {"text": "非", "is_correct": false, "explanation": "fēi（第一声）与 fèi（第四声）声调不同，“非”意思是不是、不对，与费用无关。"}, {"text": "肥", "is_correct": false, "explanation": "féi（第二声）与 fèi（第四声）声调不同，“肥”意思是胖或肥沃，与费用无关。"}, {"text": "匪", "is_correct": false, "explanation": "fěi（第三声）与 fèi（第四声）声调不同，“匪”意思是强盗，与费用无关。"}, {"text": "被", "is_correct": false, "explanation": "bèi 与 fèi 声母不同（b 与 f），“被”意思是被动或被子，与费用无关。"}], "explanations": {"费": "费（fèi）：做事或买东西时付出的钱，即本题要辨认的词。", "非": "fēi（第一声）与 fèi（第四声）声调不同，“非”意思是不是、不对，与费用无关。", "肥": "féi（第二声）与 fèi（第四声）声调不同，“肥”意思是胖或肥沃，与费用无关。", "匪": "fěi（第三声）与 fèi（第四声）声调不同，“匪”意思是强盗，与费用无关。", "被": "bèi 与 fèi 声母不同（b 与 f），“被”意思是被动或被子，与费用无关。"}, "sentence_index": null, "correct_answer": "费"}, "level_3": {"options": [{"text": "费", "is_correct": true, "explanation": "费：做事或买东西付出的钱，此处指交的费用，与“带了两百块”相合。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能交付，“交天气”不成立。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”不能缴纳，与“带了两百块”不符。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“交”指上交、缴纳，工资是领取的，不能说交工资。"}], "explanations": {"费": "费：做事或买东西付出的钱，此处指交的费用，与“带了两百块”相合。", "天气": "搭配：“天气”不能交付，“交天气”不成立。", "空气": "语义：“空气”不能缴纳，与“带了两百块”不符。", "工资": "搭配：“交”指上交、缴纳，工资是领取的，不能说交工资。"}, "sentence_index": 0, "correct_answer": "费"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我兜里的费不多了，借我点吧。", "explanation": "这里应该用〈钱〉。费指做事或买东西时付出去的钱，身上带的零用钱不叫费。"}, {"text": "他攒了十万块的费。", "explanation": "这里应该用〈积蓄〉。费指用掉、付出去的钱，攒下来的钱要说积蓄，不能说费。"}, {"text": "这次我一共付了一张费。", "explanation": "这里量词应换成“笔”，说“一笔费”。“张”多用于纸、桌子等扁平或成套的东西，不用来修饰费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86971, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "费", "is_correct": true, "explanation": "费（fèi）：做事或买东西时付出的钱，即本题要辨认的词。"}, {"text": "飞", "is_correct": false, "explanation": "fēi（第一声）与 fèi（第四声）声调不同，“飞”意思是飞行，与费用无关。"}, {"text": "诽", "is_correct": false, "explanation": "fěi（第三声）与 fèi（第四声）声调不同，“诽”意思是诽谤，与费用无关。"}, {"text": "配", "is_correct": false, "explanation": "pèi 与 fèi 声母不同（p 与 f），“配”意思是配合、搭配，与费用无关。"}, {"text": "辈", "is_correct": false, "explanation": "bèi 与 fèi 声母不同（b 与 f），“辈”意思是辈分或一代人，与费用无关。"}], "explanations": {"费": "费（fèi）：做事或买东西时付出的钱，即本题要辨认的词。", "飞": "fēi（第一声）与 fèi（第四声）声调不同，“飞”意思是飞行，与费用无关。", "诽": "fěi（第三声）与 fèi（第四声）声调不同，“诽”意思是诽谤，与费用无关。", "配": "pèi 与 fèi 声母不同（p 与 f），“配”意思是配合、搭配，与费用无关。", "辈": "bèi 与 fèi 声母不同（b 与 f），“辈”意思是辈分或一代人，与费用无关。"}, "sentence_index": null, "correct_answer": "费"}, "level_3": {"options": [{"text": "费", "is_correct": true, "explanation": "费：做事或买东西付出的钱，此处指进入前需交的费用，与“然后才能进去”相合。"}, {"text": "老师", "is_correct": false, "explanation": "配价：“交”的宾语应为款项或物品，“老师”是人，不能交。"}, {"text": "学生", "is_correct": false, "explanation": "配价：“学生”指人，“交”不能以人作宾语。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能交付，“交天气”不成立，与“交费”的语境不符。"}], "explanations": {"费": "费：做事或买东西付出的钱，此处指进入前需交的费用，与“然后才能进去”相合。", "老师": "配价：“交”的宾语应为款项或物品，“老师”是人，不能交。", "学生": "配价：“学生”指人，“交”不能以人作宾语。", "天气": "搭配：“天气”不能交付，“交天气”不成立，与“交费”的语境不符。"}, "sentence_index": 6, "correct_answer": "费"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他干了一个月，老板付给他三千块的费。", "explanation": "这里应该用〈工资〉。费是付出去的钱，老板付给员工的报酬要说工资，不能说费。"}, {"text": "这只股票的费涨了不少。", "explanation": "这里应该用〈股价〉。费指为做事或服务所付出的钱，股票的价格要说股价，不能说费。"}, {"text": "他一共向我要了一套费。", "explanation": "这里量词应换成“笔”，说“一笔费”。“套”用于成套的东西，不能修饰费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86971, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月我已经交了一费。", "corrected_sentence": "这个月我已经交了一笔费。", "error_description": "量词错误：“费”前有数量词“一”时要加量词“笔”，说“一笔费”，不能说“一费”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86971, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经交着两次费了。", "corrected_sentence": "我已经交过两次费了。", "error_description": "体标错误：表示曾经有过的经历要用“过”，“着”表示动作持续或状态，不能说“交着两次费”，应说“交过两次费了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86972, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
