INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86972, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做某事或使用某物所花的钱；费用。", "primary_collocate": null, "pronunciation": "fèi", "ipa": "fei˥˩", "syllable_count": 1, "sentences": [{"text": "办这件事不用交费，公司全包了。", "target_word": "费", "complexity_tier": "T3", "furigana": "bàn zhè jiàn shì bú yòng jiāo fèi, gōng sī quán bāo le.", "sentence_source": "generated"}, {"text": "他每个月都按时缴费。", "target_word": "费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里停车要付费吗？", "target_word": "费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住宿要交费，请先到前台办理。", "target_word": "费", "complexity_tier": "T3", "furigana": "zhù sù yào jiāo fèi, qǐng xiān dào qián tái bàn lǐ.", "sentence_source": "generated"}, {"text": "修这台电脑要交费，你先问清楚。", "target_word": "费", "complexity_tier": "T3", "furigana": "xiū zhè tái diàn nǎo yào jiāo fèi, nǐ xiān wèn qīng chu.", "sentence_source": "generated"}, {"text": "这次交费是怎么算的？", "target_word": "费", "complexity_tier": "T3", "furigana": "zhè cì jiāo fèi shì zěn me suàn de?", "sentence_source": "generated"}, {"text": "参加这次比赛不用交费。", "target_word": "费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水电的事，房东已经替我们交费了。", "target_word": "费", "complexity_tier": "T3", "furigana": "shuǐ diàn de shì, fáng dōng yǐ jīng tì wǒ men jiāo fèi le.", "sentence_source": "generated"}, {"text": "这个月我为手机交费，比以前多了不少。", "target_word": "费", "complexity_tier": "T3", "furigana": "zhè ge yuè wǒ wèi shǒu jī jiāo fèi, bǐ yǐ qián duō le bù shǎo.", "sentence_source": "generated"}, {"text": "出国留学要交费，我们早就准备好了。", "target_word": "费", "complexity_tier": "T3", "furigana": "chū guó liú xué yào jiāo fèi, wǒ men zǎo jiù zhǔn bèi hǎo le.", "sentence_source": "generated"}], "morphological_forms": [{"form": "费用", "label": "复合"}, {"form": "笔", "label": "量词"}, {"form": "費", "label": "繁体"}], "register": "中性", "sense_fingerprint": "办事或用物所需付出的费用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10a82993-50d4-4381-a959-52d6505f63fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86972, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "费", "is_correct": true, "explanation": "费（fèi）：做事或用物所花的钱，即本题要辨认的词。"}, {"text": "非", "is_correct": false, "explanation": "fēi（第一声）与 fèi（第四声）声调不同，“非”意思是不是、不对，与费用无关。"}, {"text": "肥", "is_correct": false, "explanation": "féi（第二声）与 fèi（第四声）声调不同，“肥”意思是胖或肥沃，与费用无关。"}, {"text": "匪", "is_correct": false, "explanation": "fěi（第三声）与 fèi（第四声）声调不同，“匪”意思是强盗，与费用无关。"}, {"text": "被", "is_correct": false, "explanation": "bèi 与 fèi 声母不同（b 与 f），“被”意思是被动或被子，与费用无关。"}], "explanations": {"费": "费（fèi）：做事或用物所花的钱，即本题要辨认的词。", "非": "fēi（第一声）与 fèi（第四声）声调不同，“非”意思是不是、不对，与费用无关。", "肥": "féi（第二声）与 fèi（第四声）声调不同，“肥”意思是胖或肥沃，与费用无关。", "匪": "fěi（第三声）与 fèi（第四声）声调不同，“匪”意思是强盗，与费用无关。", "被": "bèi 与 fèi 声母不同（b 与 f），“被”意思是被动或被子，与费用无关。"}, "sentence_index": null, "correct_answer": "费"}, "level_3": {"options": [{"text": "费", "is_correct": true, "explanation": "费：做事所花的钱，此处指办事的费用，与“公司全包了”的语境相合。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学生的课业，与“办这件事”“公司全包了”不相符。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是物品，与付款无关，放在“公司全包了”的语境中不通。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“交”指上交、缴纳，工资是领取的，不能说交工资。"}], "explanations": {"费": "费：做事所花的钱，此处指办事的费用，与“公司全包了”的语境相合。", "作业": "语义：“作业”是学生的课业，与“办这件事”“公司全包了”不相符。", "钥匙": "语义：“钥匙”是物品，与付款无关，放在“公司全包了”的语境中不通。", "工资": "搭配：“交”指上交、缴纳，工资是领取的，不能说交工资。"}, "sentence_index": 0, "correct_answer": "费"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我身上的费不多了，先借我一点吧。", "explanation": "这里应该用〈钱〉。费指做事或用物所花的钱，身上带的零用钱不叫费。"}, {"text": "他的费有十万块。", "explanation": "这里应该用〈存款〉。费指为做事或买东西而付出去的钱，存下来的钱不叫费，应说存款。"}, {"text": "我们这学期一共交了一张费。", "explanation": "这里量词应换成“笔”，说“一笔费”。“张”多用于纸、桌子等扁平或成套的东西，不用来修饰费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86972, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "费", "is_correct": true, "explanation": "费（fèi）：做事或用物所花的钱，即本题要辨认的词。"}, {"text": "飞", "is_correct": false, "explanation": "fēi（第一声）与 fèi（第四声）声调不同，“飞”意思是飞行，与费用无关。"}, {"text": "诽", "is_correct": false, "explanation": "fěi（第三声）与 fèi（第四声）声调不同，“诽”意思是诽谤，与费用无关。"}, {"text": "配", "is_correct": false, "explanation": "pèi 与 fèi 声母不同（p 与 f），“配”意思是配合、搭配，与费用无关。"}, {"text": "辈", "is_correct": false, "explanation": "bèi 与 fèi 声母不同（b 与 f），“辈”意思是辈分或一代人，与费用无关。"}], "explanations": {"费": "费（fèi）：做事或用物所花的钱，即本题要辨认的词。", "飞": "fēi（第一声）与 fèi（第四声）声调不同，“飞”意思是飞行，与费用无关。", "诽": "fěi（第三声）与 fèi（第四声）声调不同，“诽”意思是诽谤，与费用无关。", "配": "pèi 与 fèi 声母不同（p 与 f），“配”意思是配合、搭配，与费用无关。", "辈": "bèi 与 fèi 声母不同（b 与 f），“辈”意思是辈分或一代人，与费用无关。"}, "sentence_index": null, "correct_answer": "费"}, "level_3": {"options": [{"text": "费", "is_correct": true, "explanation": "费：做事所花的钱，此处指参加比赛的费用，与“不用交”相合。"}, {"text": "老师", "is_correct": false, "explanation": "配价：“交”的宾语应为款项或物品，“老师”是人，不能交。"}, {"text": "学生", "is_correct": false, "explanation": "配价：“学生”指人，“交”不能以人作宾语。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能交付，“交天气”不成立，与“交费”的语境不符。"}], "explanations": {"费": "费：做事所花的钱，此处指参加比赛的费用，与“不用交”相合。", "老师": "配价：“交”的宾语应为款项或物品，“老师”是人，不能交。", "学生": "配价：“学生”指人，“交”不能以人作宾语。", "天气": "搭配：“天气”不能交付，“交天气”不成立，与“交费”的语境不符。"}, "sentence_index": 6, "correct_answer": "费"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的费很便宜，我买了两件。", "explanation": "这里应该用〈价钱〉。费指做事或服务所付的费用，衣服本身的价格不叫费。"}, {"text": "他去银行取出了费。", "explanation": "这里应该用〈钱〉。费指为做事或用物付出去的钱，从银行取出来的钱不叫费。"}, {"text": "这次培训我们一共交了一套费。", "explanation": "这里量词应换成“笔”，说“一笔费”。“套”用于成套的东西，如一套衣服，不能修饰费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86972, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "住宿的费我已经交着了。", "corrected_sentence": "住宿的费我已经交了。", "error_description": "体标错误：“交”是完成的动作，要用“了”，不能用表示持续的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86972, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经交了一费。", "corrected_sentence": "他已经交了一笔费。", "error_description": "量词错误：“费”前有数量词“一”时要加量词“笔”，说“一笔费”，不能说“一费”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
