INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86973, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "每天是一天一天，没有哪一天不是。", "primary_collocate": null, "pronunciation": "měi tiān", "ipa": "meɪ̯²¹⁴ tʰiɛn⁵⁵", "syllable_count": 2, "sentences": [{"text": "我每天早上六点起床。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都走路去学校。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天晚上，妈妈都给我讲故事。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟每天喝一杯牛奶。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每天在公园里跑步。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天都很忙，没有时间看电视。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店每天早上八点开门。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每天坐地铁上班。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天都写一点日记。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫每天睡在门口。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "没有哪一天例外，一天一天都是如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6db36e4c-cdd6-4cfb-9f57-3ab5220c3d15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86973, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "每天", "is_correct": true, "explanation": "正确：“我每天早上六点起床”，“每天”表示每一天都如此，与“早上六点”搭配自然。"}, {"text": "每年", "is_correct": false, "explanation": "语义：“每年”以年为周期，与“早上六点起床”这种日常作息矛盾。"}, {"text": "每秒", "is_correct": false, "explanation": "语义：“每秒”间隔极短，每秒都在早上六点起床不合常理。"}, {"text": "半夜", "is_correct": false, "explanation": "搭配：“半夜”与“早上六点”时段冲突，两者不能同时修饰“起床”。"}], "explanations": {"每天": "正确：“我每天早上六点起床”，“每天”表示每一天都如此，与“早上六点”搭配自然。", "每年": "语义：“每年”以年为周期，与“早上六点起床”这种日常作息矛盾。", "每秒": "语义：“每秒”间隔极短，每秒都在早上六点起床不合常理。", "半夜": "搭配：“半夜”与“早上六点”时段冲突，两者不能同时修饰“起床”。"}, "sentence_index": 0, "correct_answer": "每天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天去海边，一年只去两三次。", "explanation": "这里应该用〈偶尔〉。每天表示一天一天都如此、没有例外；后半句“一年只去两三次”说明并非每天，前后矛盾。"}, {"text": "我们每天春节都回老家。", "explanation": "这里应该用〈每年〉。每天表示按天重复，春节一年只有一次，不能说“每天春节”。"}, {"text": "这所学校每天都有一次期末考试。", "explanation": "这里应该用〈每学期〉。期末考试一学期只有一次，“每天”表示每一天，不能用于一学期才发生一次的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86973, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每天", "is_correct": true, "explanation": "正确：“这家店每天早上八点开门”，“每天”表示每天营业时间固定，与“早上八点”搭配自然。"}, {"text": "每小时", "is_correct": false, "explanation": "语义：“每小时”按小时重复，与“早上八点”这一具体时刻冲突，店铺不会每小时在八点开门。"}, {"text": "凌晨", "is_correct": false, "explanation": "语义：“凌晨”指天亮前，与“早上八点”时段冲突。"}, {"text": "午夜", "is_correct": false, "explanation": "语义：“午夜”指半夜十二点前后，与“早上八点开门”矛盾。"}], "explanations": {"每天": "正确：“这家店每天早上八点开门”，“每天”表示每天营业时间固定，与“早上八点”搭配自然。", "每小时": "语义：“每小时”按小时重复，与“早上八点”这一具体时刻冲突，店铺不会每小时在八点开门。", "凌晨": "语义：“凌晨”指天亮前，与“早上八点”时段冲突。", "午夜": "语义：“午夜”指半夜十二点前后，与“早上八点开门”矛盾。"}, "sentence_index": 6, "correct_answer": "每天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都在周末去打球。", "explanation": "这里应该用〈每周〉。“每天”包括工作日，与“在周末”矛盾；应说“他每周末都去打球”。"}, {"text": "我每天都在15号发工资。", "explanation": "这里应该用〈每月〉。“每天”表示每一天，而“15号”是一个固定日子，二者矛盾；“每月都在15号发工资”才通顺。"}, {"text": "他每天熬夜，但考试前一周从不熬夜。", "explanation": "这里应该用〈经常〉。每天表示没有例外，后半句“考试前一周从不熬夜”说明并非每天，前后矛盾；“经常熬夜，但考试前一周从不熬夜”才通顺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86973, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天了晚上都看一会儿书。", "corrected_sentence": "他每天晚上都看一会儿书。", "error_description": "“了”不能直接放在“每天”之后，“每天了晚上”是错误的，应说“每天晚上”。正确说法是“他每天晚上都看一会儿书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86973, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们学校每天天都有体育课。", "corrected_sentence": "他们学校每天都有体育课。", "error_description": "“每天”后面不能再加一个“天”，“每天天”是错误的，应说“每天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
