INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86974, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "每一天；天天。", "primary_collocate": null, "pronunciation": "měi tiān", "ipa": "meɪ̯²¹⁴ tʰiɛn⁵⁵", "syllable_count": 2, "sentences": [{"text": "他每天吃两个苹果。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天下午，老人都在河边散步。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天用手机听中文歌。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐每天去图书馆看书。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天学习汉语一个小时。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天我都给奶奶打电话。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他每天要喝六杯水。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路每天都有很多车。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们每天唱着歌去学校。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班每天有五节课。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "每一天、天天，表示动作按天重复", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6db36e4c-cdd6-4cfb-9f57-3ab5220c3d15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86974, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "每天", "is_correct": true, "explanation": "正确：“他每天吃两个苹果”，“每天”表示按天重复，与日常进食相符。"}, {"text": "每秒", "is_correct": false, "explanation": "语义：“每秒”间隔极短，每秒吃两个苹果不合常理。"}, {"text": "每分钟", "is_correct": false, "explanation": "语义：“每分钟”间隔太短，每分钟吃两个苹果不是正常的说法。"}, {"text": "每小时", "is_correct": false, "explanation": "语义：每小时吃两个苹果不合常理，“每天”才符合日常饮食。"}], "explanations": {"每天": "正确：“他每天吃两个苹果”，“每天”表示按天重复，与日常进食相符。", "每秒": "语义：“每秒”间隔极短，每秒吃两个苹果不合常理。", "每分钟": "语义：“每分钟”间隔太短，每分钟吃两个苹果不是正常的说法。", "每小时": "语义：每小时吃两个苹果不合常理，“每天”才符合日常饮食。"}, "sentence_index": 0, "correct_answer": "每天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天生日都请朋友吃饭。", "explanation": "这里应该用〈每年〉。生日一年只有一次，“每天”表示按天重复，不能说“每天生日”。"}, {"text": "这个社团每天组织活动，每两周一次。", "explanation": "这里应该用〈定期〉。“定期”指按一定周期进行，“每两周一次”与“每天”矛盾。"}, {"text": "他每天在周末去图书馆，平时在家。", "explanation": "这里应该用〈有时〉。“每天”表示没有例外，而“平时在家”说明并非每天去图书馆，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86974, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每天", "is_correct": true, "explanation": "正确：“医生说他每天要喝六杯水”，“每天”符合日常饮水的建议。"}, {"text": "每周", "is_correct": false, "explanation": "语义：每周喝六杯水的量远低于医生建议的日常饮水量，不合语境。"}, {"text": "每月", "is_correct": false, "explanation": "搭配：“每月”的周期过长，与“要喝六杯水”这种日常需求不搭配。"}, {"text": "每小时", "is_correct": false, "explanation": "语义：每小时喝六杯水超出正常的饮水量，不合常理。"}], "explanations": {"每天": "正确：“医生说他每天要喝六杯水”，“每天”符合日常饮水的建议。", "每周": "语义：每周喝六杯水的量远低于医生建议的日常饮水量，不合语境。", "每月": "搭配：“每月”的周期过长，与“要喝六杯水”这种日常需求不搭配。", "每小时": "语义：每小时喝六杯水超出正常的饮水量，不合常理。"}, "sentence_index": 6, "correct_answer": "每天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校每天举办一次运动会。", "explanation": "这里应该用〈每年〉。运动会通常一年举办一次；“每天”表示每一天，与这种周期性活动矛盾。"}, {"text": "我每天加班，一个月只有两次。", "explanation": "这里应该用〈偶尔〉。“每天加班”与“一个月只有两次”矛盾；“偶尔”表示不常发生，才与后半句相符。"}, {"text": "这个班每天都有一次测验，周末没有。", "explanation": "这里应该用〈工作日〉。“每天”包括周末，与“周末没有”矛盾；说“工作日都有一次测验，周末没有”才相符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "哥哥每天天下午去跑步。", "corrected_sentence": "哥哥每天下午去跑步。", "error_description": "“每天”后面不能再加一个“天”，“每天天”是错误的，应说“每天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师每天了都在办公室备课。", "corrected_sentence": "老师每天都在办公室备课。", "error_description": "“了”不能插在“每天”和“都”之间，“每天了都”是错误的，应说“每天都”。正确说法是“老师每天都在办公室备课”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7a2f97-a24f-4325-a40f-68476bd2f9b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86976, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亏本", "is_correct": true, "explanation": "反义：亏本指投入的本钱没有收回，与“回本”意思相反。"}, {"text": "种植", "is_correct": false, "explanation": "无反义关系：种植指栽培植物，与回本没有反义关系。"}, {"text": "出版", "is_correct": false, "explanation": "无反义关系：出版指把作品印刷发行，与回本没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "无反义关系：散步指悠闲地行走，与回本没有反义关系。"}], "correct_answer": "亏本", "explanations": {"亏本": "反义：亏本指投入的本钱没有收回，与“回本”意思相反。", "种植": "无反义关系：种植指栽培植物，与回本没有反义关系。", "出版": "无反义关系：出版指把作品印刷发行，与回本没有反义关系。", "散步": "无反义关系：散步指悠闲地行走，与回本没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86976, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亏本", "is_correct": true, "explanation": "反义：亏本指投入的本钱没有收回，与“回本”意思相反。"}, {"text": "扩大", "is_correct": false, "explanation": "无反义关系：扩大指规模变大，与回本没有反义关系。"}, {"text": "上涨", "is_correct": false, "explanation": "无反义关系：上涨指价格或数量升高，与回本没有反义关系。"}, {"text": "开店", "is_correct": false, "explanation": "无反义关系：开店指开办店铺，与回本没有反义关系。"}], "correct_answer": "亏本", "explanations": {"亏本": "反义：亏本指投入的本钱没有收回，与“回本”意思相反。", "扩大": "无反义关系：扩大指规模变大，与回本没有反义关系。", "上涨": "无反义关系：上涨指价格或数量升高，与回本没有反义关系。", "开店": "无反义关系：开店指开办店铺，与回本没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86976, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "收回投入的本钱。", "primary_collocate": null, "pronunciation": "huí běn", "ipa": "xweɪ˧˥ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "他开饭店的目标是两年内回本。", "target_word": "回本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说，今年一定要回本。", "target_word": "回本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目投了很多钱，三年才回本。", "target_word": "回本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们卖了很多东西，终于回本了。", "target_word": "回本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影票卖得不好，公司很难回本。", "target_word": "回本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民种了一年菜，只够回本。", "target_word": "回本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了房子出租，十年才能回本。", "target_word": "回本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开店的钱都回本了，现在开始赚钱。", "target_word": "回本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔投资风险大，不一定回本。", "target_word": "回本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要客人多，小店很快就能回本。", "target_word": "回本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "回本了", "label": "体标（了）"}, {"form": "回过本", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "回本：把投资投入的本钱收回来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e417de8-3307-410a-8543-b657809a61d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86976, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回本", "is_correct": true, "explanation": "回本：两年内收回投入的本钱，符合“目标”的语境。"}, {"text": "关门", "is_correct": false, "explanation": "语义：关门指店铺停业倒闭，不能作为“两年内的目标”。"}, {"text": "装修", "is_correct": false, "explanation": "语义：装修是开业前的准备工作，不能作为两年内要达到的目标。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加”只说明数量变多，“两年内增加”没有说明增加什么，句意不完整，不符合“回本”的目标语境。"}], "explanations": {"回本": "回本：两年内收回投入的本钱，符合“目标”的语境。", "关门": "语义：关门指店铺停业倒闭，不能作为“两年内的目标”。", "装修": "语义：装修是开业前的准备工作，不能作为两年内要达到的目标。", "增加": "语义：“增加”只说明数量变多，“两年内增加”没有说明增加什么，句意不完整，不符合“回本”的目标语境。"}, "sentence_index": 0, "correct_answer": "回本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的学位终于回本了。", "explanation": "这里应该用〈获得〉。回本指收回投入的本钱，取得学位要用“获得”，不能用“回本”。"}, {"text": "这道题他终于回本了。", "explanation": "这里应该用〈做对〉。回本指收回投入的本钱，答对题目要用“做对”，不能用“回本”。"}, {"text": "这盏灯终于回本了。", "explanation": "这里应该用〈亮〉。回本指收回投入的本钱，灯亮要用“亮”，不能用“回本”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86976, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回本", "is_correct": true, "explanation": "回本：十年后才能收回买房投入的本钱，句意通顺。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：毕业指学生完成学业，与“买了房子出租”的语境无关，句意不通。"}, {"text": "提高", "is_correct": false, "explanation": "语义：“提高”指水平或程度上升，与“买房出租”后收回成本的语境无关，句意不通。"}, {"text": "停业", "is_correct": false, "explanation": "语义：停业指店铺暂停营业，与“买了房子出租”的语境不符。"}], "explanations": {"回本": "回本：十年后才能收回买房投入的本钱，句意通顺。", "毕业": "语义：毕业指学生完成学业，与“买了房子出租”的语境无关，句意不通。", "提高": "语义：“提高”指水平或程度上升，与“买房出租”后收回成本的语境无关，句意不通。", "停业": "语义：停业指店铺暂停营业，与“买了房子出租”的语境不符。"}, "sentence_index": 6, "correct_answer": "回本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的伤终于回本了。", "explanation": "这里应该用〈康复〉。回本指收回投入的本钱，不能用于伤势恢复。"}, {"text": "会议终于回本了。", "explanation": "这里应该用〈结束〉。回本指收回投入的本钱，不能用于会议的结束。"}, {"text": "工作终于回本了。", "explanation": "这里应该用〈完成〉。回本指收回本钱，不能用于工作的完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他开饭店两年后很回本了。", "corrected_sentence": "他开饭店两年后终于回本了。", "error_description": "错误：副词“很”不能修饰动词“回本”，应改为“终于”，表示两年后最终收回了本钱。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家小店半年就把回本了。", "corrected_sentence": "这家小店半年就回本了。", "error_description": "错误：“回本”是不及物动词，不能用“把”字结构，应去掉“把”，改为“这家小店半年就回本了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
