INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86977, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "赢得是靠自己的本事，得到别人的喜欢或者好东西。", "primary_collocate": null, "pronunciation": "yíng dé", "ipa": "iŋ˧˥ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他的笑话赢得了大家的喜爱。", "target_word": "赢得", "complexity_tier": "T3", "furigana": "tā de xiào huà yíng dé le dà jiā de xǐ ài.", "sentence_source": "generated"}, {"text": "小狗的可爱赢得了孩子们的心。", "target_word": "赢得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她唱得好，赢得了很多掌声。", "target_word": "赢得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位医生赢得了病人的信任。", "target_word": "赢得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的作品会赢得读者的喜爱。", "target_word": "赢得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他靠本事赢得了这份工作。", "target_word": "赢得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的耐心赢得了学生的心。", "target_word": "赢得", "complexity_tier": "T3", "furigana": "lǎo shī de nài xīn yíng dé le xué shēng de xīn.", "sentence_source": "generated"}, {"text": "小李的诚实赢得了老板的信任。", "target_word": "赢得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事赢得了很多人的好感。", "target_word": "赢得", "complexity_tier": "T3", "furigana": "zhè ge gù shi yíng dé le hěn duō rén de hǎo gǎn.", "sentence_source": "generated"}, {"text": "他用好菜赢得了客人的夸奖。", "target_word": "赢得", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "赢得了", "label": "体标"}, {"form": "赢得过", "label": "体标"}], "register": "中性", "sense_fingerprint": "靠本事得到别人的喜欢或好东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10a82993-50d4-4381-a959-52d6505f63fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86977, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赢得", "is_correct": true, "explanation": "赢得：凭本事得到别人的喜爱，此处指笑话受到大家喜欢。"}, {"text": "讲", "is_correct": false, "explanation": "搭配：“讲”可以接“笑话”，但不能说“讲了大家的喜爱”。"}, {"text": "打破", "is_correct": false, "explanation": "搭配：“打破”的宾语应是纪录、沉默等，不能说打破喜爱。"}, {"text": "扼杀", "is_correct": false, "explanation": "语义：“扼杀”指消灭，与笑话受人喜爱的语境相反，放在此处语义矛盾。"}], "explanations": {"赢得": "赢得：凭本事得到别人的喜爱，此处指笑话受到大家喜欢。", "讲": "搭配：“讲”可以接“笑话”，但不能说“讲了大家的喜爱”。", "打破": "搭配：“打破”的宾语应是纪录、沉默等，不能说打破喜爱。", "扼杀": "语义：“扼杀”指消灭，与笑话受人喜爱的语境相反，放在此处语义矛盾。"}, "sentence_index": 0, "correct_answer": "赢得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她去窗口赢得了护照。", "explanation": "这里应该用〈领取〉。赢得须经竞争或努力而得，护照是办理发放的，应说领取。"}, {"text": "我昨天赢得了一个包裹。", "explanation": "这里应该用〈收到〉。赢得要靠本事或努力，包裹是寄来的，应说收到。"}, {"text": "他赢得了一场高烧。", "explanation": "这里应该用〈患上〉。赢得指凭本事或努力得到好东西，高烧是生病，不能说赢得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86977, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赢得", "is_correct": true, "explanation": "赢得：凭本事或耐心得到别人的心，此处指老师的耐心打动了学生。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的宾语应是衣服、手等，不能说洗学生的心。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与耐心打动学生的正面语境相反，不能接“学生的心”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说吃学生的心。"}], "explanations": {"赢得": "赢得：凭本事或耐心得到别人的心，此处指老师的耐心打动了学生。", "洗": "搭配：“洗”的宾语应是衣服、手等，不能说洗学生的心。", "拒绝": "语义：“拒绝”与耐心打动学生的正面语境相反，不能接“学生的心”。", "吃": "搭配：“吃”的宾语应是食物，不能说吃学生的心。"}, "sentence_index": 6, "correct_answer": "赢得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店赢得了营业许可。", "explanation": "这里应该用〈获得〉。赢得多指竞争或努力后胜出所得，营业许可是审批而来的，应说获得。"}, {"text": "他被大学赢得了。", "explanation": "这里应该用〈录取〉。学校录取学生不是靠竞争所得，不能说赢得。"}, {"text": "他赢得了驾照。", "explanation": "这里应该用〈考取〉。驾照要通过考试取得，不是靠竞争赢得，应说考取。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86977, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她靠耐心赢得了的同事的好感。", "corrected_sentence": "她靠耐心赢得了同事的好感。", "error_description": "“了”后面多加了“的”：“赢得了”后应直接接宾语，说“赢得了同事的好感”，不说“赢得了的同事的好感”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86977, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他凭实力赢得了着老板的赏识。", "corrected_sentence": "他凭实力赢得了老板的赏识。", "error_description": "错误在于“了”与“着”同时出现：“了”表示已经获得，“着”表示持续状态，二者不能叠加；应说“赢得了老板的赏识”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
