INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86978, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "经过努力或竞争而获得（荣誉、胜利、好感、时间等）。", "primary_collocate": null, "pronunciation": "yíng dé", "ipa": "iŋ˧˥ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "小明努力练习，赢得了比赛。", "target_word": "赢得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的好成绩赢得了老师的表扬。", "target_word": "赢得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的服务赢得了很多客人的好感。", "target_word": "赢得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的队赢得了第一名。", "target_word": "赢得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他赢得了大家的尊重。", "target_word": "赢得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样做可以为我们赢得一些时间。", "target_word": "赢得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的队伍赢得过三次冠军。", "target_word": "赢得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用真心赢得了朋友的信任。", "target_word": "赢得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过一年的努力，他赢得了这份荣誉。", "target_word": "赢得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影赢得了很多观众的喜爱。", "target_word": "赢得", "complexity_tier": "T3", "furigana": "zhè bù diàn yǐng yíng dé le hěn duō guān zhòng de xǐ ài.", "sentence_source": "generated"}], "morphological_forms": [{"form": "赢得了", "label": "体标"}, {"form": "赢得过", "label": "体标"}], "register": "中性", "sense_fingerprint": "经过努力或竞争获得荣誉、胜利、好感、时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10a82993-50d4-4381-a959-52d6505f63fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86978, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赢得", "is_correct": true, "explanation": "赢得：经过努力或竞争而获得，此处指在比赛中取胜。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语应是食物，不能说吃比赛。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”的宾语是文件、材料，不能说打印比赛。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与“努力练习”的语境相反，放在此处语义矛盾。"}], "explanations": {"赢得": "赢得：经过努力或竞争而获得，此处指在比赛中取胜。", "吃": "配价：“吃”的宾语应是食物，不能说吃比赛。", "打印": "搭配：“打印”的宾语是文件、材料，不能说打印比赛。", "放弃": "语义：“放弃”与“努力练习”的语境相反，放在此处语义矛盾。"}, "sentence_index": 0, "correct_answer": "赢得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司赢得了一张营业执照。", "explanation": "这里应该用〈获得〉。赢得指在竞争或努力中胜出而得到，营业执照是审批发放的，不说赢得。"}, {"text": "他赢得了一场重感冒。", "explanation": "这里应该用〈患上〉。赢得指凭努力或竞争得到好东西，感冒是生病，不能说赢得。"}, {"text": "我昨天赢得了一封信。", "explanation": "这里应该用〈收到〉。赢得要靠竞争或努力，一封信是寄来的，应说收到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86978, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赢得", "is_correct": true, "explanation": "赢得：经过努力或竞争而获得，此处指队伍凭实力获得冠军。"}, {"text": "出生", "is_correct": false, "explanation": "配价：“出生”是不及物动词，后面不能带“冠军”作宾语。"}, {"text": "居住", "is_correct": false, "explanation": "配价：“居住”是不及物动词，不能带“冠军”作宾语。"}, {"text": "诞生", "is_correct": false, "explanation": "语义：“诞生”指新事物出现，与“冠军”通过比赛获得的语境不符。"}], "explanations": {"赢得": "赢得：经过努力或竞争而获得，此处指队伍凭实力获得冠军。", "出生": "配价：“出生”是不及物动词，后面不能带“冠军”作宾语。", "居住": "配价：“居住”是不及物动词，不能带“冠军”作宾语。", "诞生": "语义：“诞生”指新事物出现，与“冠军”通过比赛获得的语境不符。"}, "sentence_index": 6, "correct_answer": "赢得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她去窗口赢得了身份证。", "explanation": "这里应该用〈领取〉。赢得须经竞争或努力才能得到，身份证是办理后发放的，应说领取。"}, {"text": "他被大学赢得了。", "explanation": "这里应该用〈录取〉。学校录取学生不是靠竞争所得，不能说赢得。"}, {"text": "她赢得了研究生。", "explanation": "这里应该用〈考取〉。研究生要通过考试被录取，不是靠竞争赢得，应说考取。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这支球队赢得了的广泛的关注。", "corrected_sentence": "这支球队赢得了广泛的关注。", "error_description": "“了”后面多加了“的”：“赢得了”后应直接接宾语，说“赢得了广泛的关注”，不说“赢得了的广泛的关注”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他靠诚实赢得了着客户的信任。", "corrected_sentence": "他靠诚实赢得了客户的信任。", "error_description": "错误在于“了”与“着”同时出现：“了”表示已经获得，“着”表示持续状态，二者不能叠加；应说“赢得了客户的信任”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
