INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86979, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "节目是电视或广播中给人看、给人听的东西。", "primary_collocate": null, "pronunciation": "jié mù", "ipa": "tɕjɛ˧˥ mu˥˩", "syllable_count": 2, "sentences": [{"text": "我们家每天晚上都看电视里的节目。", "target_word": "节目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目很有意思，大家都爱看。", "target_word": "节目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚的节目太长了，我没看完。", "target_word": "节目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈喜欢听广播里的节目。", "target_word": "节目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里正在播放的节目是新闻。", "target_word": "节目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你最喜欢哪个节目？", "target_word": "节目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目每个星期六晚上八点播出。", "target_word": "节目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们很喜欢看这个节目，里面有很多小动物。", "target_word": "节目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视上的节目不错，我们都笑了。", "target_word": "节目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看过这个节目，说非常好看。", "target_word": "节目", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个节目", "label": "量词"}, {"form": "節目", "label": "繁体"}], "register": "中性", "sense_fingerprint": "电视、广播中播出、供人看听的内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c70db0a-f54e-4bc4-8d58-add9704b2190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86979, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电视机", "is_correct": false, "explanation": "搭配：“看”接的是节目、剧等内容，“电视机”是器具，不能作“看”的对象。"}, {"text": "节目", "is_correct": true, "explanation": "正确：“节目”指电视上播出、供人观看的内容，与“看”搭配。"}, {"text": "节日", "is_correct": false, "explanation": "语义：“节日”指假日，不是电视上供人观看的内容。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：“报纸”是印刷品，不是电视上播出的内容。"}], "explanations": {"电视机": "搭配：“看”接的是节目、剧等内容，“电视机”是器具，不能作“看”的对象。", "节目": "正确：“节目”指电视上播出、供人观看的内容，与“看”搭配。", "节日": "语义：“节日”指假日，不是电视上供人观看的内容。", "报纸": "语义：“报纸”是印刷品，不是电视上播出的内容。"}, "sentence_index": 0, "correct_answer": "节目"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个节目穿在身上很暖和。", "explanation": "这里应该用〈衣服〉。节目是电视或广播里供人看听的内容，不能穿在身上。"}, {"text": "我昨晚喝了这个节目。", "explanation": "这里应该用〈饮料〉。节目是供人看听的内容，不能用“喝”。"}, {"text": "这个节目要在明天交。", "explanation": "这里应该用〈作业〉。节目是播出或演出的内容，不能交，要交的是作业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86979, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明星", "is_correct": false, "explanation": "搭配：“播出”的主语应是节目或内容，不能用指人的“明星”。"}, {"text": "节目", "is_correct": true, "explanation": "正确：“节目”可以在电视或广播中定时播出，与“播出”搭配。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学习任务，不会在电视上定时播出。"}, {"text": "地址", "is_correct": false, "explanation": "语义：“地址”是住所或位置，不能在电视上播出。"}], "explanations": {"明星": "搭配：“播出”的主语应是节目或内容，不能用指人的“明星”。", "节目": "正确：“节目”可以在电视或广播中定时播出，与“播出”搭配。", "作业": "语义：“作业”是学习任务，不会在电视上定时播出。", "地址": "语义：“地址”是住所或位置，不能在电视上播出。"}, "sentence_index": 6, "correct_answer": "节目"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门节目要学一个学期。", "explanation": "这里应该用〈课程〉。节目是供人看听的内容，不是要学习的科目，不能说“学一个学期”。"}, {"text": "这个节目很好吃，大家都想尝尝。", "explanation": "这里应该用〈菜〉。节目是供人看听的内容，不能用“好吃”形容。"}, {"text": "这个节目很难玩，大家都想试试。", "explanation": "这里应该用〈游戏〉。节目是用来看或听的，不能说“玩”，“难玩”的应是游戏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86979, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家那台电视里有一只很好看的节目。", "corrected_sentence": "我家那台电视里有一个很好看的节目。", "error_description": "错误：量词“只”用错了。节目应该用量词“个”，“只”多用于动物或成对的东西，不能用于节目。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86979, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们晚会上有很多精彩的节目们。", "corrected_sentence": "我们晚会上有很多精彩的节目。", "error_description": "错误：节目后面不能加“们”。“们”只用于指人的复数，节目应直接说“很多精彩的节目”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
