INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86980, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "文艺演出中一个一个的表演项目。", "primary_collocate": null, "pronunciation": "jié mù", "ipa": "tɕjɛ˧˥ mu˥˩", "syllable_count": 2, "sentences": [{"text": "晚会上，主持人宣布：下一个节目马上开始。", "target_word": "节目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下一个节目是小红的舞蹈。", "target_word": "节目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班准备了两个节目。", "target_word": "节目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目只有三分钟，但是很精彩。", "target_word": "节目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想为新年晚会准备一个节目。", "target_word": "节目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一个节目是大家一起唱的歌。", "target_word": "节目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的节目得到了很多掌声。", "target_word": "节目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的晚会一共有八个节目。", "target_word": "节目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们班的节目是什么？", "target_word": "节目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把我们的节目放在最后一个。", "target_word": "节目", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个节目", "label": "量词"}, {"form": "節目", "label": "繁体"}], "register": "中性", "sense_fingerprint": "演出或节目单中一个一个的表演项目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c70db0a-f54e-4bc4-8d58-add9704b2190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86980, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乐器", "is_correct": false, "explanation": "搭配：“开始”的对象应是节目、比赛等活动，“乐器”是器具，不能“开始”。"}, {"text": "节目", "is_correct": true, "explanation": "正确：“节目”指晚会上一个个表演项目，主持人宣布“下一个节目”即指下一个表演。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：“礼物”是送人的物品，不是晚会上的表演项目。"}, {"text": "座位", "is_correct": false, "explanation": "语义：“座位”是座椅的位置，不是可以表演的项目。"}], "explanations": {"乐器": "搭配：“开始”的对象应是节目、比赛等活动，“乐器”是器具，不能“开始”。", "节目": "正确：“节目”指晚会上一个个表演项目，主持人宣布“下一个节目”即指下一个表演。", "礼物": "语义：“礼物”是送人的物品，不是晚会上的表演项目。", "座位": "语义：“座位”是座椅的位置，不是可以表演的项目。"}, "sentence_index": 0, "correct_answer": "节目"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个节目获得了三项专利。", "explanation": "这里应该用〈项目〉。节目指演出或播出的表演内容，不能获得专利。"}, {"text": "我昨晚踢了这个节目。", "explanation": "这里应该用〈足球〉。节目是演出内容，不能用“踢”。"}, {"text": "这个节目需要两个人玩。", "explanation": "这里应该用〈游戏〉。节目是给人看或听的内容，不能说“需要两个人玩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86980, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手机", "is_correct": false, "explanation": "语义：“手机”是通讯工具，不是表演，不能“得到掌声”。"}, {"text": "节目", "is_correct": true, "explanation": "正确：“节目”是表演项目，可以“得到掌声”。"}, {"text": "教室", "is_correct": false, "explanation": "语义：“教室”是地方，不会“得到掌声”。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是用来挡雨的东西，不是表演，不会“得到掌声”。"}], "explanations": {"手机": "语义：“手机”是通讯工具，不是表演，不能“得到掌声”。", "节目": "正确：“节目”是表演项目，可以“得到掌声”。", "教室": "语义：“教室”是地方，不会“得到掌声”。", "雨伞": "语义：“雨伞”是用来挡雨的东西，不是表演，不会“得到掌声”。"}, "sentence_index": 6, "correct_answer": "节目"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门节目要学两年。", "explanation": "这里应该用〈课程〉。节目不是要学习的科目，不能说“学两年”。"}, {"text": "他吃了这个节目。", "explanation": "这里应该用〈饭〉。节目是供人看或听的表演，不能用“吃”。"}, {"text": "这个节目长得很高。", "explanation": "这里应该用〈演员〉。节目是演出内容，不能用“长得很高”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86980, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班的节目排在第三只。", "corrected_sentence": "我们班的节目排在第三个。", "error_description": "错误：量词“只”用错了。节目应该用量词“个”，“只”多用于动物或成对的东西，不能用于节目。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86980, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班的节目们都很精彩，大家很开心。", "corrected_sentence": "我们班的节目都很精彩，大家很开心。", "error_description": "错误：节目后面加了“们”。“们”只用于指人的复数，“节目”不能加“们”，应说“我们班的节目都很精彩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
