INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86981, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国务卿是美国政府里管和别的国家打交道的大官。", "primary_collocate": null, "pronunciation": "guó wù qīng", "ipa": "kwo˧˥ u˥˩ tɕʰiŋ˥", "syllable_count": 3, "sentences": [{"text": "国务卿是美国管外交的大官。", "target_word": "国务卿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国务卿每天都要和各国打交道。", "target_word": "国务卿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统选了一位新国务卿。", "target_word": "国务卿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国务卿向总统报告了会谈情况。", "target_word": "国务卿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位国务卿会说三种语言。", "target_word": "国务卿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国务卿正在和日本代表开会。", "target_word": "国务卿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人都认识那位国务卿。", "target_word": "国务卿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国务卿带着秘书去了北京。", "target_word": "国务卿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里正在播放国务卿的讲话。", "target_word": "国务卿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国务卿昨天回到了华盛顿。", "target_word": "国务卿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "副国务卿", "label": "复合词"}, {"form": "前国务卿", "label": "复合词"}], "register": "正式", "sense_fingerprint": "美国政府里负责对外交往的大官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e417de8-3307-410a-8543-b657809a61d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86981, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国务卿", "is_correct": true, "explanation": "国务卿：美国管外交的大官，句意通顺。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师是做饭的人，与“管外交的大官”不符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能是“管外交的大官”，句意荒谬。"}, {"text": "外交", "is_correct": false, "explanation": "搭配：“是……大官”要求人作主语，“外交”不是人，不能充当主语。"}], "explanations": {"国务卿": "国务卿：美国管外交的大官，句意通顺。", "厨师": "语义：厨师是做饭的人，与“管外交的大官”不符。", "天气": "语义：天气是自然现象，不能是“管外交的大官”，句意荒谬。", "外交": "搭配：“是……大官”要求人作主语，“外交”不是人，不能充当主语。"}, "sentence_index": 0, "correct_answer": "国务卿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她是老板的国务卿，负责安排行程。", "explanation": "这里应该用〈秘书〉。国务卿是美国管外交的大官，私人老板不会有国务卿。"}, {"text": "她是中国驻法国务卿。", "explanation": "这里应该用〈大使〉。国务卿是美国的官职，中国驻法国的外交代表是大使。"}, {"text": "这位国务卿每天给我们上数学课。", "explanation": "这里应该用〈老师〉。国务卿是美国管外交的大官，不给学生上课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86981, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国务卿", "is_correct": true, "explanation": "国务卿：很多人都可能认识的高级官员，句意通顺。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能修饰“桌子”。"}, {"text": "理想", "is_correct": false, "explanation": "语义：理想是抽象概念，不能被很多人认识，句意荒谬。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能修饰“电脑”。"}], "explanations": {"国务卿": "国务卿：很多人都可能认识的高级官员，句意通顺。", "桌子": "搭配：量词“位”只用于人，不能修饰“桌子”。", "理想": "语义：理想是抽象概念，不能被很多人认识，句意荒谬。", "电脑": "搭配：量词“位”只用于人，不能修饰“电脑”。"}, "sentence_index": 6, "correct_answer": "国务卿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "美国国务卿明天要负责全国的交通规划。", "explanation": "这里应该用〈交通部长〉。美国国务卿主管外交，全国交通规划由交通部长负责。"}, {"text": "美国国务卿今天宣布了本市的新政策。", "explanation": "这里应该用〈市长〉。美国国务卿主管对外交往，本市政策由市长宣布。"}, {"text": "美国国务卿今天宣布了判决。", "explanation": "这里应该用〈法官〉。美国国务卿主管对外交往，不审判案件，宣布判决的是法官。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86981, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他见过那位国务卿们。", "corrected_sentence": "他见过那位国务卿。", "error_description": "错误：“那位”后面不能再加“们”，“国务卿”指单个的人，应去掉“们”，写作“那位国务卿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86981, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天接待了一国务卿。", "corrected_sentence": "昨天接待了一位国务卿。", "error_description": "错误：数词“一”与名词“国务卿”之间缺少量词，应补上“位”，写作“一位国务卿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
