INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86982, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "美国政府中主管外交事务的最高官员。", "primary_collocate": null, "pronunciation": "guó wù qīng", "ipa": "kwo˧˥ u˥˩ tɕʰiŋ˥", "syllable_count": 3, "sentences": [{"text": "美国国务卿今天访问了中国。", "target_word": "国务卿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国务卿负责美国的外交工作。", "target_word": "国务卿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位国务卿在会上发表了讲话。", "target_word": "国务卿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新国务卿下个月就要上任。", "target_word": "国务卿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国务卿和中国外长见了面。", "target_word": "国务卿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他曾经当过国务卿。", "target_word": "国务卿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国务卿坐飞机去了欧洲。", "target_word": "国务卿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者问国务卿一个问题。", "target_word": "国务卿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国务卿的助手准备了很多材料。", "target_word": "国务卿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统请国务卿谈谈外交问题。", "target_word": "国务卿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "副国务卿", "label": "复合词"}, {"form": "前国务卿", "label": "复合词"}], "register": "正式", "sense_fingerprint": "美国政府主管外交的最高官员的职务名称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e417de8-3307-410a-8543-b657809a61d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86982, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国务卿", "is_correct": true, "explanation": "国务卿：美国政府的外交首长，可以访问他国，句意通顺。"}, {"text": "风景", "is_correct": false, "explanation": "搭配：“访问”的主语要是人或团体，“风景”不能访问中国。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不能作为访问中国的主体，句意荒谬。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮品，不能访问中国，句意荒谬。"}], "explanations": {"国务卿": "国务卿：美国政府的外交首长，可以访问他国，句意通顺。", "风景": "搭配：“访问”的主语要是人或团体，“风景”不能访问中国。", "饼干": "语义：饼干是食品，不能作为访问中国的主体，句意荒谬。", "咖啡": "语义：咖啡是饮品，不能访问中国，句意荒谬。"}, "sentence_index": 0, "correct_answer": "国务卿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的国务卿今天很忙。", "explanation": "这里应该用〈秘书〉。国务卿是美国政府主管外交的最高官员，普通人的秘书不能称为国务卿。"}, {"text": "他现在担任中国驻美国务卿。", "explanation": "这里应该用〈大使〉。国务卿是美国政府的官职，中国派驻美国的外交代表是大使。"}, {"text": "这位国务卿经营一家小饭店。", "explanation": "这里应该用〈店主〉。国务卿是美国政府主管外交的官员，不经营饭店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86982, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国务卿", "is_correct": true, "explanation": "国务卿：可以乘飞机出访，句意通顺。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“坐飞机”的主语要是人，石头不能乘坐飞机。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不能自己坐飞机去欧洲，句意荒谬。"}, {"text": "大树", "is_correct": false, "explanation": "语义：大树是植物，不能乘飞机，句意荒谬。"}], "explanations": {"国务卿": "国务卿：可以乘飞机出访，句意通顺。", "石头": "搭配：“坐飞机”的主语要是人，石头不能乘坐飞机。", "椅子": "语义：椅子是家具，不能自己坐飞机去欧洲，句意荒谬。", "大树": "语义：大树是植物，不能乘飞机，句意荒谬。"}, "sentence_index": 6, "correct_answer": "国务卿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "美国国务卿负责国家的预算。", "explanation": "这里应该用〈财政部长〉。美国国务卿主管外交，国家预算由财政部长负责，不归国务卿。"}, {"text": "美国国务卿今天主持了法庭审判。", "explanation": "这里应该用〈法官〉。美国国务卿主管外交，不主持法庭审判。"}, {"text": "美国国务卿今天主持了学校的开学典礼。", "explanation": "这里应该用〈校长〉。开学典礼通常由校长主持，美国国务卿主管外交，不主持学校活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们见到了一国务卿。", "corrected_sentence": "我们见到了一位国务卿。", "error_description": "错误：数词“一”与名词“国务卿”之间缺少量词，应补上“位”，写作“一位国务卿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在会上见到了这几位国务卿们。", "corrected_sentence": "我们在会上见到了这几位国务卿。", "error_description": "错误：“这几位”已表示复数，之后不能再加“们”，应去掉“们”，写作“这几位国务卿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
