INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86983, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "军事是和军队、打仗有关的事。", "primary_collocate": null, "pronunciation": "jūn shì", "ipa": "tɕyn˥ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "他对军事很有兴趣。", "target_word": "军事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲的是军事方面的事。", "target_word": "军事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥在大学学军事。", "target_word": "军事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里正在说军事新闻。", "target_word": "军事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张退休前在部队，对军事很熟悉。", "target_word": "军事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时喜欢看军事书。", "target_word": "军事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家每年在军事上花很多钱。", "target_word": "军事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是研究军事的老师。", "target_word": "军事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲一生都热爱军事。", "target_word": "军事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子喜欢看军事电影。", "target_word": "军事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "军事基地", "label": "复合词"}, {"form": "军事演习", "label": "复合词"}], "register": "中性", "sense_fingerprint": "军事：与军队、打仗有关的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2568f57c-7316-43f4-ae41-0373852d042f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86983, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "军事", "is_correct": true, "explanation": "正确答案。军事，名词，指与军队、打仗有关的事。"}, {"text": "军师", "is_correct": false, "explanation": "jūn shī 与 jūn shì 第二音节声调不同（第一声与第四声），意思是出谋划策的人。"}, {"text": "军史", "is_correct": false, "explanation": "jūn shǐ 与 jūn shì 第二音节声调不同（第三声与第四声），意思是军队的历史。"}, {"text": "军制", "is_correct": false, "explanation": "jūn zhì 与 jūn shì 第二音节声母不同（zh 与 sh），意思是军队的制度。"}], "explanations": {"军事": "正确答案。军事，名词，指与军队、打仗有关的事。", "军师": "jūn shī 与 jūn shì 第二音节声调不同（第一声与第四声），意思是出谋划策的人。", "军史": "jūn shǐ 与 jūn shì 第二音节声调不同（第三声与第四声），意思是军队的历史。", "军制": "jūn zhì 与 jūn shì 第二音节声母不同（zh 与 sh），意思是军队的制度。"}, "sentence_index": null, "correct_answer": "军事"}, "level_3": {"options": [{"text": "军事", "is_correct": true, "explanation": "正确答案。军事，名词，指与军队、打仗有关的事，可以作“兴趣”的对象。"}, {"text": "痛苦", "is_correct": false, "explanation": "语义：“很有兴趣”表示喜爱，“痛苦”是负面感受，作兴趣的对象语义矛盾。"}, {"text": "星期一", "is_correct": false, "explanation": "搭配：“对……有兴趣”的对象应是事物或领域，“星期一”是时间词，“对星期一很有兴趣”不通。"}, {"text": "下午", "is_correct": false, "explanation": "语义：“下午”是时间，不能作兴趣的对象，“对下午很有兴趣”语义不通。"}], "explanations": {"军事": "正确答案。军事，名词，指与军队、打仗有关的事，可以作“兴趣”的对象。", "痛苦": "语义：“很有兴趣”表示喜爱，“痛苦”是负面感受，作兴趣的对象语义矛盾。", "星期一": "搭配：“对……有兴趣”的对象应是事物或领域，“星期一”是时间词，“对星期一很有兴趣”不通。", "下午": "语义：“下午”是时间，不能作兴趣的对象，“对下午很有兴趣”语义不通。"}, "sentence_index": 0, "correct_answer": "军事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这支军事很强大。", "explanation": "这里应该用〈军队〉。“军事”指与军队、打仗有关的事务，不指武装力量本身；“这支”后面要接军队，不能用“军事”。"}, {"text": "他是一名军事。", "explanation": "这里指人，应该用〈军人〉。“军事”指事务，不能用量词“名”来计数人。"}, {"text": "军事在山上驻扎。", "explanation": "这里应该用〈军队〉。驻扎的主体是有人员的部队，“军事”是抽象的事务，不能作施事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86983, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "军事", "is_correct": true, "explanation": "正确答案。军事，名词，此处指国家在军事方面的投入。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“在……上花钱”的对象要能被投入或购买，“空气”不能用来花钱。"}, {"text": "心跳", "is_correct": false, "explanation": "搭配：“在……上花钱”的对象要能被投入或购买，“心跳”是生理现象，不能用来花钱。"}, {"text": "呼吸", "is_correct": false, "explanation": "搭配：“呼吸”是生理活动，不能作“在……上花钱”的对象。"}], "explanations": {"军事": "正确答案。军事，名词，此处指国家在军事方面的投入。", "空气": "搭配：“在……上花钱”的对象要能被投入或购买，“空气”不能用来花钱。", "心跳": "搭配：“在……上花钱”的对象要能被投入或购买，“心跳”是生理现象，不能用来花钱。", "呼吸": "搭配：“呼吸”是生理活动，不能作“在……上花钱”的对象。"}, "sentence_index": 6, "correct_answer": "军事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去军事参观。", "explanation": "这里表示地点，应该用〈军营〉。“军事”是事务，不能作参观的场所。"}, {"text": "他穿着军事。", "explanation": "这里指衣物，应该用〈军服〉。“军事”是抽象事务，不能穿在身上。"}, {"text": "这艘军事驶向大海。", "explanation": "这里指船只，应该用〈军舰〉。“军事”不是船，不能用量词“艘”计数，也不能行驶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86983, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在军事感兴趣。", "corrected_sentence": "他对军事感兴趣。", "error_description": "“感兴趣”的对象用“对”引出，应说“对军事感兴趣”；若用“在”，后面须加“……上”，此处缺“上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86983, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把很多钱投入了军事们。", "corrected_sentence": "他们把很多钱投入了军事。", "error_description": "“军事”是抽象事务，不能加“们”表复数；应去掉“们”，说“把很多钱投入了军事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
