INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86984, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "与军队、战争有关的事情。", "primary_collocate": null, "pronunciation": "jūn shì", "ipa": "tɕyn˥ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "我不懂军事，只知道一点点。", "target_word": "军事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人一辈子都在做军事工作。", "target_word": "军事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的军事力量差不多。", "target_word": "军事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上有很多军事消息。", "target_word": "军事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了解中国的军事历史。", "target_word": "军事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军事和经济都很重要。", "target_word": "军事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目专门介绍军事知识。", "target_word": "军事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在部队工作了二十年，精通军事。", "target_word": "军事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军事上的事，他不能随便说。", "target_word": "军事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大国都很重视军事。", "target_word": "军事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "军事基地", "label": "复合词"}, {"form": "军事演习", "label": "复合词"}], "register": "中性", "sense_fingerprint": "军事：与军队、战争有关的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2568f57c-7316-43f4-ae41-0373852d042f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86984, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "军事", "is_correct": true, "explanation": "正确答案。军事，名词，指与军队、战争有关的事情。"}, {"text": "军师", "is_correct": false, "explanation": "jūn shī 与 jūn shì 第二音节声调不同（第一声与第四声），意思是出谋划策的人。"}, {"text": "军史", "is_correct": false, "explanation": "jūn shǐ 与 jūn shì 第二音节声调不同（第三声与第四声），意思是军队的历史。"}, {"text": "军制", "is_correct": false, "explanation": "jūn zhì 与 jūn shì 第二音节声母不同（zh 与 sh），意思是军队的制度。"}], "explanations": {"军事": "正确答案。军事，名词，指与军队、战争有关的事情。", "军师": "jūn shī 与 jūn shì 第二音节声调不同（第一声与第四声），意思是出谋划策的人。", "军史": "jūn shǐ 与 jūn shì 第二音节声调不同（第三声与第四声），意思是军队的历史。", "军制": "jūn zhì 与 jūn shì 第二音节声母不同（zh 与 sh），意思是军队的制度。"}, "sentence_index": null, "correct_answer": "军事"}, "level_3": {"options": [{"text": "军事", "is_correct": true, "explanation": "正确答案。军事，名词，指与军队、战争有关的事情，可以作“懂”的对象。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：“懂”的对象要是可以理解的知识或道理，“呼吸”是生理现象，不能说懂。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：“心跳”是生理现象，不能作“懂”的对象，“我不懂心跳”语义不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“懂”的宾语多为知识、技术或道理，“脚步”一般不与“懂”搭配。"}], "explanations": {"军事": "正确答案。军事，名词，指与军队、战争有关的事情，可以作“懂”的对象。", "呼吸": "语义：“懂”的对象要是可以理解的知识或道理，“呼吸”是生理现象，不能说懂。", "心跳": "语义：“心跳”是生理现象，不能作“懂”的对象，“我不懂心跳”语义不通。", "脚步": "搭配：“懂”的宾语多为知识、技术或道理，“脚步”一般不与“懂”搭配。"}, "sentence_index": 0, "correct_answer": "军事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场军事很残酷。", "explanation": "这里应该用〈战争〉。“军事”指与军队有关的事务，不指具体的战争事件；“这场”后面要接战争。"}, {"text": "我哥哥是一名军事。", "explanation": "这里指人，应该用〈军人〉。“军事”指事务，不能用量词“名”来计数人。"}, {"text": "军事正在训练。", "explanation": "这里应该用〈部队〉。训练的主体是人或部队，“军事”是抽象的事务，不能作施事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86984, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "军事", "is_correct": true, "explanation": "正确答案。军事，名词，此处指可以被介绍的知识领域。"}, {"text": "痛苦", "is_correct": false, "explanation": "语义：“介绍……知识”要求是可以学习的领域，“痛苦”是感受而不是知识领域，句子不通。"}, {"text": "尊严", "is_correct": false, "explanation": "搭配：“……知识”的前项应是可以学习的领域，“尊严”不能与“知识”搭配。"}, {"text": "叹息", "is_correct": false, "explanation": "语义：“叹息”是情绪的表现，不能作为被介绍的知识领域，语义不通。"}], "explanations": {"军事": "正确答案。军事，名词，此处指可以被介绍的知识领域。", "痛苦": "语义：“介绍……知识”要求是可以学习的领域，“痛苦”是感受而不是知识领域，句子不通。", "尊严": "搭配：“……知识”的前项应是可以学习的领域，“尊严”不能与“知识”搭配。", "叹息": "语义：“叹息”是情绪的表现，不能作为被介绍的知识领域，语义不通。"}, "sentence_index": 6, "correct_answer": "军事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "士兵住在军事里。", "explanation": "这里指住所，应该用〈军营〉。“军事”是抽象事务，不能作居住的地方。"}, {"text": "他穿上了军事。", "explanation": "这里指衣服，应该用〈军装〉。“军事”是事务，不能穿在身上。"}, {"text": "他擦亮了军事。", "explanation": "这里指具体的武器，应该用〈枪〉。“军事”是抽象事务，不能被擦亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在军事问题很关心。", "corrected_sentence": "他对军事问题很关心。", "error_description": "“关心”的对象用“对”引出，应说“对军事问题很关心”；若用“在”，后面须加“……上”，此处缺“上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他研究一个军事。", "corrected_sentence": "他研究军事。", "error_description": "“军事”是不可数的抽象名词，不能用量词“个”计数，应删去“一个”，说“他研究军事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35726a13-f82e-4a20-8211-11cdd2ec28a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
