INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86985, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "下地是从家里走到田里去，在田里做活。", "primary_collocate": null, "pronunciation": "xià dì", "ipa": "ɕja˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "爷爷每天早上五点就下地了。", "target_word": "下地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，农民都要下地种田。", "target_word": "下地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃完饭，拿着锄头下地去了。", "target_word": "下地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天还没亮，奶奶就下地了。", "target_word": "下地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天雨很大，大家都不下地。", "target_word": "下地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸下地以前，先喝了一碗粥。", "target_word": "下地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说她下午要下地拔草。", "target_word": "下地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人都下地收麦子了。", "target_word": "下地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你家今天下地吗？", "target_word": "下地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他下地回来，身上全是土。", "target_word": "下地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "下了地", "label": "体标"}, {"form": "下过地", "label": "体标"}], "register": "口语", "sense_fingerprint": "农民从家出发去田里并在田里干活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c70db0a-f54e-4bc4-8d58-add9704b2190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86985, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "下地", "is_correct": true, "explanation": "正确答案：下地（xià dì），指到田里去干活。"}, {"text": "夏季", "is_correct": false, "explanation": "xià jì 与 xià dì 声母不同（j/d），声调相同，意思是夏天。"}, {"text": "下级", "is_correct": false, "explanation": "xià jí 与 xià dì 声母不同（j/d）且第二音节声调不同（二声/四声），意思是下一级。"}, {"text": "下底", "is_correct": false, "explanation": "xià dǐ 与 xià dì 第二音节声调不同（三声/四声），意思是梯形的下底。"}], "explanations": {"下地": "正确答案：下地（xià dì），指到田里去干活。", "夏季": "xià jì 与 xià dì 声母不同（j/d），声调相同，意思是夏天。", "下级": "xià jí 与 xià dì 声母不同（j/d）且第二音节声调不同（二声/四声），意思是下一级。", "下底": "xià dǐ 与 xià dì 第二音节声调不同（三声/四声），意思是梯形的下底。"}, "sentence_index": null, "correct_answer": "下地"}, "level_3": {"options": [{"text": "下地", "is_correct": true, "explanation": "正确：指到田里干活，符合爷爷早上出门干活的语境。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”是一次性的事，不能说“每天早上五点就毕业了”。"}, {"text": "上学", "is_correct": false, "explanation": "搭配：“上学”多指学生去学校，不能用来说爷爷的日常。"}, {"text": "出差", "is_correct": false, "explanation": "语义：“出差”指因公外出，与爷爷每天早上的日常不符。"}], "explanations": {"下地": "正确：指到田里干活，符合爷爷早上出门干活的语境。", "毕业": "语义：“毕业”是一次性的事，不能说“每天早上五点就毕业了”。", "上学": "搭配：“上学”多指学生去学校，不能用来说爷爷的日常。", "出差": "语义：“出差”指因公外出，与爷爷每天早上的日常不符。"}, "sentence_index": 0, "correct_answer": "下地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妹妹下地打了一场篮球。", "explanation": "这里不该用〈下地〉。下地只指到田里干农活，不能用来表示在球场上打篮球。"}, {"text": "天还没亮，奶奶就下地去上班了。", "explanation": "下地只指到田里干农活，这里说的是去单位工作，这种意思不能用“下地”表示。"}, {"text": "奶奶下地去银行取钱了。", "explanation": "下地只指到田里干农活，不能用来表示去银行办事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86985, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下地", "is_correct": true, "explanation": "正确：指到田里干活，与“下午要……拔草”的语境相符。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：“下棋”是娱乐活动，与“拔草”这种农活不符。"}, {"text": "出国", "is_correct": false, "explanation": "搭配：“出国”指到国外去，与“拔草”的地点和活动不搭配。"}, {"text": "上课", "is_correct": false, "explanation": "语义：“上课”指在教室学习，与“拔草”的农活不符。"}], "explanations": {"下地": "正确：指到田里干活，与“下午要……拔草”的语境相符。", "下棋": "语义：“下棋”是娱乐活动，与“拔草”这种农活不符。", "出国": "搭配：“出国”指到国外去，与“拔草”的地点和活动不搭配。", "上课": "语义：“上课”指在教室学习，与“拔草”的农活不符。"}, "sentence_index": 6, "correct_answer": "下地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他下地去学校上课了。", "explanation": "下地只指到田里干农活，不能用来表示去学校上课这类去向。"}, {"text": "我们下地去逛街吧。", "explanation": "下地只指到田里干农活，不能用来表示逛街这类在城里进行的活动。"}, {"text": "他下地去医院看病了。", "explanation": "下地只指到田里干农活，不能用来表示去医院看病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86985, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷每天早上五点就下地着。", "corrected_sentence": "爷爷每天早上五点就下地了。", "error_description": "错误：“下地”表示去田里干活这一动作已经开始，句末不能用表示持续状态的“着”。正确：应用“了”，说“就下地了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86985, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈说她明天下地了就去拔草。", "corrected_sentence": "妈妈说她明天下了地就去拔草。", "error_description": "错误：“了”放在离合词“下地”之后，写成“下地了”。正确：“下了地”，“了”应插在“下”和“地”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
