INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86986, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到田里去干农活。", "primary_collocate": null, "pronunciation": "xià dì", "ipa": "ɕja˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "秋天，农民们忙着下地收玉米。", "target_word": "下地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我常跟爸爸下地干活儿。", "target_word": "下地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他十岁就能下地帮忙了。", "target_word": "下地", "complexity_tier": "T3", "furigana": "tā shí suì jiù néng xià dì bāng máng le.", "sentence_source": "generated"}, {"text": "我们明天一起下地浇水吧。", "target_word": "下地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民们中午不下地，在家休息。", "target_word": "下地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年纪大了，不能再下地了。", "target_word": "下地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全家人都下地帮忙割稻子。", "target_word": "下地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他下地干了一上午活，累坏了。", "target_word": "下地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天下地的人很多。", "target_word": "下地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈带着孩子下地摘菜。", "target_word": "下地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "下了地", "label": "体标"}, {"form": "下过地", "label": "体标"}], "register": "口语", "sense_fingerprint": "到田里去干农活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c70db0a-f54e-4bc4-8d58-add9704b2190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
