INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86986, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下地", "is_correct": true, "explanation": "正确：到田里去帮忙割稻子，符合“全家人都……帮忙割稻子”的语境。"}, {"text": "上学", "is_correct": false, "explanation": "语义：“上学”指去学校读书，与割稻子的劳动不符。"}, {"text": "去医院", "is_correct": false, "explanation": "语义：“去医院”指看病，与全家人一起割稻子的语境不符。"}, {"text": "出差", "is_correct": false, "explanation": "搭配：“出差”是因公外出，全家人不会一起出差，与“帮忙割稻子”不搭配。"}], "explanations": {"下地": "正确：到田里去帮忙割稻子，符合“全家人都……帮忙割稻子”的语境。", "上学": "语义：“上学”指去学校读书，与割稻子的劳动不符。", "去医院": "语义：“去医院”指看病，与全家人一起割稻子的语境不符。", "出差": "搭配：“出差”是因公外出，全家人不会一起出差，与“帮忙割稻子”不搭配。"}, "sentence_index": 6, "correct_answer": "下地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大学毕业后，他主动下地去山区支教。", "explanation": "这里应该用〈下乡〉。在此义项中，下地只指到田里干农活，去山区支教应说下乡，不能说下地。"}, {"text": "他坐飞机下地去北京开会了。", "explanation": "这里不该用〈下地〉。在此义项中，下地只指到田里干农活，坐飞机去开会与农活无关。"}, {"text": "孩子下地去参加了音乐会。", "explanation": "这里不该用〈下地〉。在此义项中，下地只指到田里干农活，去音乐会这类活动与农活无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86986, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民们每天忙着下地了干活。", "corrected_sentence": "农民们每天忙着下地干活。", "error_description": "错误：离合词“下地”后面不能直接加“了”，写成“下地了干活”是错的，“了”应插在“下”和“地”之间。正确：“忙着下地干活”，“忙着”已表示动作正在进行，句中不需要“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86986, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "全家人都下地了插秧。", "corrected_sentence": "全家人都下了地插秧。", "error_description": "错误：“了”放在离合词“下地”之后，写成“下地了插秧”。正确：“下了地插秧”，“了”应插在“下”和“地”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
