INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86987, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "选是从很多个里面拿出自己想要的。", "primary_collocate": null, "pronunciation": "xuǎn", "ipa": "ɕɥɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "我想选一件红色的衣服。", "target_word": "选", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菜单上有很多菜，你先选吧。", "target_word": "选", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈让我在两本书里选一本。", "target_word": "选", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你选哪个颜色？", "target_word": "选", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他选了一条最短的路。", "target_word": "选", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么多水果，我选了苹果。", "target_word": "选", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们正在选自己喜欢的玩具。", "target_word": "选", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你选一个座位。", "target_word": "选", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我选过这门课，很有意思。", "target_word": "选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把喜欢的鞋选出来了。", "target_word": "选", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "选了", "label": "体标"}, {"form": "选过", "label": "体标"}], "register": "口语", "sense_fingerprint": "从很多个里面拿出自己想要的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10a82993-50d4-4381-a959-52d6505f63fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86987, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "选", "is_correct": true, "explanation": "正确。选 xuǎn，意思是从很多个里挑出自己想要的。"}, {"text": "显", "is_correct": false, "explanation": "显 xiǎn 与 选 xuǎn 韵母不同（ian 与 uan），意思是显示、明显。"}, {"text": "宣", "is_correct": false, "explanation": "宣 xuān 与 选 xuǎn 声调不同（第一声与第三声），意思是宣布、宣传。"}, {"text": "玄", "is_correct": false, "explanation": "玄 xuán 与 选 xuǎn 声调不同（第二声与第三声），意思是神秘。"}, {"text": "炫", "is_correct": false, "explanation": "炫 xuàn 与 选 xuǎn 声调不同（第四声与第三声），意思是炫耀。"}], "explanations": {"选": "正确。选 xuǎn，意思是从很多个里挑出自己想要的。", "显": "显 xiǎn 与 选 xuǎn 韵母不同（ian 与 uan），意思是显示、明显。", "宣": "宣 xuān 与 选 xuǎn 声调不同（第一声与第三声），意思是宣布、宣传。", "玄": "玄 xuán 与 选 xuǎn 声调不同（第二声与第三声），意思是神秘。", "炫": "炫 xuàn 与 选 xuǎn 声调不同（第四声与第三声），意思是炫耀。"}, "sentence_index": null, "correct_answer": "选"}, "level_3": {"options": [{"text": "选", "is_correct": true, "explanation": "正确。选是从几件衣服里挑出想要的一件，能接“想……一件衣服”。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语应是食物，不能说吃一件衣服。"}, {"text": "喝", "is_correct": false, "explanation": "配价：“喝”的宾语应是饮料，不能说喝一件衣服。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”用于文字，不能说写一件红色的衣服。"}], "explanations": {"选": "正确。选是从几件衣服里挑出想要的一件，能接“想……一件衣服”。", "吃": "配价：“吃”的宾语应是食物，不能说吃一件衣服。", "喝": "配价：“喝”的宾语应是饮料，不能说喝一件衣服。", "写": "搭配：“写”用于文字，不能说写一件红色的衣服。"}, "sentence_index": 0, "correct_answer": "选"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我选了丢在地铁上的手机。", "explanation": "这里应该用〈找〉。选是从多个里挑出想要的，丢了的东西要用“找”，不能说“选”。"}, {"text": "他总选我的毛病。", "explanation": "这里应该用〈挑〉。挑毛病是找出不足，选是从现成的东西里拿出想要的，不能说“选毛病”。"}, {"text": "我选了明天比赛的结果。", "explanation": "这里应该用〈预测〉。选是从现成的东西里挑出一样，比赛结果还没出来，只能预测或猜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86987, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "选", "is_correct": true, "explanation": "正确。选 xuǎn，意思是从很多个里挑出自己想要的。"}, {"text": "险", "is_correct": false, "explanation": "险 xiǎn 与 选 xuǎn 韵母不同（ian 与 uan），意思是危险。"}, {"text": "喧", "is_correct": false, "explanation": "喧 xuān 与 选 xuǎn 声调不同（第一声与第三声），意思是喧闹。"}, {"text": "悬", "is_correct": false, "explanation": "悬 xuán 与 选 xuǎn 声调不同（第二声与第三声），意思是悬挂。"}, {"text": "眩", "is_correct": false, "explanation": "眩 xuàn 与 选 xuǎn 声调不同（第四声与第三声），意思是眩晕。"}], "explanations": {"选": "正确。选 xuǎn，意思是从很多个里挑出自己想要的。", "险": "险 xiǎn 与 选 xuǎn 韵母不同（ian 与 uan），意思是危险。", "喧": "喧 xuān 与 选 xuǎn 声调不同（第一声与第三声），意思是喧闹。", "悬": "悬 xuán 与 选 xuǎn 声调不同（第二声与第三声），意思是悬挂。", "眩": "眩 xuàn 与 选 xuǎn 声调不同（第四声与第三声），意思是眩晕。"}, "sentence_index": null, "correct_answer": "选"}, "level_3": {"options": [{"text": "选", "is_correct": true, "explanation": "正确。选是从很多玩具里挑出自己喜欢的，能接“自己喜欢的玩具”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌，不能说唱玩具。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣物，不能说穿玩具。"}, {"text": "喂", "is_correct": false, "explanation": "配价：“喂”的对象应是人或动物，玩具不能被喂。"}], "explanations": {"选": "正确。选是从很多玩具里挑出自己喜欢的，能接“自己喜欢的玩具”。", "唱": "搭配：“唱”的对象是歌，不能说唱玩具。", "穿": "搭配：“穿”用于衣物，不能说穿玩具。", "喂": "配价：“喂”的对象应是人或动物，玩具不能被喂。"}, "sentence_index": 6, "correct_answer": "选"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我选了我的出生地。", "explanation": "这里的“选”被当成〈确定〉来用；出生地是既定的，没有可挑的余地，应说“我的出生地是……”。"}, {"text": "我选了我的身高。", "explanation": "这里的“选”被当成〈量〉来用；身高要用“量”来测，不能从几个选项中挑出。"}, {"text": "我选了一个好梦。", "explanation": "这里应该用〈做〉。梦不能从很多个里挑出来，要说“做了一个好梦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86987, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想选了一件蓝色的毛衣。", "corrected_sentence": "我想选一件蓝色的毛衣。", "error_description": "错误在于“选”后面多了“了”。“想”表示还没有发生的打算，不能与表示完成的“了”同用；应说“我想选一件蓝色的毛衣”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86987, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把好看的外套出选来了。", "corrected_sentence": "妈妈把好看的外套选出来了。", "error_description": "错误在于结果补语语序：“选出来”中的“选”与“出来”不能拆开，“出”被放到了“选”前面；应说“选出来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
