INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86990, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用棉、麻、丝等纤维织成的材料，可用来制作衣物、被褥等。", "primary_collocate": null, "pronunciation": "bù", "ipa": "pu˥˩", "syllable_count": 1, "sentences": [{"text": "商店里有很多好看的布。", "target_word": "布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种布摸起来很舒服。", "target_word": "布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天我喜欢穿用布做的衣服。", "target_word": "布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从箱子里拿出一块旧布。", "target_word": "布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布洗过以后变小了。", "target_word": "布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块蓝布是用棉线织成的。", "target_word": "布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们带一块布来上课。", "target_word": "布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种布很结实，可以做书包。", "target_word": "布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用一块干净的布擦眼镜。", "target_word": "布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那匹布很长，有二十米。", "target_word": "布", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "匹", "label": "量词"}, {"form": "布鞋", "label": "复合词"}, {"form": "布袋", "label": "复合词"}], "register": "中性", "sense_fingerprint": "布：用棉、麻、丝等纤维织成的材料，制作衣物被褥", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98bb113-2be5-474e-b481-0147080f3c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86990, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "布", "is_correct": true, "explanation": "布是用棉、麻、丝等纤维织成的材料，可制作衣物、被褥等。"}, {"text": "补", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）声调不同，意思是补充、修补。"}, {"text": "捕", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）声调不同，意思是捕捉。"}, {"text": "铺", "is_correct": false, "explanation": "pù（第四声）与 bù 声母不同（p 送气，b 不送气），意思是店铺。"}, {"text": "木", "is_correct": false, "explanation": "mù（第四声）与 bù 声母不同（m 与 b），意思是树木。"}], "explanations": {"布": "布是用棉、麻、丝等纤维织成的材料，可制作衣物、被褥等。", "补": "bǔ（第三声）与 bù（第四声）声调不同，意思是补充、修补。", "捕": "bǔ（第三声）与 bù（第四声）声调不同，意思是捕捉。", "铺": "pù（第四声）与 bù 声母不同（p 送气，b 不送气），意思是店铺。", "木": "mù（第四声）与 bù 声母不同（m 与 b），意思是树木。"}, "sentence_index": null, "correct_answer": "布"}, "level_3": {"options": [{"text": "布", "is_correct": true, "explanation": "布指织成的布料，“商店里有很多好看的布”说得通。"}, {"text": "老人", "is_correct": false, "explanation": "语义：老人是人，不会成为商店里待售的东西，与“商店里”的语境不符。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然景物，不会出现在商店里，与语境不符。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“好看”形容外观，不与“味道”搭配，“好看的味道”说不通。"}], "explanations": {"布": "布指织成的布料，“商店里有很多好看的布”说得通。", "老人": "语义：老人是人，不会成为商店里待售的东西，与“商店里”的语境不符。", "河流": "语义：河流是自然景物，不会出现在商店里，与语境不符。", "味道": "搭配：“好看”形容外观，不与“味道”搭配，“好看的味道”说不通。"}, "sentence_index": 0, "correct_answer": "布"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的布很细嫩。", "explanation": "这里应该用〈皮肤〉。“细嫩”用于形容皮肤，布是织成的材料，不能用来形容人。"}, {"text": "他每天弹布练习一个小时。", "explanation": "这里应该用〈钢琴〉。布是织物，不能用“弹”来演奏，弹的对象应是钢琴等乐器。"}, {"text": "我每天早上吃一块布当早饭。", "explanation": "这里应该用〈面包〉。布是织物，不能吃，早饭应吃面包等食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c31f9a31-de21-4b9e-b3f4-0442fdf8b505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86990, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "布", "is_correct": true, "explanation": "布是用棉、麻、丝等纤维织成的材料，可制作衣物、被褥等。"}, {"text": "幕", "is_correct": false, "explanation": "mù（第四声）与 bù 声母不同（m 与 b），意思是帷幕、幕布。"}, {"text": "墓", "is_correct": false, "explanation": "mù（第四声）与 bù 声母不同（m 与 b），意思是坟墓。"}, {"text": "度", "is_correct": false, "explanation": "dù（第四声）与 bù 声母不同（d 与 b），意思是程度、度量。"}, {"text": "肚", "is_correct": false, "explanation": "dù（第四声）与 bù 声母不同（d 与 b），意思是肚子。"}], "explanations": {"布": "布是用棉、麻、丝等纤维织成的材料，可制作衣物、被褥等。", "幕": "mù（第四声）与 bù 声母不同（m 与 b），意思是帷幕、幕布。", "墓": "mù（第四声）与 bù 声母不同（m 与 b），意思是坟墓。", "度": "dù（第四声）与 bù 声母不同（d 与 b），意思是程度、度量。", "肚": "dù（第四声）与 bù 声母不同（d 与 b），意思是肚子。"}, "sentence_index": null, "correct_answer": "布"}, "level_3": {"options": [{"text": "布", "is_correct": true, "explanation": "布指织成的布料，“老师让我们带一块布来上课”说得通。"}, {"text": "地", "is_correct": false, "explanation": "配价：“带”要求可以随身携带的东西，土地不能带进教室。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空无法被带进教室，“带一块天空”说不通。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳无法被带进教室，“带一块太阳”与语境不符。"}], "explanations": {"布": "布指织成的布料，“老师让我们带一块布来上课”说得通。", "地": "配价：“带”要求可以随身携带的东西，土地不能带进教室。", "天空": "语义：天空无法被带进教室，“带一块天空”说不通。", "太阳": "语义：太阳无法被带进教室，“带一块太阳”与语境不符。"}, "sentence_index": 6, "correct_answer": "布"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她织毛衣用了很多布。", "explanation": "这里应该用〈毛线〉。织毛衣要用毛线，布不能用来织毛衣。"}, {"text": "妈妈每天烤布，孩子们都很爱吃。", "explanation": "这里应该用〈饼干〉。布是织物，不能用“烤”来做食品，烤的对象应是饼干等食物。"}, {"text": "他用一块布把扣子缝好了。", "explanation": "这里应该用〈线〉。缝扣子要用线，布不能代替线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c31f9a31-de21-4b9e-b3f4-0442fdf8b505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86990, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她买了一个布做窗帘。", "corrected_sentence": "她买了一匹布做窗帘。", "error_description": "错误在量词：布料应用“匹”（或“块”）计量，不用“个”。错误形式是“一个布”，正确形式是“一匹布”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c31f9a31-de21-4b9e-b3f4-0442fdf8b505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86990, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想买一把布。", "corrected_sentence": "我想买一块布。", "error_description": "错误在量词：“把”用于有柄的器具，布应用“块”或“匹”计量。错误形式是“一把布”，正确形式是“一块布”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c31f9a31-de21-4b9e-b3f4-0442fdf8b505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
