INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86991, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国家队是从全国挑出来的最厉害的运动员组成的队。", "primary_collocate": null, "pronunciation": "guó jiā duì", "ipa": "kuo˧˥ tɕja˥ twei˥˩", "syllable_count": 3, "sentences": [{"text": "他跑得很快，被选进了国家队。", "target_word": "国家队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家队的运动员每天都要训练。", "target_word": "国家队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥想成为国家队的游泳运动员。", "target_word": "国家队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她十六岁就进了国家队。", "target_word": "国家队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家队教练今天选出了新队员。", "target_word": "国家队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支国家队去年拿过世界冠军。", "target_word": "国家队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小的梦想就是加入国家队。", "target_word": "国家队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家队的比赛我们全家都爱看。", "target_word": "国家队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受伤了，不能再留在国家队。", "target_word": "国家队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家队的队员都来自全国各地。", "target_word": "国家队", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支", "label": "量词"}, {"form": "国家队员", "label": "复合"}, {"form": "國家隊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "国家队：从全国选出最厉害的运动员组成的队", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e95692-f9f1-4226-adcd-b55c18dffb26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86991, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乐团", "is_correct": false, "explanation": "语义：句中“跑得很快”说的是体育运动，与乐团不符。"}, {"text": "国家队", "is_correct": true, "explanation": "正确：国家队是从全国挑出的最厉害运动员组成的队，“跑得很快，被选进了”与之相合。"}, {"text": "冰箱", "is_correct": false, "explanation": "配价：“被选进”要求受选入的是人或团体，冰箱不能充当。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“被选进厨房”不成搭配，人不会被选进厨房。"}], "explanations": {"乐团": "语义：句中“跑得很快”说的是体育运动，与乐团不符。", "国家队": "正确：国家队是从全国挑出的最厉害运动员组成的队，“跑得很快，被选进了”与之相合。", "冰箱": "配价：“被选进”要求受选入的是人或团体，冰箱不能充当。", "厨房": "搭配：“被选进厨房”不成搭配，人不会被选进厨房。"}, "sentence_index": 0, "correct_answer": "国家队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在学校的国家队里踢球。", "explanation": "这里应该用〈球队〉。国家队指从全国挑出的队，学校的队只能说球队。"}, {"text": "这个城市的国家队只参加本市的比赛。", "explanation": "这里应该用〈市队〉。国家队是从全国挑出的队，只代表一个城市、只参加本市比赛的队应说市队。"}, {"text": "他是我们社区的国家队队长。", "explanation": "这里应该用〈社区队〉。国家队是从全国挑出的队，社区自己的队应说社区队。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86991, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "森林", "is_correct": false, "explanation": "语义：“加入”要求受加入的是团体或组织，森林不是可以加入的团体。"}, {"text": "蛋糕", "is_correct": false, "explanation": "配价：“加入”的宾语应是组织或团队，“蛋糕”不能充当。"}, {"text": "国家队", "is_correct": true, "explanation": "正确：国家队指代表全国的运动队，“梦想就是加入”与之相合。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“加入书包”不成搭配，书包不是可以加入的团队。"}], "explanations": {"森林": "语义：“加入”要求受加入的是团体或组织，森林不是可以加入的团体。", "蛋糕": "配价：“加入”的宾语应是组织或团队，“蛋糕”不能充当。", "国家队": "正确：国家队指代表全国的运动队，“梦想就是加入”与之相合。", "书包": "搭配：“加入书包”不成搭配，书包不是可以加入的团队。"}, "sentence_index": 6, "correct_answer": "国家队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的国家队队员都是十岁的孩子。", "explanation": "这里应该用〈少年队〉。国家队是全国选拔的优秀运动员组成的，十岁孩子的队应说少年队。"}, {"text": "我们班的国家队每周训练两次。", "explanation": "这里应该用〈班队〉。国家队指从全国挑出的队，班里的队应说班队。"}, {"text": "这所学校的国家队每天放学后训练。", "explanation": "这里应该用〈校队〉。国家队代表全国，学校的队应说校队。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86991, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只国家队今年在比赛中获得了金牌。", "corrected_sentence": "那支国家队今年在比赛中获得了金牌。", "error_description": "量词错误：“国家队”是队，量词用“支”，不用“只”。应说“那支国家队”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86991, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两支国家队们都来到了我们城市。", "corrected_sentence": "两支国家队都来到了我们城市。", "error_description": "词缀错误：“国家队”是集体名词，后面不能加“们”。应说“两支国家队”，不说“国家队们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86993, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "免", "is_correct": true, "explanation": "正确答案：“任”（委任职务）与“免”（免去职务）意义相反，构成“任免”。"}, {"text": "写", "is_correct": false, "explanation": "“写”是书写，与“任”没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”是移动，与“任”没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "“吃”是进食，与“任”没有反义关系。"}], "correct_answer": "免", "explanations": {"免": "正确答案：“任”（委任职务）与“免”（免去职务）意义相反，构成“任免”。", "写": "“写”是书写，与“任”没有反义关系。", "跑": "“跑”是移动，与“任”没有反义关系。", "吃": "“吃”是进食，与“任”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86993, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "免", "is_correct": true, "explanation": "正确答案：“任”（委任职务）与“免”（免去职务）意义相反，构成“任免”。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”是歌唱，与“任”没有反义关系。"}, {"text": "走", "is_correct": false, "explanation": "“走”是行走，与“任”没有反义关系。"}, {"text": "看", "is_correct": false, "explanation": "“看”是观看，与“任”没有反义关系。"}], "correct_answer": "免", "explanations": {"免": "正确答案：“任”（委任职务）与“免”（免去职务）意义相反，构成“任免”。", "唱": "“唱”是歌唱，与“任”没有反义关系。", "走": "“走”是行走，与“任”没有反义关系。", "看": "“看”是观看，与“任”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86993, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "任用某人担当某个职务。", "primary_collocate": null, "pronunciation": "rèn", "ipa": "ʐən˥˩", "syllable_count": 1, "sentences": [{"text": "公司任他为销售经理。", "target_word": "任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校任李老师为班主任。", "target_word": "任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板任小王做新店的店长。", "target_word": "任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国王任他为大臣。", "target_word": "任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市长任他为新的秘书。", "target_word": "任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司去年任她为部门主管。", "target_word": "任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院任王医生为新院长。", "target_word": "任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师任我做班长，我很高兴。", "target_word": "任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球队任他为队长。", "target_word": "任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总统任这位将军为国防部长。", "target_word": "任", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "任用某人担当职务：任某人为／做某职", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdba5b8c-a597-4c90-bcad-019807f38244') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86993, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "任", "is_correct": true, "explanation": "正确答案：“任”（rèn）是委派某人担任职务的意思。"}, {"text": "人", "is_correct": false, "explanation": "声调与 rèn 不同（rén，第二声），意思是人。"}, {"text": "忍", "is_correct": false, "explanation": "声调与 rèn 不同（rěn，第三声），意思是忍受。"}, {"text": "扔", "is_correct": false, "explanation": "韵母 ēng 与 èn 不同且声调不同（rēng，第一声），意思是丢掉。"}, {"text": "闰", "is_correct": false, "explanation": "韵母 ùn 与 èn 不同（rùn，第四声），意思是闰月。"}], "explanations": {"任": "正确答案：“任”（rèn）是委派某人担任职务的意思。", "人": "声调与 rèn 不同（rén，第二声），意思是人。", "忍": "声调与 rèn 不同（rěn，第三声），意思是忍受。", "扔": "韵母 ēng 与 èn 不同且声调不同（rēng，第一声），意思是丢掉。", "闰": "韵母 ùn 与 èn 不同（rùn，第四声），意思是闰月。"}, "sentence_index": null, "correct_answer": "任"}, "level_3": {"options": [{"text": "任", "is_correct": true, "explanation": "正确答案：“任”表示委任，“公司任他为销售经理”符合句意。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”是赠送或递送，不能表示任命职务。"}, {"text": "让", "is_correct": false, "explanation": "配价：“让”后要接动词性成分，“让他为销售经理”不成立，应说“让他当销售经理”。"}, {"text": "教", "is_correct": false, "explanation": "语义：“教”是教导的意思，不能表示任命他为经理。"}], "explanations": {"任": "正确答案：“任”表示委任，“公司任他为销售经理”符合句意。", "送": "语义：“送”是赠送或递送，不能表示任命职务。", "让": "配价：“让”后要接动词性成分，“让他为销售经理”不成立，应说“让他当销售经理”。", "教": "语义：“教”是教导的意思，不能表示任命他为经理。"}, "sentence_index": 0, "correct_answer": "任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班里任他为班长，大家都投了票。", "explanation": "“任”是上级委派职务，经投票产生的职务不能用“任”。这里应该用〈选〉。"}, {"text": "妈妈任我为好帮手，我很高兴。", "explanation": "这里应该用〈认〉。“任”是委派某人担任职务，“好帮手”不是职务，应说“认我为好帮手”。"}, {"text": "他任这把椅子三年了。", "explanation": "这里应该用〈坐〉。“任”用于职务，不能用于物品；“坐这把椅子”才是正确搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86993, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "任", "is_correct": true, "explanation": "正确答案：“任”表示委任，“医院任王医生为新院长”符合句意。"}, {"text": "赠", "is_correct": false, "explanation": "语义：“赠”是赠送，不能表示任命职务。"}, {"text": "扶", "is_correct": false, "explanation": "语义：“扶”是搀扶或支持，不能表示任命职务。"}, {"text": "叫", "is_correct": false, "explanation": "配价：“叫”后要接动词性成分，“叫王医生为新院长”不成立，应说“叫王医生当新院长”。"}], "explanations": {"任": "正确答案：“任”表示委任，“医院任王医生为新院长”符合句意。", "赠": "语义：“赠”是赠送，不能表示任命职务。", "扶": "语义：“扶”是搀扶或支持，不能表示任命职务。", "叫": "配价：“叫”后要接动词性成分，“叫王医生为新院长”不成立，应说“叫王医生当新院长”。"}, "sentence_index": 6, "correct_answer": "任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们投票，任她为班长。", "explanation": "“任”是上级委派职务，学生投票产生的职务不能用“任”。这里应该用〈选〉。"}, {"text": "我们任他为好朋友。", "explanation": "“任”是上级委派人担任职务，朋友关系不能用“任”；这里应该用〈认〉。"}, {"text": "他任这个问题三天了。", "explanation": "“任”用于职务，不能用于问题。这里应该用〈研究〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86993, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校了任张老师为年级组长，大家都很支持。", "corrected_sentence": "学校任张老师为年级组长，大家都很支持。", "error_description": "语序错误：“了”不能放在动词“任”的前面，应说“学校任张老师为年级组长”；若要用“了”，应放在“任”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86993, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社区任李阿姨志愿者队长，大家都很高兴。", "corrected_sentence": "社区任李阿姨为志愿者队长，大家都很高兴。", "error_description": "漏字错误：“任”后接人名再接职务时，中间需要“为”或“做”，此句漏掉了“为”，应说“任李阿姨为志愿者队长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86994, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "卸", "is_correct": true, "explanation": "正确答案：“卸”指卸去职务，与“担任”意思相反，即“卸任”。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”是歌唱，与“担任”没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”是移动，与“担任”没有反义关系。"}, {"text": "煮", "is_correct": false, "explanation": "“煮”是烹饪，与“担任”没有反义关系。"}], "correct_answer": "卸", "explanations": {"卸": "正确答案：“卸”指卸去职务，与“担任”意思相反，即“卸任”。", "唱": "“唱”是歌唱，与“担任”没有反义关系。", "跑": "“跑”是移动，与“担任”没有反义关系。", "煮": "“煮”是烹饪，与“担任”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
