INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86994, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "担任某项职务。", "primary_collocate": null, "pronunciation": "rèn", "ipa": "ʐən˥˩", "syllable_count": 1, "sentences": [{"text": "他任校长已经十年了。", "target_word": "任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她曾任市长，现在退休了。", "target_word": "任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他去年任公司的总经理。", "target_word": "任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "李先生任班主任三年了。", "target_word": "任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他任医院的院长，工作很忙。", "target_word": "任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她任学生会主席时很忙。", "target_word": "任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在村里任书记。", "target_word": "任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "张老师任我们的数学老师。", "target_word": "任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李任组长，大家都放心。", "target_word": "任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他任过两年校长。", "target_word": "任", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "任过", "label": "体标"}], "register": "书面", "sense_fingerprint": "自己担任某个职务：任＋职务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdba5b8c-a597-4c90-bcad-019807f38244') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86994, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "任", "is_correct": true, "explanation": "正确答案：“任”（rèn）是担任某项职务的意思。"}, {"text": "人", "is_correct": false, "explanation": "声调与 rèn 不同（rén，第二声），意思是人。"}, {"text": "忍", "is_correct": false, "explanation": "声调与 rèn 不同（rěn，第三声），意思是忍受。"}, {"text": "扔", "is_correct": false, "explanation": "韵母 ēng 与 èn 不同且声调不同（rēng，第一声），意思是丢掉。"}, {"text": "闰", "is_correct": false, "explanation": "韵母 ùn 与 èn 不同（rùn，第四声），意思是闰月。"}], "explanations": {"任": "正确答案：“任”（rèn）是担任某项职务的意思。", "人": "声调与 rèn 不同（rén，第二声），意思是人。", "忍": "声调与 rèn 不同（rěn，第三声），意思是忍受。", "扔": "韵母 ēng 与 èn 不同且声调不同（rēng，第一声），意思是丢掉。", "闰": "韵母 ùn 与 èn 不同（rùn，第四声），意思是闰月。"}, "sentence_index": null, "correct_answer": "任"}, "level_3": {"options": [{"text": "任", "is_correct": true, "explanation": "正确答案：“任”表示担任职务，“他任校长已经十年了”符合句意。"}, {"text": "辞", "is_correct": false, "explanation": "语义：“辞”是辞去职务，句子会变成“辞校长已经十年”，即已不在任，与“任校长已经十年”的在任含义不符。"}, {"text": "卸", "is_correct": false, "explanation": "语义：“卸”是卸下，不能表示担任校长。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”不能与“校长”搭配。"}], "explanations": {"任": "正确答案：“任”表示担任职务，“他任校长已经十年了”符合句意。", "辞": "语义：“辞”是辞去职务，句子会变成“辞校长已经十年”，即已不在任，与“任校长已经十年”的在任含义不符。", "卸": "语义：“卸”是卸下，不能表示担任校长。", "修": "搭配：“修”不能与“校长”搭配。"}, "sentence_index": 0, "correct_answer": "任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他任修车店三年了。", "explanation": "这里应该用〈经营〉。“任”用于职务，修车店是场所，不能说“任修车店”。"}, {"text": "他任过三年书店。", "explanation": "这里应该用〈开〉。“任”用于职务，书店是场所，不能说“任书店”。"}, {"text": "他任这辆车三年了。", "explanation": "这里应该用〈开〉。“任”后接职务，车是物品，不能说“任这辆车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86994, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "任", "is_correct": true, "explanation": "正确答案：“任”表示担任职务，“他在村里任书记”符合句意。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”是燃烧，不能表示担任书记。"}, {"text": "扛", "is_correct": false, "explanation": "搭配：“扛”通常与物体搭配，不能与“书记”搭配。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与担任职务的意思不符。"}], "explanations": {"任": "正确答案：“任”表示担任职务，“他在村里任书记”符合句意。", "烧": "语义：“烧”是燃烧，不能表示担任书记。", "扛": "搭配：“扛”通常与物体搭配，不能与“书记”搭配。", "扔": "语义：“扔”是丢弃，与担任职务的意思不符。"}, "sentence_index": 6, "correct_answer": "任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他任过三年学生。", "explanation": "“任”后接职务，“学生”是身份而不是职务，不能用“任”；这里应该用〈当〉。"}, {"text": "他任过两年的邻居。", "explanation": "“任”表示担任职务，“邻居”是身份而不是职务，不能用“任”；这里应该用〈做〉。"}, {"text": "他任过两年厨房。", "explanation": "这里应该用〈待〉。“任”用于职务，厨房是场所，不能说“任厨房”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她任过教务主任已经三年了。", "corrected_sentence": "她任教务主任已经三年了。", "error_description": "体标误用：“任过”表示经历，不能与“已经……了”表示的持续时间同用，应说“任”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
