INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86995, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "图版是书里专门印图画的那一页。", "primary_collocate": null, "pronunciation": "tú bǎn", "ipa": "tʰu³⁵ pan²¹⁴", "syllable_count": 2, "sentences": [{"text": "这本书的图版都很漂亮。", "target_word": "图版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请翻到第十页，那是一张图版。", "target_word": "图版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套书有二十页图版。", "target_word": "图版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图版上印着很多老照片。", "target_word": "图版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们看一下图版里的地图。", "target_word": "图版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图版放在书的最后面。", "target_word": "图版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本画册的图版印得很清楚。", "target_word": "图版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢书里的彩色图版。", "target_word": "图版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图版旁边有一行小字。", "target_word": "图版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把图版一页一页地看完了。", "target_word": "图版", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "彩色图版", "label": "复合"}], "register": "书面", "sense_fingerprint": "书中专门印图画的一页", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bb5dbd0-8999-44e2-b7a7-f670f6a1f680') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86995, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "图版", "is_correct": true, "explanation": "正确：图版指书里专门印图画的一页，读 tú bǎn。"}, {"text": "头版", "is_correct": false, "explanation": "tóu（头）与 tú（图）韵母不同（ou / u），意思是报纸的头一版。"}, {"text": "秃斑", "is_correct": false, "explanation": "秃斑（tū bān）与“图版”（tú bǎn）声母韵母相同，声调不同，意思是头上没有头发的斑块。"}, {"text": "图案", "is_correct": false, "explanation": "图案（tú àn）第二个音节没有声母 b，声调也不同，意思是装饰用的花纹。"}], "explanations": {"图版": "正确：图版指书里专门印图画的一页，读 tú bǎn。", "头版": "tóu（头）与 tú（图）韵母不同（ou / u），意思是报纸的头一版。", "秃斑": "秃斑（tū bān）与“图版”（tú bǎn）声母韵母相同，声调不同，意思是头上没有头发的斑块。", "图案": "图案（tú àn）第二个音节没有声母 b，声调也不同，意思是装饰用的花纹。"}, "sentence_index": null, "correct_answer": "图版"}, "level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：书里不会有厨房，「这本书的厨房」说不通。"}, {"text": "图版", "is_correct": true, "explanation": "正确：图版是书中的印刷页，「这本书的图版」说得通，「都很漂亮」也能描述它。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子是食物，不属于书，「这本书的饺子」说不通。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：「这本书的」后面要接书的组成部分，手套不是书的部分，这种所属关系不成立。"}], "explanations": {"厨房": "语义：书里不会有厨房，「这本书的厨房」说不通。", "图版": "正确：图版是书中的印刷页，「这本书的图版」说得通，「都很漂亮」也能描述它。", "饺子": "语义：饺子是食物，不属于书，「这本书的饺子」说不通。", "手套": "搭配：「这本书的」后面要接书的组成部分，手套不是书的部分，这种所属关系不成立。"}, "sentence_index": 0, "correct_answer": "图版"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在图版上画了一张设计图，画得很细。", "explanation": "这里应该用〈图板〉。图版指书刊中印好图画的一页，不能在上面画图；画图要用图板。"}, {"text": "他用图版画出了销售数据的变化。", "explanation": "这里应该用〈图表〉。图版指书页上印好的图画，不能用来画数据变化图；这类图要用图表。"}, {"text": "妈妈把图版垫在下面，切菜时用来当作案板。", "explanation": "这里应该用〈案板〉。图版是印有图画的书页，不能当切菜的案板，那样用是把它的用途用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86995, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "声音", "is_correct": false, "explanation": "语义：声音无法被印在纸上，「印得很清楚」只能用于文字或图像。"}, {"text": "图版", "is_correct": true, "explanation": "正确：图版是画册里印出的图片页，「印得很清楚」正好描述它。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：「印」不搭配「味道」，味道印不出来，「印得很清楚」不成立。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步是动作发出的声音，无法印在画册上。"}], "explanations": {"声音": "语义：声音无法被印在纸上，「印得很清楚」只能用于文字或图像。", "图版": "正确：图版是画册里印出的图片页，「印得很清楚」正好描述它。", "味道": "搭配：「印」不搭配「味道」，味道印不出来，「印得很清楚」不成立。", "脚步": "语义：脚步是动作发出的声音，无法印在画册上。"}, "sentence_index": 6, "correct_answer": "图版"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子在纸上把图版画得很可爱。", "explanation": "这里应该用〈图画〉。图版是印好的书页，不能用「画」来制作；能被画出来的是图画。"}, {"text": "他在书的最后找到一张图版，上面写满了文字。", "explanation": "这里应该用〈正文〉。图版是印图画的页面，满页都是文字时应说〈正文〉，不能叫图版。"}, {"text": "他在图版上写了一封信，寄给了朋友。", "explanation": "这里应该用〈信纸〉。图版是印好图画的书页，不能拿来写信，写信要用信纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86995, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他手里拿着一只图版，仔细地看。", "corrected_sentence": "他手里拿着一张图版，仔细地看。", "error_description": "量词错误：图版是书页，应该用〈张〉，不能用〈只〉。〈只〉用于动物或成对的物品。正确说法是「一张图版」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86995, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套画册里的那只图版印得很清楚。", "corrected_sentence": "这套画册里的那张图版印得很清楚。", "error_description": "量词错误：图版是书页，应该用〈张〉，不能用〈只〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
