INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86996, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "再会是和别人分开的时候说的话，意思是以后再见面。", "primary_collocate": null, "pronunciation": "zài huì", "ipa": "t͡saɪ˥˩ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他挥挥手说：“再会！”", "target_word": "再会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车要开了，我们说了再会。", "target_word": "再会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“再会，祝你一路平安！”", "target_word": "再会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老朋友笑着说再会。", "target_word": "再会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对大家说：“再会，我走了。”", "target_word": "再会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在车站，他们互相说再会。", "target_word": "再会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天先到这里，再会！", "target_word": "再会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“再会！”孩子们向老师挥手。", "target_word": "再会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说了再会，就转身走了。", "target_word": "再会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在门口说再会。", "target_word": "再会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "叹词，分别时的告别语，意思是以后再见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdba5b8c-a597-4c90-bcad-019807f38244') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86996, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "再会", "is_correct": true, "explanation": "正确答案：“再会”（zài huì）是分别时的告别语，意思是以后再见。"}, {"text": "再婚", "is_correct": false, "explanation": "“婚”（hūn，第一声）与 huì 韵母和声调都不同，意思是再次结婚。"}, {"text": "载货", "is_correct": false, "explanation": "第二个音节 huò 与 huì 韵母不同，意思是装载货物。"}, {"text": "再回", "is_correct": false, "explanation": "“回”（huí，第二声）与 huì（第四声）声调不同，意思是再次回来。"}], "explanations": {"再会": "正确答案：“再会”（zài huì）是分别时的告别语，意思是以后再见。", "再婚": "“婚”（hūn，第一声）与 huì 韵母和声调都不同，意思是再次结婚。", "载货": "第二个音节 huò 与 huì 韵母不同，意思是装载货物。", "再回": "“回”（huí，第二声）与 huì（第四声）声调不同，意思是再次回来。"}, "sentence_index": null, "correct_answer": "再会"}, "level_3": {"options": [{"text": "再会", "is_correct": true, "explanation": "正确答案：“再会”是挥手告别时的用语，与句中的“挥挥手”相合。"}, {"text": "哎哟", "is_correct": false, "explanation": "语义：“哎哟”表示疼痛或吃惊，与挥手告别的语境不符。"}, {"text": "咦", "is_correct": false, "explanation": "语义：“咦”表示疑惑或意外，不是告别时的用语。"}, {"text": "救命", "is_correct": false, "explanation": "语义：“救命”是呼救之语，与挥手告别的语境完全不符。"}], "explanations": {"再会": "正确答案：“再会”是挥手告别时的用语，与句中的“挥挥手”相合。", "哎哟": "语义：“哎哟”表示疼痛或吃惊，与挥手告别的语境不符。", "咦": "语义：“咦”表示疑惑或意外，不是告别时的用语。", "救命": "语义：“救命”是呼救之语，与挥手告别的语境完全不符。"}, "sentence_index": 0, "correct_answer": "再会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一进门就大声说：“再会！”", "explanation": "“再会”是分别时的告别语，进门时打招呼不能用。这里应该用〈你好〉。"}, {"text": "他问朋友明天要不要一起去看电影，朋友说：“再会。”", "explanation": "“再会”是告别语，表示答应邀请时不能用。这里应该用〈好啊〉。"}, {"text": "他不小心撞到人，连忙说：“再会。”", "explanation": "“再会”是告别语，用于道歉不合适。这里应该用〈对不起〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86996, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再会", "is_correct": true, "explanation": "正确答案：“再会”用于分别时，与“今天先到这里”的结束语境相合。"}, {"text": "哎呀", "is_correct": false, "explanation": "语义：“哎呀”表示意外或懊恼，与结束会议的语境不符。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”用于招呼或呼唤，不能表示结束时的告别。"}, {"text": "请问", "is_correct": false, "explanation": "语义：“请问”是开口询问时的招呼语，不能用来结束会面。"}], "explanations": {"再会": "正确答案：“再会”用于分别时，与“今天先到这里”的结束语境相合。", "哎呀": "语义：“哎呀”表示意外或懊恼，与结束会议的语境不符。", "喂": "语义：“喂”用于招呼或呼唤，不能表示结束时的告别。", "请问": "语义：“请问”是开口询问时的招呼语，不能用来结束会面。"}, "sentence_index": 6, "correct_answer": "再会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板问我同不同意，我连忙说：“再会。”", "explanation": "“再会”是告别语，不能用来表示答应。这里应该用〈好的〉。"}, {"text": "饭桌上，妈妈问我要不要再吃一碗，我说：“再会。”", "explanation": "“再会”是告别语，回答别人劝吃时不能用。这里应该用〈不要了〉。"}, {"text": "他忘了带钥匙，对门卫说：“再会。”", "explanation": "“再会”是告别语，请求别人帮忙时不能用。这里应该用〈请帮我开一下门〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86996, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "客人刚进门，他说了一声再会。", "corrected_sentence": "客人要走了，他说了一声再会。", "error_description": "“再会”是分别时的告别语，客人刚到时不能说；应改为在客人要走时说“再会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86996, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他向我们挥了挥手，说了一个再会。", "corrected_sentence": "他向我们挥了挥手，说了一声再会。", "error_description": "量词错误：告别语前的量词应为“一声”，说“说了一声再会”；“一个”不能用于告别语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
