INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86997, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "书刊中专门印刷图片的版面或页面。", "primary_collocate": null, "pronunciation": "tú bǎn", "ipa": "tʰu³⁵ pan²¹⁴", "syllable_count": 2, "sentences": [{"text": "这本杂志有八页彩色图版。", "target_word": "图版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编辑正在检查今天的图版。", "target_word": "图版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸的图版要用好纸来印。", "target_word": "图版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这期期刊的图版太少了。", "target_word": "图版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图版和文字要放在不同的页面上。", "target_word": "图版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷厂把图版印好了。", "target_word": "图版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个图版的颜色有点儿暗。", "target_word": "图版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂志社请他来设计图版。", "target_word": "图版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学术书刊常常需要很多图版。", "target_word": "图版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图版的位置不对，要重新排。", "target_word": "图版", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "彩色图版", "label": "复合"}], "register": "书面", "sense_fingerprint": "书刊里专门印刷图片的版面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bb5dbd0-8999-44e2-b7a7-f670f6a1f680') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86997, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "图版", "is_correct": true, "explanation": "正确：图版指书刊中专门印图片的版面，读 tú bǎn。"}, {"text": "头版", "is_correct": false, "explanation": "tóu（头）与 tú（图）韵母不同（ou / u），意思是报纸的头一版。"}, {"text": "秃斑", "is_correct": false, "explanation": "秃斑（tū bān）与“图版”（tú bǎn）声母韵母相同，声调不同，意思是头上没有头发的斑块。"}, {"text": "图案", "is_correct": false, "explanation": "图案（tú àn）第二个音节没有声母 b，声调也不同，意思是装饰用的花纹。"}], "explanations": {"图版": "正确：图版指书刊中专门印图片的版面，读 tú bǎn。", "头版": "tóu（头）与 tú（图）韵母不同（ou / u），意思是报纸的头一版。", "秃斑": "秃斑（tū bān）与“图版”（tú bǎn）声母韵母相同，声调不同，意思是头上没有头发的斑块。", "图案": "图案（tú àn）第二个音节没有声母 b，声调也不同，意思是装饰用的花纹。"}, "sentence_index": null, "correct_answer": "图版"}, "level_3": {"options": [{"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘挂在窗户上，不是印刷品，杂志里不会有「八页彩色窗帘」。"}, {"text": "图版", "is_correct": true, "explanation": "正确：图版指书刊中印图片的版面，「八页彩色」正好用来计量它。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是印刷品，「这本杂志有八页彩色手机」说不通。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：「页」用来计量纸张，墨水不能用「八页」来数。"}], "explanations": {"窗帘": "语义：窗帘挂在窗户上，不是印刷品，杂志里不会有「八页彩色窗帘」。", "图版": "正确：图版指书刊中印图片的版面，「八页彩色」正好用来计量它。", "手机": "语义：手机不是印刷品，「这本杂志有八页彩色手机」说不通。", "墨水": "搭配：「页」用来计量纸张，墨水不能用「八页」来数。"}, "sentence_index": 0, "correct_answer": "图版"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块布的图版很漂亮。", "explanation": "这里应该用〈图案〉。图版指书刊中印图片的版面，不用来说布料上的花纹。"}, {"text": "他每天晚上读一章图版，已经读到第十章了。", "explanation": "这里应该用〈小说〉。图版是印图片的版面，不是分章阅读的文字作品。"}, {"text": "妈妈把图版挂在墙上，每天撕掉一页看日期。", "explanation": "这里应该用〈挂历〉。图版是印图片的书页，不用来看日期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86997, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：价格不是有颜色的东西，「这个价格的颜色」说不通。"}, {"text": "图版", "is_correct": true, "explanation": "正确：图版是印有图片的版面，「这个图版的颜色」指它的印刷颜色，说得通。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度没有颜色，「这个温度的颜色」说不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「颜色」能修饰可见的物体，「体重」没有颜色，二者不搭配。"}], "explanations": {"价格": "语义：价格不是有颜色的东西，「这个价格的颜色」说不通。", "图版": "正确：图版是印有图片的版面，「这个图版的颜色」指它的印刷颜色，说得通。", "温度": "语义：温度没有颜色，「这个温度的颜色」说不通。", "体重": "搭配：「颜色」能修饰可见的物体，「体重」没有颜色，二者不搭配。"}, "sentence_index": 6, "correct_answer": "图版"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书出了三种图版，内容各不相同。", "explanation": "这里应该用〈版本〉。图版指印图画的版面，不是指同一本书的不同版次。"}, {"text": "这台电视的图版坏了，要换一个新的屏幕。", "explanation": "这里应该用〈屏幕〉。图版指书刊中印图片的版面，不指电视的显示部分，这样用是把它的意义用错了。"}, {"text": "他在图版上算账，把账目一笔一笔记下来。", "explanation": "这里应该用〈账本〉。图版是印图画的书页，不能用来记账。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86997, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "编辑把那只图版退回去了。", "corrected_sentence": "编辑把那张图版退回去了。", "error_description": "量词错误：图版是书页，应该用〈张〉，不能用〈只〉。正确说法是「那张图版」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86997, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只图版的颜色有点儿暗，要重新印。", "corrected_sentence": "这张图版的颜色有点儿暗，要重新印。", "error_description": "量词错误：图版是书页，应该用〈张〉，不能用〈只〉。正确说法是「这张图版」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
