INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86998, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "告别时说的话，表示希望日后再见面。", "primary_collocate": null, "pronunciation": "zài huì", "ipa": "t͡saɪ˥˩ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "“再会，希望明年再见！”", "target_word": "再会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向我们鞠躬说：“再会。”", "target_word": "再会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临走前，她轻轻说了一声再会。", "target_word": "再会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们站在门口，说着再会。", "target_word": "再会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业那天，大家哭着说再会。", "target_word": "再会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信的最后，他写道：“再会，保重。”", "target_word": "再会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“再会！”她在雨中大声喊。", "target_word": "再会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人对客人说：“再会，路上小心。”", "target_word": "再会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们笑着说再会，约好下个月见。", "target_word": "再会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "再会，我的朋友，后会有期。", "target_word": "再会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "叹词，告别时说的话，希望日后再见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdba5b8c-a597-4c90-bcad-019807f38244') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86998, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "再会", "is_correct": true, "explanation": "正确答案：“再会”（zài huì）是告别时说的话，希望日后再见。"}, {"text": "再婚", "is_correct": false, "explanation": "“婚”（hūn，第一声）与 huì 韵母和声调都不同，意思是再次结婚。"}, {"text": "载货", "is_correct": false, "explanation": "第二个音节 huò 与 huì 韵母不同，意思是装载货物。"}, {"text": "再回", "is_correct": false, "explanation": "“回”（huí，第二声）与 huì（第四声）声调不同，意思是再次回来。"}], "explanations": {"再会": "正确答案：“再会”（zài huì）是告别时说的话，希望日后再见。", "再婚": "“婚”（hūn，第一声）与 huì 韵母和声调都不同，意思是再次结婚。", "载货": "第二个音节 huò 与 huì 韵母不同，意思是装载货物。", "再回": "“回”（huí，第二声）与 huì（第四声）声调不同，意思是再次回来。"}, "sentence_index": null, "correct_answer": "再会"}, "level_3": {"options": [{"text": "再会", "is_correct": true, "explanation": "正确答案：“再会”表示希望日后再见，与“希望明年再见”相合。"}, {"text": "哎哟", "is_correct": false, "explanation": "语义：“哎哟”表示疼痛，与希望日后相见的语境不符。"}, {"text": "咦", "is_correct": false, "explanation": "语义：“咦”表示疑惑，不能用于表达告别的心愿。"}, {"text": "救命", "is_correct": false, "explanation": "语义：“救命”是呼救之语，与希望日后再见的告别语境完全不符。"}], "explanations": {"再会": "正确答案：“再会”表示希望日后再见，与“希望明年再见”相合。", "哎哟": "语义：“哎哟”表示疼痛，与希望日后相见的语境不符。", "咦": "语义：“咦”表示疑惑，不能用于表达告别的心愿。", "救命": "语义：“救命”是呼救之语，与希望日后再见的告别语境完全不符。"}, "sentence_index": 0, "correct_answer": "再会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朋友送我一本好书，我高兴地说：“再会。”", "explanation": "“再会”是告别语，表示感谢时不能用。这里应该用〈谢谢〉。"}, {"text": "他不小心踩到我的脚，我连忙说：“再会。”", "explanation": "“再会”是告别语，被人踩到脚时不能用。这里应该用〈哎哟〉。"}, {"text": "老师走进教室，对同学们说：“再会！”", "explanation": "“再会”是告别语，见面时不能用。这里应该用〈大家好〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86998, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再会", "is_correct": true, "explanation": "正确答案：“再会”是告别语，与“大声喊”的告别语境相合。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：“嘘”表示让人安静，与大声喊的动作相矛盾。"}, {"text": "唉", "is_correct": false, "explanation": "语义：“唉”表示叹息，不能表示大声呼喊的告别。"}, {"text": "嗯", "is_correct": false, "explanation": "语义：“嗯”是应答或思考时的声音，不能用来大声呼喊告别。"}], "explanations": {"再会": "正确答案：“再会”是告别语，与“大声喊”的告别语境相合。", "嘘": "语义：“嘘”表示让人安静，与大声喊的动作相矛盾。", "唉": "语义：“唉”表示叹息，不能表示大声呼喊的告别。", "嗯": "语义：“嗯”是应答或思考时的声音，不能用来大声呼喊告别。"}, "sentence_index": 6, "correct_answer": "再会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把作业交上去，老师问还有没有别的，我说：“再会。”", "explanation": "“再会”是告别语，不能用来回答没有其他事。这里应该用〈没有了〉。"}, {"text": "我想问路，就对路人说：“再会。”", "explanation": "“再会”是告别语，向别人询问时不能用。这里应该用〈请问〉。"}, {"text": "服务员问我要不要加汤，我说：“再会。”", "explanation": "“再会”是告别语，回答别人是否加汤时不能用。这里应该用〈不用了〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86998, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "见到老师时，她笑着说了一声再会。", "corrected_sentence": "离开老师时，她笑着说了一声再会。", "error_description": "“再会”是分别时说的话，见到别人时不能用；应改为离开时说“再会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86998, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他转身说了一个再会，就走了。", "corrected_sentence": "他转身说了一声再会，就走了。", "error_description": "量词错误：告别语前的量词应为“一声”，应说“说了一声再会”；“一个”不能用于告别语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
