INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86999, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "向后是朝着后面的方向去。", "primary_collocate": null, "pronunciation": "xiàng hòu", "ipa": "ɕjɑŋ˥˩ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "请大家向后走一步。", "target_word": "向后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面有车，你先向后退一点儿。", "target_word": "向后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向后跑了几步，停了下来。", "target_word": "向后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子向后退了两步，躲到了妈妈身边。", "target_word": "向后", "complexity_tier": "T3", "furigana": "háizi xiàng hòu tuì le liǎng bù, duǒ dào le māma shēnbiān.", "sentence_source": "generated"}, {"text": "火车慢慢地向后开了。", "target_word": "向后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把椅子向后拉了一下。", "target_word": "向后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "向后退一步，你就能看到全部。", "target_word": "向后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请向后走，不要站在门口。", "target_word": "向后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗看见大水，吓得向后跑。", "target_word": "向后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车可以向后开吗？", "target_word": "向后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "向後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体或物体朝后面移动、退去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c70db0a-f54e-4bc4-8d58-add9704b2190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86999, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "向后", "is_correct": true, "explanation": "正确答案：向后（xiàng hòu），表示朝后面的方向。"}, {"text": "相互", "is_correct": false, "explanation": "xiāng hù 与 xiàng hòu 第一音节声调不同，第二音节韵母不同（u/ou），意思是彼此。"}, {"text": "先后", "is_correct": false, "explanation": "xiān hòu 与 xiàng hòu 第一音节韵尾不同（n/ng）且声调不同，意思是先与后的顺序。"}, {"text": "巷口", "is_correct": false, "explanation": "xiàng kǒu 与 xiàng hòu 第二音节声母不同（k/h）且声调不同，意思是小巷的出口。"}], "explanations": {"向后": "正确答案：向后（xiàng hòu），表示朝后面的方向。", "相互": "xiāng hù 与 xiàng hòu 第一音节声调不同，第二音节韵母不同（u/ou），意思是彼此。", "先后": "xiān hòu 与 xiàng hòu 第一音节韵尾不同（n/ng）且声调不同，意思是先与后的顺序。", "巷口": "xiàng kǒu 与 xiàng hòu 第二音节声母不同（k/h）且声调不同，意思是小巷的出口。"}, "sentence_index": null, "correct_answer": "向后"}, "level_3": {"options": [{"text": "向后", "is_correct": true, "explanation": "正确：表示朝后面的方向，符合“走一步”的动作。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已完成，与“请大家……走一步”的祈使语气不符。"}, {"text": "偷偷", "is_correct": false, "explanation": "语义：“偷偷”指暗中进行，与“请大家”这种公开的指令相冲突。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：“曾经”表示过去的经历，与祈使句要求的将来动作不符。"}], "explanations": {"向后": "正确：表示朝后面的方向，符合“走一步”的动作。", "已经": "体貌：“已经”表示动作已完成，与“请大家……走一步”的祈使语气不符。", "偷偷": "语义：“偷偷”指暗中进行，与“请大家”这种公开的指令相冲突。", "曾经": "体貌：“曾经”表示过去的经历，与祈使句要求的将来动作不符。"}, "sentence_index": 0, "correct_answer": "向后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天向后上班。", "explanation": "这里不该用〈向后〉。“向后”表示朝后面的方向，不能修饰“上班”这种去单位工作的行为，去上班应说〈去〉。"}, {"text": "他这学期的成绩向后提高了。", "explanation": "这里不该用〈向后〉。在此义项中，“向后”只表示空间方向，不能表示成绩的变化；成绩变好应说〈进步〉。"}, {"text": "我们要向后迈进，争取更大的进步。", "explanation": "这里应该用〈向前〉。迈进、前进的方向是向前，向后迈进与“争取进步”的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86999, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "向后", "is_correct": true, "explanation": "正确：表示朝后面的方向，与“退一步，就能看到全部”的语境相符。"}, {"text": "向前", "is_correct": false, "explanation": "方向：“向前退”自相矛盾，“退”是向后移动，与“向前”相反。"}, {"text": "早就", "is_correct": false, "explanation": "体貌：“早就”表示很早以前已经发生，与“你就能看到”的假设结果矛盾。"}, {"text": "大声", "is_correct": false, "explanation": "语义：“大声”修饰发声，不能修饰“退一步”这种身体的移动。"}], "explanations": {"向后": "正确：表示朝后面的方向，与“退一步，就能看到全部”的语境相符。", "向前": "方向：“向前退”自相矛盾，“退”是向后移动，与“向前”相反。", "早就": "体貌：“早就”表示很早以前已经发生，与“你就能看到”的假设结果矛盾。", "大声": "语义：“大声”修饰发声，不能修饰“退一步”这种身体的移动。"}, "sentence_index": 6, "correct_answer": "向后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们正向后迎着朝阳走去。", "explanation": "这里应该用〈向前〉。迎着朝阳是朝前走，“向后”与“迎着”的方向相反。"}, {"text": "电梯向后降了三层。", "explanation": "这里应该用〈向下〉。电梯是上下移动，“向后”指水平的后方，不能表示下降。"}, {"text": "这首歌向后流行了很多年。", "explanation": "这里应该用〈一直〉。在此义项中，“向后”只表示方向，不能用来表示“流行”的持续。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86999, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他向后的退了两步。", "corrected_sentence": "他向后退了两步。", "error_description": "错误：“向后”作状语修饰动词“退”，后面不能加“的”。正确：“向后退了两步”，应去掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86999, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他向后地拉了一下椅子。", "corrected_sentence": "他向后拉了一下椅子。", "error_description": "错误：“向后”后面多加了“地”。正确：“向后拉”，“向后”作状语直接修饰动词，不需要“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
