INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87000, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "朝着后面的方向。", "primary_collocate": null, "pronunciation": "xiàng hòu", "ipa": "ɕjɑŋ˥˩ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他向后看了一眼，没有人。", "target_word": "向后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她向后转过身，对我挥了挥手，说再见。", "target_word": "向后", "complexity_tier": "T3", "furigana": "tā xiàng hòu zhuǎn guo shēn, duì wǒ huī le huī shǒu, shuō zàijiàn.", "sentence_source": "generated"}, {"text": "他头向后一仰，笑了起来。", "target_word": "向后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风从前面来，雨向后飘。", "target_word": "向后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向后指了指，说车站在那里。", "target_word": "向后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我向后靠在椅子上休息。", "target_word": "向后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把头发向后梳得很整齐。", "target_word": "向后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子向后伸手，想拿书包。", "target_word": "向后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我向后转头，看见老朋友来了。", "target_word": "向后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的身体向后倒了一下。", "target_word": "向后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "向後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动作所朝的方向是后面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c70db0a-f54e-4bc4-8d58-add9704b2190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87000, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "向后", "is_correct": true, "explanation": "正确答案：向后（xiàng hòu），表示朝后面的方向。"}, {"text": "相互", "is_correct": false, "explanation": "xiāng hù 与 xiàng hòu 第一音节声调不同，第二音节韵母不同（u/ou），意思是彼此。"}, {"text": "先后", "is_correct": false, "explanation": "xiān hòu 与 xiàng hòu 第一音节韵尾不同（n/ng）且声调不同，意思是先与后的顺序。"}, {"text": "巷口", "is_correct": false, "explanation": "xiàng kǒu 与 xiàng hòu 第二音节声母不同（k/h）且声调不同，意思是小巷的出口。"}], "explanations": {"向后": "正确答案：向后（xiàng hòu），表示朝后面的方向。", "相互": "xiāng hù 与 xiàng hòu 第一音节声调不同，第二音节韵母不同（u/ou），意思是彼此。", "先后": "xiān hòu 与 xiàng hòu 第一音节韵尾不同（n/ng）且声调不同，意思是先与后的顺序。", "巷口": "xiàng kǒu 与 xiàng hòu 第二音节声母不同（k/h）且声调不同，意思是小巷的出口。"}, "sentence_index": null, "correct_answer": "向后"}, "level_3": {"options": [{"text": "向后", "is_correct": true, "explanation": "正确：朝后面看，符合“看了一眼，没有人”的语境。"}, {"text": "相互", "is_correct": false, "explanation": "搭配：“相互”要求多个主体，“他”是单数，不能说“他相互看”。"}, {"text": "大声", "is_correct": false, "explanation": "语义：“大声”修饰发声，与“看”这个动作不符。"}, {"text": "不断", "is_correct": false, "explanation": "语义：“不断”表示持续进行，与“看了一眼”这种一次性动作相矛盾。"}], "explanations": {"向后": "正确：朝后面看，符合“看了一眼，没有人”的语境。", "相互": "搭配：“相互”要求多个主体，“他”是单数，不能说“他相互看”。", "大声": "语义：“大声”修饰发声，与“看”这个动作不符。", "不断": "语义：“不断”表示持续进行，与“看了一眼”这种一次性动作相矛盾。"}, "sentence_index": 0, "correct_answer": "向后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向后考上了大学。", "explanation": "这里不该用〈向后〉。“向后”只表示空间方向，不能用来表示“考上大学”这种结果。"}, {"text": "他向后迈进，离目标越来越近。", "explanation": "这里应该用〈向前〉。迈进是朝前推进，“向后迈进”与“离目标越来越近”矛盾。"}, {"text": "电梯向后下降了三层。", "explanation": "这里应该用〈向下〉。电梯是上下移动，“向后”指水平的后方，不能表示下降。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87000, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "向后", "is_correct": true, "explanation": "正确：表示朝后方向梳，与“梳得很整齐”的语境相符。"}, {"text": "相互", "is_correct": false, "explanation": "搭配：“相互”要求多个主体，“他”是单数，不能说“他把头发相互梳”。"}, {"text": "差点", "is_correct": false, "explanation": "语义：“差点”表示几乎发生却未发生，与“梳得很整齐”这一已完成的结果矛盾。"}, {"text": "猛地", "is_correct": false, "explanation": "语义：“猛地”表示突然、用力，与“梳得很整齐”的细致动作矛盾。"}], "explanations": {"向后": "正确：表示朝后方向梳，与“梳得很整齐”的语境相符。", "相互": "搭配：“相互”要求多个主体，“他”是单数，不能说“他把头发相互梳”。", "差点": "语义：“差点”表示几乎发生却未发生，与“梳得很整齐”这一已完成的结果矛盾。", "猛地": "语义：“猛地”表示突然、用力，与“梳得很整齐”的细致动作矛盾。"}, "sentence_index": 6, "correct_answer": "向后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌向后流行了很多年。", "explanation": "这里应该用〈一直〉。“向后”只表示方向，不能用来表示“流行”的持续。"}, {"text": "他向后打了一个电话。", "explanation": "这里不该用〈向后〉。“向后”只表示方向，不能引出打电话的对象；应说“他给朋友打了一个电话”。"}, {"text": "我向后喝了一杯水。", "explanation": "这里不该用〈向后〉。“向后”表示方向，不能修饰“喝”这个动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87000, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她向后的看了看，没有人。", "corrected_sentence": "她向后看了看，没有人。", "error_description": "错误：“向后”作状语修饰动词“看”，后面不能加“的”。正确：“向后看了看”，应去掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97905bf7-e8b6-4b20-9b8e-44e14e24da56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
