INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87001, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "实行是真的去做，照着去做。", "primary_collocate": null, "pronunciation": "shí xíng", "ipa": "ʂɨ˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "你说得对，我们马上实行。", "target_word": "实行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法很好，可是没人实行。", "target_word": "实行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了很多计划，但从来不实行。", "target_word": "实行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈定了新规矩，我们都认真实行。", "target_word": "实行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的建议，我已经实行了一个月。", "target_word": "实行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减肥计划，他只实行了三天。", "target_word": "实行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光说不做不行，要实行才有用。", "target_word": "实行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个想法太大，很难实行。", "target_word": "实行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先试着实行一下这个办法。", "target_word": "实行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早睡早起的计划，你实行了吗？", "target_word": "实行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "实行了", "label": "体标"}, {"form": "实行过", "label": "体标"}], "register": "中性", "sense_fingerprint": "照着想法或办法真的去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10a82993-50d4-4381-a959-52d6505f63fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87001, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "实行", "is_correct": true, "explanation": "正确。“实行”表示照着想法真的去做，与“马上”搭配。"}, {"text": "吵", "is_correct": false, "explanation": "语义：“你说得对”表示同意对方，“吵”与这种同意的语境相反，句子不通。"}, {"text": "对不起", "is_correct": false, "explanation": "语法：“对不起”是致歉用语，不能作“我们马上”的谓语，句子不成立。"}, {"text": "谢谢", "is_correct": false, "explanation": "语法：“谢谢”是道谢用语，不能与“我们马上”组成完整句子。"}], "explanations": {"实行": "正确。“实行”表示照着想法真的去做，与“马上”搭配。", "吵": "语义：“你说得对”表示同意对方，“吵”与这种同意的语境相反，句子不通。", "对不起": "语法：“对不起”是致歉用语，不能作“我们马上”的谓语，句子不成立。", "谢谢": "语法：“谢谢”是道谢用语，不能与“我们马上”组成完整句子。"}, "sentence_index": 0, "correct_answer": "实行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于实行了自己的梦想。", "explanation": "这里应该用〈实现〉。“实行”用于计划、制度、办法，梦想、目标要用“实现”。"}, {"text": "我们正在实行讨论。", "explanation": "这里应该用〈进行〉。“实行”的对象是计划、制度或办法，“讨论”这类活动要用“进行”。"}, {"text": "他一直没有实行自己的诺言。", "explanation": "这里应该用〈履行〉。“诺言”要用“履行”，“实行”用于计划或办法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87001, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实行", "is_correct": true, "explanation": "正确。“实行”表示真的去做，与“光说不做不行”的语境一致。"}, {"text": "讲", "is_correct": false, "explanation": "语义：句子强调要“做”，“讲”与“光说不做”的语境相反，意思矛盾。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“才有用”组成合理的动作搭配，句子不通。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”要接衣物等，“要穿才有用”说不通。"}], "explanations": {"实行": "正确。“实行”表示真的去做，与“光说不做不行”的语境一致。", "讲": "语义：句子强调要“做”，“讲”与“光说不做”的语境相反，意思矛盾。", "吃": "搭配：“吃”不能与“才有用”组成合理的动作搭配，句子不通。", "穿": "搭配：“穿”要接衣物等，“要穿才有用”说不通。"}, "sentence_index": 6, "correct_answer": "实行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去医院实行了一个月。", "explanation": "这里应该用〈实习〉。“实行”指真的去做、照着去做，“在医院工作学习”要用“实习”。"}, {"text": "这本书实行了十万册。", "explanation": "这里应该用〈发行〉。“实行”指真的去做，书籍出版上市要用“发行”。"}, {"text": "我们班实行了一场比赛。", "explanation": "这里应该用〈举行〉。“实行”指真的去做，“比赛”这类活动要用“举行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87001, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他说的办法很好，我们明天就实行过。", "corrected_sentence": "他说的办法很好，我们明天就实行。", "error_description": "错误：“过”表示过去的经历，句中“明天”表示将来，不能用“实行过”，应去掉“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87001, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个方案不错，我们先把实行一下。", "corrected_sentence": "这个方案不错，我们先实行一下。", "error_description": "把字句错误：“把”后面要有宾语，“实行”后面没有宾语，应去掉“把”，说“先实行一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
