INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87002, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把政策、制度、计划等付诸行动。", "primary_collocate": null, "pronunciation": "shí xíng", "ipa": "ʂɨ˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我们学校实行新的作息制度。", "target_word": "实行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市实行了垃圾分类。", "target_word": "实行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司从下个月起实行新规定。", "target_word": "实行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家实行九年义务教育。", "target_word": "实行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司实行每周五天工作制。", "target_word": "实行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项政策已经实行十年了。", "target_word": "实行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院实行预约挂号制度。", "target_word": "实行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多地方实行了限行政策。", "target_word": "实行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新计划明年一月开始实行。", "target_word": "实行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校对学生实行统一管理。", "target_word": "实行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "实行了", "label": "体标"}, {"form": "实行过", "label": "体标"}], "register": "书面", "sense_fingerprint": "把政策制度规定正式付诸施行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10a82993-50d4-4381-a959-52d6505f63fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87002, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "实行", "is_correct": true, "explanation": "正确。“实行”表示把制度付诸施行，与“作息制度”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”要接可以吃的东西，“作息制度”不能被“吃”。"}, {"text": "忘", "is_correct": false, "explanation": "语义：“忘”表示忘记，与学校制定并施行作息制度的语境相反，句子不合理。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：“摔”不能与“制度”搭配，说“摔制度”不通。"}], "explanations": {"实行": "正确。“实行”表示把制度付诸施行，与“作息制度”搭配。", "吃": "搭配：“吃”要接可以吃的东西，“作息制度”不能被“吃”。", "忘": "语义：“忘”表示忘记，与学校制定并施行作息制度的语境相反，句子不合理。", "摔": "搭配：“摔”不能与“制度”搭配，说“摔制度”不通。"}, "sentence_index": 0, "correct_answer": "实行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校实行了一场运动会。", "explanation": "这里应该用〈举行〉。“实行”用于政策、制度，“运动会”这类活动要用“举行”。"}, {"text": "这家出版社实行了一本新书。", "explanation": "这里应该用〈发行〉。“实行”用于政策、制度，书籍上市要用“发行”。"}, {"text": "他在银行实行了一年。", "explanation": "这里应该用〈实习〉。“实行”用于政策、制度，在单位学习工作要用“实习”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87002, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实行", "is_correct": true, "explanation": "正确。“实行”表示把制度付诸施行，与“预约挂号制度”搭配。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是唱歌，不能用于“预约挂号制度”，句子不通。"}, {"text": "挖", "is_correct": false, "explanation": "搭配：“挖”一般接具体物体或坑洞，“挖制度”说不通。"}, {"text": "锁", "is_correct": false, "explanation": "搭配：“锁”一般接门、箱子等，“锁制度”不能这样说。"}], "explanations": {"实行": "正确。“实行”表示把制度付诸施行，与“预约挂号制度”搭配。", "唱": "语义：“唱”是唱歌，不能用于“预约挂号制度”，句子不通。", "挖": "搭配：“挖”一般接具体物体或坑洞，“挖制度”说不通。", "锁": "搭配：“锁”一般接门、箱子等，“锁制度”不能这样说。"}, "sentence_index": 6, "correct_answer": "实行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司终于实行了五年目标。", "explanation": "这里应该用〈实现〉。“实行”用于政策、制度，“目标”要用“实现”。"}, {"text": "学校正在实行调查。", "explanation": "这里应该用〈进行〉。“实行”的对象是政策、制度，“调查”要用“进行”。"}, {"text": "公司明天要实行一个会议。", "explanation": "这里应该用〈召开〉。“实行”用于政策、制度，开会议要用“召开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个学校从明年起实行了新的考试制度。", "corrected_sentence": "这个学校从明年起实行新的考试制度。", "error_description": "错误：句中有“从明年起”表示将来，“实行”后面不能加“了”，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市从来没有实行了垃圾分类。", "corrected_sentence": "这个城市从来没有实行过垃圾分类。", "error_description": "错误：“从来没有”否定过去的经历，“实行”后面应该用“过”，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
