INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87003, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地板是屋子里我们脚踩的那一层，常常是木头做的。", "primary_collocate": null, "pronunciation": "dì bǎn", "ipa": "ti˥˩ pan˨˩˦", "syllable_count": 2, "sentences": [{"text": "我家的地板是木头做的。", "target_word": "地板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子坐在地板上玩玩具。", "target_word": "地板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地板很干净，进门要换鞋。", "target_word": "地板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天都用拖把拖地板。", "target_word": "地板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水洒在地板上了，快拿布来擦。", "target_word": "地板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫躺在温暖的地板上睡觉。", "target_word": "地板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把书放在地板上。", "target_word": "地板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天光脚踩地板，脚很凉。", "target_word": "地板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地板太滑，你走路要小心。", "target_word": "地板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈正在擦客厅的地板。", "target_word": "地板", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块地板", "label": "量词"}, {"form": "木地板", "label": "复合"}, {"form": "地板砖", "label": "复合"}], "register": "中性", "sense_fingerprint": "地板：屋子里脚踩的那一层地面，常指木地面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e417de8-3307-410a-8543-b657809a61d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87003, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地板", "is_correct": true, "explanation": "地板（dì bǎn）：屋子里脚踩的那一层地面。"}, {"text": "地毯", "is_correct": false, "explanation": "tǎn（第三声）与 bǎn（第三声）声母不同（t 与 b），意思是铺在地上的毯子。"}, {"text": "底板", "is_correct": false, "explanation": "dǐ（第三声）与 dì（第四声）声调不同，意思是最下面的一层板。"}, {"text": "壁板", "is_correct": false, "explanation": "bì（第四声）与 dì（第四声）声母不同（b 与 d），意思是墙上的板材。"}], "explanations": {"地板": "地板（dì bǎn）：屋子里脚踩的那一层地面。", "地毯": "tǎn（第三声）与 bǎn（第三声）声母不同（t 与 b），意思是铺在地上的毯子。", "底板": "dǐ（第三声）与 dì（第四声）声调不同，意思是最下面的一层板。", "壁板": "bì（第四声）与 dì（第四声）声母不同（b 与 d），意思是墙上的板材。"}, "sentence_index": null, "correct_answer": "地板"}, "level_3": {"options": [{"text": "地板", "is_correct": true, "explanation": "地板：屋子里铺在地面上的一层，可以是木头做的，符合句意。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图是纸或图像，不会是木头做的。"}, {"text": "地址", "is_correct": false, "explanation": "语义：地址是文字信息，不能说“木头做的地址”。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃本身是一种材料，不能说“玻璃是木头做的”。"}], "explanations": {"地板": "地板：屋子里铺在地面上的一层，可以是木头做的，符合句意。", "地图": "语义：地图是纸或图像，不会是木头做的。", "地址": "语义：地址是文字信息，不能说“木头做的地址”。", "玻璃": "语义：玻璃本身是一种材料，不能说“玻璃是木头做的”。"}, "sentence_index": 0, "correct_answer": "地板"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用地板炒了一盘菜。", "explanation": "这里应该用〈蔬菜〉。地板是建材，不能用来炒菜，炒菜要用蔬菜等食材。"}, {"text": "街道的地板被雨水冲坏了。", "explanation": "这里应该用〈路面〉。地板指室内铺设的地面，街道的表面应说路面。"}, {"text": "把水倒进地板里。", "explanation": "这里应该用〈桶〉。地板不是容器，不能说“倒进地板里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87003, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地板", "is_correct": true, "explanation": "地板：可以放置物品的平面，符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能用来放置东西，“放在天空上”不成立。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“放在……上”的处所一般是平面或物体，不说“放在眼睛上”。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水是液体，不能作为放书的平面。"}], "explanations": {"地板": "地板：可以放置物品的平面，符合句意。", "天空": "语义：天空不能用来放置东西，“放在天空上”不成立。", "眼睛": "搭配：“放在……上”的处所一般是平面或物体，不说“放在眼睛上”。", "墨水": "语义：墨水是液体，不能作为放书的平面。"}, "sentence_index": 6, "correct_answer": "地板"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他戴上地板出门了。", "explanation": "这里应该用〈帽子〉。地板是屋里脚踩的地面，不能戴在头上。"}, {"text": "他把画挂在地板上。", "explanation": "这里应该用〈墙〉。画要挂在墙上，地板不能用来挂画。"}, {"text": "他渴了，喝了一杯地板。", "explanation": "这里应该用〈水〉。地板不是饮料，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87003, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小狗趴在地板里睡觉。", "corrected_sentence": "小狗趴在地板上睡觉。", "error_description": "错误形式：“趴在地板里”；正确形式：“趴在地板上”。地板是平面，小狗趴在它的表面，要用“上”，不用“里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87003, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把地板擦。", "corrected_sentence": "妈妈把地板擦干净了。", "error_description": "“把”字句缺少补语：错误形式“把地板擦”；正确形式“把地板擦干净了”。“把”字句的动词后通常需要补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
