INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87004, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "房间里铺在地面上的木板或其他材料。", "primary_collocate": null, "pronunciation": "dì bǎn", "ipa": "ti˥˩ pan˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们新买了一块地板。", "target_word": "地板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在卧室里铺地板。", "target_word": "地板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种地板防水，适合铺在厨房。", "target_word": "地板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧地板坏了，我们打算换新的。", "target_word": "地板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套房子的地板用的是红木。", "target_word": "地板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铺地板以前，要先把地面扫干净。", "target_word": "地板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种地板的价格不太贵。", "target_word": "地板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅说这块地板有点儿湿。", "target_word": "地板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地板的颜色和墙一样，看着很舒服。", "target_word": "地板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想给客厅换一种新地板。", "target_word": "地板", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块地板", "label": "量词"}, {"form": "木地板", "label": "复合"}, {"form": "地板砖", "label": "复合"}], "register": "中性", "sense_fingerprint": "地板：铺在房间地面上的建筑材料，可买、铺、换", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e417de8-3307-410a-8543-b657809a61d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87004, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地板", "is_correct": true, "explanation": "地板（dì bǎn）：房间里铺在地面上的建材。"}, {"text": "地毯", "is_correct": false, "explanation": "tǎn（第三声）与 bǎn（第三声）声母不同（t 与 b），意思是铺在地上的毯子。"}, {"text": "底板", "is_correct": false, "explanation": "dǐ（第三声）与 dì（第四声）声调不同，意思是最下面的一层板。"}, {"text": "壁板", "is_correct": false, "explanation": "bì（第四声）与 dì（第四声）声母不同（b 与 d），意思是墙上的板材。"}], "explanations": {"地板": "地板（dì bǎn）：房间里铺在地面上的建材。", "地毯": "tǎn（第三声）与 bǎn（第三声）声母不同（t 与 b），意思是铺在地上的毯子。", "底板": "dǐ（第三声）与 dì（第四声）声调不同，意思是最下面的一层板。", "壁板": "bì（第四声）与 dì（第四声）声母不同（b 与 d），意思是墙上的板材。"}, "sentence_index": null, "correct_answer": "地板"}, "level_3": {"options": [{"text": "地板", "is_correct": true, "explanation": "地板：铺在房间地面上的建材，可以买，符合句意。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙不能被买，“新买了一块墙”不成立。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能买，也不能用“块”计量。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：量词“块”通常不搭配“空气”，不说“一块空气”。"}], "explanations": {"地板": "地板：铺在房间地面上的建材，可以买，符合句意。", "墙": "语义：墙不能被买，“新买了一块墙”不成立。", "天气": "语义：天气不能买，也不能用“块”计量。", "空气": "搭配：量词“块”通常不搭配“空气”，不说“一块空气”。"}, "sentence_index": 0, "correct_answer": "地板"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把地板放进了冰箱。", "explanation": "这里应该用〈食物〉。地板是建材，不能放进冰箱，放进冰箱的应是食物。"}, {"text": "我们买了一块新地板，用来做窗帘。", "explanation": "这里应该用〈布〉。地板是铺在地面的建材，不能用来做窗帘，做窗帘要用布。"}, {"text": "我们用地板擦桌子。", "explanation": "这里应该用〈抹布〉。地板是铺设的建材，不能当擦拭工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87004, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地板", "is_correct": true, "explanation": "地板：铺在地面上的建材，有价格，符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空没有价格，不能说“这种天空的价格”。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是商品，不能说“月亮的价格”。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：“价格”通常指商品，“阳光的价格”不常见。"}], "explanations": {"地板": "地板：铺在地面上的建材，有价格，符合句意。", "天空": "语义：天空没有价格，不能说“这种天空的价格”。", "月亮": "语义：月亮不是商品，不能说“月亮的价格”。", "阳光": "搭配：“价格”通常指商品，“阳光的价格”不常见。"}, "sentence_index": 6, "correct_answer": "地板"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想给屋顶换一种新地板。", "explanation": "这里应该用〈瓦〉。屋顶常用瓦，地板铺在地面，不能用在屋顶。"}, {"text": "我想给窗户换一种新地板。", "explanation": "这里应该用〈玻璃〉。窗户要装玻璃，地板不能装在窗户上。"}, {"text": "我想给书换一种新地板。", "explanation": "这里应该用〈封面〉。书的外面是封面，地板是铺在地面的建材，不能用在书上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了一只新地板。", "corrected_sentence": "他买了一块新地板。", "error_description": "错误形式：“一只新地板”；正确形式：“一块新地板”。“只”用于动物或成对物品中的一个，地板要用量词“块”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87004, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把地板铺。", "corrected_sentence": "工人把地板铺好了。", "error_description": "“把”字句缺少补语：错误形式“把地板铺”；正确形式“把地板铺好了”。“把”字句的动词后通常需要补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87005, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离线", "is_correct": true, "explanation": "正确答案。离线与在线意思相反，指不在网络上、无法被即时联系。"}, {"text": "忙碌", "is_correct": false, "explanation": "忙碌说事情多，与是否上网无关，不构成反义关系。"}, {"text": "结实", "is_correct": false, "explanation": "结实形容物体坚固，与人的上网状态无关，不是反义词。"}, {"text": "富有", "is_correct": false, "explanation": "富有指钱财或内涵多，与在线、离线无关。"}], "correct_answer": "离线", "explanations": {"离线": "正确答案。离线与在线意思相反，指不在网络上、无法被即时联系。", "忙碌": "忙碌说事情多，与是否上网无关，不构成反义关系。", "结实": "结实形容物体坚固，与人的上网状态无关，不是反义词。", "富有": "富有指钱财或内涵多，与在线、离线无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87005, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离线", "is_correct": true, "explanation": "正确答案。离线与在线意思相反，指不在网络上、无法被即时联系。"}, {"text": "灵活", "is_correct": false, "explanation": "灵活形容动作或思路敏捷，与是否上网无关，不构成反义关系。"}, {"text": "富裕", "is_correct": false, "explanation": "富裕指经济条件好，与上网状态无关。"}, {"text": "完整", "is_correct": false, "explanation": "完整指没有缺少，与在线、离线的对立无关。"}], "correct_answer": "离线", "explanations": {"离线": "正确答案。离线与在线意思相反，指不在网络上、无法被即时联系。", "灵活": "灵活形容动作或思路敏捷，与是否上网无关，不构成反义关系。", "富裕": "富裕指经济条件好，与上网状态无关。", "完整": "完整指没有缺少，与在线、离线的对立无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87005, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "在线是人正在用手机或电脑上网，别人马上就能找到他。", "primary_collocate": null, "pronunciation": "zài xiàn", "ipa": "tsaɪ˥˩ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "小王在线吗？我有事找他。", "target_word": "在线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你晚上在线的话，我们视频聊聊。", "target_word": "在线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的头像亮着，说明她在线。", "target_word": "在线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上八点都在线。", "target_word": "在线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈不在线，我给她打电话。", "target_word": "在线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在线的时候，你可以发消息。", "target_word": "在线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友们都在线，我们开始吧。", "target_word": "在线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天他一直不在线，我没找到他。", "target_word": "在线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在线，你快给她发消息。", "target_word": "在线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他刚才还在线，现在下线了。", "target_word": "在线", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "在線", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人正在上网，别人能马上联系到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdba5b8c-a597-4c90-bcad-019807f38244') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87005, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "在线", "is_correct": true, "explanation": "正确答案。在线指人正在用手机或电脑上网，别人能马上找到他。"}, {"text": "再见", "is_correct": false, "explanation": "zàijiàn 与 zàixiàn 的声母不同（j 与 x），意思是告别。"}, {"text": "在先", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）只有声调不同，意思是在前面、事先。"}, {"text": "在校", "is_correct": false, "explanation": "xiào 与 xiàn 的韵母不同（ao 与 an），意思是在学校。"}], "explanations": {"在线": "正确答案。在线指人正在用手机或电脑上网，别人能马上找到他。", "再见": "zàijiàn 与 zàixiàn 的声母不同（j 与 x），意思是告别。", "在先": "xiān（第一声）与 xiàn（第四声）只有声调不同，意思是在前面、事先。", "在校": "xiào 与 xiàn 的韵母不同（ao 与 an），意思是在学校。"}, "sentence_index": null, "correct_answer": "在线"}, "level_3": {"options": [{"text": "在线", "is_correct": true, "explanation": "正确答案。说明小王是否在网上、能否马上找到，与后文“我有事找他”相符。"}, {"text": "安静", "is_correct": false, "explanation": "语义：安静形容环境或状态安稳，不能用来询问一个人能否被找到。"}, {"text": "健康", "is_correct": false, "explanation": "语义：健康说的是身体状况，与能否联系到人无关，句子不通。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：漂亮形容外貌，不能用来问人是否可以被联系。"}], "explanations": {"在线": "正确答案。说明小王是否在网上、能否马上找到，与后文“我有事找他”相符。", "安静": "语义：安静形容环境或状态安稳，不能用来询问一个人能否被找到。", "健康": "语义：健康说的是身体状况，与能否联系到人无关，句子不通。", "漂亮": "体貌：漂亮形容外貌，不能用来问人是否可以被联系。"}, "sentence_index": 0, "correct_answer": "在线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头很在线，摸起来很舒服。", "explanation": "这里误把〈在线〉用来形容石头。在线只说人或设备接入网络，石头不能联网；想说石头光滑，应用〈光滑〉。"}, {"text": "这个苹果很在线，又甜又脆。", "explanation": "这里应该用〈新鲜〉。新鲜指食物刚采下不久；在线只说人或设备接入网络，不能用来形容苹果。"}, {"text": "爷爷还在线，身体很好。", "explanation": "这里应该用〈在世〉。在世指人还活着；在线只说网络连接状态，不能用来说人是否活着。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87005, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "在线", "is_correct": true, "explanation": "正确答案。在线指人正在上网，别人能马上找到他。"}, {"text": "在建", "is_correct": false, "explanation": "jiàn 与 xiàn 声母不同（j 与 x），意思是正在建设中。"}, {"text": "再想", "is_correct": false, "explanation": "xiǎng（第三声）与 xiàn（第四声）韵母和声调都不同，意思是再考虑。"}, {"text": "在先", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）只有声调不同，意思是在前面、事先。"}], "explanations": {"在线": "正确答案。在线指人正在上网，别人能马上找到他。", "在建": "jiàn 与 xiàn 声母不同（j 与 x），意思是正在建设中。", "再想": "xiǎng（第三声）与 xiàn（第四声）韵母和声调都不同，意思是再考虑。", "在先": "xiān（第一声）与 xiàn（第四声）只有声调不同，意思是在前面、事先。"}, "sentence_index": null, "correct_answer": "在线"}, "level_3": {"options": [{"text": "在线", "is_correct": true, "explanation": "正确答案。说明朋友们能否在网上被即时找到，与“我们开始吧”的语境相符。"}, {"text": "出差", "is_correct": false, "explanation": "语义：“出差”指因公外出，“朋友们都出差”与“我们开始吧”的语境不合，句意不通。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：热闹指场面喧闹，与“朋友们在线”不符，也无法说明可以开始。"}, {"text": "礼貌", "is_correct": false, "explanation": "搭配：礼貌形容人的待人态度，不能用来描述朋友们的联网状态。"}], "explanations": {"在线": "正确答案。说明朋友们能否在网上被即时找到，与“我们开始吧”的语境相符。", "出差": "语义：“出差”指因公外出，“朋友们都出差”与“我们开始吧”的语境不合，句意不通。", "热闹": "语义：热闹指场面喧闹，与“朋友们在线”不符，也无法说明可以开始。", "礼貌": "搭配：礼貌形容人的待人态度，不能用来描述朋友们的联网状态。"}, "sentence_index": 6, "correct_answer": "在线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "书记在线十年，很有威望。", "explanation": "这里应该用〈在位〉。在位指担任某个职务；在线只说网络连接状态，不能用来说人任职。"}, {"text": "客厅里有一张在线的桌子。", "explanation": "这里应该用〈放在〉。放在说物品所处的位置；在线只说人或设备接入网络，桌子不能联网，这里误把〈在线〉当作位置用。"}, {"text": "这件衣服很在线，穿着很暖和。", "explanation": "这里应该用〈厚〉。厚形容衣服不薄；在线只说人接入网络的状态，不能形容衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87005, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你在在线吗？", "corrected_sentence": "你在线吗？", "error_description": "“在线”是一个词，“在”不能重复；应去掉多余的“在”，说“你在线吗？”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87005, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他现在线吗？", "corrected_sentence": "他现在在线吗？", "error_description": "“在线”是一个词，不能漏掉其中的“在”；“他现在线吗”缺了“在”，应说“他现在在线吗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87006, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离线", "is_correct": true, "explanation": "正确答案。离线与在线意思相反，指设备或服务未接入网络，无法随时使用。"}, {"text": "流畅", "is_correct": false, "explanation": "流畅形容动作或文字连贯，与网络连接状态无关，不构成反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "干净形容清洁程度，与是否联网无关。"}, {"text": "便宜", "is_correct": false, "explanation": "便宜形容价格低，与是否在线无关。"}], "correct_answer": "离线", "explanations": {"离线": "正确答案。离线与在线意思相反，指设备或服务未接入网络，无法随时使用。", "流畅": "流畅形容动作或文字连贯，与网络连接状态无关，不构成反义关系。", "干净": "干净形容清洁程度，与是否联网无关。", "便宜": "便宜形容价格低，与是否在线无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87006, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离线", "is_correct": true, "explanation": "正确答案。离线与在线意思相反，指设备或服务未接入网络。"}, {"text": "清晰", "is_correct": false, "explanation": "清晰形容事物分明、容易看懂，与网络连接状态无关。"}, {"text": "厚实", "is_correct": false, "explanation": "厚实形容物体厚重结实，与是否在线无关。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速形容速度快，与在线、离线的对立无关。"}], "correct_answer": "离线", "explanations": {"离线": "正确答案。离线与在线意思相反，指设备或服务未接入网络。", "清晰": "清晰形容事物分明、容易看懂，与网络连接状态无关。", "厚实": "厚实形容物体厚重结实，与是否在线无关。", "迅速": "迅速形容速度快，与在线、离线的对立无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87006, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "连接着网络，正处于可以随时联系或使用的状态。", "primary_collocate": null, "pronunciation": "zài xiàn", "ipa": "tsaɪ˥˩ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "客服系统一直在线，有问题可以问。", "target_word": "在线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台电脑现在不在线。", "target_word": "在线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "服务器在线，可以正常使用。", "target_word": "在线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏需要在线才能玩。", "target_word": "在线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的网站一直在线，很方便。", "target_word": "在线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打印机没有在线，请检查网线。", "target_word": "在线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电子词典在线时可以查新词。", "target_word": "在线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家书店的网站在线，买书又快又便宜。", "target_word": "在线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "问诊平台在线时，病人可以随时问。", "target_word": "在线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机没有信号，就不能在线。", "target_word": "在线", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "在線", "label": "繁体"}], "register": "中性", "sense_fingerprint": "设备、服务或资源连着网络，随时可用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdba5b8c-a597-4c90-bcad-019807f38244') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87006, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "在线", "is_correct": true, "explanation": "正确答案。在线指设备或服务已接入网络，随时可用。"}, {"text": "再见", "is_correct": false, "explanation": "zàijiàn 与 zàixiàn 的声母不同（j 与 x），意思是告别。"}, {"text": "在先", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）只有声调不同，意思是在前面、事先。"}, {"text": "在校", "is_correct": false, "explanation": "xiào 与 xiàn 的韵母不同（ao 与 an），意思是在学校。"}], "explanations": {"在线": "正确答案。在线指设备或服务已接入网络，随时可用。", "再见": "zàijiàn 与 zàixiàn 的声母不同（j 与 x），意思是告别。", "在先": "xiān（第一声）与 xiàn（第四声）只有声调不同，意思是在前面、事先。", "在校": "xiào 与 xiàn 的韵母不同（ao 与 an），意思是在学校。"}, "sentence_index": null, "correct_answer": "在线"}, "level_3": {"options": [{"text": "在线", "is_correct": true, "explanation": "正确答案。客服系统处于可以随时使用的状态，与“有问题可以问”相符。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：清楚说明事情明白，不能描述客服的服务状态，句意不通。"}, {"text": "结实", "is_correct": false, "explanation": "语义：结实形容物体坚固，不能用来形容客服的可联系状态。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：漂亮形容外貌，不能用来描述客服是否随时可用。"}], "explanations": {"在线": "正确答案。客服系统处于可以随时使用的状态，与“有问题可以问”相符。", "清楚": "语义：清楚说明事情明白，不能描述客服的服务状态，句意不通。", "结实": "语义：结实形容物体坚固，不能用来形容客服的可联系状态。", "漂亮": "体貌：漂亮形容外貌，不能用来描述客服是否随时可用。"}, "sentence_index": 0, "correct_answer": "在线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把伞已经在线了，可以拿出去用。", "explanation": "这里应该用〈修好〉。修好指东西恢复可用；在线只指设备或服务连接网络，伞不能联网。"}, {"text": "这张椅子需要在线才能坐。", "explanation": "这里应该用〈通电〉。通电说设备接上电源后才能用；在线只指设备或服务连接网络，椅子不能联网。"}, {"text": "这个苹果已经在线了，可以吃。", "explanation": "这里应该用〈成熟〉。成熟指水果长到可以吃的程度；在线只指设备或服务连接网络，不能用来形容苹果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87006, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "在线", "is_correct": true, "explanation": "正确答案。在线指设备或服务已接入网络，随时可用。"}, {"text": "在建", "is_correct": false, "explanation": "jiàn 与 xiàn 声母不同（j 与 x），意思是正在建设中。"}, {"text": "再想", "is_correct": false, "explanation": "xiǎng（第三声）与 xiàn（第四声）韵母和声调都不同，意思是再考虑。"}, {"text": "在先", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）只有声调不同，意思是在前面、事先。"}], "explanations": {"在线": "正确答案。在线指设备或服务已接入网络，随时可用。", "在建": "jiàn 与 xiàn 声母不同（j 与 x），意思是正在建设中。", "再想": "xiǎng（第三声）与 xiàn（第四声）韵母和声调都不同，意思是再考虑。", "在先": "xiān（第一声）与 xiàn（第四声）只有声调不同，意思是在前面、事先。"}, "sentence_index": null, "correct_answer": "在线"}, "level_3": {"options": [{"text": "在线", "is_correct": true, "explanation": "正确答案。说明词典处于可用的联网状态，与“可以查新词”相符。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：严肃形容态度认真，不能描述词典的联网状态，句意不通。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：热闹指场面喧闹，不能用来说明词典能否使用。"}, {"text": "礼貌", "is_correct": false, "explanation": "搭配：礼貌用于形容人的态度，不能修饰电子词典。"}], "explanations": {"在线": "正确答案。说明词典处于可用的联网状态，与“可以查新词”相符。", "严肃": "语义：严肃形容态度认真，不能描述词典的联网状态，句意不通。", "热闹": "语义：热闹指场面喧闹，不能用来说明词典能否使用。", "礼貌": "搭配：礼貌用于形容人的态度，不能修饰电子词典。"}, "sentence_index": 6, "correct_answer": "在线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯水很在线，喝起来很凉。", "explanation": "这里应该用〈冰〉。冰形容很凉；在线只指设备或服务连接网络，不能形容水。"}, {"text": "这张床很在线，睡起来很软。", "explanation": "这里应该用〈软和〉。软和形容物体柔软；在线只指设备或服务连接网络，床不能联网，不能用来形容床。"}, {"text": "这本纸书在线了，可以放回书架。", "explanation": "这里应该用〈看完〉。看完指读完了书；在线只指设备或服务连接网络，纸书不能联网。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台服务器被在线，很稳定。", "corrected_sentence": "这台服务器在线，很稳定。", "error_description": "“在线”是不及物的状态词，不能用“被”构成被动句，应去掉“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "打印机现在在在线吗？", "corrected_sentence": "打印机现在在线吗？", "error_description": "“在线”是一个词，“在”不能重复；应说“打印机现在在线吗？”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87009, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内政", "is_correct": true, "explanation": "正确。内政指国家内部的政务，与面向别国的外交正好相对。"}, {"text": "军事", "is_correct": false, "explanation": "军事与外交都属国家事务，但二者不构成反义关系，不能成对。"}, {"text": "文化", "is_correct": false, "explanation": "文化是另一个领域，与外交没有相对立的关系。"}, {"text": "经济", "is_correct": false, "explanation": "经济不是外交的反义词，两者不能成对。"}], "correct_answer": "内政", "explanations": {"内政": "正确。内政指国家内部的政务，与面向别国的外交正好相对。", "军事": "军事与外交都属国家事务，但二者不构成反义关系，不能成对。", "文化": "文化是另一个领域，与外交没有相对立的关系。", "经济": "经济不是外交的反义词，两者不能成对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87009, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内政", "is_correct": true, "explanation": "正确。内政指国家内部的政务，与面向别国的外交正好相对。"}, {"text": "贸易", "is_correct": false, "explanation": "贸易是外交常涉及的内容之一，但不是外交的反义词。"}, {"text": "科技", "is_correct": false, "explanation": "科技与外交不构成反义关系，不能成对。"}, {"text": "教育", "is_correct": false, "explanation": "教育与外交不构成反义关系，不能成对。"}], "correct_answer": "内政", "explanations": {"内政": "正确。内政指国家内部的政务，与面向别国的外交正好相对。", "贸易": "贸易是外交常涉及的内容之一，但不是外交的反义词。", "科技": "科技与外交不构成反义关系，不能成对。", "教育": "教育与外交不构成反义关系，不能成对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87009, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "外交是一个国家和别的国家来往，好好商量事情。", "primary_collocate": null, "pronunciation": "wài jiāo", "ipa": "waɪ˥˩ tɕiɑʊ˥", "syllable_count": 2, "sentences": [{"text": "我的爸爸做外交工作。", "target_word": "外交", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "两个国家的外交很重要。", "target_word": "外交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想学外交，以后为国家工作。", "target_word": "外交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外交就是国家和国家商量事情。", "target_word": "外交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国和很多国家有外交来往。", "target_word": "外交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从事外交工作三十年了。", "target_word": "外交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的外交能让两国成为朋友。", "target_word": "外交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她大学学的是外交。", "target_word": "外交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的外交越来越好。", "target_word": "外交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外交的事情不能太着急。", "target_word": "外交", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "外交政策", "label": "复合"}], "register": "正式", "sense_fingerprint": "一个国家和别的国家来往、商量事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10a82993-50d4-4381-a959-52d6505f63fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87009, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "外交", "is_correct": true, "explanation": "正确。外交 wàijiāo，指国家之间的往来与谈判。"}, {"text": "外教", "is_correct": false, "explanation": "外教 wàijiào 与 外交 wàijiāo 第二个音节声调不同（交 jiāo 第一声，教 jiào 第四声），意思是外国教师。"}, {"text": "外角", "is_correct": false, "explanation": "外角 wàijiǎo 与 外交 wàijiāo 第二个音节声调不同（角 jiǎo 第三声），意思是外侧的角。"}, {"text": "未交", "is_correct": false, "explanation": "未交 wèijiāo 与 外交 wàijiāo 第一个音节韵母不同（ei 与 ai），意思是还没有交出。"}], "explanations": {"外交": "正确。外交 wàijiāo，指国家之间的往来与谈判。", "外教": "外教 wàijiào 与 外交 wàijiāo 第二个音节声调不同（交 jiāo 第一声，教 jiào 第四声），意思是外国教师。", "外角": "外角 wàijiǎo 与 外交 wàijiāo 第二个音节声调不同（角 jiǎo 第三声），意思是外侧的角。", "未交": "未交 wèijiāo 与 外交 wàijiāo 第一个音节韵母不同（ei 与 ai），意思是还没有交出。"}, "sentence_index": null, "correct_answer": "外交"}, "level_3": {"options": [{"text": "外交", "is_correct": true, "explanation": "正确。外交是国家间的交往工作，能接“做……工作”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是可以拿来做的工作。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“做”后面接的是职业或工作，不能说做工资。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：“蔬菜”是食材，不能作为工作内容。"}], "explanations": {"外交": "正确。外交是国家间的交往工作，能接“做……工作”。", "天气": "语义：“天气”不是可以拿来做的工作。", "工资": "搭配：“做”后面接的是职业或工作，不能说做工资。", "蔬菜": "语义：“蔬菜”是食材，不能作为工作内容。"}, "sentence_index": 0, "correct_answer": "外交"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋大楼的外交很漂亮。", "explanation": "这里应该用〈外观〉。外交指国家间的往来，建筑的样子要说“外观”。"}, {"text": "我们下午去外交散步。", "explanation": "这里应该用〈外面〉。外交指国家间的官方往来，出门散步的地方要说“外面”。"}, {"text": "外交就是国家管理本国的事务。", "explanation": "这里应该用〈内政〉。外交处理的是与别国的关系，管理本国事务要用内政。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87009, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "外交", "is_correct": true, "explanation": "正确。外交 wàijiāo，指国家之间的往来与谈判。"}, {"text": "外销", "is_correct": false, "explanation": "外销 wàixiāo 与 外交 wàijiāo 声母不同（x 与 j），意思是向外国销售。"}, {"text": "外间", "is_correct": false, "explanation": "外间 wàijiān 与 外交 wàijiāo 第二个音节韵母不同（ian 与 iao），意思是外面、外界。"}, {"text": "未交", "is_correct": false, "explanation": "未交 wèijiāo 与 外交 wàijiāo 第一个音节韵母不同（ei 与 ai），意思是还没有交出。"}], "explanations": {"外交": "正确。外交 wàijiāo，指国家之间的往来与谈判。", "外销": "外销 wàixiāo 与 外交 wàijiāo 声母不同（x 与 j），意思是向外国销售。", "外间": "外间 wàijiān 与 外交 wàijiāo 第二个音节韵母不同（ian 与 iao），意思是外面、外界。", "未交": "未交 wèijiāo 与 外交 wàijiāo 第一个音节韵母不同（ei 与 ai），意思是还没有交出。"}, "sentence_index": null, "correct_answer": "外交"}, "level_3": {"options": [{"text": "外交", "is_correct": true, "explanation": "正确。外交能让两国成为朋友，是国家之间的正式往来。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“钢琴”是乐器，不能让两国成为朋友。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是口语化的闲话，与正式的国际关系语境不合。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：“铅笔”是文具，与两国关系无关。"}], "explanations": {"外交": "正确。外交能让两国成为朋友，是国家之间的正式往来。", "钢琴": "语义：“钢琴”是乐器，不能让两国成为朋友。", "八卦": "语域：“八卦”是口语化的闲话，与正式的国际关系语境不合。", "铅笔": "语义：“铅笔”是文具，与两国关系无关。"}, "sentence_index": 6, "correct_answer": "外交"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "外交就是国家之间做买卖。", "explanation": "这里应该用〈外贸〉。外交指政府之间的谈判与往来，国家间做买卖属于外贸。"}, {"text": "外交就是人们出去看风景。", "explanation": "这里应该用〈旅游〉。外交是国家之间的正式交涉，不是游览。"}, {"text": "他的外交很好看，穿着很讲究。", "explanation": "这里的“外交”被当成〈外表〉来用；外交指国家间的往来，形容人的外貌要用“外表”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.promp