INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87009, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们需要加强一个外交。", "corrected_sentence": "我们需要加强外交。", "error_description": "错误在于“外交”前多了量词“一个”。“外交”是抽象名词，不能用“个”来计数；应说“我们需要加强外交”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87009, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她外交工作很久了。", "corrected_sentence": "她做外交工作很久了。", "error_description": "漏字错误：漏掉了动词“做”。“外交工作”要由“做”带出，应说“她做外交工作很久了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87010, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内政", "is_correct": true, "explanation": "正确。内政指国家内部的政务，与面向别国的外交正好相对。"}, {"text": "旅游", "is_correct": false, "explanation": "旅游与外交不构成反义关系，不能成对。"}, {"text": "体育", "is_correct": false, "explanation": "体育与外交不构成反义关系，不能成对。"}, {"text": "农业", "is_correct": false, "explanation": "农业与外交不构成反义关系，不能成对。"}], "correct_answer": "内政", "explanations": {"内政": "正确。内政指国家内部的政务，与面向别国的外交正好相对。", "旅游": "旅游与外交不构成反义关系，不能成对。", "体育": "体育与外交不构成反义关系，不能成对。", "农业": "农业与外交不构成反义关系，不能成对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
