INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87010, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家之间为处理相互关系而进行的交往和谈判等活动。", "primary_collocate": null, "pronunciation": "wài jiāo", "ipa": "waɪ˥˩ tɕiɑʊ˥", "syllable_count": 2, "sentences": [{"text": "两国通过外交谈判解决了问题。", "target_word": "外交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的外交政策没有变。", "target_word": "外交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年来，两国的外交活动很多。", "target_word": "外交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外交让两国关系变好了。", "target_word": "外交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在大学研究国家的外交历史。", "target_word": "外交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小国也要有自己的外交。", "target_word": "外交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争以后，两国开始了外交谈判。", "target_word": "外交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外交需要耐心和智慧。", "target_word": "外交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家之间的外交关系越来越近。", "target_word": "外交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的外交经验很多。", "target_word": "外交", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "外交政策", "label": "复合"}], "register": "正式", "sense_fingerprint": "国家之间处理关系的交往和谈判活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10a82993-50d4-4381-a959-52d6505f63fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87010, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "外交", "is_correct": true, "explanation": "正确。外交 wàijiāo，指国家之间为处理关系而进行的交往和谈判。"}, {"text": "外教", "is_correct": false, "explanation": "外教 wàijiào 与 外交 wàijiāo 第二个音节声调不同（交 jiāo 第一声，教 jiào 第四声），意思是外国教师。"}, {"text": "外销", "is_correct": false, "explanation": "外销 wàixiāo 与 外交 wàijiāo 声母不同（x 与 j），意思是向外国销售。"}, {"text": "外角", "is_correct": false, "explanation": "外角 wàijiǎo 与 外交 wàijiāo 第二个音节声调不同（角 jiǎo 第三声），意思是外侧的角。"}], "explanations": {"外交": "正确。外交 wàijiāo，指国家之间为处理关系而进行的交往和谈判。", "外教": "外教 wàijiào 与 外交 wàijiāo 第二个音节声调不同（交 jiāo 第一声，教 jiào 第四声），意思是外国教师。", "外销": "外销 wàixiāo 与 外交 wàijiāo 声母不同（x 与 j），意思是向外国销售。", "外角": "外角 wàijiǎo 与 外交 wàijiāo 第二个音节声调不同（角 jiǎo 第三声），意思是外侧的角。"}, "sentence_index": null, "correct_answer": "外交"}, "level_3": {"options": [{"text": "外交", "is_correct": true, "explanation": "正确。两国通过外交谈判解决问题，“外交”修饰“谈判”。"}, {"text": "足球", "is_correct": false, "explanation": "语义：“足球”是体育运动，不能用来解决两国之间的问题。"}, {"text": "大哥", "is_correct": false, "explanation": "语域：“大哥”是口语化的称呼，不适合正式的国家谈判语境。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：“蛋糕”是食品，与国家间的谈判无关。"}], "explanations": {"外交": "正确。两国通过外交谈判解决问题，“外交”修饰“谈判”。", "足球": "语义：“足球”是体育运动，不能用来解决两国之间的问题。", "大哥": "语域：“大哥”是口语化的称呼，不适合正式的国家谈判语境。", "蛋糕": "语义：“蛋糕”是食品，与国家间的谈判无关。"}, "sentence_index": 0, "correct_answer": "外交"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国的银行之间每天都做很多外交。", "explanation": "这里应该用〈外汇〉。外交指国家间的官方交涉，银行间的货币兑换要说“外汇”。"}, {"text": "我们班的老师每周都有很多外交。", "explanation": "这里应该用〈会议〉。外交指国家间的官方交涉，班里老师的例会要说“会议”。"}, {"text": "外交让孩子的成绩变好了。", "explanation": "这里的“外交”被当成〈教育〉来用；孩子的成绩要靠学习和教育，外交只指国家之间的交涉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87010, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "外交", "is_correct": true, "explanation": "正确。外交 wàijiāo，指国家之间为处理关系而进行的交往和谈判。"}, {"text": "未交", "is_correct": false, "explanation": "未交 wèijiāo 与 外交 wàijiāo 第一个音节韵母不同（ei 与 ai），意思是还没有交出。"}, {"text": "外销", "is_correct": false, "explanation": "外销 wàixiāo 与 外交 wàijiāo 声母不同（x 与 j），意思是向外国销售。"}, {"text": "外间", "is_correct": false, "explanation": "外间 wàijiān 与 外交 wàijiāo 第二个音节韵母不同（ian 与 iao），意思是外面、外界。"}], "explanations": {"外交": "正确。外交 wàijiāo，指国家之间为处理关系而进行的交往和谈判。", "未交": "未交 wèijiāo 与 外交 wàijiāo 第一个音节韵母不同（ei 与 ai），意思是还没有交出。", "外销": "外销 wàixiāo 与 外交 wàijiāo 声母不同（x 与 j），意思是向外国销售。", "外间": "外间 wàijiān 与 外交 wàijiāo 第二个音节韵母不同（ian 与 iao），意思是外面、外界。"}, "sentence_index": null, "correct_answer": "外交"}, "level_3": {"options": [{"text": "外交", "is_correct": true, "explanation": "正确。战争以后两国开始的是外交谈判，“外交”修饰“谈判”。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：“菜单”是点菜的单子，不能用来进行国家间的谈判。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：“婚礼”是婚庆仪式，与战后两国的谈判无关。"}, {"text": "盐", "is_correct": false, "explanation": "搭配：“谈判”前一般不能接“盐”这样的调味品。"}], "explanations": {"外交": "正确。战争以后两国开始的是外交谈判，“外交”修饰“谈判”。", "菜单": "语义：“菜单”是点菜的单子，不能用来进行国家间的谈判。", "婚礼": "语义：“婚礼”是婚庆仪式，与战后两国的谈判无关。", "盐": "搭配：“谈判”前一般不能接“盐”这样的调味品。"}, "sentence_index": 6, "correct_answer": "外交"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校里有很多外交。", "explanation": "这里应该用〈外教〉。外交指国家间的官方往来，学校里的外国老师要说“外教”。"}, {"text": "她穿了一件新的外交。", "explanation": "这里应该用〈外套〉。外交指国家间的官方往来，穿在身上的衣服要说“外套”。"}, {"text": "他是一位很有名的外交医生。", "explanation": "这里应该用〈外科〉。外交指国家间的交涉，做手术的医生要说“外科”医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两国通过外交了化解了矛盾。", "corrected_sentence": "两国通过外交化解了矛盾。", "error_description": "错误：“了”多出一个，放在“外交”之后是多余的，应去掉；“化解了”中的“了”已经足够。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国都重视一个外交。", "corrected_sentence": "两国都重视外交。", "error_description": "量词错误：“外交”是抽象名词，前面不能加“一个”；应说“两国都重视外交”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7978dd81-c7a5-479f-94f1-4162974bb544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
