INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87012, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "构成一个整体的最基础的组成单位。", "primary_collocate": null, "pronunciation": "jī běn dān wèi", "ipa": "tɕi˥ pən˨˩ tan˥ uei˥˩", "syllable_count": 4, "sentences": [{"text": "家庭是社会的基本单位。", "target_word": "基本单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "细胞是生命的基本单位。", "target_word": "基本单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班级是学校管理的基本单位。", "target_word": "基本单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原子是构成物质的基本单位。", "target_word": "基本单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "句子是语言表达的基本单位。", "target_word": "基本单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司以小组作为工作的基本单位。", "target_word": "基本单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在军队里，班是最小的基本单位。", "target_word": "基本单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把一个家庭当作统计的基本单位。", "target_word": "基本单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "字是汉语书写的基本单位。", "target_word": "基本单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个游戏里，每个小队是比赛的基本单位。", "target_word": "基本单位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "构成整体的最基础的组成单位，如家庭、细胞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba8f283-b84f-405a-98d3-c66977be6fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87012, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：颜色是物体的外观，不能指社会的组成单位。"}, {"text": "基本单位", "is_correct": true, "explanation": "正确。家庭是社会的基本单位，与“家庭是社会的……”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是天象，不能是社会的组成部分。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的身体条件，不能用来指家庭。"}], "explanations": {"颜色": "语义：颜色是物体的外观，不能指社会的组成单位。", "基本单位": "正确。家庭是社会的基本单位，与“家庭是社会的……”相符。", "天气": "语义：天气是天象，不能是社会的组成部分。", "身高": "体貌：身高是人的身体条件，不能用来指家庭。"}, "sentence_index": 0, "correct_answer": "基本单位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的基本单位很低。", "explanation": "这里应该用〈气温〉。基本单位是构成整体的最基础的单位，天气的冷暖要说气温。"}, {"text": "他的基本单位很深。", "explanation": "这里应该用〈伤口〉。基本单位不能表示伤口的深浅，身体受伤的程度要说伤口深。"}, {"text": "这盏灯的基本单位很高。", "explanation": "这里应该用〈亮度〉。基本单位不能表示灯光的明暗，应说亮度高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87012, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "语义：味道是食物或气体的感受，不能指军队里的组织单位。"}, {"text": "基本单位", "is_correct": true, "explanation": "正确。在军队里，班是最小的基本单位，与“班是最小的……”相符。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能用来指班这种组织。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指人或事物存在的时间，不能说“班是最小的年龄”。"}], "explanations": {"味道": "语义：味道是食物或气体的感受，不能指军队里的组织单位。", "基本单位": "正确。在军队里，班是最小的基本单位，与“班是最小的……”相符。", "身材": "体貌：身材指人的体形，不能用来指班这种组织。", "年龄": "语义：年龄指人或事物存在的时间，不能说“班是最小的年龄”。"}, "sentence_index": 6, "correct_answer": "基本单位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他今天的基本单位很好。", "explanation": "这里应该用〈心情〉。基本单位不能表示人的情绪，应说心情好。"}, {"text": "这碗汤的基本单位很鲜。", "explanation": "这里应该用〈味道〉。基本单位不能表示食物的滋味，应说味道鲜。"}, {"text": "这朵花的基本单位很鲜艳。", "explanation": "这里应该用〈颜色〉。基本单位不能表示花的颜色，应说颜色鲜艳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个游戏有三只基本单位。", "corrected_sentence": "这个游戏有三个基本单位。", "error_description": "「基本单位」的量词应为「个」。「只」用于动物或成对东西中的一个，不能用来数「基本单位」。正确说法：这个游戏有三个基本单位。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个游戏有两条基本单位。", "corrected_sentence": "这个游戏有两个基本单位。", "error_description": "「基本单位」的量词应为「个」。「条」用于细长的东西，不能用来数「基本单位」。正确说法：这个游戏有两个基本单位。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
