INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87013, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桌子上放着一张新的白纸，旁边有一张书。", "corrected_sentence": "桌子上放着一张新的白纸，旁边有一本书。", "error_description": "量词错误：“书”是装订成册的，应该用“本”，不能用“张”（“张”用于纸、票等平面的东西）。应说“旁边有一本书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87013, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "信封里有一张生日卡片，桌上有一张电脑。", "corrected_sentence": "信封里有一张生日卡片，桌上有一台电脑。", "error_description": "量词错误：“电脑”是机器，应该用“台”，不能用“张”（“张”用于纸、票等平面的东西）。应说“桌上有一台电脑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
