INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87014, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于床、嘴、脸、网、弓等有平面或能张合的东西。", "primary_collocate": null, "pronunciation": "zhāng", "ipa": "ʈʂɑŋ˥", "syllable_count": 1, "sentences": [{"text": "我房间里有一张床。", "target_word": "张", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他有一张很会说话的嘴。", "target_word": "张", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她有一张圆圆的小脸。", "target_word": "张", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "渔夫在河边放了一张大网。", "target_word": "张", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张床太小，爸爸睡不下。", "target_word": "张", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客厅里有一张大沙发。", "target_word": "张", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "照片里那张脸我很熟。", "target_word": "张", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她那张小嘴一直说个不停。", "target_word": "张", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "船上挂着一张大帆，顺风向前驶去。", "target_word": "张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把一张旧弓挂在墙上。", "target_word": "张", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "張", "label": "繁体"}, {"form": "张张", "label": "重叠"}], "register": "中性", "sense_fingerprint": "量词，用于床、嘴、脸、网、弓、沙发等有平面或能张合的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: 3 words above tier T1 (max 2): 帆 (Zipf 3.19), 顺风 (Zipf 3.58), 驶 (Zipf 3.52)']::text[], 'ef6fb817-c5a5-47d1-a0ed-24e25267f898') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87014, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "张", "is_correct": true, "explanation": "张 zhāng（第一声）：本题词目，量词，用于床、脸等有平面或能张合的东西。"}, {"text": "账", "is_correct": false, "explanation": "zhàng（第四声）与 zhāng（第一声）声调不同，意思是账目。"}, {"text": "涨", "is_correct": false, "explanation": "zhǎng（第三声）与 zhāng（第一声）声调不同，意思是上涨。"}, {"text": "争", "is_correct": false, "explanation": "zhēng 与 zhāng 韵母不同（eng 与 ang），意思是争夺。"}], "explanations": {"张": "张 zhāng（第一声）：本题词目，量词，用于床、脸等有平面或能张合的东西。", "账": "zhàng（第四声）与 zhāng（第一声）声调不同，意思是账目。", "涨": "zhǎng（第三声）与 zhāng（第一声）声调不同，意思是上涨。", "争": "zhēng 与 zhāng 韵母不同（eng 与 ang），意思是争夺。"}, "sentence_index": null, "correct_answer": "张"}, "level_3": {"options": [{"text": "张", "is_correct": true, "explanation": "张：量词，用于床等有平面的东西，符合句意。"}, {"text": "座", "is_correct": false, "explanation": "搭配：“座”用于山、桥、大型建筑等，不能用于床。"}, {"text": "辆", "is_correct": false, "explanation": "搭配：“辆”用于车辆，不能用于床。"}, {"text": "本", "is_correct": false, "explanation": "语义：“本”指书册，与“床”的语义不合。"}], "explanations": {"张": "张：量词，用于床等有平面的东西，符合句意。", "座": "搭配：“座”用于山、桥、大型建筑等，不能用于床。", "辆": "搭配：“辆”用于车辆，不能用于床。", "本": "语义：“本”指书册，与“床”的语义不合。"}, "sentence_index": 0, "correct_answer": "张"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "渔夫在河边放了一根大网。", "explanation": "这里应该用〈张〉。“根”用于细长的东西，网不这么数。"}, {"text": "渔夫在河边放了一顶大网。", "explanation": "这里应该用〈张〉。“顶”用于帽子、帐篷等，渔网不这么数。"}, {"text": "渔夫在河边放了一枚大网。", "explanation": "这里应该用〈张〉。“枚”用于硬币、徽章等小件物品，渔网不这么数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87014, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "张", "is_correct": true, "explanation": "张 zhāng（第一声）：本题词目，量词，用于脸等有平面或能张合的东西。"}, {"text": "掌", "is_correct": false, "explanation": "zhǎng（第三声）与 zhāng（第一声）声调不同，意思是手掌。"}, {"text": "蒸", "is_correct": false, "explanation": "zhēng 与 zhāng 韵母不同（eng 与 ang），意思是蒸煮。"}, {"text": "伤", "is_correct": false, "explanation": "shāng 与 zhāng 声母不同（sh 与 zh），意思是受伤。"}], "explanations": {"张": "张 zhāng（第一声）：本题词目，量词，用于脸等有平面或能张合的东西。", "掌": "zhǎng（第三声）与 zhāng（第一声）声调不同，意思是手掌。", "蒸": "zhēng 与 zhāng 韵母不同（eng 与 ang），意思是蒸煮。", "伤": "shāng 与 zhāng 声母不同（sh 与 zh），意思是受伤。"}, "sentence_index": null, "correct_answer": "张"}, "level_3": {"options": [{"text": "张", "is_correct": true, "explanation": "张：量词，用于脸，符合句意。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”多用于动物或成对器官中的一个，与整张脸的整体性冲突。"}, {"text": "棵", "is_correct": false, "explanation": "搭配：“棵”用于树木等植物，不能用于脸。"}, {"text": "颗", "is_correct": false, "explanation": "搭配：“颗”用于粒状的圆物，不能用于脸。"}], "explanations": {"张": "张：量词，用于脸，符合句意。", "只": "语义：“只”多用于动物或成对器官中的一个，与整张脸的整体性冲突。", "棵": "搭配：“棵”用于树木等植物，不能用于脸。", "颗": "搭配：“颗”用于粒状的圆物，不能用于脸。"}, "sentence_index": 6, "correct_answer": "张"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老人把一幅旧弓挂在墙上。", "explanation": "这里应该用〈张〉。“幅”用于字画、图画，弓不这么数。"}, {"text": "老人把一首旧弓挂在墙上。", "explanation": "这里应该用〈张〉。“首”用于诗歌、歌曲，弓不这么数。"}, {"text": "老人把一篇旧弓挂在墙上。", "explanation": "这里应该用〈张〉。“篇”用于文章，弓不这么数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warning