INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "阳台上放着一张旧沙发，他的一张脚受伤了。", "corrected_sentence": "阳台上放着一张旧沙发，他的一只脚受伤了。", "error_description": "量词错误：“脚”成对，应该用“只”，不能用“张”（“张”用于床、脸等有平面或能张合的东西）。应说“他的一只脚受伤了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "照片里那张脸我很熟，他的一张腿受伤了。", "corrected_sentence": "照片里那张脸我很熟，他的一条腿受伤了。", "error_description": "量词错误：“腿”用“条”，不能用“张”（“张”用于脸、床等有平面或能张合的东西）。应说“他的一条腿受伤了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87017, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "挖", "is_correct": true, "explanation": "挖是掘出，与填把空处塞满的动作相反，是这个义项的反义词。"}, {"text": "走", "is_correct": false, "explanation": "走是移动，与填没有反义关系。"}, {"text": "笑", "is_correct": false, "explanation": "笑指表情或声音，与填没有反义关系。"}, {"text": "看", "is_correct": false, "explanation": "看是用眼睛注意，与填没有反义关系。"}], "correct_answer": "挖", "explanations": {"挖": "挖是掘出，与填把空处塞满的动作相反，是这个义项的反义词。", "走": "走是移动，与填没有反义关系。", "笑": "笑指表情或声音，与填没有反义关系。", "看": "看是用眼睛注意，与填没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
