INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87017, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "填是把东西放进空的地方，让它满起来。", "primary_collocate": null, "pronunciation": "tián", "ipa": "tʰjɛn˧˥", "syllable_count": 1, "sentences": [{"text": "工人用土把坑填上了。", "target_word": "填", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿石头去填那个小洞。", "target_word": "填", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有个坑，请找人填一填。", "target_word": "填", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在沙滩上用沙子填了一个洞。", "target_word": "填", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个洞太深，一车土填不满。", "target_word": "填", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把墙上的洞填好了。", "target_word": "填", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把池里的水放掉，再填上土。", "target_word": "填", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边挖一边填，忙了一上午。", "target_word": "填", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坑里填着很多石头。", "target_word": "填", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心点，别踩进没填好的坑里。", "target_word": "填", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "填了", "label": "体标"}, {"form": "填过", "label": "体标"}, {"form": "填着", "label": "体标"}, {"form": "填一填", "label": "重叠"}, {"form": "填满", "label": "复合词"}], "register": "中性", "sense_fingerprint": "把东西放进坑洞等空处，使其满", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d9b7acb-06c4-4953-b400-63e6e8a36ece') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87017, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "填", "is_correct": true, "explanation": "填是把东西放进空的地方，使它满，如“填坑”，读作 tián（第二声）。"}, {"text": "天", "is_correct": false, "explanation": "tiān（第一声）与 tián（第二声）声调不同，意思是天空。"}, {"text": "添", "is_correct": false, "explanation": "tiān（第一声）与 tián（第二声）声调不同，意思是增加、加上。"}, {"text": "前", "is_correct": false, "explanation": "qián（第二声）与 tián（第二声）只差声母 q 与 t，声调相同，意思是前面。"}], "explanations": {"填": "填是把东西放进空的地方，使它满，如“填坑”，读作 tián（第二声）。", "天": "tiān（第一声）与 tián（第二声）声调不同，意思是天空。", "添": "tiān（第一声）与 tián（第二声）声调不同，意思是增加、加上。", "前": "qián（第二声）与 tián（第二声）只差声母 q 与 t，声调相同，意思是前面。"}, "sentence_index": null, "correct_answer": "填"}, "level_3": {"options": [{"text": "挖", "is_correct": false, "explanation": "语义：“挖”是掘出，不是把土放进坑里，与句中“上了”的意思冲突。"}, {"text": "填", "is_correct": true, "explanation": "填是把土放进坑里使坑满，与句意一致。"}, {"text": "踩", "is_correct": false, "explanation": "搭配：“踩”接的是脚所踏之处，不说“用土踩坑”。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语应是可以吃的东西，不能以“坑”为对象。"}], "explanations": {"挖": "语义：“挖”是掘出，不是把土放进坑里，与句中“上了”的意思冲突。", "填": "填是把土放进坑里使坑满，与句意一致。", "踩": "搭配：“踩”接的是脚所踏之处，不说“用土踩坑”。", "吃": "配价：“吃”的宾语应是可以吃的东西，不能以“坑”为对象。"}, "sentence_index": 0, "correct_answer": "填"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈往汤里填了一勺盐。", "explanation": "这里应该用〈添〉。添是往某物里再加入东西，填是把空缺塞满；汤里没有空缺，不说“填”。"}, {"text": "他把牛奶填进了杯子里。", "explanation": "这里应该用〈倒〉。倒是把液体注入容器，填用于把固体塞进空缺；牛奶是液体，不说“填”。"}, {"text": "他在桌子腿下填了一张纸。", "explanation": "这里应该用〈垫〉。垫是放在物体底下使其加高或平稳，填是把东西塞进空缺使其满；在桌腿下放纸只能说“垫”，不说“填”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87017, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "填", "is_correct": true, "explanation": "填是把东西放进空的地方，使它满，如“填坑”，读作 tián（第二声）。"}, {"text": "钱", "is_correct": false, "explanation": "qián（第二声）与 tián 只差声母 q 与 t，声调相同，意思是钱财。"}, {"text": "年", "is_correct": false, "explanation": "nián 与 tián 声母不同（n 与 t），声调相同，意思是年份。"}, {"text": "连", "is_correct": false, "explanation": "lián 与 tián 声母不同（l 与 t），声调相同，意思是连接。"}, {"text": "闲", "is_correct": false, "explanation": "xián 与 tián 声母不同（x 与 t），声调相同，意思是空闲。"}], "explanations": {"填": "填是把东西放进空的地方，使它满，如“填坑”，读作 tián（第二声）。", "钱": "qián（第二声）与 tián 只差声母 q 与 t，声调相同，意思是钱财。", "年": "nián 与 tián 声母不同（n 与 t），声调相同，意思是年份。", "连": "lián 与 tián 声母不同（l 与 t），声调相同，意思是连接。", "闲": "xián 与 tián 声母不同（x 与 t），声调相同，意思是空闲。"}, "sentence_index": null, "correct_answer": "填"}, "level_3": {"options": [{"text": "洗", "is_correct": false, "explanation": "语义：“洗”是用水去污，不能把土加到上面。"}, {"text": "填", "is_correct": true, "explanation": "填是把土放进去使其满，与句意一致。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”的宾语应是歌曲，不能以“土”为对象。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”是抹去，与“再……上土”的加入之意相反。"}], "explanations": {"洗": "语义：“洗”是用水去污，不能把土加到上面。", "填": "填是把土放进去使其满，与句意一致。", "唱": "配价：“唱”的宾语应是歌曲，不能以“土”为对象。", "擦": "语义：“擦”是抹去，与“再……上土”的加入之意相反。"}, "sentence_index": 6, "correct_answer": "填"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钥匙填进了锁眼里。", "explanation": "这里应该用〈插〉。插是把细长的东西伸进窄孔，填是把空缺塞满；钥匙插进锁眼不说“填”。"}, {"text": "他把那幅画填在墙上。", "explanation": "这里应该用〈挂〉。挂是把东西悬挂起来，填是把空缺塞满；画挂在墙上不说“填”。"}, {"text": "他拿刷子在墙上填了一层白漆。", "explanation": "这里应该用〈刷〉。刷是用刷子把涂料涂在表面，填是把空缺塞满；往墙上刷漆只能说“刷”，不说“填”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87017, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们把坑填了平。", "corrected_sentence": "他们把坑填平了。", "error_description": "错误形式“填了平”。结果补语“平”紧跟动词，了应放在补语之后，正确说法是“填平了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87017, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年填了过那个坑。", "corrected_sentence": "他去年填过那个坑。", "error_description": "错误形式“填了过那个坑”。「了」和「过」不能同时用在「填」后，去掉「了」，正确说法是「填过那个坑」，表示过去曾经做过这件事。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
