INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87018, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在表格或空格里写上内容。", "primary_collocate": null, "pronunciation": "tián", "ipa": "tʰjɛn˧˥", "syllable_count": 1, "sentences": [{"text": "请在表格里填你的名字。", "target_word": "填", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张表要填两次吗？", "target_word": "填", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在空格里填了一个字。", "target_word": "填", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，先填好这张表再走。", "target_word": "填", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了填电话号码。", "target_word": "填", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "填完表，请交给前台。", "target_word": "填", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地址写错了，请重新填。", "target_word": "填", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在登记表上填着年龄。", "target_word": "填", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里该填什么词？", "target_word": "填", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在表格的空白处填上了日期。", "target_word": "填", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "填了", "label": "体标"}, {"form": "填过", "label": "体标"}, {"form": "填着", "label": "体标"}, {"form": "填一填", "label": "重叠"}, {"form": "填写", "label": "复合词"}, {"form": "填空", "label": "复合词"}], "register": "中性", "sense_fingerprint": "在表格或空格里写上内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d9b7acb-06c4-4953-b400-63e6e8a36ece') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87018, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "填", "is_correct": true, "explanation": "填是在表格或空格里写上内容，读作 tián（第二声）。"}, {"text": "天", "is_correct": false, "explanation": "tiān（第一声）与 tián（第二声）声调不同，意思是天空。"}, {"text": "舔", "is_correct": false, "explanation": "tiǎn（第三声）与 tián（第二声）声调不同，意思是用舌头碰。"}, {"text": "前", "is_correct": false, "explanation": "qián（第二声）与 tián（第二声）只差声母 q 与 t，声调相同，意思是前面。"}], "explanations": {"填": "填是在表格或空格里写上内容，读作 tián（第二声）。", "天": "tiān（第一声）与 tián（第二声）声调不同，意思是天空。", "舔": "tiǎn（第三声）与 tián（第二声）声调不同，意思是用舌头碰。", "前": "qián（第二声）与 tián（第二声）只差声母 q 与 t，声调相同，意思是前面。"}, "sentence_index": null, "correct_answer": "填"}, "level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "配价：“喝”的宾语应是饮料，不能说“喝你的名字”。"}, {"text": "填", "is_correct": true, "explanation": "填是在表格的空格里写上内容，与句意一致。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”要求歌曲作宾语，不能说“唱你的名字”。"}, {"text": "踩", "is_correct": false, "explanation": "搭配：“踩”接的是脚所踏之处，不说“在表格里踩名字”。"}], "explanations": {"喝": "配价：“喝”的宾语应是饮料，不能说“喝你的名字”。", "填": "填是在表格的空格里写上内容，与句意一致。", "唱": "配价：“唱”要求歌曲作宾语，不能说“唱你的名字”。", "踩": "搭配：“踩”接的是脚所踏之处，不说“在表格里踩名字”。"}, "sentence_index": 0, "correct_answer": "填"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在纸上填了一首诗。", "explanation": "这里应该用〈写〉。写可以在白纸上进行，填用于表格、空格等有空位的地方；在白纸上写诗不说“填”。"}, {"text": "他把老师的地址填在墙上。", "explanation": "这里应该用〈写〉。写可以写在任何地方，填只用于表格、空格等留有空位的地方；墙上没有空格，不说“填”。"}, {"text": "他在电脑上填了一封信。", "explanation": "这里应该用〈打〉。打是用键盘输入文字，填是在表格或空格里写上内容；在电脑上打信不说“填”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87018, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "填", "is_correct": true, "explanation": "填是在表格或空格里写上内容，读作 tián（第二声）。"}, {"text": "钱", "is_correct": false, "explanation": "qián（第二声）与 tián 只差声母 q 与 t，声调相同，意思是钱财。"}, {"text": "连", "is_correct": false, "explanation": "lián 与 tián 声母不同（l 与 t），声调相同，意思是连接。"}, {"text": "闲", "is_correct": false, "explanation": "xián 与 tián 声母不同（x 与 t），声调相同，意思是空闲。"}], "explanations": {"填": "填是在表格或空格里写上内容，读作 tián（第二声）。", "钱": "qián（第二声）与 tián 只差声母 q 与 t，声调相同，意思是钱财。", "连": "lián 与 tián 声母不同（l 与 t），声调相同，意思是连接。", "闲": "xián 与 tián 声母不同（x 与 t），声调相同，意思是空闲。"}, "sentence_index": null, "correct_answer": "填"}, "level_3": {"options": [{"text": "洗", "is_correct": false, "explanation": "语义：“洗”是用水去污，不能用来指重新写地址。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”要求食物作宾语，不能说“重新吃”地址。"}, {"text": "挖", "is_correct": false, "explanation": "语义：“挖”是掘出，与“重新”写内容的意思不合。"}, {"text": "填", "is_correct": true, "explanation": "填是在表格或空格里重新写上内容，与句意一致。"}], "explanations": {"洗": "语义：“洗”是用水去污，不能用来指重新写地址。", "吃": "配价：“吃”要求食物作宾语，不能说“重新吃”地址。", "挖": "语义：“挖”是掘出，与“重新”写内容的意思不合。", "填": "填是在表格或空格里重新写上内容，与句意一致。"}, "sentence_index": 6, "correct_answer": "填"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把几枝花填进了花瓶里。", "explanation": "这里应该用〈插〉。插是把细长的东西伸进窄口或孔中，填是把空缺塞满；把花插进花瓶不说“填”。"}, {"text": "他拿刷子在墙上填了一层白漆。", "explanation": "这里应该用〈涂〉。涂是把颜料均匀抹在表面，填是在空格里写上内容；刷漆不说“填”。"}, {"text": "他往瓶子里填了一些水。", "explanation": "这里应该用〈灌〉。灌是把液体注入容器，填用于把固体塞进空缺或写上内容；水是液体，不说“填”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我填了过这张表。", "corrected_sentence": "我填过这张表。", "error_description": "错误形式“我填了过这张表”。“了”与“过”不能同时用于同一个动词，应去掉“了”，写作“我填过这张表”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把那张表填了完。", "corrected_sentence": "他把那张表填完了。", "error_description": "错误形式“填了完”。结果补语“完”应紧跟动词，了放在补语之后，正确说法是“填完了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df7b5f9-a36d-419e-b476-086e255fd5f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87019, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放", "is_correct": true, "explanation": "反义：“抓起”是拿起，“放下”是松手放下，二者构成反义关系。"}, {"text": "送", "is_correct": false, "explanation": "送是给予、递交，与“抓”不构成反义关系。"}, {"text": "推", "is_correct": false, "explanation": "推是用力使物体移动，与“抓”的拿住义没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "吃是把食物咽下，与“抓”没有反义关系。"}], "correct_answer": "放", "explanations": {"放": "反义：“抓起”是拿起，“放下”是松手放下，二者构成反义关系。", "送": "送是给予、递交，与“抓”不构成反义关系。", "推": "推是用力使物体移动，与“抓”的拿住义没有反义关系。", "吃": "吃是把食物咽下，与“抓”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87019, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放", "is_correct": true, "explanation": "反义：“抓”是握住，“放开”是松开，二者构成反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱是发声唱歌，与“抓”没有反义关系。"}, {"text": "画", "is_correct": false, "explanation": "画是用笔描绘，与“抓”没有反义关系。"}, {"text": "喝", "is_correct": false, "explanation": "喝是把液体咽下，与“抓”没有反义关系。"}], "correct_answer": "放", "explanations": {"放": "反义：“抓”是握住，“放开”是松开，二者构成反义关系。", "唱": "唱是发声唱歌，与“抓”没有反义关系。", "画": "画是用笔描绘，与“抓”没有反义关系。", "喝": "喝是把液体咽下，与“抓”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87019, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "抓是用手紧紧拿住。", "primary_collocate": null, "pronunciation": "zhuā", "ipa": "ʈʂwa˥", "syllable_count": 1, "sentences": [{"text": "他用手抓一把米。", "target_word": "抓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小孩抓着我的手不放。", "target_word": "抓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在地铁里抓着扶手。", "target_word": "抓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抓起桌上的笔就写。", "target_word": "抓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她紧紧抓住妈妈的衣角。", "target_word": "抓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他伸手去抓掉下来的书。", "target_word": "抓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗抓不住那只球，球滚走了。", "target_word": "抓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸把我的书包抓在手里。", "target_word": "抓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，快抓住你的帽子！", "target_word": "抓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你抓一下我的手，别摔倒。", "target_word": "抓", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "抓了", "label": "体标（完成）"}, {"form": "抓着", "label": "体标（持续）"}, {"form": "抓过", "label": "体标（经历）"}, {"form": "抓住", "label": "复合词"}], "register": "口语", "sense_fingerprint": "用手紧紧拿住东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa572e2a-b4ac-45be-a597-2cd926dc15a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87019, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抓", "is_correct": true, "explanation": "正确答案：抓（zhuā，第一声），表示用手紧紧拿住东西。"}, {"text": "爪", "is_correct": false, "explanation": "zhuǎ（第三声）与 zhuā（第一声）声调不同，意思是动物的爪子。"}, {"text": "刷", "is_correct": false, "explanation": "shuā 与 zhuā 声母不同（sh 与 zh），意思是用刷子刷洗。"}, {"text": "砖", "is_correct": false, "explanation": "zhuān 与 zhuā 韵母不同（多了 n），意思是砖头。"}, {"text": "装", "is_correct": false, "explanation": "zhuāng 与 zhuā 韵母不同（多了 ng），意思是装载或安装。"}], "explanations": {"抓": "正确答案：抓（zhuā，第一声），表示用手紧紧拿住东西。", "爪": "zhuǎ（第三声）与 zhuā（第一声）声调不同，意思是动物的爪子。", "刷": "shuā 与 zhuā 声母不同（sh 与 zh），意思是用刷子刷洗。", "砖": "zhuān 与 zhuā 韵母不同（多了 n），意思是砖头。", "装": "zhuāng 与 zhuā 韵母不同（多了 ng），意思是装载或安装。"}, "sentence_index": null, "correct_answer": "抓"}, "level_3": {"options": [{"text": "抓", "is_correct": true, "explanation": "正确：“抓一把米”指用手抓取，与句中“用手”相合。"}, {"text": "画", "is_correct": false, "explanation": "语义：“画”指用笔描绘，与用手取米无关。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声唱歌，与用手取米无关。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”需要书写的对象，米不能被书写。"}], "explanations": {"抓": "正确：“抓一把米”指用手抓取，与句中“用手”相合。", "画": "语义：“画”指用笔描绘，与用手取米无关。", "唱": "语义：“唱”指发声唱歌，与用手取米无关。", "写": "配价：“写”需要书写的对象，米不能被书写。"}, "sentence_index": 0, "correct_answer": "抓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈抓开了书，认真地读起来。", "explanation": "这里应该用〈翻〉。抓是紧紧拿住，不能表示翻开书页。"}, {"text": "她用粉笔抓了几个字在黑板上。", "explanation": "这里应该用〈写〉。抓是用手紧紧拿住，不能表示用粉笔书写，写字要用“写”。"}, {"text": "他抓开了窗户，风吹了进来。", "explanation": "这里应该用〈打开〉。抓是紧紧拿住，不能表示开启窗户。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87019, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "抓", "is_correct": true, "explanation": "正确答案：抓（zhuā，第一声），表示用手紧紧拿住东西。"}, {"text": "专", "is_correct": false, "explanation": "zhuān 与 zhuā 韵母不同（多了 n），意思是专门、专业。"}, {"text": "庄", "is_correct": false, "explanation": "zhuāng 与 zhuā 韵母不同（多了 ng），意思是村庄或庄稼。"}, {"text": "妆", "is_correct": false, "explanation": "zhuāng 与 zhuā 韵母不同（多了 ng），意思是化妆。"}, {"text": "桩", "is_correct": false, "explanation": "zhuāng 与 zhuā 韵母不同（多了 ng），意思是木桩。"}], "explanations": {"抓": "正确答案：抓（zhuā，第一声），表示用手紧紧拿住东西。", "专": "zhuān 与 zhuā 韵母不同（多了 n），意思是专门、专业。", "庄": "zhuāng 与 zhuā 韵母不同（多了 ng），意思是村庄或庄稼。", "妆": "zhuāng 与 zhuā 韵母不同（多了 ng），意思是化妆。", "桩": "zhuāng 与 zhuā 韵母不同（多了 ng），意思是木桩。"}, "sentence_index": null, "correct_answer": "抓"}, "level_3": {"options": [{"text": "抓", "is_correct": true, "explanation": "正确：“抓不住”指拿不稳，与“小狗……那只球”的语境相合。"}, {"text": "喝", "is_correct": false, "explanation": "配价：“喝”的宾语应是饮料，不能以球为宾语。"}, {"text": "画", "is_correct": false, "explanation": "语义：“画”指用笔描绘，与拿住球无关。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”指用刀分开，与拿住球不合。"}], "explanations": {"抓": "正确：“抓不住”指拿不稳，与“小狗……那只球”的语境相合。", "喝": "配价：“喝”的宾语应是饮料，不能以球为宾语。", "画": "语义：“画”指用笔描绘，与拿住球无关。", "切": "语义：“切”指用刀分开，与拿住球不合。"}, "sentence_index": 6, "correct_answer": "抓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用抹布抓了一下桌子。", "explanation": "这里应该用〈擦〉。抓是拿住，不能用来擦拭桌面。"}, {"text": "他一下子就抓出了这道题的办法，很快就做完了。", "explanation": "这里应该用〈想出〉。抓是用手拿住，不能表示想出办法。"}, {"text": "他用力抓了一下门铃，门铃响了。", "explanation": "这里应该用〈按〉。抓是紧紧拿住，不能表示按下门铃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87019, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把伞抓很紧。", "corrected_sentence": "他把伞抓得很紧。", "error_description": "错误：“抓”后的补语要用“得”连接。正确形式是“抓得很紧”，不能省去“得”直接说“抓很紧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87019, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他紧紧抓了着绳子不放。", "corrected_sentence": "他紧紧抓着绳子不放。", "error_description": "错误：“抓”后表示持续的“着”不能与“了”同用。正确形式是“抓着”，不能说“抓了着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87020, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放", "is_correct": true, "explanation": "反义：“抓到”是把东西拿住，“放”是松开、放走，二者构成反义关系。"}, {"text": "送", "is_correct": false, "explanation": "送是给予、递交，与“抓”不构成反义关系。"}, {"text": "推", "is_correct": false, "explanation": "推是用力使物体移动，与“抓”的拿住、捉住义没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "吃是把食物咽下，与“抓”没有反义关系。"}], "correct_answer": "放", "explanations": {"放": "反义：“抓到”是把东西拿住，“放”是松开、放走，二者构成反义关系。", "送": "送是给予、递交，与“抓”不构成反义关系。", "推": "推是用力使物体移动，与“抓”的拿住、捉住义没有反义关系。", "吃": "吃是把食物咽下，与“抓”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87020, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放", "is_correct": true, "explanation": "反义：“抓紧”是握住不放，“放”是松开，二者构成反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱是发声唱歌，与“抓”没有反义关系。"}, {"text": "画", "is_correct": false, "explanation": "画是用笔描绘，与“抓”没有反义关系。"}, {"text": "喝", "is_correct": false, "explanation": "喝是把液体咽下，与“抓”没有反义关系。"}], "correct_answer": "放", "explanations": {"放": "反义：“抓紧”是握住不放，“放”是松开，二者构成反义关系。", "唱": "唱是发声唱歌，与“抓”没有反义关系。", "画": "画是用笔描绘，与“抓”没有反义关系。", "喝": "喝是把液体咽下，与“抓”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87020, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或爪子紧紧拿住；捉住。", "primary_collocate": null, "pronunciation": "zhuā", "ipa": "ʈʂwa˥", "syllable_count": 1, "sentences": [{"text": "他一把抓住了我的手。", "target_word": "抓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猫想抓桌子上的鱼。", "target_word": "抓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子用手抓着妈妈的衣服。", "target_word": "抓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察抓到了那个小偷。", "target_word": "抓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请抓好扶手，车要开了。", "target_word": "抓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他伸手抓了一把糖。", "target_word": "抓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "猫抓到老鼠，高兴极了。", "target_word": "抓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鸟用爪子抓着树枝。", "target_word": "抓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想抓住那只蝴蝶，可是它飞走了。", "target_word": "抓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把绳子抓得很紧，手心都出汗了。", "target_word": "抓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抓了", "label": "体标（完成）"}, {"form": "抓着", "label": "体标（持续）"}, {"form": "抓过", "label": "体标（经历）"}, {"form": "抓住", "label": "复合词"}], "register": "口语", "sense_fingerprint": "用手或爪子紧紧拿住、捉住人或动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: 3 words above tier T1 (max 2): 绳子 (Zipf 3.86), 手心 (Zipf 3.27), 出汗 (Zipf 3.34)']::text[], 'aa572e2a-b4ac-45be-a597-2cd926dc15a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87020, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抓", "is_correct": true, "explanation": "正确答案：抓（zhuā，第一声），表示用手或爪子紧紧拿住。"}, {"text": "爪", "is_correct": false, "explanation": "zhuǎ（第三声）与 zhuā（第一声）声调不同，意思是动物的爪子。"}, {"text": "刷", "is_correct": false, "explanation": "shuā 与 zhuā 声母不同（sh 与 zh），意思是用刷子刷洗。"}, {"text": "砖", "is_correct": false, "explanation": "zhuān 与 zhuā 韵母不同（多了 n），意思是砖头。"}, {"text": "装", "is_correct": false, "explanation": "zhuāng 与 zhuā 韵母不同（多了 ng），意思是装载或安装。"}], "explanations": {"抓": "正确答案：抓（zhuā，第一声），表示用手或爪子紧紧拿住。", "爪": "zhuǎ（第三声）与 zhuā（第一声）声调不同，意思是动物的爪子。", "刷": "shuā 与 zhuā 声母不同（sh 与 zh），意思是用刷子刷洗。", "砖": "zhuān 与 zhuā 韵母不同（多了 n），意思是砖头。", "装": "zhuāng 与 zhuā 韵母不同（多了 ng），意思是装载或安装。"}, "sentence_index": null, "correct_answer": "抓"}, "level_3": {"options": [{"text": "抓", "is_correct": true, "explanation": "正确：“抓住”指用手紧紧握住，与“一把”及“抓住了我的手”相合。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”指用刀分开，与用手握住别人的手不合。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指用笔书写，不能用来形容握住别人的手。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语应是食物，不能以“我的手”作宾语。"}], "explanations": {"抓": "正确：“抓住”指用手紧紧握住，与“一把”及“抓住了我的手”相合。", "切": "语义：“切”指用刀分开，与用手握住别人的手不合。", "写": "语义：“写”指用笔书写，不能用来形容握住别人的手。", "吃": "配价：“吃”的宾语应是食物，不能以“我的手”作宾语。"}, "sentence_index": 0, "correct_answer": "抓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子抓了一首歌，大家都很喜欢。", "explanation": "这里应该用〈唱〉。抓是用手拿住，不能表示唱歌，唱歌要用“唱”。"}, {"text": "他用毛笔抓了三个字，写得很漂亮。", "explanation": "这里应该用〈写〉。抓是用手紧紧拿住，不能表示书写，写字要用“写”。"}, {"text": "我抓了他一眼，他没有注意到。", "explanation": "这里应该用〈看〉。抓是拿住东西，不能用于视线，“抓一眼”不成词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87020, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "抓", "is_correct": true, "explanation": "正确答案：抓（zhuā，第一声），表示用手或爪子紧紧拿住。"}, {"text": "专", "is_correct": false, "explanation": "zhuān 与 zhuā 韵母不同（多了 n），意思是专门、专业。"}, {"text": "庄", "is_correct": false, "explanation": "zhuāng 与 zhuā 韵母不同（多了 ng），意思是村庄或庄稼。"}, {"text": "妆", "is_correct": false, "explanation": "zhuāng 与 zhuā 韵母不同（多了 ng），意思是化妆。"}, {"text": "桩", "is_correct": false, "explanation": "zhuāng 与 zhuā 韵母不同（多了 ng），意思是木桩。"}], "explanations": {"抓": "正确答案：抓（zhuā，第一声），表示用手或爪子紧紧拿住。", "专": "zhuān 与 zhuā 韵母不同（多了 n），意思是专门、专业。", "庄": "zhuāng 与 zhuā 韵母不同（多了 ng），意思是村庄或庄稼。", "妆": "zhuāng 与 zhuā 韵母不同（多了 ng），意思是化妆。", "桩": "zhuāng 与 zhuā 韵母不同（多了 ng），意思是木桩。"}, "sentence_index": null, "correct_answer": "抓"}, "level_3": {"options": [{"text": "抓", "is_correct": true, "explanation": "正确：“抓到”指用手或爪子捉住，与“猫……老鼠”的捕捉语境相合。"}, {"text": "画", "is_correct": false, "explanation": "语义：“画”指用笔描绘，与猫捕捉老鼠无关。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声唱歌，与捕捉老鼠无关。"}, {"text": "放", "is_correct": false, "explanation": "配价：“放”要求处所宾语，老鼠不是处所，不能说“放到老鼠”。"}], "explanations": {"抓": "正确：“抓到”指用手或爪子捉住，与“猫……老鼠”的捕捉语境相合。", "画": "语义：“画”指用笔描绘，与猫捕捉老鼠无关。", "唱": "语义：“唱”指发声唱歌，与捕捉老鼠无关。", "放": "配价：“放”要求处所宾语，老鼠不是处所，不能说“放到老鼠”。"}, "sentence_index": 6, "correct_answer": "抓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用力抓开了那扇门。", "explanation": "这里应该用〈推〉。抓是用手拿住，不能表示用力把门推开。"}, {"text": "他用手抓出了一道题的答案，很快就做完了。", "explanation": "这里应该用〈想出〉。抓是用手拿住，不能表示想出答案。"}, {"text": "他用毛巾抓桌子，把它擦干净了。", "explanation": "这里应该用〈擦〉。抓是拿住，不能用来擦拭桌面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
