INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87022, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "男女双方经法律或社会承认而结成夫妻的关系。", "primary_collocate": null, "pronunciation": "hūn yīn", "ipa": "xwən˥ in˥", "syllable_count": 2, "sentences": [{"text": "法律保护合法的婚姻。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家不承认这种婚姻。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的婚姻在法律上已经结束了。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结婚时要先到民政局登记，婚姻才有效。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚姻关系需要法律承认。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人没有登记，不算合法婚姻。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律规定，婚姻自由，别人不能干涉。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想结束这段婚姻，决定去法院。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官说，这段婚姻从一开始就无效。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离婚以后，婚姻关系就不存在了。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}], "register": "正式", "sense_fingerprint": "婚姻：经法律或社会承认的夫妻关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98bb113-2be5-474e-b481-0147080f3c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87022, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感情", "is_correct": false, "explanation": "语义：感情是心理状态，不是法律保护的关系，不能说“合法的感情”。"}, {"text": "婚姻", "is_correct": true, "explanation": "正确。“婚姻”是经法律承认的夫妻关系，可以“合法”，并受法律保护。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不可能“合法”，法律也不保护它。"}, {"text": "信用", "is_correct": false, "explanation": "搭配：“合法的”一般修饰婚姻、收入、行为，不说“合法的信用”。"}], "explanations": {"感情": "语义：感情是心理状态，不是法律保护的关系，不能说“合法的感情”。", "婚姻": "正确。“婚姻”是经法律承认的夫妻关系，可以“合法”，并受法律保护。", "天气": "语义：天气是自然现象，不可能“合法”，法律也不保护它。", "信用": "搭配：“合法的”一般修饰婚姻、收入、行为，不说“合法的信用”。"}, "sentence_index": 0, "correct_answer": "婚姻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们在律师的见证下签订了婚姻。", "explanation": "这里应该用〈合同〉。签订用于合同、协议，婚姻是关系，不能签订。"}, {"text": "他决定起诉婚姻。", "explanation": "这里应该用〈对方〉。起诉的对象是人或机构，婚姻是关系，不能被起诉。"}, {"text": "婚姻保护公民的权利。", "explanation": "这里应该用〈宪法〉。宪法是保护者，婚姻是关系，不能做“保护”的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c31f9a31-de21-4b9e-b3f4-0442fdf8b505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87022, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "语义：身高是身体特征，不属于可以“自由”选择、别人不能干涉的事。"}, {"text": "粮食", "is_correct": false, "explanation": "语义：粮食是物资，不是个人可以自由决定、受法律保护的关系。"}, {"text": "婚姻", "is_correct": true, "explanation": "正确。“婚姻自由”指结婚与否由个人决定，别人不能干涉，符合语境。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“自由”通常修饰婚姻、信仰、言论等，不说“工资自由”。"}], "explanations": {"身高": "语义：身高是身体特征，不属于可以“自由”选择、别人不能干涉的事。", "粮食": "语义：粮食是物资，不是个人可以自由决定、受法律保护的关系。", "婚姻": "正确。“婚姻自由”指结婚与否由个人决定，别人不能干涉，符合语境。", "工资": "搭配：“自由”通常修饰婚姻、信仰、言论等，不说“工资自由”。"}, "sentence_index": 6, "correct_answer": "婚姻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "婚姻在教堂举行，很多人都来了。", "explanation": "这里应该用〈婚礼〉。婚礼是可以举行的仪式，婚姻是关系，不能“举行”。"}, {"text": "这段婚姻有很多员工，大家都很努力。", "explanation": "这里应该用〈公司〉。公司有员工，婚姻是两人之间的关系，不能说有员工。"}, {"text": "他把婚姻搬上了车。", "explanation": "这里应该用〈行李〉。搬用于行李、家具等实物，婚姻是两人之间的法律关系，不能被搬动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c31f9a31-de21-4b9e-b3f4-0442fdf8b505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87022, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种婚姻被不法律承认。", "corrected_sentence": "这种婚姻不被法律承认。", "error_description": "否定词“不”应放在“被”之前。错误形式：被不法律承认；正确形式：不被法律承认。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c31f9a31-de21-4b9e-b3f4-0442fdf8b505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87022, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法院把这只婚姻判为无效。", "corrected_sentence": "法院把这段婚姻判为无效。", "error_description": "量词错误：“婚姻”应该用量词“段”，不能用“只”。错误形式：这只婚姻；正确形式：这段婚姻。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c31f9a31-de21-4b9e-b3f4-0442fdf8b505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
