INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87023, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "外出是从家里走到外面去，去别的地方。", "primary_collocate": null, "pronunciation": "wài chū", "ipa": "wai⁵¹ tʂʰu⁵⁵", "syllable_count": 2, "sentences": [{"text": "妈妈每天早上外出买菜。", "target_word": "外出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太冷了，我不想外出。", "target_word": "外出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他外出的时候忘了带钥匙。", "target_word": "外出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下大雨，请不要外出。", "target_word": "外出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷身体不好，很少外出。", "target_word": "外出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们外出玩儿，天黑才回来。", "target_word": "外出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外出时要把门关好。", "target_word": "外出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你外出了吗？我敲门没人应。", "target_word": "外出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今天没有外出，一直在家看书。", "target_word": "外出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他外出散步，走了一个小时。", "target_word": "外出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外出了", "label": "体标"}, {"form": "外出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "从家里走到外面去别的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bb5dbd0-8999-44e2-b7a7-f670f6a1f680') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87023, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "睡觉", "is_correct": false, "explanation": "语义：人睡觉时不能去买菜，「睡觉买菜」说不通。"}, {"text": "外出", "is_correct": true, "explanation": "正确：外出指离开家到外面去，与「买菜」连用，说的是出门买菜。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：下雨是天气现象，不是人的动作，「下雨买菜」说不通。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：「结婚」后面不能接「买菜」这样的动作，二者不搭配。"}], "explanations": {"睡觉": "语义：人睡觉时不能去买菜，「睡觉买菜」说不通。", "外出": "正确：外出指离开家到外面去，与「买菜」连用，说的是出门买菜。", "下雨": "语义：下雨是天气现象，不是人的动作，「下雨买菜」说不通。", "结婚": "搭配：「结婚」后面不能接「买菜」这样的动作，二者不搭配。"}, "sentence_index": 0, "correct_answer": "外出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她明年要外出，嫁到南方去。", "explanation": "这里应该用〈出嫁〉。外出指离开家去办事或游玩，不指女子出嫁。"}, {"text": "他外出的那天，一直坐在屋里看书，没有离开过。", "explanation": "这里应该用〈留守〉。外出是离开家到外面去，句中却说没有离开，词义矛盾。"}, {"text": "他外出时，在家里站了一整天，一步也没迈出去。", "explanation": "这里应该用〈在家〉。外出是离开家到外面去，句中却说一步也没迈出去，词义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87023, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出生", "is_correct": false, "explanation": "语义：出生指人刚出世，「出生时要把门关好」没有道理。"}, {"text": "外出", "is_correct": true, "explanation": "正确：外出是离开家的动作，「外出时要把门关好」说得通。"}, {"text": "同意", "is_correct": false, "explanation": "语义：「同意」指对某件事表态，与出门时关门无关，「同意时要把门关好」句意说不通。"}, {"text": "去世", "is_correct": false, "explanation": "语义：人去世的时候不会要求把门关好，「去世时要把门关好」不成立。"}], "explanations": {"出生": "语义：出生指人刚出世，「出生时要把门关好」没有道理。", "外出": "正确：外出是离开家的动作，「外出时要把门关好」说得通。", "同意": "语义：「同意」指对某件事表态，与出门时关门无关，「同意时要把门关好」句意说不通。", "去世": "语义：人去世的时候不会要求把门关好，「去世时要把门关好」不成立。"}, "sentence_index": 6, "correct_answer": "外出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他外出的时候，一直躺在床上，没有起来过。", "explanation": "这里应该用〈卧床〉。外出是离开家到外面去，句中却说一直躺在床上，词义相反。"}, {"text": "他外出的那个下午，一直在厨房里做饭，没出过家门。", "explanation": "这里应该用〈在家〉。外出是离开家到外面去，句中却说没出过家门，词义相反。"}, {"text": "我外出的那天，一直坐在电脑前打字，哪儿也没去。", "explanation": "这里应该用〈宅家〉。外出是离开家到外面去，句中却说哪儿也没去，词义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87023, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天下午外出办事着，很晚才回来。", "corrected_sentence": "他昨天下午外出办事了，很晚才回来。", "error_description": "体标误用：「昨天下午」的「外出办事」是已经完成的动作，应该用表示完成的「了」，说「外出办事了」。「着」表示动作或状态正在持续，不能用在这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87023, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚刚很外出了，你等一下吧。", "corrected_sentence": "他刚刚外出了，你等一下吧。", "error_description": "程度副词错误：「外出」是表示动作的动词，不能用「很」修饰，应说「他刚刚外出了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
