INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87024, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "离开家或所在的地方到外面去。", "primary_collocate": null, "pronunciation": "wài chū", "ipa": "wai⁵¹ tʂʰu⁵⁵", "syllable_count": 2, "sentences": [{"text": "经理外出开会了，下午才回来。", "target_word": "外出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师今天外出，不在办公室。", "target_word": "外出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常因为工作外出。", "target_word": "外出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我外出的这几天，请你帮我看家。", "target_word": "外出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校不让学生随便外出。", "target_word": "外出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生外出看病人去了。", "target_word": "外出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外出办事的人很多，车站很热闹。", "target_word": "外出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问李先生外出了吗？", "target_word": "外出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月都要外出一次。", "target_word": "外出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的同事外出学习了三天。", "target_word": "外出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外出了", "label": "体标"}, {"form": "外出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "离开家或工作的地方到外面去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bb5dbd0-8999-44e2-b7a7-f670f6a1f680') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87024, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下雨", "is_correct": false, "explanation": "语义：下雨是天气现象，不能作为经理的动作，「经理下雨开会」说不通。"}, {"text": "外出", "is_correct": true, "explanation": "正确：外出指离开公司去办事，「经理外出开会」说得通。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生只能说人的出世，「经理出生开会」不成立。"}, {"text": "修理", "is_correct": false, "explanation": "配价：「修理」必须带修理的对象，单独用在这里不成立。"}], "explanations": {"下雨": "语义：下雨是天气现象，不能作为经理的动作，「经理下雨开会」说不通。", "外出": "正确：外出指离开公司去办事，「经理外出开会」说得通。", "出生": "语义：出生只能说人的出世，「经理出生开会」不成立。", "修理": "配价：「修理」必须带修理的对象，单独用在这里不成立。"}, "sentence_index": 0, "correct_answer": "外出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去年外出了，一整年都坐在办公室里，连门都没出过。", "explanation": "这里应该用〈坐班〉。外出是离开所在地到外面去，句中却说一整年都没出过门，词义矛盾。"}, {"text": "经理外出的那天，一直坐在办公室里，没有离开过。", "explanation": "这里应该用〈留守〉。外出是离开所在地到外面去，句中却说没有离开，词义矛盾。"}, {"text": "王老师外出，却一直在办公室里批改作业，哪儿也没去。", "explanation": "这里应该用〈在家〉。外出是离开所在地到外面去，句中却说哪儿也没去，词义矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87024, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发烧", "is_correct": false, "explanation": "搭配：「办事」要求主体能去办事，「发烧」不能与「办事」搭配。"}, {"text": "外出", "is_correct": true, "explanation": "正确：外出办事指离开家或单位去办事，「车站很热闹」正好与之呼应。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳是在水里的运动，与「车站很热闹」的场景不合。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌的人不是办事的人，「唱歌办事的人很多」说不通。"}], "explanations": {"发烧": "搭配：「办事」要求主体能去办事，「发烧」不能与「办事」搭配。", "外出": "正确：外出办事指离开家或单位去办事，「车站很热闹」正好与之呼应。", "游泳": "语义：游泳是在水里的运动，与「车站很热闹」的场景不合。", "唱歌": "语义：唱歌的人不是办事的人，「唱歌办事的人很多」说不通。"}, "sentence_index": 6, "correct_answer": "外出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他外出的时候，一直睡在沙发上，醒来还在屋里。", "explanation": "这里应该用〈在家〉。外出是离开所在地到外面去，句中却说一直在屋里，词义矛盾。"}, {"text": "经理外出的那个上午，一直在办公室里打电话，没离开过座位。", "explanation": "这里应该用〈在办公室〉。外出是离开所在地到外面去，句中却说没离开过，词义矛盾。"}, {"text": "我外出的那几天，一直在书桌前写作业，一步也没挪动。", "explanation": "这里应该用〈在家〉。外出是离开所在地到外面去，句中却说一步也没挪动，词义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "王老师今天下午了外出了。", "corrected_sentence": "王老师今天下午外出了。", "error_description": "体标错误：「了」是动态助词，只应放在动词之后，说「外出了」；动词之前多加的「了」是错误的，「了外出了」不成立，应删去动词前的「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87024, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他今天不有外出。", "corrected_sentence": "他今天没有外出。", "error_description": "否定词错误：「没有」用于否定已经发生或未发生的动作，「不有」不成立。正确说法是「没有外出」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d64e6bc-6739-4118-896c-a51f88732ae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87025, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "古代", "is_correct": true, "explanation": "古代与现代相对，指离今天较远的时期，二者是反义关系。"}, {"text": "农村", "is_correct": false, "explanation": "农村是地域概念，与时期无关，不与“现代”构成反义。"}, {"text": "海洋", "is_correct": false, "explanation": "海洋是自然地理事物，与“现代”无关。"}, {"text": "运动", "is_correct": false, "explanation": "运动指身体活动或社会活动，与“现代”不构成反义关系。"}], "correct_answer": "古代", "explanations": {"古代": "古代与现代相对，指离今天较远的时期，二者是反义关系。", "农村": "农村是地域概念，与时期无关，不与“现代”构成反义。", "海洋": "海洋是自然地理事物，与“现代”无关。", "运动": "运动指身体活动或社会活动，与“现代”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87025, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "古代", "is_correct": true, "explanation": "古代与现代相对，指离今天较远的时期，二者是反义关系。"}, {"text": "乡村", "is_correct": false, "explanation": "乡村是地域概念，与时期无关，不与“现代”构成反义。"}, {"text": "森林", "is_correct": false, "explanation": "森林是自然事物，与“现代”无关。"}, {"text": "火车", "is_correct": false, "explanation": "火车是交通工具，与“现代”不构成反义关系。"}], "correct_answer": "古代", "explanations": {"古代": "古代与现代相对，指离今天较远的时期，二者是反义关系。", "乡村": "乡村是地域概念，与时期无关，不与“现代”构成反义。", "森林": "森林是自然事物，与“现代”无关。", "火车": "火车是交通工具，与“现代”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87025, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "现代是离我们现在不太远的这个时代。", "primary_collocate": null, "pronunciation": "xiàn dài", "ipa": "ɕjɛn˥˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "古代的人写信，现代的人发短信。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥是现代才建起来的。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要比较古代和现代的房子。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲的是中国现代的历史。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代离我们不太远，只有一百年。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆左边是古代的东西，右边是现代的东西。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一幅现代的画，不是古代的。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些照片属于现代，看起来不太旧。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在现代，中国发生了很大的变化。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代的作家写的小说，我都喜欢。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "现代人", "label": "复合"}, {"form": "现代化", "label": "复合"}], "register": "中性", "sense_fingerprint": "现代：与古代相对，离今天不太远的时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed471b59-6733-4165-85bc-54587c636e4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87025, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "现代", "is_correct": true, "explanation": "正确：与前句“古代”形成对比，表示当今的人。"}, {"text": "古代", "is_correct": false, "explanation": "语义：前后两句都说“古代”，失去了与“现代”的对比。"}, {"text": "远古", "is_correct": false, "explanation": "语义：远古时代还没有短信，与“发短信”相矛盾。"}, {"text": "明朝", "is_correct": false, "explanation": "搭配：“明朝”是朝代名，与“的人发短信”的时间搭配不通。"}], "explanations": {"现代": "正确：与前句“古代”形成对比，表示当今的人。", "古代": "语义：前后两句都说“古代”，失去了与“现代”的对比。", "远古": "语义：远古时代还没有短信，与“发短信”相矛盾。", "明朝": "搭配：“明朝”是朝代名，与“的人发短信”的时间搭配不通。"}, "sentence_index": 0, "correct_answer": "现代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的现代很努力。", "explanation": "这里应该用〈同学〉。现代是时间名词，只指一段时代，不能指人，“我的同学很努力”中的人要用〈同学〉。"}, {"text": "这位现代很认真。", "explanation": "这里应该用〈老师〉。现代指时代，不能指人，“这位老师很认真”中的人要用〈老师〉。"}, {"text": "现代很热。", "explanation": "这里应该用〈今天〉。现代指一个时代，不能指某一天的天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87025, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现代", "is_correct": true, "explanation": "正确：与后半句“不是古代的”相对，表示当代的画。"}, {"text": "古代", "is_correct": false, "explanation": "语义：“不是古代的”与“古代的画”自相矛盾，句意不通。"}, {"text": "唐朝", "is_correct": false, "explanation": "语义：唐朝属于古代，与“不是古代的”的对比相矛盾。"}, {"text": "汉朝", "is_correct": false, "explanation": "语义：汉朝属于古代，与“不是古代的”的对比相矛盾。"}], "explanations": {"现代": "正确：与后半句“不是古代的”相对，表示当代的画。", "古代": "语义：“不是古代的”与“古代的画”自相矛盾，句意不通。", "唐朝": "语义：唐朝属于古代，与“不是古代的”的对比相矛盾。", "汉朝": "语义：汉朝属于古代，与“不是古代的”的对比相矛盾。"}, "sentence_index": 6, "correct_answer": "现代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "现代是下午三点。", "explanation": "这里应该用〈现在〉。现代是指一个时代的名词，不能用来指具体的时刻。"}, {"text": "我每天现代七点起床。", "explanation": "这里应该用〈早上〉。现代指一个时代，不能表示一天中的某个时段，要说“每天早上七点起床”。"}, {"text": "我们明天去现代吃饭。", "explanation": "这里应该用〈餐厅〉。现代是时代名称，不能作地点名词，去吃饭要说“去餐厅”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87025, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "现代了的建筑和古代的很不一样。", "corrected_sentence": "现代的建筑和古代的很不一样。", "error_description": "错误：“现代”后多加了“了”，“了”不能插在修饰语和中心语之间。应写作“现代的建筑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87025, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "现代地作家写得很好。", "corrected_sentence": "现代的作家写得很好。", "error_description": "错误：修饰名词“作家”要用“的”，“地”用来修饰动词或形容词。应写作“现代的作家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87026, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "古代", "is_correct": true, "explanation": "古代与现代在时间上相对，指过去的时代，二者是反义关系。"}, {"text": "历史", "is_correct": false, "explanation": "历史指过去发生的事情及其记载，与“现代”不构成反义关系。"}, {"text": "农村", "is_correct": false, "explanation": "农村是地域概念，与时代无关，不与“现代”构成反义。"}, {"text": "海洋", "is_correct": false, "explanation": "海洋是自然地理事物，与“现代”的时代含义无关。"}], "correct_answer": "古代", "explanations": {"古代": "古代与现代在时间上相对，指过去的时代，二者是反义关系。", "历史": "历史指过去发生的事情及其记载，与“现代”不构成反义关系。", "农村": "农村是地域概念，与时代无关，不与“现代”构成反义。", "海洋": "海洋是自然地理事物，与“现代”的时代含义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87026, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "古代", "is_correct": true, "explanation": "古代与现代在时间上相对，指过去的时代，二者是反义关系。"}, {"text": "乡村", "is_correct": false, "explanation": "乡村是地域概念，与时代无关，不与“现代”构成反义。"}, {"text": "森林", "is_correct": false, "explanation": "森林是自然事物，与“现代”的时代含义无关。"}, {"text": "火车", "is_correct": false, "explanation": "火车是交通工具，与“现代”不构成反义关系。"}], "correct_answer": "古代", "explanations": {"古代": "古代与现代在时间上相对，指过去的时代，二者是反义关系。", "乡村": "乡村是地域概念，与时代无关，不与“现代”构成反义。", "森林": "森林是自然事物，与“现代”的时代含义无关。", "火车": "火车是交通工具，与“现代”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87026, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指当代；现在这个时代。", "primary_collocate": null, "pronunciation": "xiàn dài", "ipa": "ɕjɛn˥˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "在现代，人们可以用手机买东西。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代的生活比以前方便多了。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢研究现代的音乐。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院用的是现代的技术。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代的年轻人常常很忙。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代的城市里有很多高楼。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在书里写了现代的故事。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在现代，坐飞机去别的国家很平常。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影说的是现代的事情。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，现代的孩子知道得很多。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "现代人", "label": "复合"}, {"form": "现代化", "label": "复合"}], "register": "中性", "sense_fingerprint": "现代：当代，我们现在生活的这个时代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed471b59-6733-4165-85bc-54587c636e4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87026, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "现代", "is_correct": true, "explanation": "正确：“在现代”指当今这个时代，与用手机买东西的语境相符。"}, {"text": "古代", "is_correct": false, "explanation": "语义：古代没有手机，与“用手机买东西”相矛盾。"}, {"text": "上古", "is_correct": false, "explanation": "语义：上古时期没有手机，与“用手机买东西”相矛盾。"}, {"text": "明朝", "is_correct": false, "explanation": "语义：明朝时期没有手机，与句中“用手机买东西”冲突。"}], "explanations": {"现代": "正确：“在现代”指当今这个时代，与用手机买东西的语境相符。", "古代": "语义：古代没有手机，与“用手机买东西”相矛盾。", "上古": "语义：上古时期没有手机，与“用手机买东西”相矛盾。", "明朝": "语义：明朝时期没有手机，与句中“用手机买东西”冲突。"}, "sentence_index": 0, "correct_answer": "现代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是一个新的现代。", "explanation": "这里应该用〈时代〉。现代专指当今这一时期，不能说“一个现代”“新的现代”，泛指一段历史要用〈时代〉。"}, {"text": "我的现代很聪明。", "explanation": "这里应该用〈朋友〉。现代是指时代的名词，不能指人，指人要用〈朋友〉。"}, {"text": "那段现代很难忘。", "explanation": "这里应该用〈时期〉。现代专指当下这个时代，不能用来指一段有限的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87026, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现代", "is_correct": true, "explanation": "正确：“写了现代的故事”指以当今时代为背景的故事，与句意相符。"}, {"text": "然后", "is_correct": false, "explanation": "语法：“然后”是连词，不能修饰“故事”，“写了然后的故事”不成立。"}, {"text": "因为", "is_correct": false, "explanation": "语法：“因为”是连词，不能修饰“故事”，“写了因为的故事”不成立。"}, {"text": "吗", "is_correct": false, "explanation": "语法：“吗”是语气词，不能修饰名词，“写了吗的故事”不成立。"}], "explanations": {"现代": "正确：“写了现代的故事”指以当今时代为背景的故事，与句意相符。", "然后": "语法：“然后”是连词，不能修饰“故事”，“写了然后的故事”不成立。", "因为": "语法：“因为”是连词，不能修饰“故事”，“写了因为的故事”不成立。", "吗": "语法：“吗”是语气词，不能修饰名词，“写了吗的故事”不成立。"}, "sentence_index": 6, "correct_answer": "现代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "现代是晚上九点。", "explanation": "这里应该用〈现在〉。现代是指一个时代的名词，不能用来指具体的时刻。"}, {"text": "这个苹果很现代，很好吃。", "explanation": "这里应该用〈新鲜〉。现代是指时代的名词，不能用来形容食物的新鲜程度。"}, {"text": "他每天在现代学习八小时。", "explanation": "这里应该用〈学校〉。现代不是学习的场所，要说“在学校学习”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87026, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在现代了，人们常常靠网络学习。", "corrected_sentence": "在现代，人们常常靠网络学习。", "error_description": "错误：“现代”后多加了“了”。“现代”是时间名词，不能带“了”，应去掉“了”，写作“在现代，……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87026, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "现代地音乐很受年轻人欢迎。", "corrected_sentence": "现代的音乐很受年轻人欢迎。", "error_description": "错误：修饰名词“音乐”要用“的”，“地”用来修饰动词或形容词。应写作“现代的音乐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
