INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87027, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "将军是带着很多兵打仗的人，是军队里很大的官。", "primary_collocate": null, "pronunciation": "jiāng jūn", "ipa": "tɕjaŋ˥ tɕyn˥", "syllable_count": 2, "sentences": [{"text": "将军带着士兵走进了城。", "target_word": "将军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位将军打过很多仗。", "target_word": "将军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爷爷是一位老将军。", "target_word": "将军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军坐在马上，看着前面的山。", "target_word": "将军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王很相信这位将军。", "target_word": "将军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军把地图放在桌子上。", "target_word": "将军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个将军让大家晚上休息。", "target_word": "将军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，他想当将军。", "target_word": "将军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军说：“明天早上我们出发。”", "target_word": "将军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们都很怕那位严格的将军。", "target_word": "将军", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}], "register": "中性", "sense_fingerprint": "带兵打仗的军队大官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eb1202a-debe-449b-9a5c-f738d8413e68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87027, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "将军", "is_correct": true, "explanation": "将军指带兵打仗的军队大官，能带着士兵走进城，句子成立。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生不会带着士兵走进城，与语境矛盾。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不带兵打仗，“带着士兵走进了城”与其身份不符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是物品，不能带着士兵走进城。"}], "explanations": {"将军": "将军指带兵打仗的军队大官，能带着士兵走进城，句子成立。", "学生": "语义：学生不会带着士兵走进城，与语境矛盾。", "厨师": "语义：厨师不带兵打仗，“带着士兵走进了城”与其身份不符。", "桌子": "语义：桌子是物品，不能带着士兵走进城。"}, "sentence_index": 0, "correct_answer": "将军"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一条将军，带着很多兵打仗。", "explanation": "这里应该用〈位〉。量词“条”用于长条形的东西或某些动物，指人的将军要用“位”。"}, {"text": "我昨天买了一把将军。", "explanation": "这里应该用〈位〉。量词“把”用于有柄的器物，将军指人，要用“位”。"}, {"text": "他刚入伍，现在只是一名将军。", "explanation": "这里应该用〈士兵〉。将军是高级军官的军衔，刚入伍的新兵不能称将军。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87027, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "将军", "is_correct": true, "explanation": "将军指带兵的大官，能让大家晚上休息，句子成立。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟的作用是叫人起床，与“让大家晚上休息”相反。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“雨”的量词要用“场”，不说“那个雨”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有意志，不能让大家休息。"}], "explanations": {"将军": "将军指带兵的大官，能让大家晚上休息，句子成立。", "闹钟": "语义：闹钟的作用是叫人起床，与“让大家晚上休息”相反。", "雨": "搭配：“雨”的量词要用“场”，不说“那个雨”。", "石头": "语义：石头没有意志，不能让大家休息。"}, "sentence_index": 6, "correct_answer": "将军"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家医院的将军每天给很多病人看病。", "explanation": "这里应该用〈医生〉。将军是军队的高级官衔，医院里看病的人不能称将军。"}, {"text": "这家公司的将军每天都很早来上班。", "explanation": "这里应该用〈老板〉。将军是军队的高级官衔，公司的负责人不能称将军。"}, {"text": "这支球队的将军每场比赛都在场边指挥。", "explanation": "这里应该用〈教练〉。将军是军队的高级官衔，球队的指导者不能称将军。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87027, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条将军在城里住了三年。", "corrected_sentence": "这位将军在城里住了三年。", "error_description": "量词错误：“条”用于长条形的东西，指人的将军要用“位”。应说“这位将军”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87027, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三位将军们一起走进了城。", "corrected_sentence": "三位将军一起走进了城。", "error_description": "“三位将军们”是错误的：有数量词修饰时不加“们”。应说“三位将军”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
