INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87028, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军衔中将官的统称，也泛指高级军事指挥官。", "primary_collocate": null, "pronunciation": "jiāng jūn", "ipa": "tɕjaŋ˥ tɕyn˥", "syllable_count": 2, "sentences": [{"text": "这位将军今天来学校参观。", "target_word": "将军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我国一位有名的将军。", "target_word": "将军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上有一张将军的照片。", "target_word": "将军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三位将军一起开会。", "target_word": "将军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位将军已经退休十年了。", "target_word": "将军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小兵一步步成为将军。", "target_word": "将军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军的家就在这座老楼里。", "target_word": "将军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里正在采访一位老将军。", "target_word": "将军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家给将军发了一枚奖章。", "target_word": "将军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位将军写过一本书。", "target_word": "将军", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}], "register": "中性", "sense_fingerprint": "将官统称，高级军事指挥官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eb1202a-debe-449b-9a5c-f738d8413e68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87028, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "将军", "is_correct": true, "explanation": "将军指高级军事指挥官，能来学校参观，句子成立。"}, {"text": "铅笔", "is_correct": false, "explanation": "搭配：量词“位”只用于人，铅笔不能用“这位”修饰。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能来学校参观，与句子的主语不相容。"}, {"text": "老鼠", "is_correct": false, "explanation": "搭配：量词“位”只用于人，老鼠应用“只”，且老鼠不来参观。"}], "explanations": {"将军": "将军指高级军事指挥官，能来学校参观，句子成立。", "铅笔": "搭配：量词“位”只用于人，铅笔不能用“这位”修饰。", "石头": "语义：石头不能来学校参观，与句子的主语不相容。", "老鼠": "搭配：量词“位”只用于人，老鼠应用“只”，且老鼠不来参观。"}, "sentence_index": 0, "correct_answer": "将军"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的三张将军一起开会。", "explanation": "这里应该用〈位〉。量词“张”用于平面的东西，将军指人，要用“位”。"}, {"text": "三只将军一起开会。", "explanation": "这里应该用〈位〉。量词“只”用于动物，将军指人，要用“位”。"}, {"text": "他才入伍一个月，已经是将军了。", "explanation": "这里应该用〈士兵〉。将军是高级军官的军衔，刚入伍的新兵不能称将军。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "将军", "is_correct": true, "explanation": "将军指高级军事指挥官，一位将军住在这座老楼里，句子成立。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是物品，没有“家”。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不是人，不会有家住在楼里。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是机构，不是能住在楼里的个体，没有“家”。"}], "explanations": {"将军": "将军指高级军事指挥官，一位将军住在这座老楼里，句子成立。", "桌子": "语义：桌子是物品，没有“家”。", "太阳": "语义：太阳不是人，不会有家住在楼里。", "学校": "语义：学校是机构，不是能住在楼里的个体，没有“家”。"}, "sentence_index": 6, "correct_answer": "将军"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家医院的将军很有名，很多病人都来找他看病。", "explanation": "这里应该用〈医生〉。将军是军队中的高级官衔，医院里的医生不能称将军。"}, {"text": "这家饭馆的将军每天早上都做很好吃的早饭。", "explanation": "这里应该用〈厨师〉。将军是军队中的高级官衔，饭馆里做饭的人不能称将军。"}, {"text": "这家学校的将军每天都给学生上数学课。", "explanation": "这里应该用〈老师〉。将军是军队中的高级官衔，给学生上课的人不能称将军。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的爷爷是一只将军。", "corrected_sentence": "他的爷爷是一位将军。", "error_description": "量词错误：“一只”用于动物，指人的将军要用量词“位”。应说“一位将军”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只将军来了。", "corrected_sentence": "那位将军来了。", "error_description": "量词错误：“只”用于动物，指人的将军要用量词“位”。应说“那位将军”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
