INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87029, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "多大是用来问几岁，或者问东西有多大。", "primary_collocate": null, "pronunciation": "duō dà", "ipa": "two˥ ta˥˩", "syllable_count": 2, "sentences": [{"text": "你弟弟今年多大了？", "target_word": "多大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间有多大？", "target_word": "多大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你女儿多大了，上学了吗？", "target_word": "多大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只狗有多大？比猫大吗？", "target_word": "多大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，你们学校有多大？", "target_word": "多大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的孩子多大了？会走路了吗？", "target_word": "多大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这个操场有多大吗？", "target_word": "多大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小男孩看起来有多大？", "target_word": "多大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你家的院子有多大？", "target_word": "多大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你奶奶多大年纪了？", "target_word": "多大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "多大年纪", "label": "复合"}], "register": "口语", "sense_fingerprint": "多大：问几岁或东西大小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e95692-f9f1-4226-adcd-b55c18dffb26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87029, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "什么", "is_correct": false, "explanation": "语义：“什么”问事物或情况，不能用来问弟弟的年龄。"}, {"text": "多大", "is_correct": true, "explanation": "正确：多大用来问年龄，句中问“弟弟今年……了”，正与之相合。"}, {"text": "谁", "is_correct": false, "explanation": "配价：“谁”指人，而“今年……了”需要数量或程度的答案，不能用“谁”。"}, {"text": "哪", "is_correct": false, "explanation": "搭配：“哪”需与“个、些”等合用，不能直接接“今年……了”。"}], "explanations": {"什么": "语义：“什么”问事物或情况，不能用来问弟弟的年龄。", "多大": "正确：多大用来问年龄，句中问“弟弟今年……了”，正与之相合。", "谁": "配价：“谁”指人，而“今年……了”需要数量或程度的答案，不能用“谁”。", "哪": "搭配：“哪”需与“个、些”等合用，不能直接接“今年……了”。"}, "sentence_index": 0, "correct_answer": "多大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书有多大页？", "explanation": "这里应该用〈多少〉。问页数要用“多少”，“多大”只用来问年龄或大小。"}, {"text": "学校离这里有多大？", "explanation": "这里应该用〈多远〉。问距离要用“多远”，“多大”不能用来问距离。"}, {"text": "这次旅行用了多大？", "explanation": "这里应该用〈多久〉。问时间长短要用“多久”，“多大”不能问时长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87029, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怎么", "is_correct": false, "explanation": "搭配：“这个操场有怎么吗”不成句，“怎么”后需接动词或形容词。"}, {"text": "多大", "is_correct": true, "explanation": "正确：多大用来问大小，句中“你知道这个操场有……吗”正与之相合。"}, {"text": "那么", "is_correct": false, "explanation": "搭配：“那么”后需接形容词，“有那么吗”不成立。"}, {"text": "怎样", "is_correct": false, "explanation": "语义：“怎样”问情况或方式，不能用来问操场的大小。"}], "explanations": {"怎么": "搭配：“这个操场有怎么吗”不成句，“怎么”后需接动词或形容词。", "多大": "正确：多大用来问大小，句中“你知道这个操场有……吗”正与之相合。", "那么": "搭配：“那么”后需接形容词，“有那么吗”不成立。", "怎样": "语义：“怎样”问情况或方式，不能用来问操场的大小。"}, "sentence_index": 6, "correct_answer": "多大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了多大本书？", "explanation": "这里应该用〈多少〉。问数量要用“多少”，“多大”不能用于计数。"}, {"text": "这次会议开了多大？", "explanation": "这里应该用〈多久〉。问时长要用“多久”，“多大”不能问时长。"}, {"text": "学校离我家多大？", "explanation": "这里应该用〈多远〉。问距离要用“多远”，“多大”不能问距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87029, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他哥哥今年几多大了？", "corrected_sentence": "他哥哥今年多大了？", "error_description": "添加错误：“多大”前不能再加“几”。应说“他哥哥今年多大了”，不说“几多大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87029, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个公园有多多大？离这里远吗？", "corrected_sentence": "这个公园有多大？离这里远吗？", "error_description": "添加错误：“多大”前不能再加“多”，应说“这个公园有多大”，不说“这个公园有多多大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
