INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87033, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大四是大学里的最后一年，也指这一年的学生。", "primary_collocate": null, "pronunciation": "dà sì", "ipa": "tɑ˥˩ sɿ˥˩", "syllable_count": 2, "sentences": [{"text": "他今年大四，下个月就要毕业了。", "target_word": "大四", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大四的学生都在忙着找工作。", "target_word": "大四", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐大四那年去北京实习了。", "target_word": "大四", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大四是大学生活的最后一年。", "target_word": "大四", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们大四的同学常常一起复习考研。", "target_word": "大四", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明年我就上大四了，得开始写毕业论文。", "target_word": "大四", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了大四，教室里的人越来越少。", "target_word": "大四", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个周末，大四的学长请我们吃饭。", "target_word": "大四", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大四那年，他把所有的时间都用在了学习上。", "target_word": "大四", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在大四时拿到了一家公司的录用通知。", "target_word": "大四", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大四学生", "label": "复合"}, {"form": "大四生", "label": "复合"}], "register": "中性", "sense_fingerprint": "大学最后一年，也指这一年级的学生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c817ef8-4072-4671-8660-bc5321147c0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87033, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大四", "is_correct": true, "explanation": "「大四」指大学最后一年，读作 dà sì。"}, {"text": "大事", "is_correct": false, "explanation": "「大事」dà shì：sì 与 shì 声母不同（s 与 sh），意思是“大事情”。"}, {"text": "大志", "is_correct": false, "explanation": "「大志」dà zhì：sì 与 zhì 声母不同（s 与 zh），意思是“远大的志向”。"}, {"text": "大字", "is_correct": false, "explanation": "「大字」dà zì：sì 与 zì 声母不同（s 与 z），意思是“大的字”。"}], "explanations": {"大四": "「大四」指大学最后一年，读作 dà sì。", "大事": "「大事」dà shì：sì 与 shì 声母不同（s 与 sh），意思是“大事情”。", "大志": "「大志」dà zhì：sì 与 zhì 声母不同（s 与 zh），意思是“远大的志向”。", "大字": "「大字」dà zì：sì 与 zì 声母不同（s 与 z），意思是“大的字”。"}, "sentence_index": null, "correct_answer": "大四"}, "level_3": {"options": [{"text": "大四", "is_correct": true, "explanation": "“他今年大四”指大学最后一年，与“下个月就要毕业”相符。"}, {"text": "大一", "is_correct": false, "explanation": "语义：大一刚入学，不会“下个月就要毕业”。"}, {"text": "研一", "is_correct": false, "explanation": "语义：研一是研究生第一年，离毕业还很远。"}, {"text": "硕士", "is_correct": false, "explanation": "搭配：“今年”后接的是年级，不说“今年硕士”这种学位。"}], "explanations": {"大四": "“他今年大四”指大学最后一年，与“下个月就要毕业”相符。", "大一": "语义：大一刚入学，不会“下个月就要毕业”。", "研一": "语义：研一是研究生第一年，离毕业还很远。", "硕士": "搭配：“今年”后接的是年级，不说“今年硕士”这种学位。"}, "sentence_index": 0, "correct_answer": "大四"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我弟弟今年大四，每天都要复习高考。", "explanation": "这里应该用〈高三〉。“大四”只指大学本科第四学年，复习高考属于高中阶段，应说“高三”。"}, {"text": "我女儿今年大四，马上要上初中了。", "explanation": "这里应该用〈六年级〉。“大四”只指大学本科第四学年，马上升入初中的孩子应说“六年级”。"}, {"text": "我们幼儿园里有很多大四的小朋友。", "explanation": "这里应该用〈大班〉。“大四”只指大学本科第四学年，幼儿园的孩子应说“大班”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87033, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大四", "is_correct": true, "explanation": "「大四」指大学最后一年，读作 dà sì。"}, {"text": "大字", "is_correct": false, "explanation": "「大字」dà zì：sì 与 zì 声母不同（s 与 z），意思是“大的字”。"}, {"text": "大势", "is_correct": false, "explanation": "「大势」dà shì：sì 与 shì 声母不同（s 与 sh），意思是“大体的形势”。"}, {"text": "大智", "is_correct": false, "explanation": "「大智」dà zhì：sì 与 zhì 声母不同（s 与 zh），意思是“大的智慧”。"}], "explanations": {"大四": "「大四」指大学最后一年，读作 dà sì。", "大字": "「大字」dà zì：sì 与 zì 声母不同（s 与 z），意思是“大的字”。", "大势": "「大势」dà shì：sì 与 shì 声母不同（s 与 sh），意思是“大体的形势”。", "大智": "「大智」dà zhì：sì 与 zhì 声母不同（s 与 zh），意思是“大的智慧”。"}, "sentence_index": null, "correct_answer": "大四"}, "level_3": {"options": [{"text": "大四", "is_correct": true, "explanation": "“到了大四，教室里的人越来越少”符合毕业前人员减少的情形。"}, {"text": "高一", "is_correct": false, "explanation": "语义：高一是高中新生阶段，课程满，不会因临近毕业而教室人越来越少。"}, {"text": "小学一年级", "is_correct": false, "explanation": "语义：小学一年级是低年级，与“教室里的人越来越少”这一变化无关。"}, {"text": "大一", "is_correct": false, "explanation": "语义：大一刚入学，课程最多，不会出现临近毕业、教室人越来越少的情形。"}], "explanations": {"大四": "“到了大四，教室里的人越来越少”符合毕业前人员减少的情形。", "高一": "语义：高一是高中新生阶段，课程满，不会因临近毕业而教室人越来越少。", "小学一年级": "语义：小学一年级是低年级，与“教室里的人越来越少”这一变化无关。", "大一": "语义：大一刚入学，课程最多，不会出现临近毕业、教室人越来越少的情形。"}, "sentence_index": 6, "correct_answer": "大四"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我表哥大四时每周都要参加升旗仪式。", "explanation": "这里应该用〈高一〉。“大四”指大学本科，升旗仪式是中学的活动，应说“高一”。"}, {"text": "他大四那年就考上了重点高中。", "explanation": "这里应该用〈初三〉。“大四”指大学，考上重点高中发生在初中阶段，应说“初三”。"}, {"text": "这栋大四是新建的，有三层楼。", "explanation": "这里应该用〈楼〉。“大四”是年级，不能指建筑，应说“这栋楼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87033, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我弟弟后年就大四过了。", "corrected_sentence": "我弟弟后年就大四了。", "error_description": "体貌错误：“大四”说的是将来的事，“过”表示已经发生，不能与“后年”搭配。正确说法是“后年就大四了”，不能说“大四过了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87033, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下个学期，大四地学长会来给我们讲座。", "corrected_sentence": "下个学期，大四的学长会来给我们讲座。", "error_description": "结构助词错误：修饰名词“学长”要用“的”，不能用“地”（“地”用于修饰动词、形容词）。应说“大四的学长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
