INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87034, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大学本科的第四年级。", "primary_collocate": null, "pronunciation": "dà sì", "ipa": "tɑ˥˩ sɿ˥˩", "syllable_count": 2, "sentences": [{"text": "大三过完就是大四了。", "target_word": "大四", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟现在读大四，专业是医学。", "target_word": "大四", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大一是新生，大四快要毕业。", "target_word": "大四", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "本科的最后一年叫大四。", "target_word": "大四", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他大四才开始学英语，进步很快。", "target_word": "大四", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "读完大三，下学期就升大四了。", "target_word": "大四", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大四的课不多，大家都在准备毕业。", "target_word": "大四", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她大四时选修过一门日语课。", "target_word": "大四", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人到了大四，才发现时间过得太快。", "target_word": "大四", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给大四的同学办了一个毕业晚会。", "target_word": "大四", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大四学生", "label": "复合"}, {"form": "大四生", "label": "复合"}], "register": "中性", "sense_fingerprint": "大学本科的第四个年级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c817ef8-4072-4671-8660-bc5321147c0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87034, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大四", "is_correct": true, "explanation": "「大四」指大学本科的第四年级，读作 dà sì。"}, {"text": "大志", "is_correct": false, "explanation": "「大志」dà zhì：sì 与 zhì 声母不同（s 与 zh），意思是“远大的志向”。"}, {"text": "大字", "is_correct": false, "explanation": "「大字」dà zì：sì 与 zì 声母不同（s 与 z），意思是“大的字”。"}, {"text": "大事", "is_correct": false, "explanation": "「大事」dà shì：sì 与 shì 声母不同（s 与 sh），意思是“大事情”。"}], "explanations": {"大四": "「大四」指大学本科的第四年级，读作 dà sì。", "大志": "「大志」dà zhì：sì 与 zhì 声母不同（s 与 zh），意思是“远大的志向”。", "大字": "「大字」dà zì：sì 与 zì 声母不同（s 与 z），意思是“大的字”。", "大事": "「大事」dà shì：sì 与 shì 声母不同（s 与 sh），意思是“大事情”。"}, "sentence_index": null, "correct_answer": "大四"}, "level_3": {"options": [{"text": "大四", "is_correct": true, "explanation": "“大三过完就是大四了”指大三之后进入大学本科第四年级，符合句意。"}, {"text": "大一", "is_correct": false, "explanation": "语义：大一在大三之前，“大三过完就是大一了”顺序不对。"}, {"text": "高三", "is_correct": false, "explanation": "语义：高三是高中年级，与“大三”所属的大学阶段不衔接。"}, {"text": "硕士", "is_correct": false, "explanation": "搭配：“大三过完”后接的是年级，不说“就是硕士了”，硕士是学位。"}], "explanations": {"大四": "“大三过完就是大四了”指大三之后进入大学本科第四年级，符合句意。", "大一": "语义：大一在大三之前，“大三过完就是大一了”顺序不对。", "高三": "语义：高三是高中年级，与“大三”所属的大学阶段不衔接。", "硕士": "搭配：“大三过完”后接的是年级，不说“就是硕士了”，硕士是学位。"}, "sentence_index": 0, "correct_answer": "大四"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我弟弟今年大四，正在准备高考。", "explanation": "这里应该用〈高三〉。“大四”只指大学本科年级，高考复习属于高中阶段，应说“高三”。"}, {"text": "我侄子读大四，马上要中考了。", "explanation": "这里应该用〈初三〉。“大四”指大学，马上要中考的应是初三学生。"}, {"text": "他大四那年才刚上小学。", "explanation": "这里应该用〈一年级〉。“大四”只指大学本科第四年级，刚上小学应说“一年级”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87034, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大四", "is_correct": true, "explanation": "「大四」指大学本科的第四年级，读作 dà sì。"}, {"text": "大使", "is_correct": false, "explanation": "「大使」dà shǐ：sì 与 shǐ 声母、声调都不同（s 与 sh，第四声与第三声），意思是“国家派驻外国的最高外交代表”。"}, {"text": "大赛", "is_correct": false, "explanation": "「大赛」dà sài：sì 与 sài 韵母不同（i 与 ai），意思是“大型比赛”。"}, {"text": "大树", "is_correct": false, "explanation": "「大树」dà shù：sì 与 shù 声母、韵母都不同（s 与 sh，i 与 u），意思是“高大的树”。"}], "explanations": {"大四": "「大四」指大学本科的第四年级，读作 dà sì。", "大使": "「大使」dà shǐ：sì 与 shǐ 声母、声调都不同（s 与 sh，第四声与第三声），意思是“国家派驻外国的最高外交代表”。", "大赛": "「大赛」dà sài：sì 与 sài 韵母不同（i 与 ai），意思是“大型比赛”。", "大树": "「大树」dà shù：sì 与 shù 声母、韵母都不同（s 与 sh，i 与 u），意思是“高大的树”。"}, "sentence_index": null, "correct_answer": "大四"}, "level_3": {"options": [{"text": "大四", "is_correct": true, "explanation": "“大四的课不多，大家都在准备毕业”指大学最后一年，课少、准备毕业，符合句意。"}, {"text": "大二", "is_correct": false, "explanation": "语义：大二课程还多，大家不会都在准备毕业。"}, {"text": "高二", "is_correct": false, "explanation": "语义：高二是高中阶段，不会“都在准备毕业”。"}, {"text": "小学三年级", "is_correct": false, "explanation": "语义：小学三年级离毕业还很远，与“大家都在准备毕业”不符。"}], "explanations": {"大四": "“大四的课不多，大家都在准备毕业”指大学最后一年，课少、准备毕业，符合句意。", "大二": "语义：大二课程还多，大家不会都在准备毕业。", "高二": "语义：高二是高中阶段，不会“都在准备毕业”。", "小学三年级": "语义：小学三年级离毕业还很远，与“大家都在准备毕业”不符。"}, "sentence_index": 6, "correct_answer": "大四"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我女儿在大四时参加了奥数比赛。", "explanation": "这里应该用〈小学六年级〉。“大四”只指大学，小学生参加奥数比赛时要说年级。"}, {"text": "我哥哥大四时还在中学读书。", "explanation": "这里应该用〈高一〉。“大四”指大学本科，还在中学读书的学生应说“高一”。"}, {"text": "我妹妹今年大四，刚上幼儿园。", "explanation": "这里应该用〈小班〉。“大四”只指大学本科年级，刚上幼儿园的孩子应说“小班”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87034, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他大四就时开始准备考研了。", "corrected_sentence": "他大四时就开始准备考研了。", "error_description": "语序错误：“大四时”是时间状语，“时”要紧跟“大四”，“就”放在“时”之后，应说“大四时就”，不能说“大四就时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87034, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我侄子明年就大四过了。", "corrected_sentence": "我侄子明年就大四了。", "error_description": "体貌错误：“大四”说的是将来的事，“过”表示已经发生，不能与“明年”搭配。正确说法是“明年就大四了”，不能说“大四过了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
