INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87035, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "谈是两个人你一句我一句地说话。", "primary_collocate": null, "pronunciation": "tán", "ipa": "tʰan˧˥", "syllable_count": 1, "sentences": [{"text": "我们坐下来谈一谈吧。", "target_word": "谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在咖啡馆里谈了两个小时。", "target_word": "谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们坐在树下，谈着天气。", "target_word": "谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电话里和朋友谈了很久。", "target_word": "谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们边吃饭边谈。", "target_word": "谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩谈得很开心。", "target_word": "谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我和同学谈了很多。", "target_word": "谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢和邻居坐在一起谈。", "target_word": "谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想跟你谈一件小事。", "target_word": "谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们谈了一个晚上，还没谈完。", "target_word": "谈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "谈了", "label": "体标"}, {"form": "谈着", "label": "体标"}, {"form": "谈过", "label": "体标"}, {"form": "谈谈", "label": "重叠"}, {"form": "談", "label": "繁体"}], "register": "口语", "sense_fingerprint": "谈：两人你一句我一句地聊天说话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed471b59-6733-4165-85bc-54587c636e4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87035, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "谈", "is_correct": true, "explanation": "tán（第二声）：两人一句一句地说话，即本词条的正确答案。"}, {"text": "堂", "is_correct": false, "explanation": "táng（第二声）与 tán 韵母不同（-ang 与 -an），意思是礼堂、厅堂。"}, {"text": "糖", "is_correct": false, "explanation": "táng（第二声）与 tán 韵母不同（-ang 与 -an），意思是糖。"}, {"text": "探", "is_correct": false, "explanation": "tàn（第四声）与 tán 声调不同，意思是探望或探索。"}, {"text": "坦", "is_correct": false, "explanation": "tǎn（第三声）与 tán 声调不同，意思是平坦。"}, {"text": "摊", "is_correct": false, "explanation": "tān（第一声）与 tán 声调不同，意思是摊位或摊开。"}], "explanations": {"谈": "tán（第二声）：两人一句一句地说话，即本词条的正确答案。", "堂": "táng（第二声）与 tán 韵母不同（-ang 与 -an），意思是礼堂、厅堂。", "糖": "táng（第二声）与 tán 韵母不同（-ang 与 -an），意思是糖。", "探": "tàn（第四声）与 tán 声调不同，意思是探望或探索。", "坦": "tǎn（第三声）与 tán 声调不同，意思是平坦。", "摊": "tān（第一声）与 tán 声调不同，意思是摊位或摊开。"}, "sentence_index": null, "correct_answer": "谈"}, "level_3": {"options": [{"text": "谈", "is_correct": true, "explanation": "正确：与后文“一谈”组成“谈一谈”，表示两人交流。"}, {"text": "说", "is_correct": false, "explanation": "搭配：“说一谈”不成词，“说”与后面的“谈”重复，不能组成“谈一谈”的结构。"}, {"text": "聊", "is_correct": false, "explanation": "语义：“聊”偏重闲聊，与后接的“一谈”无法组成重叠结构，句意不通。"}, {"text": "想", "is_correct": false, "explanation": "配价：“想”不能带“一谈”这样的动词结构作宾语，句子不成立。"}], "explanations": {"谈": "正确：与后文“一谈”组成“谈一谈”，表示两人交流。", "说": "搭配：“说一谈”不成词，“说”与后面的“谈”重复，不能组成“谈一谈”的结构。", "聊": "语义：“聊”偏重闲聊，与后接的“一谈”无法组成重叠结构，句意不通。", "想": "配价：“想”不能带“一谈”这样的动词结构作宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "谈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他谈了一双鞋。", "explanation": "这里应该用〈买〉。“谈”指交换意见，不能与“一双鞋”搭配，要说“买了一双鞋”。"}, {"text": "妈妈谈了一锅粥。", "explanation": "这里应该用〈煮〉。“谈”不能指煮东西，要说“煮了一锅粥”。"}, {"text": "她谈了一首歌。", "explanation": "这里应该用〈唱〉。“谈”不能用于唱歌，要说“唱了一首歌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
