is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87036, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "谈", "is_correct": true, "explanation": "tán（第二声）：彼此对话，交换意见，即本词条的正确答案。"}, {"text": "糖", "is_correct": false, "explanation": "táng（第二声）与 tán 韵母不同（-ang 与 -an），意思是糖。"}, {"text": "堂", "is_correct": false, "explanation": "táng（第二声）与 tán 韵母不同（-ang 与 -an），意思是礼堂、厅堂。"}, {"text": "探", "is_correct": false, "explanation": "tàn（第四声）与 tán 声调不同，意思是探望或探索。"}, {"text": "坦", "is_correct": false, "explanation": "tǎn（第三声）与 tán 声调不同，意思是平坦。"}, {"text": "摊", "is_correct": false, "explanation": "tān（第一声）与 tán 声调不同，意思是摊位或摊开。"}], "explanations": {"谈": "tán（第二声）：彼此对话，交换意见，即本词条的正确答案。", "糖": "táng（第二声）与 tán 韵母不同（-ang 与 -an），意思是糖。", "堂": "táng（第二声）与 tán 韵母不同（-ang 与 -an），意思是礼堂、厅堂。", "探": "tàn（第四声）与 tán 声调不同，意思是探望或探索。", "坦": "tǎn（第三声）与 tán 声调不同，意思是平坦。", "摊": "tān（第一声）与 tán 声调不同，意思是摊位或摊开。"}, "sentence_index": null, "correct_answer": "谈"}, "level_3": {"options": [{"text": "谈", "is_correct": true, "explanation": "正确：与后文“一谈”组成“谈一谈”，表示商量工作的问题。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”与“谈”近义，但后接“一谈”会形成重复且不成词的结构。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”含指责之意，与“商量工作的问题”的语境不符。"}, {"text": "处理", "is_correct": false, "explanation": "搭配：“处理”与后接的“一谈”组合不通，且句子表达的不是处理事务。"}], "explanations": {"谈": "正确：与后文“一谈”组成“谈一谈”，表示商量工作的问题。", "讨论": "搭配：“讨论”与“谈”近义，但后接“一谈”会形成重复且不成词的结构。", "批评": "语义：“批评”含指责之意，与“商量工作的问题”的语境不符。", "处理": "搭配：“处理”与后接的“一谈”组合不通，且句子表达的不是处理事务。"}, "sentence_index": 0, "correct_answer": "谈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们谈了一顿饭。", "explanation": "这里应该用〈吃〉。“谈”指交换意见，不能与“一顿饭”搭配，要说“吃了一顿饭”。"}, {"text": "他谈了一把伞。", "explanation": "这里应该用〈借〉。“谈”不能指借东西，要说“借了一把伞”。"}, {"text": "他谈了一辆自行车。", "explanation": "这里应该用〈修〉。“谈”不能指修理，要说“修了一辆自行车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87036, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "谈", "is_correct": true, "explanation": "tán（第二声）：彼此对话，交换意见，即本词条的正确答案。"}, {"text": "唐", "is_correct": false, "explanation": "táng（第二声）与 tán 韵母不同（-ang 与 -an），意思是唐朝。"}, {"text": "塘", "is_correct": false, "explanation": "táng（第二声）与 tán 韵母不同（-ang 与 -an），意思是池塘。"}, {"text": "叹", "is_correct": false, "explanation": "tàn（第四声）与 tán 声调不同，意思是叹气。"}, {"text": "毯", "is_correct": false, "explanation": "tǎn（第三声）与 tán 声调不同，意思是毯子。"}, {"text": "贪", "is_correct": false, "explanation": "tān（第一声）与 tán 声调不同，意思是贪婪。"}], "explanations": {"谈": "tán（第二声）：彼此对话，交换意见，即本词条的正确答案。", "唐": "táng（第二声）与 tán 韵母不同（-ang 与 -an），意思是唐朝。", "塘": "táng（第二声）与 tán 韵母不同（-ang 与 -an），意思是池塘。", "叹": "tàn（第四声）与 tán 声调不同，意思是叹气。", "毯": "tǎn（第三声）与 tán 声调不同，意思是毯子。", "贪": "tān（第一声）与 tán 声调不同，意思是贪婪。"}, "sentence_index": null, "correct_answer": "谈"}, "level_3": {"options": [{"text": "谈", "is_correct": true, "explanation": "正确：“明天再谈”表示以后再商量，与句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能以“这件事”为对象，“明天再吃这件事”不通。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”不能带“这件事”作宾语，句子不成立。"}, {"text": "跳", "is_correct": false, "explanation": "搭配：“跳”不能以“这件事”为对象，“明天再跳这件事”不成立。"}], "explanations": {"谈": "正确：“明天再谈”表示以后再商量，与句意相符。", "吃": "搭配：“吃”不能以“这件事”为对象，“明天再吃这件事”不通。", "睡": "配价：“睡”不能带“这件事”作宾语，句子不成立。", "跳": "搭配：“跳”不能以“这件事”为对象，“明天再跳这件事”不成立。"}, "sentence_index": 6, "correct_answer": "谈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他谈了一杯水。", "explanation": "这里应该用〈喝〉。“谈”不能与“一杯水”搭配，要说“喝了一杯水”。"}, {"text": "他谈了一件衣服。", "explanation": "这里应该用〈洗〉。“谈”不能指洗衣服，要说“洗了一件衣服”。"}, {"text": "他谈了一张桌子。", "explanation": "这里应该用〈擦〉。“谈”不能指擦拭，要说“擦了一张桌子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87036, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们以前谈了过这件事情。", "corrected_sentence": "我们以前谈过这件事情。", "error_description": "错误：“了”与“过”不能同时用于同一动词，“过”表示经历，应紧跟在“谈”后面，写作“谈过这件事情”，去掉多余的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87036, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们谈谈一下吃饭的事吧。", "corrected_sentence": "我们谈谈吃饭的事吧。", "error_description": "错误：“谈谈”已表示短时间的商量，不能再加“一下”，应去掉“一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
