INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87038, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "代表一定阶级、阶层或集团的利益，以取得或维持国家政权为目标的政治组织。", "primary_collocate": null, "pronunciation": "zhèng dǎng", "ipa": "ʈʂɤŋ˥˩ tɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个国家有两个大政党。", "target_word": "政党", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想加入一个政党。", "target_word": "政党", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "两个政党都想赢得选举。", "target_word": "政党", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个政党在去年的选举中赢了。", "target_word": "政党", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个政党都有自己的主张。", "target_word": "政党", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政党的领导人今天开了会。", "target_word": "政党", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是这个政党的重要成员。", "target_word": "政党", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个政党已经管理国家十年了。", "target_word": "政党", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，政党要为人民做事。", "target_word": "政党", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个政党的名字，我没听过。", "target_word": "政党", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "执政党", "label": "复合词"}, {"form": "政党政治", "label": "复合词"}], "register": "正式", "sense_fingerprint": "以取得或维持国家政权为目标的政治组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa572e2a-b4ac-45be-a597-2cd926dc15a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87038, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政党", "is_correct": true, "explanation": "正确：“两个大政党”指两个政治组织，与“这个国家有”相合。"}, {"text": "政治", "is_correct": false, "explanation": "语义：“政治”指政治活动，不是可以用“两个大”来计数的组织。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指冷热阴晴，与“这个国家有两个大……”语义不合。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：“乐器”是演奏用的器具，不能与“这个国家有两个大”搭配成立。"}], "explanations": {"政党": "正确：“两个大政党”指两个政治组织，与“这个国家有”相合。", "政治": "语义：“政治”指政治活动，不是可以用“两个大”来计数的组织。", "天气": "语义：“天气”指冷热阴晴，与“这个国家有两个大……”语义不合。", "乐器": "语义：“乐器”是演奏用的器具，不能与“这个国家有两个大”搭配成立。"}, "sentence_index": 0, "correct_answer": "政党"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去年成了政党。", "explanation": "这里应该用〈党员〉。政党是组织，不是人，不能说“成了政党”；“成为”后面应是人，如“成了党员”。"}, {"text": "这位政党在去年的选举中赢了。", "explanation": "这里应该用〈个〉。“位”用于人，政党是组织，应说“这个政党”。"}, {"text": "这个政党在去年的比赛中赢了。", "explanation": "这里应该用〈球队〉。政党是政治组织，不参加体育比赛，“赢了比赛”的主语应是球队。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87038, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政党", "is_correct": true, "explanation": "正确：“这个政党的重要成员”指该政治组织的成员，与句意相合。"}, {"text": "书", "is_correct": false, "explanation": "语义：书没有成员，不能说“这本书的重要成员”。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物不是由成员组成的团体，句子语义不通。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图没有成员，“重要成员”一词不适用于地图。"}], "explanations": {"政党": "正确：“这个政党的重要成员”指该政治组织的成员，与句意相合。", "书": "语义：书没有成员，不能说“这本书的重要成员”。", "食物": "语义：食物不是由成员组成的团体，句子语义不通。", "地图": "语义：地图没有成员，“重要成员”一词不适用于地图。"}, "sentence_index": 6, "correct_answer": "政党"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个政党唱了一首歌，大家都很喜欢。", "explanation": "这里应该用〈歌手〉。政党是政治组织，不会唱歌。"}, {"text": "他在原来的政党里学习游泳。", "explanation": "这里应该用〈游泳馆〉。政党是政治组织，不是学习游泳的场所。"}, {"text": "那个政党画了一幅画。", "explanation": "这里应该用〈画家〉。政党是政治组织，不能动手画画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87038, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个国家刚成立了一只新政党。", "corrected_sentence": "那个国家刚成立了一个新政党。", "error_description": "错误：“政党”的量词用错。“只”用于动物，政党是组织，应用“个”，说“一个新政党”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87038, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这名政党想赢得下一次选举。", "corrected_sentence": "这个政党想赢得下一次选举。", "error_description": "错误：“政党”的量词用错。“名”用于人，政党是组织，应用“个”，说“这个政党”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
