INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87039, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大海是很大很大的一片水，一眼望不到头。", "primary_collocate": null, "pronunciation": "dà hǎi", "ipa": "tɑ˥˩ xaɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "站在海边，只能看见一片大海。", "target_word": "大海", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大海很大，一眼望不到头。", "target_word": "大海", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们坐船出发，周围全是大海。", "target_word": "大海", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天，孩子们喜欢去大海里游泳。", "target_word": "大海", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天很蓝，大海也很蓝，分不清哪里是天。", "target_word": "大海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着大海，想起了远方的家人。", "target_word": "大海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，大海上就起了大浪。", "target_word": "大海", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "渔民每天开船到大海上捕鱼。", "target_word": "大海", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我第一次见到大海，高兴得跳了起来。", "target_word": "大海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把一个小瓶子扔进了大海。", "target_word": "大海", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一眼望不到边的大片海水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c817ef8-4072-4671-8660-bc5321147c0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87039, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大海", "is_correct": true, "explanation": "「大海」指一眼望不到边的大片海水，读作 dà hǎi。"}, {"text": "大好", "is_correct": false, "explanation": "「大好」dà hǎo：hǎi 与 hǎo 韵母不同（ai 与 ao），意思是“非常好”。"}, {"text": "大喊", "is_correct": false, "explanation": "「大喊」dà hǎn：hǎi 与 hǎn 韵母不同（ai 与 an），意思是“大声喊叫”。"}, {"text": "大害", "is_correct": false, "explanation": "「大害」dà hài：hǎi（第三声）与 hài（第四声）声调不同，意思是“大的祸害”。"}], "explanations": {"大海": "「大海」指一眼望不到边的大片海水，读作 dà hǎi。", "大好": "「大好」dà hǎo：hǎi 与 hǎo 韵母不同（ai 与 ao），意思是“非常好”。", "大喊": "「大喊」dà hǎn：hǎi 与 hǎn 韵母不同（ai 与 an），意思是“大声喊叫”。", "大害": "「大害」dà hài：hǎi（第三声）与 hài（第四声）声调不同，意思是“大的祸害”。"}, "sentence_index": null, "correct_answer": "大海"}, "level_3": {"options": [{"text": "大海", "is_correct": true, "explanation": "“站在海边，只能看见一片大海”指一大片海水，符合句意。"}, {"text": "森林", "is_correct": false, "explanation": "语义：站在海边看到的是海，不会是“一片森林”。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：海边不会看见“一片沙漠”，与“海边”的场景冲突。"}, {"text": "教室", "is_correct": false, "explanation": "搭配与语义：“一片”不计量“教室”，且站在海边不会只看见教室。"}], "explanations": {"大海": "“站在海边，只能看见一片大海”指一大片海水，符合句意。", "森林": "语义：站在海边看到的是海，不会是“一片森林”。", "沙漠": "语义：海边不会看见“一片沙漠”，与“海边”的场景冲突。", "教室": "搭配与语义：“一片”不计量“教室”，且站在海边不会只看见教室。"}, "sentence_index": 0, "correct_answer": "大海"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片大海很小，几分钟就能走完。", "explanation": "这里应该用〈池塘〉。“大海”指广阔的海洋，不能用来形容几分钟就能走完的水域。"}, {"text": "我把大海装进杯子里带回了家。", "explanation": "这里应该用〈海水〉。“大海”广阔无边，不能装进杯子，能装的是“海水”。"}, {"text": "这片大海只有脸盆那么大，一伸手就能摸到底。", "explanation": "这里应该用〈水洼〉。“大海”指一眼望不到边的大片海水，不能只有脸盆那么大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87039, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大海", "is_correct": true, "explanation": "「大海」指一眼望不到边的大片海水，读作 dà hǎi。"}, {"text": "大改", "is_correct": false, "explanation": "「大改」dà gǎi：hǎi 与 gǎi 声母不同（h 与 g），意思是“大规模修改”。"}, {"text": "大孩", "is_correct": false, "explanation": "「大孩」dà hái：hǎi（第三声）与 hái（第二声）声调不同，意思是“年龄较大的孩子”。"}, {"text": "大汉", "is_correct": false, "explanation": "「大汉」dà hàn：hǎi 与 hàn 韵母和声调都不同（ai 与 an），意思是“身材高大的男子”。"}], "explanations": {"大海": "「大海」指一眼望不到边的大片海水，读作 dà hǎi。", "大改": "「大改」dà gǎi：hǎi 与 gǎi 声母不同（h 与 g），意思是“大规模修改”。", "大孩": "「大孩」dà hái：hǎi（第三声）与 hái（第二声）声调不同，意思是“年龄较大的孩子”。", "大汉": "「大汉」dà hàn：hǎi 与 hàn 韵母和声调都不同（ai 与 an），意思是“身材高大的男子”。"}, "sentence_index": null, "correct_answer": "大海"}, "level_3": {"options": [{"text": "大海", "is_correct": true, "explanation": "“风一吹，大海上就起了大浪”指大片海面起浪，符合句意。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌上不会因风一吹而“起大浪”，句意不通。"}, {"text": "屋顶", "is_correct": false, "explanation": "语义：屋顶上不会因风一吹而“起大浪”，“大浪”只出现在水面。"}, {"text": "高空", "is_correct": false, "explanation": "搭配：“高空上”不说“起大浪”，大浪只出现在水面。"}], "explanations": {"大海": "“风一吹，大海上就起了大浪”指大片海面起浪，符合句意。", "书桌": "语义：书桌上不会因风一吹而“起大浪”，句意不通。", "屋顶": "语义：屋顶上不会因风一吹而“起大浪”，“大浪”只出现在水面。", "高空": "搭配：“高空上”不说“起大浪”，大浪只出现在水面。"}, "sentence_index": 6, "correct_answer": "大海"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片大海一步就能跨过去。", "explanation": "这里应该用〈小溪〉。“大海”宽阔无边，不能一步跨过去。"}, {"text": "妈妈在厨房的大海里洗碗。", "explanation": "这里应该用〈水池〉。“大海”是广阔的海水，厨房里洗碗用的是“水池”。"}, {"text": "这片大海只有游泳池那么大，几步就能走到头。", "explanation": "这里应该用〈游泳池〉。“大海”宽阔无边，不能只有游泳池那么大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87039, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "远处有一座大海，波浪很大。", "corrected_sentence": "远处有一片大海，波浪很大。", "error_description": "量词错误：大片海水应该用量词“片”，“座”用于山、楼等。正确说法是“一片大海”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87039, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小船大海上漂着。", "corrected_sentence": "小船在大海上漂着。", "error_description": "介词漏掉：表示地点的“大海上”前要用介词“在”引出，不能省去。应说“小船在大海上漂着”，不能说“小船大海上漂着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
