INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87040, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "广阔的海洋。", "primary_collocate": null, "pronunciation": "dà hǎi", "ipa": "tɑ˥˩ xaɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "大海养育了沿海的人们。", "target_word": "大海", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地球表面大部分被大海覆盖。", "target_word": "大海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这艘船要穿过大海去另一个国家。", "target_word": "大海", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大海里有很多种鱼和海草。", "target_word": "大海", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的梦想是驾船遍游大海。", "target_word": "大海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大海的深处住着许多我们不认识的动物。", "target_word": "大海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海鸟在大海上空飞来飞去。", "target_word": "大海", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老船长一辈子都在大海上生活。", "target_word": "大海", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大海有时安静，有时会突然变得很危险。", "target_word": "大海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水最后会流进大海。", "target_word": "大海", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "广阔的海洋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c817ef8-4072-4671-8660-bc5321147c0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87040, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大海", "is_correct": true, "explanation": "「大海」指广阔的海洋，读作 dà hǎi。"}, {"text": "大改", "is_correct": false, "explanation": "「大改」dà gǎi：hǎi 与 gǎi 声母不同（h 与 g），意思是“大规模修改”。"}, {"text": "大喊", "is_correct": false, "explanation": "「大喊」dà hǎn：hǎi 与 hǎn 韵母不同（ai 与 an），意思是“大声喊叫”。"}, {"text": "大好", "is_correct": false, "explanation": "「大好」dà hǎo：hǎi 与 hǎo 韵母不同（ai 与 ao），意思是“非常好”。"}], "explanations": {"大海": "「大海」指广阔的海洋，读作 dà hǎi。", "大改": "「大改」dà gǎi：hǎi 与 gǎi 声母不同（h 与 g），意思是“大规模修改”。", "大喊": "「大喊」dà hǎn：hǎi 与 hǎn 韵母不同（ai 与 an），意思是“大声喊叫”。", "大好": "「大好」dà hǎo：hǎi 与 hǎo 韵母不同（ai 与 ao），意思是“非常好”。"}, "sentence_index": null, "correct_answer": "大海"}, "level_3": {"options": [{"text": "大海", "is_correct": true, "explanation": "“大海养育了沿海的人们”指海洋哺育沿海居民，符合句意。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠无法养育沿海的人们，与“沿海”的语境冲突。"}, {"text": "草原", "is_correct": false, "explanation": "语义：草原与“沿海”的语境相矛盾，不符合句意。"}, {"text": "理论", "is_correct": false, "explanation": "搭配：“养育”不搭配“理论”，只能说自然环境或地域养育人。"}], "explanations": {"大海": "“大海养育了沿海的人们”指海洋哺育沿海居民，符合句意。", "沙漠": "语义：沙漠无法养育沿海的人们，与“沿海”的语境冲突。", "草原": "语义：草原与“沿海”的语境相矛盾，不符合句意。", "理论": "搭配：“养育”不搭配“理论”，只能说自然环境或地域养育人。"}, "sentence_index": 0, "correct_answer": "大海"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片大海很小，只有几条渔船停靠。", "explanation": "这里应该用〈海湾〉。“大海”指广阔的海洋，不能用来形容只能停几条渔船的小海湾。"}, {"text": "这条大海很长，最后流进了东海。", "explanation": "这里应该用〈河〉。“大海”是海洋，不能说“这条大海”，河流才会流进东海。"}, {"text": "我家阳台上有一个大海，里面养着两条金鱼。", "explanation": "这里应该用〈鱼缸〉。“大海”是广阔的海洋，阳台上养金鱼的是“鱼缸”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87040, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大海", "is_correct": true, "explanation": "「大海」指广阔的海洋，读作 dà hǎi。"}, {"text": "大害", "is_correct": false, "explanation": "「大害」dà hài：hǎi（第三声）与 hài（第四声）声调不同，意思是“大的祸害”。"}, {"text": "大孩", "is_correct": false, "explanation": "「大孩」dà hái：hǎi（第三声）与 hái（第二声）声调不同，意思是“年龄较大的孩子”。"}, {"text": "大汉", "is_correct": false, "explanation": "「大汉」dà hàn：hǎi 与 hàn 韵母和声调都不同（ai 与 an），意思是“身材高大的男子”。"}], "explanations": {"大海": "「大海」指广阔的海洋，读作 dà hǎi。", "大害": "「大害」dà hài：hǎi（第三声）与 hài（第四声）声调不同，意思是“大的祸害”。", "大孩": "「大孩」dà hái：hǎi（第三声）与 hái（第二声）声调不同，意思是“年龄较大的孩子”。", "大汉": "「大汉」dà hàn：hǎi 与 hàn 韵母和声调都不同（ai 与 an），意思是“身材高大的男子”。"}, "sentence_index": null, "correct_answer": "大海"}, "level_3": {"options": [{"text": "大海", "is_correct": true, "explanation": "“海鸟在大海上空飞来飞去”指海鸟在海面上空飞翔，符合句意。"}, {"text": "房间", "is_correct": false, "explanation": "语义：海鸟不会在房间上空飞来飞去，与“海鸟”的情景不符。"}, {"text": "教室", "is_correct": false, "explanation": "语义：海鸟不会在教室上空飞行，句意不通。"}, {"text": "思想", "is_correct": false, "explanation": "搭配：“上空”指空间，不能说“思想上空”。"}], "explanations": {"大海": "“海鸟在大海上空飞来飞去”指海鸟在海面上空飞翔，符合句意。", "房间": "语义：海鸟不会在房间上空飞来飞去，与“海鸟”的情景不符。", "教室": "语义：海鸟不会在教室上空飞行，句意不通。", "思想": "搭配：“上空”指空间，不能说“思想上空”。"}, "sentence_index": 6, "correct_answer": "大海"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片大海里长满了荷花。", "explanation": "这里应该用〈池塘〉。“大海”是广阔的海洋，荷花生长在池塘里，不长在大海里。"}, {"text": "我渴了，把一杯大海喝了下去。", "explanation": "这里应该用〈水〉。“大海”是广阔的海洋，不能装在杯子里喝。"}, {"text": "这片大海只有一个水缸那么大，一伸手就能摸到底。", "explanation": "这里应该用〈水洼〉。“大海”指广阔的海洋，不能只有一个水缸那么大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "渔民们驾船驶向一座大海深处。", "corrected_sentence": "渔民们驾船驶向大海深处。", "error_description": "量词错误：“大海深处”是处所，前面不能加量词“座”。应说“驶向大海深处”，不要加“一座”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他明天横渡过大海。", "corrected_sentence": "他明天横渡大海。", "error_description": "体标错误：动态助词“过”表示已经发生的经历，不能与表示将来的“明天”搭配，应去掉“过”，说“明天横渡大海”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87041, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aa74082-3c8b-4a38-b801-f88e0d556f49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
