INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87041, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "替是帮别人做事，或者代替别人。", "primary_collocate": null, "pronunciation": "tì", "ipa": "tʰi˥˩", "syllable_count": 1, "sentences": [{"text": "你替我去开会吧。", "target_word": "替", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天我替同事上班。", "target_word": "替", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他生病了，我替他请了假。", "target_word": "替", "complexity_tier": "T3", "furigana": "tā shēngbìng le, wǒ tì tā qǐng le jià.", "sentence_source": "generated"}, {"text": "妈妈替我买了一本书。", "target_word": "替", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你替我拿一下这个包。", "target_word": "替", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天我有事，你能替我上课吗？", "target_word": "替", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不在，我替他把信收下了。", "target_word": "替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王累了，我来替他开车。", "target_word": "替", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁能替老师发这些书？", "target_word": "替", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "奶奶忙不过来，我就替她洗了碗。", "target_word": "替", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "替代", "label": "复合"}, {"form": "替换", "label": "复合"}], "register": "口语", "sense_fingerprint": "替·代替别人做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d39edd-56d4-44c7-b5fd-93bb63a43a9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87041, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "替", "is_correct": true, "explanation": "替读 tì（第四声），意思是代别人做事，是本题的目标词。"}, {"text": "体", "is_correct": false, "explanation": "tǐ（第三声）与 tì（第四声）声调不同，体的意思是身体。"}, {"text": "提", "is_correct": false, "explanation": "tí（第二声）与 tì（第四声）声调不同，提的意思是提起、提出。"}, {"text": "地", "is_correct": false, "explanation": "dì 与 tì 声母不同（d 与 t），地的意思是土地。"}, {"text": "次", "is_correct": false, "explanation": "cì 与 tì 声母不同（c 与 t），次的意思是次数。"}, {"text": "四", "is_correct": false, "explanation": "sì 与 tì 声母不同（s 与 t），四的意思是数字四。"}], "explanations": {"替": "替读 tì（第四声），意思是代别人做事，是本题的目标词。", "体": "tǐ（第三声）与 tì（第四声）声调不同，体的意思是身体。", "提": "tí（第二声）与 tì（第四声）声调不同，提的意思是提起、提出。", "地": "dì 与 tì 声母不同（d 与 t），地的意思是土地。", "次": "cì 与 tì 声母不同（c 与 t），次的意思是次数。", "四": "sì 与 tì 声母不同（s 与 t），四的意思是数字四。"}, "sentence_index": null, "correct_answer": "替"}, "level_3": {"options": [{"text": "替", "is_correct": true, "explanation": "替：代别人做事，「你替我去开会」即代我去参加会议，符合句意。"}, {"text": "从", "is_correct": false, "explanation": "配价：“从”引出起点或来源，“从我去开会”没有合理的起点，句子不成立。"}, {"text": "向", "is_correct": false, "explanation": "语义：“向”表示朝向或对象，与“代我去开会”的意思不符。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”后要接被处置的宾语，“你把我去开会”结构不成立。"}], "explanations": {"替": "替：代别人做事，「你替我去开会」即代我去参加会议，符合句意。", "从": "配价：“从”引出起点或来源，“从我去开会”没有合理的起点，句子不成立。", "向": "语义：“向”表示朝向或对象，与“代我去开会”的意思不符。", "把": "配价：“把”后要接被处置的宾语，“你把我去开会”结构不成立。"}, "sentence_index": 0, "correct_answer": "替"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他替我睡着了。", "explanation": "“替”表示代别人做事，但“睡着”是人自己的状态，别人不能替你睡着，这句话不合逻辑。"}, {"text": "我替我自己洗了碗。", "explanation": "这里应该用〈亲自〉。“替”表示代别人做事，自己动手做的事要用〈亲自〉，不能说“替我自己”。"}, {"text": "妈妈替我吃了药。", "explanation": "“替”表示代别人做事，但吃药是为了治自己的病，别人替我吃药没有用，这句话不合逻辑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aa74082-3c8b-4a38-b801-f88e0d556f49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87041, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "替", "is_correct": true, "explanation": "替读 tì（第四声），意思是代别人做事，是本题的目标词。"}, {"text": "他", "is_correct": false, "explanation": "tā（第一声）与 tì（第四声）声调不同，他的意思是他。"}, {"text": "梯", "is_correct": false, "explanation": "tī（第一声）与 tì（第四声）声调不同，梯的意思是梯子。"}, {"text": "题", "is_correct": false, "explanation": "tí（第二声）与 tì（第四声）声调不同，题的意思是题目。"}, {"text": "弟", "is_correct": false, "explanation": "dì 与 tì 声母不同（d 与 t），弟的意思是弟弟。"}], "explanations": {"替": "替读 tì（第四声），意思是代别人做事，是本题的目标词。", "他": "tā（第一声）与 tì（第四声）声调不同，他的意思是他。", "梯": "tī（第一声）与 tì（第四声）声调不同，梯的意思是梯子。", "题": "tí（第二声）与 tì（第四声）声调不同，题的意思是题目。", "弟": "dì 与 tì 声母不同（d 与 t），弟的意思是弟弟。"}, "sentence_index": null, "correct_answer": "替"}, "level_3": {"options": [{"text": "替", "is_correct": true, "explanation": "替：代他收信，「我替他把信收下了」即代他接收信件，符合句意。"}, {"text": "对", "is_correct": false, "explanation": "搭配：“对”后接对象，“对他把信收下”结构不通。"}, {"text": "在", "is_correct": false, "explanation": "配价：“在”引出处所，“在他把信收下”不成立。"}, {"text": "朝", "is_correct": false, "explanation": "语义：“朝”表示方向，与“代他收信”的意思不符。"}], "explanations": {"替": "替：代他收信，「我替他把信收下了」即代他接收信件，符合句意。", "对": "搭配：“对”后接对象，“对他把信收下”结构不通。", "在": "配价：“在”引出处所，“在他把信收下”不成立。", "朝": "语义：“朝”表示方向，与“代他收信”的意思不符。"}, "sentence_index": 6, "correct_answer": "替"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他替我考上了大学。", "explanation": "“替”表示代别人做事，但考上大学是本人的结果，别人不能替你考上，这句话不合逻辑。"}, {"text": "我替他结婚了。", "explanation": "“替”表示代别人做事，结婚要本人完成，不能代替，本人结婚应说〈成家〉。"}, {"text": "他替我生病了。", "explanation": "“替”表示代别人做事，生病是本人的状态，不能由别人代替，本人患病应说〈病倒〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aa74082-3c8b-4a38-b801-f88e0d556f49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
