INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87043, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大谈是说得很多、很起劲。", "primary_collocate": null, "pronunciation": "dà tán", "ipa": "ta˥˩ tʰan˧˥", "syllable_count": 2, "sentences": [{"text": "他一喝酒就大谈自己年轻时的故事。", "target_word": "大谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们坐在一起，大谈明天的足球比赛。", "target_word": "大谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王最爱大谈他儿子的成绩。", "target_word": "大谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她见了老同学，大谈了一个小时旅行的事。", "target_word": "大谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会上，经理没有大谈计划，只说了三点。", "target_word": "大谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是大谈理想，却从来不去做。", "target_word": "大谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在饭桌上大谈今年的天气和收成。", "target_word": "大谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人喜欢在别人面前大谈自己的钱。", "target_word": "大谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家围着桌子，大谈这次旅行的有趣事情。", "target_word": "大谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "儿子回家后大谈学校里新来的老师。", "target_word": "大谈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大谈了", "label": "体标"}, {"form": "大谈特谈", "label": "固定格式"}], "register": "中性", "sense_fingerprint": "说得很多、很起劲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e95692-f9f1-4226-adcd-b55c18dffb26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87043, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大谈", "is_correct": true, "explanation": "大谈（dà tán）意思是说得很多、很起劲，是正确答案。"}, {"text": "大堂", "is_correct": false, "explanation": "大堂（dà táng）与大谈的韵母不同（an 与 ang），意思是大厅。"}, {"text": "大叹", "is_correct": false, "explanation": "大叹（dà tàn）第二个音节声调不同（tàn 第四声，tán 第二声），意思是大声叹息。"}, {"text": "大摊", "is_correct": false, "explanation": "大摊（dà tān）第二个音节声调不同（tān 第一声，tán 第二声），意思是较大的摊位，不常用。"}], "explanations": {"大谈": "大谈（dà tán）意思是说得很多、很起劲，是正确答案。", "大堂": "大堂（dà táng）与大谈的韵母不同（an 与 ang），意思是大厅。", "大叹": "大叹（dà tàn）第二个音节声调不同（tàn 第四声，tán 第二声），意思是大声叹息。", "大摊": "大摊（dà tān）第二个音节声调不同（tān 第一声，tán 第二声），意思是较大的摊位，不常用。"}, "sentence_index": null, "correct_answer": "大谈"}, "level_3": {"options": [{"text": "大谈", "is_correct": true, "explanation": "大谈表示说得很多、很起劲，与“自己年轻时的故事”搭配，句意通顺。"}, {"text": "大骂", "is_correct": false, "explanation": "语义：“大骂”指严厉指责，与“讲年轻时的故事”的语境不合。"}, {"text": "大笑", "is_correct": false, "explanation": "配价：“大笑”是不及物动词，不能直接带“自己年轻时的故事”作宾语。"}, {"text": "大哭", "is_correct": false, "explanation": "配价：“大哭”是不及物动词，后面不能接“故事”这样的宾语。"}], "explanations": {"大谈": "大谈表示说得很多、很起劲，与“自己年轻时的故事”搭配，句意通顺。", "大骂": "语义：“大骂”指严厉指责，与“讲年轻时的故事”的语境不合。", "大笑": "配价：“大笑”是不及物动词，不能直接带“自己年轻时的故事”作宾语。", "大哭": "配价：“大哭”是不及物动词，后面不能接“故事”这样的宾语。"}, "sentence_index": 0, "correct_answer": "大谈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他问我去不去，我只大谈了两个字：是的。", "explanation": "这里应该用〈回答〉。大谈强调说得很多、很起劲，不能用于简短地应答。"}, {"text": "他对我大谈了一句“你好”。", "explanation": "这里应该用〈说〉。大谈强调说得很多，不能用于只说一句话的情况。"}, {"text": "他在角落里小声大谈了几句。", "explanation": "这里应该用〈嘀咕〉。大谈强调大量、起劲地说，与“小声”的低语相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87043, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大谈", "is_correct": true, "explanation": "大谈表示说得很多，与“饭桌上谈今年的天气和收成”相符。"}, {"text": "大吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能接“天气和收成”。"}, {"text": "大睡", "is_correct": false, "explanation": "语义：“睡”与饭桌上谈话的场景不合，句意不通。"}, {"text": "大跑", "is_correct": false, "explanation": "配价：“跑”是不及物动词，不能带“天气和收成”作宾语。"}], "explanations": {"大谈": "大谈表示说得很多，与“饭桌上谈今年的天气和收成”相符。", "大吃": "搭配：“吃”的宾语应是食物，不能接“天气和收成”。", "大睡": "语义：“睡”与饭桌上谈话的场景不合，句意不通。", "大跑": "配价：“跑”是不及物动词，不能带“天气和收成”作宾语。"}, "sentence_index": 6, "correct_answer": "大谈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他三言两语就大谈完了这件事。", "explanation": "这里应该用〈讲〉。大谈强调说得很多、很起劲，与“三言两语”的简短说法相矛盾。"}, {"text": "他大谈了一碗面。", "explanation": "这里应该用〈吃〉。大谈指说得很多，不能与“一碗面”这样的食物搭配。"}, {"text": "他沉默着大谈了一番计划。", "explanation": "这里应该用〈透露〉。大谈强调大量、起劲地说，与“沉默”的寡言相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87043, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他大谈很起劲。", "corrected_sentence": "他大谈得很起劲。", "error_description": "错误：“大谈”之后要用补语标记“得”连接“很起劲”，应说“大谈得很起劲”，不能省略“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
