INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87044, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大量地、起劲地谈论。", "primary_collocate": null, "pronunciation": "dà tán", "ipa": "ta˥˩ tʰan˧˥", "syllable_count": 2, "sentences": [{"text": "电视上的专家都在大谈经济问题。", "target_word": "大谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课时他大谈电影，老师很生气。", "target_word": "大谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上大谈环保的好处。", "target_word": "大谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上大谈新办法，大家都很兴奋。", "target_word": "大谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有很多人大谈这部新电影。", "target_word": "大谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长在会上大谈学习的重要性。", "target_word": "大谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在饭馆里大谈政治，声音很大。", "target_word": "大谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天没有大谈语法，只做了练习。", "target_word": "大谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人大谈未来，老人却想着现在。", "target_word": "大谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者们围着他，让他大谈成功的经验。", "target_word": "大谈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大谈了", "label": "体标"}, {"form": "大谈特谈", "label": "固定格式"}], "register": "中性", "sense_fingerprint": "大量地、起劲地谈论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e95692-f9f1-4226-adcd-b55c18dffb26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = E