INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87044, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大谈", "is_correct": true, "explanation": "大谈（dà tán）意思是大量地、起劲地谈论，是正确答案。"}, {"text": "大堂", "is_correct": false, "explanation": "大堂（dà táng）与大谈的韵母不同（an 与 ang），意思是大厅。"}, {"text": "大叹", "is_correct": false, "explanation": "大叹（dà tàn）第二个音节声调不同（tàn 第四声，tán 第二声），意思是大声叹息。"}, {"text": "大摊", "is_correct": false, "explanation": "大摊（dà tān）第二个音节声调不同（tān 第一声，tán 第二声），意思是较大的摊位，不常用。"}], "explanations": {"大谈": "大谈（dà tán）意思是大量地、起劲地谈论，是正确答案。", "大堂": "大堂（dà táng）与大谈的韵母不同（an 与 ang），意思是大厅。", "大叹": "大叹（dà tàn）第二个音节声调不同（tàn 第四声，tán 第二声），意思是大声叹息。", "大摊": "大摊（dà tān）第二个音节声调不同（tān 第一声，tán 第二声），意思是较大的摊位，不常用。"}, "sentence_index": null, "correct_answer": "大谈"}, "level_3": {"options": [{"text": "大谈", "is_correct": true, "explanation": "大谈表示大量地谈论，与“专家在谈经济问题”的语境相符。"}, {"text": "大哭", "is_correct": false, "explanation": "配价：“大哭”是不及物动词，不能带“经济问题”作宾语。"}, {"text": "大笑", "is_correct": false, "explanation": "配价：“大笑”后面不能接表示话题的“经济问题”。"}, {"text": "大睡", "is_correct": false, "explanation": "语义：“睡”与“专家讨论经济问题”的场景无关，句意不通。"}], "explanations": {"大谈": "大谈表示大量地谈论，与“专家在谈经济问题”的语境相符。", "大哭": "配价：“大哭”是不及物动词，不能带“经济问题”作宾语。", "大笑": "配价：“大笑”后面不能接表示话题的“经济问题”。", "大睡": "语义：“睡”与“专家讨论经济问题”的场景无关，句意不通。"}, "sentence_index": 0, "correct_answer": "大谈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我问他要不要喝，他只大谈了两个字：不要。", "explanation": "这里应该用〈回答〉。大谈强调说得很多、很起劲，不能用于简短地应答。"}, {"text": "他对我大谈了一句“谢谢”。", "explanation": "这里应该用〈说〉。大谈强调说得很多，不能用于只说一句话的情况。"}, {"text": "他默默地大谈了一段台词。", "explanation": "这里应该用〈背诵〉。大谈强调大量、起劲地说，与“默默地”的安静相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87044, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大谈", "is_correct": true, "explanation": "大谈表示大量地谈论，与“在饭馆里谈政治、声音很大”相符。"}, {"text": "大吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能接“政治”。"}, {"text": "大睡", "is_correct": false, "explanation": "语义：“睡”与饭馆里高声谈话的情境不合。"}, {"text": "大跑", "is_correct": false, "explanation": "配价：“跑”不能带“政治”作宾语，句意不通。"}], "explanations": {"大谈": "大谈表示大量地谈论，与“在饭馆里谈政治、声音很大”相符。", "大吃": "搭配：“吃”的宾语应是食物，不能接“政治”。", "大睡": "语义：“睡”与饭馆里高声谈话的情境不合。", "大跑": "配价：“跑”不能带“政治”作宾语，句意不通。"}, "sentence_index": 6, "correct_answer": "大谈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他悄悄大谈了一点消息。", "explanation": "这里应该用〈透露〉。大谈强调大量、起劲地说，与“悄悄”的低调相矛盾。"}, {"text": "他大谈了一杯茶。", "explanation": "这里应该用〈喝〉。大谈指说得很多，不能与“一杯茶”这样的饮品搭配。"}, {"text": "他大谈了一朵花。", "explanation": "这里应该用〈摘〉。大谈指说话，不表示摘取的动作，不能与“一朵花”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老王大谈很起劲。", "corrected_sentence": "老王大谈得很起劲。", "error_description": "错误：“大谈”之后要用补语标记“得”连接“很起劲”，应说“大谈得很起劲”，不能省略“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们正在大谈了自己的计划。", "corrected_sentence": "他们正在大谈自己的计划。", "error_description": "错误：“正在”表示动作正在进行，不能与表示完成的“了”同时使用，应说“正在大谈自己的计划”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
