INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87046, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "处理；做；创设。", "primary_collocate": null, "pronunciation": "bàn", "ipa": "pan˥˩", "syllable_count": 1, "sentences": [{"text": "我要去银行办一张卡。", "target_word": "办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在北京办了一家小公司。", "target_word": "办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事你来办吧。", "target_word": "办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校每年都办一次运动会。", "target_word": "办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想办一个中文学校。", "target_word": "办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，在哪里办护照？", "target_word": "办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈帮我办好了手续。", "target_word": "办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在公园里办了一场画展。", "target_word": "办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么大的事，一个人办不了。", "target_word": "办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城里新办了一家图书馆。", "target_word": "办", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "办了", "label": "体标"}, {"form": "办过", "label": "体标"}, {"form": "办理", "label": "复合"}, {"form": "辦", "label": "繁体"}], "register": "口语", "sense_fingerprint": "办：处理事务、办理手续，或创办学校、公司等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed471b59-6733-4165-85bc-54587c636e4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87046, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "办", "is_correct": true, "explanation": "正确答案：办（bàn，第四声），意思是处理、办理。"}, {"text": "班", "is_correct": false, "explanation": "bān（第一声）与 bàn（第四声）声调不同，意思是班级。"}, {"text": "板", "is_correct": false, "explanation": "bǎn（第三声）与 bàn（第四声）声调不同，意思是木板。"}, {"text": "判", "is_correct": false, "explanation": "pàn 与 bàn 声母不同（p 与 b），意思是判断、判决。"}, {"text": "棒", "is_correct": false, "explanation": "bàng 与 bàn 韵尾不同（ng 与 n），意思是棒子、很好。"}, {"text": "慢", "is_correct": false, "explanation": "màn 与 bàn 声母不同（m 与 b），意思是缓慢。"}], "explanations": {"办": "正确答案：办（bàn，第四声），意思是处理、办理。", "班": "bān（第一声）与 bàn（第四声）声调不同，意思是班级。", "板": "bǎn（第三声）与 bàn（第四声）声调不同，意思是木板。", "判": "pàn 与 bàn 声母不同（p 与 b），意思是判断、判决。", "棒": "bàng 与 bàn 韵尾不同（ng 与 n），意思是棒子、很好。", "慢": "màn 与 bàn 声母不同（m 与 b），意思是缓慢。"}, "sentence_index": null, "correct_answer": "办"}, "level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，不能与“卡”搭配。"}, {"text": "办", "is_correct": true, "explanation": "正确：“办一张卡”指办理、申请一张卡，符合句中去银行的语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，“卡”不能吃。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物、餐具等，不能说“洗一张卡”。"}], "explanations": {"唱": "语义：“唱”的对象是歌曲，不能与“卡”搭配。", "办": "正确：“办一张卡”指办理、申请一张卡，符合句中去银行的语境。", "吃": "语义：“吃”的对象是食物，“卡”不能吃。", "洗": "搭配：“洗”的对象是衣物、餐具等，不能说“洗一张卡”。"}, "sentence_index": 0, "correct_answer": "办"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于办完了午觉。", "explanation": "这里应该用〈睡〉。办不用于“午觉”这类动作，应说“睡午觉”。"}, {"text": "他每天都办牛奶。", "explanation": "这里应该用〈喝〉。办不表示饮用，“办牛奶”不成立。"}, {"text": "我每天都办碗。", "explanation": "这里应该用〈洗〉。办不用于清洗餐具，只能说“洗碗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87046, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "办", "is_correct": true, "explanation": "正确答案：办（bàn，第四声），意思是处理、办理。"}, {"text": "笨", "is_correct": false, "explanation": "bèn 与 bàn 韵母不同（en 与 an），意思是笨拙。"}, {"text": "盼", "is_correct": false, "explanation": "pàn 与 bàn 声母不同（p 与 b），意思是盼望。"}, {"text": "败", "is_correct": false, "explanation": "bài 与 bàn 韵母不同（ai 与 an），意思是失败。"}, {"text": "版", "is_correct": false, "explanation": "bǎn（第三声）与 bàn（第四声）声调不同，意思是版本、版面。"}], "explanations": {"办": "正确答案：办（bàn，第四声），意思是处理、办理。", "笨": "bèn 与 bàn 韵母不同（en 与 an），意思是笨拙。", "盼": "pàn 与 bàn 声母不同（p 与 b），意思是盼望。", "败": "bài 与 bàn 韵母不同（ai 与 an），意思是失败。", "版": "bǎn（第三声）与 bàn（第四声）声调不同，意思是版本、版面。"}, "sentence_index": null, "correct_answer": "办"}, "level_3": {"options": [{"text": "咬", "is_correct": false, "explanation": "语义：“咬”的对象是具体物体，不能用来指手续。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“手续”作宾语。"}, {"text": "办", "is_correct": true, "explanation": "正确：“办好了手续”指把手续办成，符合句中帮忙的语境。"}, {"text": "笑", "is_correct": false, "explanation": "语义：“笑”不能与“手续”搭配，句子无法表达办理事务。"}], "explanations": {"咬": "语义：“咬”的对象是具体物体，不能用来指手续。", "睡": "配价：“睡”是不及物动词，不能带“手续”作宾语。", "办": "正确：“办好了手续”指把手续办成，符合句中帮忙的语境。", "笑": "语义：“笑”不能与“手续”搭配，句子无法表达办理事务。"}, "sentence_index": 6, "correct_answer": "办"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他办了一圈操场。", "explanation": "这里应该用〈跑〉。办不表示跑步，“办一圈操场”不成立。"}, {"text": "我办了一封信。", "explanation": "这里应该用〈写〉。办不用于书写，“办一封信”不成立。"}, {"text": "他办了一个包裹。", "explanation": "这里应该用〈寄〉。办不表示寄送物品，“办包裹”不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid,