INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87046, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经好办了签证。", "corrected_sentence": "他已经办好了签证。", "error_description": "错误形式“好办了”（“好办”是形容词，表示容易办）；正确形式“办好了”。“好”是结果补语，必须紧跟在“办”后面，表示把事情办成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
