INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87047, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "有着的意思是有，常常用在比较长的话里。", "primary_collocate": null, "pronunciation": "yǒu zhe", "ipa": "joʊ˨˩˦ ʈʂɤ", "syllable_count": 2, "sentences": [{"text": "这座城市有着一千多年的历史。", "target_word": "有着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有着一双明亮的大眼睛。", "target_word": "有着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小村子有着美丽的风景。", "target_word": "有着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有着很多志同道合的好朋友，大家常常一起旅行。", "target_word": "有着", "complexity_tier": "T3", "furigana": "tā yǒu zhe hěn duō zhì tóng dào hé de hǎo péng you dà jiā cháng cháng yì qǐ lǚ xíng", "sentence_source": "generated"}, {"text": "这家店有着几十年的老手艺。", "target_word": "有着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们两个人有着相同的爱好。", "target_word": "有着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师有着丰富的教学经验。", "target_word": "有着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山有着很多有趣的故事。", "target_word": "有着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就有着一个画家梦。", "target_word": "有着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小狗有着一身白色的毛。", "target_word": "有着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "有着：书面语的“有”，多用在较长的句子里，后面带名词性成分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08020456-83a6-4525-94f5-4b11f7843608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87047, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有着", "is_correct": true, "explanation": "正确。“有着”（yǒu zhe）表示具有，是这里要学的词。"}, {"text": "游着", "is_correct": false, "explanation": "yóu zhe 与 yǒu zhe 第一个音节声调不同（第二声与第三声），意思是在水里游动。"}, {"text": "悠着", "is_correct": false, "explanation": "yōu zhe 与 yǒu zhe 声调不同（第一声与第三声），意思是慢慢来、不要太用力。"}, {"text": "幼者", "is_correct": false, "explanation": "yòu zhě 与 yǒu zhe 声调不同（第四声与第三声，第二个音节也不是轻声），意思是年幼的人。"}], "explanations": {"有着": "正确。“有着”（yǒu zhe）表示具有，是这里要学的词。", "游着": "yóu zhe 与 yǒu zhe 第一个音节声调不同（第二声与第三声），意思是在水里游动。", "悠着": "yōu zhe 与 yǒu zhe 声调不同（第一声与第三声），意思是慢慢来、不要太用力。", "幼者": "yòu zhě 与 yǒu zhe 声调不同（第四声与第三声，第二个音节也不是轻声），意思是年幼的人。"}, "sentence_index": null, "correct_answer": "有着"}, "level_3": {"options": [{"text": "讨厌", "is_correct": false, "explanation": "语义：城市没有情感，不能“讨厌”一千多年的历史，句子说的是城市具有这段历史。"}, {"text": "有着", "is_correct": true, "explanation": "正确。“有着”表示具有，用来描述城市拥有悠久的历史，符合句子语境。"}, {"text": "想念", "is_correct": false, "explanation": "语义：“想念”需要有感情的主体，城市不会想念历史，这里要表示城市具有历史。"}, {"text": "搞", "is_correct": false, "explanation": "语域：“搞”口语色彩较重，与“一千多年的历史”这类书面表达不协调，也不说“搞历史”。"}], "explanations": {"讨厌": "语义：城市没有情感，不能“讨厌”一千多年的历史，句子说的是城市具有这段历史。", "有着": "正确。“有着”表示具有，用来描述城市拥有悠久的历史，符合句子语境。", "想念": "语义：“想念”需要有感情的主体，城市不会想念历史，这里要表示城市具有历史。", "搞": "语域：“搞”口语色彩较重，与“一千多年的历史”这类书面表达不协调，也不说“搞历史”。"}, "sentence_index": 0, "correct_answer": "有着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次数学考试有着一百分。", "explanation": "这里应该用〈考〉。“有着”表示具有的特点，不用于说考试得分，应说“他这次数学考了一百分”。"}, {"text": "他去图书馆时有着一本词典。", "explanation": "这里应该用〈带〉。“有着”表示长期具有的特征，不用于随身携带的具体物品，这里要说“带着一本词典”。"}, {"text": "我昨天有着一次体检。", "explanation": "这里应该用〈做〉。“有着”表示具有的特点或持续的状态，不用于说一次性的活动，应说“我昨天做了一次体检”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87047, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穿", "is_correct": false, "explanation": "语义：经验不能“穿”在身上，“穿”只搭配衣物，这里说的是老师具备的经验。"}, {"text": "有着", "is_correct": true, "explanation": "正确。“有着”表示具有，“老师有着丰富的教学经验”说明老师具备的能力，符合书面语的说法。"}, {"text": "饮用", "is_correct": false, "explanation": "搭配：“饮用”的对象是饮料之类的液体，不说“饮用经验”。"}, {"text": "捣鼓", "is_correct": false, "explanation": "语域：“捣鼓”口语色彩重，不说“捣鼓经验”，与书面语的句子不协调。"}], "explanations": {"穿": "语义：经验不能“穿”在身上，“穿”只搭配衣物，这里说的是老师具备的经验。", "有着": "正确。“有着”表示具有，“老师有着丰富的教学经验”说明老师具备的能力，符合书面语的说法。", "饮用": "搭配：“饮用”的对象是饮料之类的液体，不说“饮用经验”。", "捣鼓": "语域：“捣鼓”口语色彩重，不说“捣鼓经验”，与书面语的句子不协调。"}, "sentence_index": 6, "correct_answer": "有着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场大雨有着很大的损失。", "explanation": "这里应该用〈造成〉。“有着”表示具有的特点，损失是事件造成的结果，要说“造成很大的损失”。"}, {"text": "他每天早上有着一个小时去跑步。", "explanation": "这里应该用〈花〉。“有着”表示具有的特点，不用于说花费的时间，应说“他每天早上花一个小时去跑步”。"}, {"text": "他上个星期有着一场比赛。", "explanation": "这里应该用〈参加〉。“有着”表示长期具有的特点，不用于说一次性的活动，应说“他上个星期参加了一场比赛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87047, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所大学有有着悠久的历史。", "corrected_sentence": "这所大学有着悠久的历史。", "error_description": "多了一个“有”。“有着”是一个词，前面不能再加“有”，应改为“这所大学有着悠久的历史”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87047, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片森林有着了丰富的资源。", "corrected_sentence": "这片森林有着丰富的资源。", "error_description": "多了“了”。“有着”后面不能再加“了”，两个动态助词不能连用，应改为“这片森林有着丰富的资源”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87048, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缺乏", "is_correct": true, "explanation": "反义：在“具有”这一义项上，“缺乏”与“有着”意思相对。"}, {"text": "唱歌", "is_correct": false, "explanation": "无反义关系：“唱歌”是一种活动，与“具有”的意思无关。"}, {"text": "写作", "is_correct": false, "explanation": "无反义关系：“写作”是一种行为，与“具有”的意思无关。"}, {"text": "游泳", "is_correct": false, "explanation": "无反义关系：“游泳”是一种运动，与“具有”的意思无关。"}], "correct_answer": "缺乏", "explanations": {"缺乏": "反义：在“具有”这一义项上，“缺乏”与“有着”意思相对。", "唱歌": "无反义关系：“唱歌”是一种活动，与“具有”的意思无关。", "写作": "无反义关系：“写作”是一种行为，与“具有”的意思无关。", "游泳": "无反义关系：“游泳”是一种运动，与“具有”的意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
