INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87048, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "动词，具有；拥有（多带抽象事物作宾语）。", "primary_collocate": null, "pronunciation": "yǒu zhe", "ipa": "joʊ˨˩˦ ʈʂɤ", "syllable_count": 2, "sentences": [{"text": "这种文化有着深远的影响。", "target_word": "有着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对工作有着很高的热情。", "target_word": "有着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国之间有着密切的关系。", "target_word": "有着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个想法有着重要的意义。", "target_word": "有着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对音乐有着特别的感情。", "target_word": "有着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两件事有着不同的原因。", "target_word": "有着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人有着无限的可能。", "target_word": "有着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有着独特的魅力。", "target_word": "有着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家对这件事有着不同的看法。", "target_word": "有着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书对孩子有着很大的帮助。", "target_word": "有着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "有着：具有、拥有，宾语多为抽象事物，如影响、意义、关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08020456-83a6-4525-94f5-4b11f7843608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87048, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有着", "is_correct": true, "explanation": "正确。“有着”（yǒu zhe）表示具有，是这里要学的词。"}, {"text": "游着", "is_correct": false, "explanation": "yóu zhe 与 yǒu zhe 第一个音节声调不同（第二声与第三声），意思是在水里游动。"}, {"text": "悠着", "is_correct": false, "explanation": "yōu zhe 与 yǒu zhe 声调不同（第一声与第三声），意思是慢慢来、不要太用力。"}, {"text": "幼者", "is_correct": false, "explanation": "yòu zhě 与 yǒu zhe 声调不同（第四声与第三声，第二个音节也不是轻声），意思是年幼的人。"}], "explanations": {"有着": "正确。“有着”（yǒu zhe）表示具有，是这里要学的词。", "游着": "yóu zhe 与 yǒu zhe 第一个音节声调不同（第二声与第三声），意思是在水里游动。", "悠着": "yōu zhe 与 yǒu zhe 声调不同（第一声与第三声），意思是慢慢来、不要太用力。", "幼者": "yòu zhě 与 yǒu zhe 声调不同（第四声与第三声，第二个音节也不是轻声），意思是年幼的人。"}, "sentence_index": null, "correct_answer": "有着"}, "level_3": {"options": [{"text": "打听", "is_correct": false, "explanation": "搭配：“打听”的对象是消息、情况，不说“打听深远的影响”。"}, {"text": "有着", "is_correct": true, "explanation": "正确。“有着”表示具有，文化具有深远的影响，符合句子语境。"}, {"text": "憎恨", "is_correct": false, "explanation": "语义：“憎恨”需要有感情的主体，文化不会憎恨影响，句子说的是文化本身带来的影响。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指吃东西，不能吃影响，这里要说文化具有影响。"}], "explanations": {"打听": "搭配：“打听”的对象是消息、情况，不说“打听深远的影响”。", "有着": "正确。“有着”表示具有，文化具有深远的影响，符合句子语境。", "憎恨": "语义：“憎恨”需要有感情的主体，文化不会憎恨影响，句子说的是文化本身带来的影响。", "吃": "语义：“吃”指吃东西，不能吃影响，这里要说文化具有影响。"}, "sentence_index": 0, "correct_answer": "有着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次英语有着一百分。", "explanation": "这里应该用〈考〉。“有着”表示具有的特点，不用于说考试得分，应说“他这次英语考了一百分”。"}, {"text": "他对这件事有着一次道歉。", "explanation": "这里应该用〈做〉。“有着”不用于说一次性的言语行为，应说“他对这件事做了一次道歉”。"}, {"text": "这场地震有着三十人的死亡。", "explanation": "这里应该用〈造成〉。“有着”表示具有的特点，不用于说事件导致的伤亡，应说“这场地震造成了三十人死亡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87048, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穿", "is_correct": false, "explanation": "语义：“穿”搭配衣物，“可能”不能穿在身上，这里要表示年轻人具有可能性。"}, {"text": "有着", "is_correct": true, "explanation": "正确。“有着”表示具有，“年轻人有着无限的可能”说的是年轻人具备的潜力。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”的对象是墙上的物品、招牌等，不说“挂可能”。"}, {"text": "搞", "is_correct": false, "explanation": "语域：“搞”口语色彩重，“搞可能”不成搭配，与句子的书面语气不协调。"}], "explanations": {"穿": "语义：“穿”搭配衣物，“可能”不能穿在身上，这里要表示年轻人具有可能性。", "有着": "正确。“有着”表示具有，“年轻人有着无限的可能”说的是年轻人具备的潜力。", "挂": "搭配：“挂”的对象是墙上的物品、招牌等，不说“挂可能”。", "搞": "语域：“搞”口语色彩重，“搞可能”不成搭配，与句子的书面语气不协调。"}, "sentence_index": 6, "correct_answer": "有着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛我们有着第一名。", "explanation": "这里应该用〈取得〉。“有着”表示具有的特点，不用于说比赛中获得的名次，这里要说“取得第一名”。"}, {"text": "他的做法有着一次批评。", "explanation": "这里应该用〈受到〉。“有着”不用于一次性的评价，应说“他的做法受到了批评”。"}, {"text": "我们有着一封信。", "explanation": "这里应该用〈收到〉。“有着”表示长期具有的特点，不用于说收到的一件具体物品，这里要说“收到一封信”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87048, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影没有着独特的风格。", "corrected_sentence": "这部电影有着独特的风格。", "error_description": "多了“没”。“有着”只用于肯定句，不说“没有着”，应去掉“没”，改为“这部电影有着独特的风格”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87048, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个民族有着过丰富的文化。", "corrected_sentence": "这个民族有着丰富的文化。", "error_description": "“过”放在了“着”后面。“着”与“过”两个动态助词不能连用，应改为“这个民族有着丰富的文化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
