INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87051, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "下来是从高的地方到低的地方来。", "primary_collocate": null, "pronunciation": "xià lái", "ipa": "ɕja˥˩ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "请你从楼上下来吃饭。", "target_word": "下来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "猫从树上下来了。", "target_word": "下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷慢慢地从山上下来。", "target_word": "下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你快从桌子上下来！", "target_word": "下来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从二楼跑下来找我。", "target_word": "下来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们从车上下来了。", "target_word": "下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "气球飘到了高处，过了很久才慢慢下来。", "target_word": "下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把箱子从车上搬下来。", "target_word": "下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机从空中慢慢降下来。", "target_word": "下来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟爬上树，不敢下来了。", "target_word": "下来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "下来了", "label": "体标（完成）"}, {"form": "下得来", "label": "可能补语"}, {"form": "下不来", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "从高的地方到低的地方来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T1: 3 words above tier T1 (max 2): 气球 (Zipf 3.87), 飘 (Zipf 3.75), 高处 (Zipf 3.62)']::text[], 'aa572e2a-b4ac-45be-a597-2cd926dc15a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87051, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上去", "is_correct": false, "explanation": "语义：“上去”是向上远离说话人，与“从楼上”过来吃饭的方向相反。"}, {"text": "上来", "is_correct": false, "explanation": "语义：“上来”表示向上来，与“从楼上”这一起点矛盾。"}, {"text": "进去", "is_correct": false, "explanation": "搭配：“进去”要求进入某个处所，“楼上”不能作进入的终点。"}, {"text": "下来", "is_correct": true, "explanation": "“下来”表示从楼上来到说话人所在处，与“请你从楼上……吃饭”相合。"}], "explanations": {"上去": "语义：“上去”是向上远离说话人，与“从楼上”过来吃饭的方向相反。", "上来": "语义：“上来”表示向上来，与“从楼上”这一起点矛盾。", "进去": "搭配：“进去”要求进入某个处所，“楼上”不能作进入的终点。", "下来": "“下来”表示从楼上来到说话人所在处，与“请你从楼上……吃饭”相合。"}, "sentence_index": 0, "correct_answer": "下来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电梯从一楼下来到了十楼。", "explanation": "这里应该用〈上去〉。从一楼到十楼是由低到高，不能用“下来”。"}, {"text": "他从山脚下来，爬到了山顶。", "explanation": "这里应该用〈上去〉。从山脚到山顶是由低到高，不能用“下来”。"}, {"text": "我们要把这项研究进行下来。", "explanation": "这里应该用〈下去〉。“下去”表示动作继续到将来，“下来”表示从过去延续到现在，不能用于将来的继续。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87051, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进去", "is_correct": false, "explanation": "搭配：“进去”要求进入某个处所，此句中没有可进入的处所。"}, {"text": "出去", "is_correct": false, "explanation": "语义：“出去”指向外离开某处，与气球从高处慢慢落下的意思不符。"}, {"text": "起来", "is_correct": false, "explanation": "语义：“起来”表示向上或动作开始，与“飘到高处”之后的下落相反。"}, {"text": "下来", "is_correct": true, "explanation": "“下来”表示由高处向下、朝说话人所在处移动，与气球慢慢落下相合。"}], "explanations": {"进去": "搭配：“进去”要求进入某个处所，此句中没有可进入的处所。", "出去": "语义：“出去”指向外离开某处，与气球从高处慢慢落下的意思不符。", "起来": "语义：“起来”表示向上或动作开始，与“飘到高处”之后的下落相反。", "下来": "“下来”表示由高处向下、朝说话人所在处移动，与气球慢慢落下相合。"}, "sentence_index": 6, "correct_answer": "下来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "太阳从东边下来了，天亮了。", "explanation": "这里应该用〈升起来〉。太阳出来是由低到高，不能用“下来”。"}, {"text": "猴子从地上下来，爬到了树顶。", "explanation": "这里应该用〈爬上去〉。从地上到树顶是由低到高，不能用“下来”。"}, {"text": "他从地下室下来，到了一楼。", "explanation": "这里应该用〈上来〉。从地下室到一楼是由低到高，不能用“下来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87051, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小狗从沙发上跳下来下来了。", "corrected_sentence": "小狗从沙发上跳下来了。", "error_description": "错误形式是“跳下来下来了”，正确形式是“跳下来了”。“下来”只能出现一次，多写的一个“下来”是重复成分。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87051, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把东西从车上拿很下来了。", "corrected_sentence": "他把东西从车上拿下来了。", "error_description": "错误形式是“拿很下来了”，正确形式是“拿下来了”。程度副词“很”不能修饰趋向补语“下来”，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
