INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87057, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "天心是天空最中间的地方。", "primary_collocate": null, "pronunciation": "tiān xīn", "ipa": "tʰien˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "月亮慢慢升到了天心。", "target_word": "天心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳走到天心时，天气最热。", "target_word": "天心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里，一轮明月挂在天心。", "target_word": "天心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "抬头一看，天心有一朵白云。", "target_word": "天心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中午的太阳正在天心。", "target_word": "天心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湖水很静，天心的月亮落在水里。", "target_word": "天心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "星星一颗一颗出现，天心最亮。", "target_word": "天心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "月到天心，四周安静极了。", "target_word": "天心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞鸟飞过天心，不见了。", "target_word": "天心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人望着天心，轻轻说了一句话。", "target_word": "天心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "天空最中间的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8381a54f-c1d7-4b10-9819-04a640eace4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87057, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天心", "is_correct": true, "explanation": "天心：天空最中间的地方，是正确答案。"}, {"text": "点心", "is_correct": false, "explanation": "声母和声调不同：diǎn（第三声）与 tiān（第一声）不同，意思是小吃。"}, {"text": "天星", "is_correct": false, "explanation": "韵母不同：xīng（后鼻音）与 xīn（前鼻音）不同，意思是天上的星星。"}, {"text": "甜心", "is_correct": false, "explanation": "声调不同：tián（第二声）与 tiān（第一声）不同，声母韵母相同，意思是甜美的心或昵称。"}], "explanations": {"天心": "天心：天空最中间的地方，是正确答案。", "点心": "声母和声调不同：diǎn（第三声）与 tiān（第一声）不同，意思是小吃。", "天星": "韵母不同：xīng（后鼻音）与 xīn（前鼻音）不同，意思是天上的星星。", "甜心": "声调不同：tián（第二声）与 tiān（第一声）不同，声母韵母相同，意思是甜美的心或昵称。"}, "sentence_index": null, "correct_answer": "天心"}, "level_3": {"options": [{"text": "天心", "is_correct": true, "explanation": "天心：天空的中央，月亮升到天空最高处，与句意相符。"}, {"text": "海底", "is_correct": false, "explanation": "语义：月亮是在天上升起，不会升到海底。"}, {"text": "地下", "is_correct": false, "explanation": "语义：月亮在天上，不能升到地下。"}, {"text": "墙角", "is_correct": false, "explanation": "搭配：「升到」后接天空中的位置，不说升到墙角。"}], "explanations": {"天心": "天心：天空的中央，月亮升到天空最高处，与句意相符。", "海底": "语义：月亮是在天上升起，不会升到海底。", "地下": "语义：月亮在天上，不能升到地下。", "墙角": "搭配：「升到」后接天空中的位置，不说升到墙角。"}, "sentence_index": 0, "correct_answer": "天心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "远处的天心有一座小山。", "explanation": "这里应该用〈天边〉。天心指天空的中央，远处的山在地平线附近，要用天边。"}, {"text": "这间教室的天心放着一张桌子。", "explanation": "这里应该用〈中央〉。天心只指天空的中央，房间里的中间要用中央。"}, {"text": "山的天心有一座小庙。", "explanation": "这里应该用〈高处〉。天心指天空中央，不指山上的位置，要用高处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87057, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天心", "is_correct": true, "explanation": "天心：天空中央，星星出现后最亮的地方，与句意相符。"}, {"text": "地面", "is_correct": false, "explanation": "语义：星星在天空出现，地面不会因此最亮。"}, {"text": "地底", "is_correct": false, "explanation": "语义：星星在天上，地底不可能最亮。"}, {"text": "脚下", "is_correct": false, "explanation": "搭配：「最亮」不接「脚下」作主语，说脚下最亮不自然。"}], "explanations": {"天心": "天心：天空中央，星星出现后最亮的地方，与句意相符。", "地面": "语义：星星在天空出现，地面不会因此最亮。", "地底": "语义：星星在天上，地底不可能最亮。", "脚下": "搭配：「最亮」不接「脚下」作主语，说脚下最亮不自然。"}, "sentence_index": 6, "correct_answer": "天心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们低头看着天心。", "explanation": "这里应该用〈地面〉。天心指天空的中央，低头看的是地上，要用地面。"}, {"text": "城市的天心有一座大广场。", "explanation": "这里应该用〈中心〉。天心只指天空的中央，城市的中心区域要用中心。"}, {"text": "树的天心站着一只鸟。", "explanation": "这里应该用〈顶端〉。天心指天空的中央，树的最高处要用顶端。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87057, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "太阳慢慢升天心。", "corrected_sentence": "太阳慢慢升到天心。", "error_description": "错误：「升天心」。表示上升到某处要用「升到」，缺少「到」，应为「升到天心」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87057, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "半夜，一颗亮星挂天心。", "corrected_sentence": "半夜，一颗亮星挂在天心。", "error_description": "错误：「挂天心」。表示东西挂在某个位置，动词「挂」后面要加「在」，应为「挂在天心」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
