INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87059, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "条例是一条一条写下来的规矩，大家都要照着做。", "primary_collocate": null, "pronunciation": "tiáo lì", "ipa": "tʰjɑʊ˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "公司的新条例说，上班不能迟到。", "target_word": "条例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校有一份条例，大家都要遵守。", "target_word": "条例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区的条例写得很清楚。", "target_word": "条例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照条例，我们不能在这里停车。", "target_word": "条例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份条例一共有十条。", "target_word": "条例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们读了班级条例。", "target_word": "条例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆的条例要求大家保持安静。", "target_word": "条例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没读条例就把车停在了门口。", "target_word": "条例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宿舍条例不让我们晚上十一点以后大声说话。", "target_word": "条例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的同学要先读一读条例。", "target_word": "条例", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项条例", "label": "量词"}, {"form": "管理条例", "label": "复合词"}, {"form": "條例", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "条例：学校、公司、小区等写成一条一条的规矩，大家都要遵守", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08020456-83a6-4525-94f5-4b11f7843608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87059, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "条例", "is_correct": true, "explanation": "正确。“条例”（tiáo lì）指分条列出的规章，是这里要学的词。"}, {"text": "条理", "is_correct": false, "explanation": "tiáo lǐ 与 tiáo lì 第二个音节声调不同（第三声与第四声），意思是做事有次序。"}, {"text": "调理", "is_correct": false, "explanation": "tiáo lǐ 与 tiáo lì 第二个音节声调不同（第三声与第四声），意思是调养身体、安排处理。"}, {"text": "挑理", "is_correct": false, "explanation": "tiāo lǐ 与 tiáo lì 两个音节声调都不同（第一声与第二声，第三声与第四声），意思是挑毛病、找别人的不是。"}], "explanations": {"条例": "正确。“条例”（tiáo lì）指分条列出的规章，是这里要学的词。", "条理": "tiáo lǐ 与 tiáo lì 第二个音节声调不同（第三声与第四声），意思是做事有次序。", "调理": "tiáo lǐ 与 tiáo lì 第二个音节声调不同（第三声与第四声），意思是调养身体、安排处理。", "挑理": "tiāo lǐ 与 tiáo lì 两个音节声调都不同（第一声与第二声，第三声与第四声），意思是挑毛病、找别人的不是。"}, "sentence_index": null, "correct_answer": "条例"}, "level_3": {"options": [{"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不会规定上班时间，“公司的新歌曲说……”不符合常识。"}, {"text": "条例", "is_correct": true, "explanation": "正确。“条例”是规定性的书面文件，可以“说”出规定，符合语境。"}, {"text": "段子", "is_correct": false, "explanation": "语域：“段子”是口语和网络用语，与“公司的新……说”这类正式规章的语境不符。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：菜谱记录做菜的方法，不会规定上班的要求，这里要的是规章文件。"}], "explanations": {"歌曲": "语义：歌曲不会规定上班时间，“公司的新歌曲说……”不符合常识。", "条例": "正确。“条例”是规定性的书面文件，可以“说”出规定，符合语境。", "段子": "语域：“段子”是口语和网络用语，与“公司的新……说”这类正式规章的语境不符。", "菜谱": "语义：菜谱记录做菜的方法，不会规定上班的要求，这里要的是规章文件。"}, "sentence_index": 0, "correct_answer": "条例"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上跑步，这是他的条例。", "explanation": "这里应该用〈习惯〉。条例是成文的规章，个人的生活习惯不能说成条例，这里应说“这是他的习惯”。"}, {"text": "我在条例上看到了今天的天气。", "explanation": "这里应该用〈天气预报〉。条例是要大家遵守的规矩，不报告天气，应说“在天气预报里看到了今天的天气”。"}, {"text": "见面时拥抱是我们这里的条例。", "explanation": "这里应该用〈习俗〉。条例是成文的规章，地方习俗不能叫条例，应说“是我们这里的习俗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87059, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乐曲", "is_correct": false, "explanation": "语义：乐曲是音乐作品，不会对人提出安静的要求，这里要的是规章文件。"}, {"text": "条例", "is_correct": true, "explanation": "正确。“条例”是规章，可以要求大家保持安静，符合图书馆的语境。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”口语色彩重，也不能对人提出要求，与正式规章的语境不协调。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是饮品，不会要求人保持安静，句子要的是可以提出规定的文件。"}], "explanations": {"乐曲": "语义：乐曲是音乐作品，不会对人提出安静的要求，这里要的是规章文件。", "条例": "正确。“条例”是规章，可以要求大家保持安静，符合图书馆的语境。", "玩意儿": "语域：“玩意儿”口语色彩重，也不能对人提出要求，与正式规章的语境不协调。", "饮料": "语义：饮料是饮品，不会要求人保持安静，句子要的是可以提出规定的文件。"}, "sentence_index": 6, "correct_answer": "条例"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在条例上学习历史。", "explanation": "这里应该用〈课本〉。条例是规章文件，不是用来学习历史的读物，应说“在课本上学习历史”。"}, {"text": "这份条例介绍了新产品。", "explanation": "这里应该用〈宣传单〉。条例用来规定大家的行为，介绍产品要用〈宣传单〉。"}, {"text": "这道菜的条例写得很清楚。", "explanation": "这里应该用〈菜谱〉。条例是规章，讲解做菜步骤的文字要用〈菜谱〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87059, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校新出台了一把条例。", "corrected_sentence": "学校新出台了一项条例。", "error_description": "量词用错。“把”多用于有柄的物件，不用来数规章；条例通常用〈项〉或〈份〉，应改为“学校新出台了一项条例”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87059, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "图书馆贴出了一只新条例。", "corrected_sentence": "图书馆贴出了一份新条例。", "error_description": "量词用错。“只”用于动物等，不能数条例；条例用〈份〉或〈项〉，应改为“图书馆贴出了一份新条例”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
