INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87060, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由国家机关或团体制定的、分条列出的规章制度。", "primary_collocate": null, "pronunciation": "tiáo lì", "ipa": "tʰjɑʊ˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "市政府公布了新的交通条例。", "target_word": "条例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项条例明年一月开始执行。", "target_word": "条例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家出台了环境保护条例。", "target_word": "条例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部条例对食品安全作了详细规定。", "target_word": "条例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据条例，公司必须按时发工资。", "target_word": "条例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市人大通过了这项条例。", "target_word": "条例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "违反条例的人要交罚款。", "target_word": "条例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家正在修改这部管理条例。", "target_word": "条例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "协会制定了行业条例。", "target_word": "条例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个条例保护了很多消费者。", "target_word": "条例", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项条例", "label": "量词"}, {"form": "管理条例", "label": "复合词"}, {"form": "條例", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "条例：国家机关或团体制定并公布的、分条列出的正式规章", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08020456-83a6-4525-94f5-4b11f7843608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87060, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "条例", "is_correct": true, "explanation": "正确。“条例”（tiáo lì）指分条列出的规章，是这里要学的词。"}, {"text": "条理", "is_correct": false, "explanation": "tiáo lǐ 与 tiáo lì 第二个音节声调不同（第三声与第四声），意思是做事有次序。"}, {"text": "调理", "is_correct": false, "explanation": "tiáo lǐ 与 tiáo lì 第二个音节声调不同（第三声与第四声），意思是调养身体、安排处理。"}, {"text": "挑理", "is_correct": false, "explanation": "tiāo lǐ 与 tiáo lì 两个音节声调都不同（第一声与第二声，第三声与第四声），意思是挑毛病、找别人的不是。"}], "explanations": {"条例": "正确。“条例”（tiáo lì）指分条列出的规章，是这里要学的词。", "条理": "tiáo lǐ 与 tiáo lì 第二个音节声调不同（第三声与第四声），意思是做事有次序。", "调理": "tiáo lǐ 与 tiáo lì 第二个音节声调不同（第三声与第四声），意思是调养身体、安排处理。", "挑理": "tiāo lǐ 与 tiáo lì 两个音节声调都不同（第一声与第二声，第三声与第四声），意思是挑毛病、找别人的不是。"}, "sentence_index": null, "correct_answer": "条例"}, "level_3": {"options": [{"text": "食谱", "is_correct": false, "explanation": "语义：食谱记录做菜的方法，不是交通方面的规定，说“交通食谱”不通。"}, {"text": "条例", "is_correct": true, "explanation": "正确。“交通条例”是政府发布的交通规定，符合“公布”的语境。"}, {"text": "段子", "is_correct": false, "explanation": "语域：“段子”口语色彩重，不能“公布”，与政府文件的语境不协调。"}, {"text": "相册", "is_correct": false, "explanation": "语义：相册收存照片，不是交通规定，政府不会公布“交通相册”。"}], "explanations": {"食谱": "语义：食谱记录做菜的方法，不是交通方面的规定，说“交通食谱”不通。", "条例": "正确。“交通条例”是政府发布的交通规定，符合“公布”的语境。", "段子": "语域：“段子”口语色彩重，不能“公布”，与政府文件的语境不协调。", "相册": "语义：相册收存照片，不是交通规定，政府不会公布“交通相册”。"}, "sentence_index": 0, "correct_answer": "条例"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的条例规定晚上十点要睡觉。", "explanation": "这里应该用〈家规〉。条例是国家机关或团体制定的规章，家里的规矩不能叫条例。"}, {"text": "这部条例教我们怎么做蛋糕。", "explanation": "这里应该用〈食谱〉。条例是分条列出的规章，教人做菜的书要用〈食谱〉。"}, {"text": "这部条例的情节很精彩。", "explanation": "这里应该用〈小说〉。条例是规章，不写情节，应说“这部小说的情节很精彩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87060, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不能被“违反”，这里要的是规定性的文件。"}, {"text": "条例", "is_correct": true, "explanation": "正确。“违反条例”指违背规定，符合语境。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“违反”的对象是规定或法律，不说“违反汽车”。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是食物，不能被“违反”，这里要表示违背规定。"}], "explanations": {"歌曲": "语义：歌曲不能被“违反”，这里要的是规定性的文件。", "条例": "正确。“违反条例”指违背规定，符合语境。", "汽车": "搭配：“违反”的对象是规定或法律，不说“违反汽车”。", "水果": "语义：水果是食物，不能被“违反”，这里要表示违背规定。"}, "sentence_index": 6, "correct_answer": "条例"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我给朋友写了一份条例，表达感谢。", "explanation": "这里应该用〈信〉。条例是规章，不是用来表达感谢的文字，这里应说“写了一封信”。"}, {"text": "饭馆的条例上写着很多菜。", "explanation": "这里应该用〈菜单〉。条例是规章，不列菜品，要说“菜单上写着很多菜”。"}, {"text": "孩子们喜欢在条例里看童话。", "explanation": "这里应该用〈故事书〉。条例是规章文件，孩子们读的童话要用〈故事书〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87060, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "省政府公布了一把新的环保条例。", "corrected_sentence": "省政府公布了一项新的环保条例。", "error_description": "量词用错。条例应该用〈项〉，〈把〉用于有柄的东西，应改为“省政府公布了一项新的环保条例”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87060, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市人大通过了一场新的条例。", "corrected_sentence": "市人大通过了一项新的条例。", "error_description": "量词用错。〈场〉用于比赛、活动等，条例应该用〈项〉，应改为“市人大通过了一项新的条例”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
