INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87061, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "天条是天上定下的规矩。人们常说，大家都要守的规矩，也叫天条。", "primary_collocate": null, "pronunciation": "tiān tiáo", "ipa": "tʰjɛn˥ tʰjɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "在我们公司，准时上班是一条天条。", "target_word": "天条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对妈妈来说，孩子的安全是不能碰的天条。", "target_word": "天条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个村子里，不能乱砍树是大家的天条。", "target_word": "天条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说过，不准说谎是我们店的天条。", "target_word": "天条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车喝酒，那可是谁都不能碰的天条。", "target_word": "天条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家人有一条天条：吃饭时不许看手机。", "target_word": "天条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班有条天条，上课不能迟到。", "target_word": "天条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把早睡当成天条，从来不熬夜。", "target_word": "天条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对医生来说，救人是第一条天条。", "target_word": "天条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁也不能破坏这条天条，大家都要守。", "target_word": "天条", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条天条", "label": "量词"}], "register": "中性", "sense_fingerprint": "天条：本指天上定下的规矩，常用来指人人必须遵守、不能违反的规矩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157c64-73c7-4e54-9585-b5a2f818129e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87061, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "河流", "is_correct": false, "explanation": "语义：“河流”是自然的水道，不是人人必须遵守的规定，与“准时上班是一条……”不合。"}, {"text": "天条", "is_correct": true, "explanation": "天条：天上定下的规矩，也指大家都要守的规矩，“准时上班”正是这样的规定。"}, {"text": "围巾", "is_correct": false, "explanation": "语义：“围巾”是穿戴的物件，不是规矩，句中说的是上班的要求。"}, {"text": "闪电", "is_correct": false, "explanation": "搭配：“闪电”是自然现象，不能与“准时上班”这类规定构成“是一条……”的判断。"}], "explanations": {"河流": "语义：“河流”是自然的水道，不是人人必须遵守的规定，与“准时上班是一条……”不合。", "天条": "天条：天上定下的规矩，也指大家都要守的规矩，“准时上班”正是这样的规定。", "围巾": "语义：“围巾”是穿戴的物件，不是规矩，句中说的是上班的要求。", "闪电": "搭配：“闪电”是自然现象，不能与“准时上班”这类规定构成“是一条……”的判断。"}, "sentence_index": 0, "correct_answer": "天条"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的天条有一米八，比同学都高。", "explanation": "这里应该用〈身高〉。天条指必须遵守的规定，不指身高。"}, {"text": "他的天条是打篮球。", "explanation": "这里应该用〈爱好〉。天条指必须遵守的规定，不指个人的兴趣。"}, {"text": "我的天条是当一名宇航员。", "explanation": "这里应该用〈梦想〉。天条指必须遵守的规定，不指想要实现的愿望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87061, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "池塘", "is_correct": false, "explanation": "语义：“池塘”是水面的地方，不是规定，“有条池塘，上课不能迟到”说不通。"}, {"text": "鱼", "is_correct": false, "explanation": "搭配：“有条鱼”后接“上课不能迟到”，二者没有语义联系，不搭配。"}, {"text": "天条", "is_correct": true, "explanation": "天条：大家都要守的规矩，“我们班有条天条，上课不能迟到”说的正是班里的规定。"}, {"text": "裙子", "is_correct": false, "explanation": "语义：“裙子”是衣物，不是规定，与“上课不能迟到”的语境不合。"}], "explanations": {"池塘": "语义：“池塘”是水面的地方，不是规定，“有条池塘，上课不能迟到”说不通。", "鱼": "搭配：“有条鱼”后接“上课不能迟到”，二者没有语义联系，不搭配。", "天条": "天条：大家都要守的规矩，“我们班有条天条，上课不能迟到”说的正是班里的规定。", "裙子": "语义：“裙子”是衣物，不是规定，与“上课不能迟到”的语境不合。"}, "sentence_index": 6, "correct_answer": "天条"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给孩子们出天条，让他们猜。", "explanation": "这里应该用〈谜语〉。天条指规定，不指让人猜的谜，谜语才能被出和猜。"}, {"text": "孩子们在操场上玩天条。", "explanation": "这里应该用〈游戏〉。天条指规定，不能说“玩天条”，玩的是游戏。"}, {"text": "她在台上唱天条。", "explanation": "这里应该用〈歌〉。天条指规定，不能用“唱”来搭配，唱的是歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87061, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在我家，按时吃饭是一只天条。", "corrected_sentence": "在我家，按时吃饭是一条天条。", "error_description": "量词错误：“天条”应用量词“条”，不用“只”。“只”多用于动物或成对的物件。正确说法是“一条天条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87061, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们店有一张天条：不许赊账。", "corrected_sentence": "我们店有一条天条：不许赊账。", "error_description": "量词错误：“天条”应用量词“条”，不用“张”。“张”用于纸、桌子等平面的东西。正确说法是“一条天条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
