INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87062, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87062, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "神话中天界的法规；比喻必须严格遵守的规定。", "primary_collocate": null, "pronunciation": "tiān tiáo", "ipa": "tʰjɛn˥ tʰjɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "神话里，神仙犯了天条，要受很重的罚。", "target_word": "天条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孙悟空大闹天宫，触犯了天条。", "target_word": "天条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "玉皇大帝说，天条不能改，谁也不能例外。", "target_word": "天条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "故事里，仙女爱上了凡人，违反了天条。", "target_word": "天条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这部电视剧里，天条规定神仙不能下凡。", "target_word": "天条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司的保密规定，简直就是天条。", "target_word": "天条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对这个老师来说，作业按时交是不能破的天条。", "target_word": "天条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太上老君说，违背天条的人，一定要受罚。", "target_word": "天条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在古代神话里，天条比人间的法律还严。", "target_word": "天条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项规定非常严，工人们都当它是天条。", "target_word": "天条", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条天条", "label": "量词"}], "register": "中性", "sense_fingerprint": "天条：神话中天界的法律规定，也比喻必须严格遵守、不能触犯的规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157c64-73c7-4e54-9585-b5a2f818129e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87062, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "疟疾", "is_correct": false, "explanation": "语义：“疟疾”是一种疾病，与“犯了……要受很重的罚”的违规语境不合。"}, {"text": "天条", "is_correct": true, "explanation": "天条：神话中天界的法规，神仙违反了就要受罚，与句意相合。"}, {"text": "旧病", "is_correct": false, "explanation": "语义：“犯旧病”是病又发作，不是违反规定，不会因此“受很重的罚”。"}, {"text": "瘾", "is_correct": false, "explanation": "语义：“瘾”指嗜好，不是法规，与“要受很重的罚”不合。"}], "explanations": {"疟疾": "语义：“疟疾”是一种疾病，与“犯了……要受很重的罚”的违规语境不合。", "天条": "天条：神话中天界的法规，神仙违反了就要受罚，与句意相合。", "旧病": "语义：“犯旧病”是病又发作，不是违反规定，不会因此“受很重的罚”。", "瘾": "语义：“瘾”指嗜好，不是法规，与“要受很重的罚”不合。"}, "sentence_index": 0, "correct_answer": "天条"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在天界的天条很高。", "explanation": "这里应该用〈地位〉。天条指法规，不指身份高低；说身份高低要用“地位”。"}, {"text": "他用天条搭了一座桥。", "explanation": "这里应该用〈材料〉。天条是规定，不能用来搭桥。"}, {"text": "他念天条让树长高。", "explanation": "这里应该用〈咒语〉。天条是法规，不能念；念的是咒语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87062, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家用电器，不是必须遵守的规定，与“是不能破的……”不合。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是用具，不是能“破”的规矩，与“作业按时交”的语境不合。"}, {"text": "天条", "is_correct": true, "explanation": "天条：比喻必须严格遵守、不能违反的规定，与“不能破的”相合。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：“沙发”是家具，不是必须遵守的规定，与“作业按时交是不能破的……”不合。"}], "explanations": {"冰箱": "语义：“冰箱”是家用电器，不是必须遵守的规定，与“是不能破的……”不合。", "雨伞": "语义：“雨伞”是用具，不是能“破”的规矩，与“作业按时交”的语境不合。", "天条": "天条：比喻必须严格遵守、不能违反的规定，与“不能破的”相合。", "沙发": "语义：“沙发”是家具，不是必须遵守的规定，与“作业按时交是不能破的……”不合。"}, "sentence_index": 6, "correct_answer": "天条"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把宝剑是神仙送给他的天条。", "explanation": "这里应该用〈宝物〉。天条指法规或规定，不指神仙送的物件。"}, {"text": "他天生有飞行的天条。", "explanation": "这里应该用〈天赋〉。天条不指先天的能力，要用“天赋”。"}, {"text": "他的天条很大，能飞能变。", "explanation": "这里应该用〈本事〉。天条不指人的能力，说能力要用“本事”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87062, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在天界，这件天条神仙都不能违反。", "corrected_sentence": "在天界，这条天条神仙都不能违反。", "error_description": "量词错误：“天条”应用量词“条”，不用“件”。正确说法是“这条天条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87062, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在天界，有一块天条，神仙都要遵守。", "corrected_sentence": "在天界，有一条天条，神仙都要遵守。", "error_description": "量词错误：“天条”应用量词“条”，不用“块”。正确说法是“一条天条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
