INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87063, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发射是把东西用力送到很远很高的地方。", "primary_collocate": null, "pronunciation": "fā shè", "ipa": "fa˥ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "工人们准备明天发射这枚火箭。", "target_word": "发射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们在操场上发射水火箭。", "target_word": "发射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火箭发射的时候，声音非常大。", "target_word": "发射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把卫星发射到了很高的天上。", "target_word": "发射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，火箭发射前要检查很多次。", "target_word": "发射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明年中国要发射一颗新卫星。", "target_word": "发射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明做了一个小火箭，今天在公园发射了。", "target_word": "发射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发射成功后，大家都高兴地鼓掌。", "target_word": "发射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在海边发射过很多次火箭。", "target_word": "发射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气不好，今天不能发射。", "target_word": "发射", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发射了", "label": "体标"}, {"form": "发射过", "label": "体标"}, {"form": "發射", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把火箭、卫星等东西用力送到很高很远的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa28d71a-cd8b-403b-8f08-c583f9f3d70d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87063, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "发射", "is_correct": true, "explanation": "正确选项。发射 fā shè，意思是把火箭、卫星等用力送到高处。"}, {"text": "发热", "is_correct": false, "explanation": "第二音节声母不同：rè 与 shè，声调相同。发热意思是身体发烫。"}, {"text": "发誓", "is_correct": false, "explanation": "第二音节韵母不同：shì 与 shè。发誓意思是郑重地表示保证。"}, {"text": "发色", "is_correct": false, "explanation": "发色（fà sè）与 发射 读音相近：第一字声调不同（第四声与第一声），第二字声母不同（s 与 sh）。发色意思是头发的颜色。"}], "explanations": {"发射": "正确选项。发射 fā shè，意思是把火箭、卫星等用力送到高处。", "发热": "第二音节声母不同：rè 与 shè，声调相同。发热意思是身体发烫。", "发誓": "第二音节韵母不同：shì 与 shè。发誓意思是郑重地表示保证。", "发色": "发色（fà sè）与 发射 读音相近：第一字声调不同（第四声与第一声），第二字声母不同（s 与 sh）。发色意思是头发的颜色。"}, "sentence_index": null, "correct_answer": "发射"}, "level_3": {"options": [{"text": "发射", "is_correct": true, "explanation": "正确选项。“发射”表示把火箭送出去，与“准备明天”和“这枚火箭”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能带“火箭”作宾语。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能用来处理火箭。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指唱歌，句子说的是对火箭的处理，意思不通。"}], "explanations": {"发射": "正确选项。“发射”表示把火箭送出去，与“准备明天”和“这枚火箭”相符。", "吃": "搭配：“吃”的对象是食物，不能带“火箭”作宾语。", "煮": "搭配：“煮”的对象是食物，不能用来处理火箭。", "唱": "语义：“唱”指唱歌，句子说的是对火箭的处理，意思不通。"}, "sentence_index": 0, "correct_answer": "发射"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爱迪生发射了电灯。", "explanation": "这里应该用〈发明〉。发射指把火箭、卫星等用力送到高处，电灯这类发明物要说发明。"}, {"text": "我给朋友发射了一封电子邮件。", "explanation": "这里应该用〈发送〉。发射用于火箭、卫星等大型物体，邮件、消息要说发送。"}, {"text": "他在杂志上发射了一篇文章。", "explanation": "这里应该用〈发表〉。发射不用于文章，文章要说发表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87063, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "发射", "is_correct": true, "explanation": "正确选项。发射 fā shè，意思是把火箭、卫星等用力送到高处。"}, {"text": "发涩", "is_correct": false, "explanation": "第二音节声母不同：sè 与 shè，声调相同。发涩意思是感觉干涩、不滑润。"}, {"text": "分社", "is_correct": false, "explanation": "第一音节韵母不同：fēn 与 fā，声调相同。分社意思是报社、通讯社的分支机构。"}, {"text": "反射", "is_correct": false, "explanation": "第一音节韵母与声调不同：fǎn 与 fā。反射意思是光、声波等遇到障碍后返回。"}], "explanations": {"发射": "正确选项。发射 fā shè，意思是把火箭、卫星等用力送到高处。", "发涩": "第二音节声母不同：sè 与 shè，声调相同。发涩意思是感觉干涩、不滑润。", "分社": "第一音节韵母不同：fēn 与 fā，声调相同。分社意思是报社、通讯社的分支机构。", "反射": "第一音节韵母与声调不同：fǎn 与 fā。反射意思是光、声波等遇到障碍后返回。"}, "sentence_index": null, "correct_answer": "发射"}, "level_3": {"options": [{"text": "发射", "is_correct": true, "explanation": "正确选项。“发射”表示把小火箭送出去，与“做了一个小火箭”“在公园”相符。"}, {"text": "拿", "is_correct": false, "explanation": "“拿”指握持或取得，与句中做火箭、在公园发射的动作不合。"}, {"text": "摘", "is_correct": false, "explanation": "“摘”指采下植物或果实，与句中做火箭、发射的动作不合。"}, {"text": "借", "is_correct": false, "explanation": "“借”指借入或借出，与句中做火箭、在公园发射的动作不合。"}], "explanations": {"发射": "正确选项。“发射”表示把小火箭送出去，与“做了一个小火箭”“在公园”相符。", "拿": "“拿”指握持或取得，与句中做火箭、在公园发射的动作不合。", "摘": "“摘”指采下植物或果实，与句中做火箭、发射的动作不合。", "借": "“借”指借入或借出，与句中做火箭、在公园发射的动作不合。"}, "sentence_index": 6, "correct_answer": "发射"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他能充分发射自己的能力。", "explanation": "这里应该用〈发挥〉。发射指把火箭、子弹等送出去，能力要说发挥。"}, {"text": "他向老师发射了一个微笑。", "explanation": "这里应该用〈发出〉。发射用于火箭、子弹、电波等，表情要说发出。"}, {"text": "他们在学校发射了一场运动。", "explanation": "这里应该用〈发起〉。运动、活动要说发起，发射不能用于运动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87063, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们明天要把这枚火箭发射下来。", "corrected_sentence": "工人们明天要把这枚火箭发射出去。", "error_description": "错误：“发射下来”，正确：“发射出去”。火箭是向高空送出的，应用“出去”表示离开地面，“下来”的方向相反。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87063, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "火箭已经发射在天上了。", "corrected_sentence": "火箭已经发射到天上了。", "error_description": "错误：“发射在天上”，正确：“发射到天上”。表示送达的地点要用“到”，“在”不能接在“发射”之后表示目的地。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87064, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "接收", "is_correct": true, "explanation": "正确选项。发射与接收是反义词：发射是送出电波，接收是收到电波。"}, {"text": "制造", "is_correct": false, "explanation": "与“发射”没有反义关系。“制造”指做出东西，与电波的收发无关。"}, {"text": "阅读", "is_correct": false, "explanation": "与“发射”没有反义关系。“阅读”指看文字，不涉及电波。"}, {"text": "观看", "is_correct": false, "explanation": "与“发射”没有反义关系。“观看”指看画面，不是电波收发的对立面。"}], "correct_answer": "接收", "explanations": {"接收": "正确选项。发射与接收是反义词：发射是送出电波，接收是收到电波。", "制造": "与“发射”没有反义关系。“制造”指做出东西，与电波的收发无关。", "阅读": "与“发射”没有反义关系。“阅读”指看文字，不涉及电波。", "观看": "与“发射”没有反义关系。“观看”指看画面，不是电波收发的对立面。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87064, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "接收", "is_correct": true, "explanation": "正确选项。发射与接收是反义词：发射是送出信号，接收是收到信号，与句中“向地面发射信号”相对。"}, {"text": "生产", "is_correct": false, "explanation": "与“发射”没有反义关系。“生产”指制造产品，与信号无关。"}, {"text": "购买", "is_correct": false, "explanation": "与“发射”没有反义关系。“购买”指付钱获得东西，与信号的收发无关。"}, {"text": "欣赏", "is_correct": false, "explanation": "与“发射”没有反义关系。“欣赏”指喜爱地看或听，不涉及信号。"}], "correct_answer": "接收", "explanations": {"接收": "正确选项。发射与接收是反义词：发射是送出信号，接收是收到信号，与句中“向地面发射信号”相对。", "生产": "与“发射”没有反义关系。“生产”指制造产品，与信号无关。", "购买": "与“发射”没有反义关系。“购买”指付钱获得东西，与信号的收发无关。", "欣赏": "与“发射”没有反义关系。“欣赏”指喜爱地看或听，不涉及信号。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87064, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把子弹、导弹、电波、信号等射出或送出去。", "primary_collocate": null, "pronunciation": "fā shè", "ipa": "fa˥ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "士兵向目标发射了一颗子弹。", "target_word": "发射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个基站每天都在发射信号。", "target_word": "发射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导弹发射后，很快就飞远了。", "target_word": "发射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机会发射很弱的电波。", "target_word": "发射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座电台向全国发射电波。", "target_word": "发射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在海上发射了两枚导弹。", "target_word": "发射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雷达不停地发射电波，寻找飞机。", "target_word": "发射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵把炮弹发射到山的另一边。", "target_word": "发射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机上要关手机，它会发射信号。", "target_word": "发射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卫星向地面发射信号，我们才能看电视。", "target_word": "发射", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发射了", "label": "体标"}, {"form": "发射过", "label": "体标"}, {"form": "發射", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把子弹、导弹、电波、信号等射出或送出去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa28d71a-cd8b-403b-8f08-c583f9f3d70d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87064, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "发射", "is_correct": true, "explanation": "正确选项。发射 fā shè，意思是把子弹、电波等射出或送出去。"}, {"text": "发热", "is_correct": false, "explanation": "第二音节声母不同：rè 与 shè，声调相同。发热意思是身体发烫。"}, {"text": "发誓", "is_correct": false, "explanation": "第二音节韵母不同：shì 与 shè。发誓意思是郑重地表示保证。"}, {"text": "发色", "is_correct": false, "explanation": "第二音节声母不同：sè 与 shè，声调相同。发色意思是头发的颜色。"}], "explanations": {"发射": "正确选项。发射 fā shè，意思是把子弹、电波等射出或送出去。", "发热": "第二音节声母不同：rè 与 shè，声调相同。发热意思是身体发烫。", "发誓": "第二音节韵母不同：shì 与 shè。发誓意思是郑重地表示保证。", "发色": "第二音节声母不同：sè 与 shè，声调相同。发色意思是头发的颜色。"}, "sentence_index": null, "correct_answer": "发射"}, "level_3": {"options": [{"text": "发射", "is_correct": true, "explanation": "正确选项。“发射”表示把子弹射出去，与“士兵向目标”和“一颗子弹”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能带“子弹”作宾语。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指唱歌，与士兵对目标的动作不合。"}, {"text": "瞄准", "is_correct": false, "explanation": "搭配：“瞄准”的对象是目标，不能直接带“子弹”作宾语。"}], "explanations": {"发射": "正确选项。“发射”表示把子弹射出去，与“士兵向目标”和“一颗子弹”相符。", "吃": "搭配：“吃”的对象是食物，不能带“子弹”作宾语。", "唱": "语义：“唱”指唱歌，与士兵对目标的动作不合。", "瞄准": "搭配：“瞄准”的对象是目标，不能直接带“子弹”作宾语。"}, "sentence_index": 0, "correct_answer": "发射"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我给朋友发射了一条短信。", "explanation": "这里应该用〈发送〉。发射用于子弹、电波等射出，短信、消息要说发送。"}, {"text": "贝尔发射了电话。", "explanation": "这里应该用〈发明〉。发射说的是射出或送出，电话是发明出来的，要说发明。"}, {"text": "他在报纸上发射了一篇评论。", "explanation": "这里应该用〈发表〉。文字、评论要说发表，发射不用于文字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87064, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "发射", "is_correct": true, "explanation": "正确选项。发射 fā shè，意思是把子弹、电波等射出或送出去。"}, {"text": "发生", "is_correct": false, "explanation": "第二音节韵母与声调不同：shēng 与 shè。发生意思是事情出现或产生。"}, {"text": "发烧", "is_correct": false, "explanation": "第二音节韵母与声调不同：shāo 与 shè。发烧意思是体温升高。"}, {"text": "分社", "is_correct": false, "explanation": "第一音节韵母不同：fēn 与 fā，声调相同。分社意思是报社、通讯社的分支机构。"}, {"text": "反射", "is_correct": false, "explanation": "第一音节韵母与声调不同：fǎn 与 fā。反射意思是光、声波等遇到障碍后返回。"}], "explanations": {"发射": "正确选项。发射 fā shè，意思是把子弹、电波等射出或送出去。", "发生": "第二音节韵母与声调不同：shēng 与 shè。发生意思是事情出现或产生。", "发烧": "第二音节韵母与声调不同：shāo 与 shè。发烧意思是体温升高。", "分社": "第一音节韵母不同：fēn 与 fā，声调相同。分社意思是报社、通讯社的分支机构。", "反射": "第一音节韵母与声调不同：fǎn 与 fā。反射意思是光、声波等遇到障碍后返回。"}, "sentence_index": null, "correct_answer": "发射"}, "level_3": {"options": [{"text": "发射", "is_correct": true, "explanation": "正确选项。“发射”表示发出电波，与“不停地”和“寻找飞机”相符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能用于电波。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物，不能说修理电波。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洗，与雷达发出电波的动作不合。"}], "explanations": {"发射": "正确选项。“发射”表示发出电波，与“不停地”和“寻找飞机”相符。", "煮": "搭配：“煮”的对象是食物，不能用于电波。", "修理": "搭配：“修理”的对象是器物，不能说修理电波。", "洗": "语义：“洗”指清洗，与雷达发出电波的动作不合。"}, "sentence_index": 6, "correct_answer": "发射"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他没能充分发射自己的实力。", "explanation": "这里应该用〈发挥〉。发射指把东西送出去，实力、能力要说发挥。"}, {"text": "我刚给老师发射了一封电子邮件。", "explanation": "这里应该用〈发送〉。发射用于子弹、导弹、电波等，邮件、短信要说发送。"}, {"text": "他们在学校发射了一场运动。", "explanation": "这里应该用〈发起〉。运动、活动要说发起，发射不能用于运动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87064, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "士兵把炮弹发射下来了。", "corrected_sentence": "士兵把炮弹发射出去了。", "error_description": "错误：“发射下来”，正确：“发射出去”。炮弹是向外射出的，应用“出去”表示离开射手，“下来”的方向相反。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87064, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座电台已经把电波发射在全国了。", "corrected_sentence": "这座电台已经把电波发射到全国了。", "error_description": "错误：“发射在全国”，正确：“发射到全国”。表示送达的范围要用“到”，“在”不能接在“发射”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
