INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87065, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87065, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "个中是说在这件事的里面。", "primary_collocate": null, "pronunciation": "gè zhōng", "ipa": "kɤ˥˩ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "这场比赛很精彩，个中细节值得学习。", "target_word": "个中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没说离开的原因，个中情况我不清楚。", "target_word": "个中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一场误会，个中经过很简单。", "target_word": "个中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个中苦乐，只有他自己明白。", "target_word": "个中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事有点复杂，个中关系不好说。", "target_word": "个中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们吵架了，个中原因我没问。", "target_word": "个中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人讲了他的故事，个中辛酸让人难过。", "target_word": "个中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司换了新老板，个中变化大家都看到了。", "target_word": "个中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子很不容易，个中辛苦你不懂。", "target_word": "个中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的合作失败了，个中教训要记住。", "target_word": "个中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "指前面所说这件事的内部，后接经过、情况、教训等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ef2725f-0b74-47cd-9e27-7673ad735aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87065, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谁", "is_correct": false, "explanation": "语义：“谁”只指人，不能指比赛的“细节”。"}, {"text": "那位", "is_correct": false, "explanation": "搭配：“位”只用于人，不能说“那位细节”。"}, {"text": "个中", "is_correct": true, "explanation": "正确。“个中”指这场比赛的内部，后接“细节”。"}, {"text": "本人", "is_correct": false, "explanation": "语义：“本人”指人，不能指比赛的细节。"}], "explanations": {"谁": "语义：“谁”只指人，不能指比赛的“细节”。", "那位": "搭配：“位”只用于人，不能说“那位细节”。", "个中": "正确。“个中”指这场比赛的内部，后接“细节”。", "本人": "语义：“本人”指人，不能指比赛的细节。"}, "sentence_index": 0, "correct_answer": "个中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚回家，个中就开始做饭。", "explanation": "这里应该用〈随后〉。个中只指事情或情况的内部，不表示时间先后上的接续。"}, {"text": "他很会游泳，个中还会打篮球。", "explanation": "这里应该用〈此外〉。个中指事情的内部，不表示补充；前文说游泳，后文要用〈此外〉。"}, {"text": "这两座山的个中隔着一条河。", "explanation": "这里应该用〈之间〉。个中指事情的内部，不表示两个地点的中间位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87065, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诸位", "is_correct": false, "explanation": "搭配：“诸位”是称呼人的词，不能修饰“辛酸”。"}, {"text": "何处", "is_correct": false, "explanation": "语义：“何处”问地点，不能与“辛酸”搭配作主语。"}, {"text": "这里", "is_correct": false, "explanation": "语义：“这里”指地点，不能说“这里辛酸”。"}, {"text": "个中", "is_correct": true, "explanation": "正确。“个中”指老人所讲故事的内部，后接“辛酸”。"}], "explanations": {"诸位": "搭配：“诸位”是称呼人的词，不能修饰“辛酸”。", "何处": "语义：“何处”问地点，不能与“辛酸”搭配作主语。", "这里": "语义：“这里”指地点，不能说“这里辛酸”。", "个中": "正确。“个中”指老人所讲故事的内部，后接“辛酸”。"}, "sentence_index": 6, "correct_answer": "个中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他个中很高兴，每天都笑。", "explanation": "这里应该用〈心里〉。个中只指事情或情况的内部，不指人的内心感受；说人的心情要用〈心里〉。"}, {"text": "他饿了，个中想吃点东西。", "explanation": "这里应直接说〈他想吃点东西〉。个中只指事情或情况的内部，不能用来指人的生理感受。"}, {"text": "他毕业后，个中去了外地工作。", "explanation": "这里应该用〈随后〉。个中指事情的内部，不表示时间先后上的接续。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87065, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次事故的这个中经过，警察已经查清了。", "corrected_sentence": "这次事故的个中经过，警察已经查清了。", "error_description": "“个中”本身已含“这里面”的意思，前面不能再加“这”。应说“这次事故的个中经过”，不说“这次事故的这个中经过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87065, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场争吵的个中里缘由，没有人说清楚。", "corrected_sentence": "这场争吵的个中缘由，没有人说清楚。", "error_description": "错误形式：「个中里缘由」，在「个中」后多加了「里」。正确形式：「个中缘由」。「个中」本身就是「这里面」的意思，后面不能再加「里」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
