INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87066, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "书面语，指这里面；其中。", "primary_collocate": null, "pronunciation": "gè zhōng", "ipa": "kɤ˥˩ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "个中原因很复杂，一时说不清楚。", "target_word": "个中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做了十年生意，个中辛苦只有自己知道。", "target_word": "个中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个中道理，你长大以后就明白了。", "target_word": "个中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是画画的行家，个中窍门都懂。", "target_word": "个中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个中滋味，只有亲身经历的人才知道。", "target_word": "个中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这行做了很多年，是个中高手。", "target_word": "个中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的内部问题，个中内情外人不知道。", "target_word": "个中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两人为什么分手，个中缘由没人说得清。", "target_word": "个中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市变化很大，个中变迁老居民都看在眼里。", "target_word": "个中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "股市有涨有跌，个中风险不可不知。", "target_word": "个中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "书面语代词，指这里面、其中，后接原因、滋味等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: 3 words above tier T1 (max 2): 画画 (Zipf 3.78), 行家 (Zipf 3.47), 窍门 (Zipf 3.43)']::text[], '7ef2725f-0b74-47cd-9e27-7673ad735aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87066, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大家", "is_correct": false, "explanation": "语义：“大家”指所有的人，不能修饰“原因”，“大家原因很复杂”不成话。"}, {"text": "那位", "is_correct": false, "explanation": "搭配：“位”用于称人，不能说“那位原因”。"}, {"text": "个中", "is_correct": true, "explanation": "正确。“个中”是书面语代词，指这件事的里面，后接“原因”。"}, {"text": "某人", "is_correct": false, "explanation": "语义：“某人”指不确定的人，不能修饰“原因”。"}], "explanations": {"大家": "语义：“大家”指所有的人，不能修饰“原因”，“大家原因很复杂”不成话。", "那位": "搭配：“位”用于称人，不能说“那位原因”。", "个中": "正确。“个中”是书面语代词，指这件事的里面，后接“原因”。", "某人": "语义：“某人”指不确定的人，不能修饰“原因”。"}, "sentence_index": 0, "correct_answer": "个中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈下班后，个中就去超市买菜了。", "explanation": "这里应该用〈然后〉。个中只指事情或情况的内部，不表示时间先后上的接续。"}, {"text": "他很累，个中想睡一会儿。", "explanation": "这里应直接说〈他想睡一会儿〉。个中只指事情或情况的内部，不用来表示人的生理需要。"}, {"text": "这两个城市的个中隔着一条河。", "explanation": "这里应该用〈之间〉。个中指事情的内部，不表示两个地点的中间位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87066, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诸位", "is_correct": false, "explanation": "搭配：“诸位”是对听众的称呼，不能修饰“内情”。"}, {"text": "本人", "is_correct": false, "explanation": "语义：“本人”指当事人自己，“内情”不能由人充当。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，句中没有提问，不能修饰“内情”。"}, {"text": "个中", "is_correct": true, "explanation": "正确。“个中”指这家公司问题的内部，后接“内情”。"}], "explanations": {"诸位": "搭配：“诸位”是对听众的称呼，不能修饰“内情”。", "本人": "语义：“本人”指当事人自己，“内情”不能由人充当。", "谁": "语义：“谁”是疑问代词，句中没有提问，不能修饰“内情”。", "个中": "正确。“个中”指这家公司问题的内部，后接“内情”。"}, "sentence_index": 6, "correct_answer": "个中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚下课，个中就去图书馆了。", "explanation": "这里应该用〈随后〉。个中只指事情或情况的内部，不表示时间先后上的接续。"}, {"text": "他很会做饭，个中还会弹钢琴。", "explanation": "这里应该用〈此外〉。个中指事情的内部，不表示补充；前文说做饭，后文要用〈此外〉引出另一项。"}, {"text": "他个中很高兴，每天都笑。", "explanation": "这里应该用〈心里〉。个中只指事情或情况的内部，不指人的内心感受；说人的心情要用〈心里〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87066, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事的这个中缘由，我到现在也没弄明白。", "corrected_sentence": "这件事的个中缘由，我到现在也没弄明白。", "error_description": "“个中”本身已含“这里面”的意思，前面不能再加“这”。应说“这件事的个中缘由”，不说“这件事的这个中缘由”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87066, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班有三十个学生，个中十个是女生。", "corrected_sentence": "我们班有三十个学生，其中十个是女生。", "error_description": "“个中”是书面语，指事情的内部情况（原因、滋味、道理等），不用来从一群人或物中挑出一部分。表示数量上的“里面的一部分”要用“其中”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb10411-5f09-4e75-ab6d-612ab1822677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
