INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87067, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "天生是生下来就有的，不是后来学的。", "primary_collocate": null, "pronunciation": "tiān shēng", "ipa": "tʰjɛn˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "他的音乐能力是天生的，没人教过。", "target_word": "天生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟飞行是天生的本事。", "target_word": "天生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她天生会唱歌，没学过一天。", "target_word": "天生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人天生怕高，站在楼上就害怕。", "target_word": "天生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婴儿天生会哭，不用别人教。", "target_word": "天生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他天生是左撇子，写字也用左手。", "target_word": "天生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种好记性是天生的，学不来。", "target_word": "天生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸭子天生会游泳，不需要学。", "target_word": "天生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥天生个子高，不是练出来的。", "target_word": "天生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她天生会跳舞，老师都很吃惊。", "target_word": "天生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "天生的", "label": "的字结构"}], "register": "中性", "sense_fingerprint": "生下来就有，不是后学的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e95692-f9f1-4226-adcd-b55c18dffb26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87067, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天生", "is_correct": true, "explanation": "天生表示生下来就有，与“没人教过”相符，句意通顺。"}, {"text": "买来的", "is_correct": false, "explanation": "语义：音乐能力不能用钱买来，“买来的”与句意明显不符。"}, {"text": "人为", "is_correct": false, "explanation": "语义：“人为”指人工造成，与“音乐能力”不符，且与“没人教过”冲突。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”描述人的智力，不能说“能力是聪明的”。"}], "explanations": {"天生": "天生表示生下来就有，与“没人教过”相符，句意通顺。", "买来的": "语义：音乐能力不能用钱买来，“买来的”与句意明显不符。", "人为": "语义：“人为”指人工造成，与“音乐能力”不符，且与“没人教过”冲突。", "聪明": "搭配：“聪明”描述人的智力，不能说“能力是聪明的”。"}, "sentence_index": 0, "correct_answer": "天生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的口才是天生练出来的。", "explanation": "这里应该用〈后天〉。天生表示生来就有，不能与“练出来”搭配。"}, {"text": "这把椅子是天生的。", "explanation": "这里应该用〈手工〉。天生指生来或自然形成，不能用于人造的椅子。"}, {"text": "她天生学会了画画，学得很快。", "explanation": "这里应该用〈后来〉。天生指生下来就有，不是后来学的，不能说“天生学会”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87067, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天生", "is_correct": true, "explanation": "天生表示生来就有，与“好记性”相符，句意通顺。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外表，不能修饰“好记性”。"}, {"text": "轻松", "is_correct": false, "explanation": "语义：“轻松”指做事不费力，与“学不来”相矛盾。"}, {"text": "迟钝", "is_correct": false, "explanation": "语义：“迟钝”与“好记性”意思相反，句意不通。"}], "explanations": {"天生": "天生表示生来就有，与“好记性”相符，句意通顺。", "漂亮": "搭配：“漂亮”形容外表，不能修饰“好记性”。", "轻松": "语义：“轻松”指做事不费力，与“学不来”相矛盾。", "迟钝": "语义：“迟钝”与“好记性”意思相反，句意不通。"}, "sentence_index": 6, "correct_answer": "天生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次巧遇是天生的。", "explanation": "这里应该用〈偶然〉。天生指生来具有，不能用来形容偶然的相遇。"}, {"text": "这次考试的答案是天生的。", "explanation": "这里应该用〈写出来〉。天生指生来具有，答案不可能是生来就有的。"}, {"text": "这个玩具是天生的。", "explanation": "这里应该用〈制作〉。天生指生来或自然形成，不能用于人工制作的玩具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87067, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他非常天生会画画。", "corrected_sentence": "他天生会画画。", "error_description": "错误：“天生”表示生来就有，前面不能加程度副词“非常”。应去掉“非常”，说“他天生会画画”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87067, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种好记性是天生出来的。", "corrected_sentence": "这种好记性是天生的。", "error_description": "错误：“天生”本身就表示生来具有，后面不能再加趋向补语“出来”。应说“是天生的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
