INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87068, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "生来就具有的；自然形成的。", "primary_collocate": null, "pronunciation": "tiān shēng", "ipa": "tʰjɛn˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "她天生一副好嗓子。", "target_word": "天生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子天生就很聪明。", "target_word": "天生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他天生胆子小，怕黑。", "target_word": "天生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里有一个天生的山洞。", "target_word": "天生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她天生爱笑，大家都喜欢她。", "target_word": "天生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座桥是天生的石头桥，不是人造的。", "target_word": "天生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他天生眼睛不好，从小就戴眼镜。", "target_word": "天生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫天生怕水，洗澡时一直叫。", "target_word": "天生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湖是天生的，没有人挖过。", "target_word": "天生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟天生脾气好，很少生气。", "target_word": "天生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "天生的", "label": "的字结构"}], "register": "中性", "sense_fingerprint": "生来具有；自然形成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e95692-f9f1-4226-adcd-b55c18dffb26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87068, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天生", "is_correct": true, "explanation": "天生表示生来就有，与“一副好嗓子”搭配，句意通顺。"}, {"text": "天真", "is_correct": false, "explanation": "语义：“天真”形容性格单纯，不能用来修饰“好嗓子”。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”多用于外貌或事物的美观，不能说“漂亮一副好嗓子”。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容智力，与“嗓子”无关，句子不通。"}], "explanations": {"天生": "天生表示生来就有，与“一副好嗓子”搭配，句意通顺。", "天真": "语义：“天真”形容性格单纯，不能用来修饰“好嗓子”。", "漂亮": "搭配：“漂亮”多用于外貌或事物的美观，不能说“漂亮一副好嗓子”。", "聪明": "语义：“聪明”形容智力，与“嗓子”无关，句子不通。"}, "sentence_index": 0, "correct_answer": "天生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个能力是天生培养的。", "explanation": "这里应该用〈后天〉。天生表示生来就有，不能与“培养”搭配。"}, {"text": "这条公路是天生的。", "explanation": "这里应该用〈人工修建〉。天生指生来就有或自然形成，不能用于人工修建的公路。"}, {"text": "这架钢琴是天生的。", "explanation": "这里应该用〈制作〉。天生指生来或自然形成，钢琴是人造的，不能说是天生的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87068, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天生", "is_correct": true, "explanation": "天生表示生来就有，与“眼睛不好”的生理状况相符。"}, {"text": "健康", "is_correct": false, "explanation": "搭配：“健康”描述整体身体状况，不能直接修饰“眼睛”，与“眼睛不好”冲突。"}, {"text": "正常", "is_correct": false, "explanation": "语义：“正常”指没有异常，与“眼睛不好、戴眼镜”相矛盾。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”指年龄，与“从小就戴眼镜”的身体状况无关。"}], "explanations": {"天生": "天生表示生来就有，与“眼睛不好”的生理状况相符。", "健康": "搭配：“健康”描述整体身体状况，不能直接修饰“眼睛”，与“眼睛不好”冲突。", "正常": "语义：“正常”指没有异常，与“眼睛不好、戴眼镜”相矛盾。", "年轻": "语义：“年轻”指年龄，与“从小就戴眼镜”的身体状况无关。"}, "sentence_index": 6, "correct_answer": "天生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场事故是天生的。", "explanation": "这里应该用〈意外〉。天生指生来或自然形成，不能用于偶然发生的事故。"}, {"text": "她每天天生地练习钢琴。", "explanation": "这里应该用〈刻苦〉。天生指生来具有，不能用来描述后天的努力。"}, {"text": "这次巧遇是天生的。", "explanation": "这里应该用〈偶然〉。天生指生来具有或自然形成，不能形容偶然的相遇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87068, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里有一个天生湖。", "corrected_sentence": "这里有一个天生的湖。", "error_description": "错误：“天生”修饰名词时须带“的”，应说“天生的湖”，不能省略“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87068, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟弟很天生会游泳。", "corrected_sentence": "弟弟天生会游泳。", "error_description": "错误：“天生”前不能加程度副词“很”，应去掉“很”，说“弟弟天生会游泳”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
