INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87069, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87069, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "内部是一个东西里面的地方。", "primary_collocate": null, "pronunciation": "nèi bù", "ipa": "nei˥˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "这个房子的内部很大。", "target_word": "内部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打开盒子，看了看内部。", "target_word": "内部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱内部很冷，里面有很多水果。", "target_word": "内部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的内部又干净又漂亮。", "target_word": "内部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山洞内部很黑，我们要带灯。", "target_word": "内部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想看看这台电脑的内部。", "target_word": "内部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子外面很旧，内部却很新。", "target_word": "内部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这个箱子的内部擦干净。", "target_word": "内部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机内部有很多座位。", "target_word": "内部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大楼内部有一个小花园。", "target_word": "内部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "內部", "label": "繁体"}, {"form": "内部结构", "label": "复合"}], "register": "中性", "sense_fingerprint": "房子、机器、箱子等具体物体里面的空间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62420910-ffdd-4a2d-9c1d-95797acdc4fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87069, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内部", "is_correct": true, "explanation": "正确：“这个房子的内部”指房子里面的空间，可以说“很大”。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”指时间，房子的星期不能说“很大”。"}, {"text": "贵府", "is_correct": false, "explanation": "语域：“贵府”是对他人住所的敬称，用来描述自己的房子语域不合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色可以说深或浅，但不能说房子的颜色“很大”。"}], "explanations": {"内部": "正确：“这个房子的内部”指房子里面的空间，可以说“很大”。", "星期": "语义：“星期”指时间，房子的星期不能说“很大”。", "贵府": "语域：“贵府”是对他人住所的敬称，用来描述自己的房子语域不合。", "颜色": "语义：颜色可以说深或浅，但不能说房子的颜色“很大”。"}, "sentence_index": 0, "correct_answer": "内部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯茶的内部很苦。", "explanation": "这里应该用〈味道〉。内部指东西里面的位置，说茶的苦、甜要用味道，不能说内部很苦。"}, {"text": "妈妈的内部很高兴。", "explanation": "这里应该用〈心情〉。内部指事物的里面，不用来指人的心情。"}, {"text": "这个包的内部很便宜。", "explanation": "这里应该用〈价格〉。内部不用来说价钱，要说价格便宜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87069, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内部", "is_correct": true, "explanation": "正确：“内部”与前面的“外面”相对，构成对比，句意完整。"}, {"text": "外部", "is_correct": false, "explanation": "语义：“外部”与“外面”同义，前后说外面很旧、外部却很新，自相矛盾。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不能说“很新”，与“房子外面很旧”的对比不成立。"}, {"text": "寒舍", "is_correct": false, "explanation": "语域：“寒舍”是谦辞，用在描述房子新旧的句子里语域不合。"}], "explanations": {"内部": "正确：“内部”与前面的“外面”相对，构成对比，句意完整。", "外部": "语义：“外部”与“外面”同义，前后说外面很旧、外部却很新，自相矛盾。", "年龄": "语义：年龄不能说“很新”，与“房子外面很旧”的对比不成立。", "寒舍": "语域：“寒舍”是谦辞，用在描述房子新旧的句子里语域不合。"}, "sentence_index": 6, "correct_answer": "内部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的内部很聪明。", "explanation": "这里应该用〈脑子〉。内部指事物里面的空间，不用来形容人的智力。"}, {"text": "这张照片的内部很亮。", "explanation": "这里应该用〈画面〉。内部指东西的里面，照片是平面，说照片的效果要用画面，不能说内部。"}, {"text": "这个人的内部很高。", "explanation": "这里应该用〈身高〉。内部不用来描述人的身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87069, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请箱子内部装满水。", "corrected_sentence": "请在箱子内部装满水。", "error_description": "漏掉介词“在”。“箱子内部”作地点要用“在”，应为“在箱子内部装满水”；去掉“在”后句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87069, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冰箱的内部冷地很。", "corrected_sentence": "冰箱的内部冷得很。", "error_description": "“得”误写为“地”。“冷”作补语，要接在“内部”后用“得”，应为“冷得很”；“冷地很”中“地”是状语标记，不能放在形容词后作补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87070, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外部", "is_correct": true, "explanation": "外部与内部相对，指某一范围之外、事物的外面，是这一义项的反义词。"}, {"text": "桌子", "is_correct": false, "explanation": "桌子是具体家具，与“内部”的范围义没有反义关系。"}, {"text": "海洋", "is_correct": false, "explanation": "海洋是地理名词，与“内部”没有反义关系。"}, {"text": "老师", "is_correct": false, "explanation": "老师指人，与“内部”的范围义没有反义关系。"}], "correct_answer": "外部", "explanations": {"外部": "外部与内部相对，指某一范围之外、事物的外面，是这一义项的反义词。", "桌子": "桌子是具体家具，与“内部”的范围义没有反义关系。", "海洋": "海洋是地理名词，与“内部”没有反义关系。", "老师": "老师指人，与“内部”的范围义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87070, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外部", "is_correct": true, "explanation": "外部与内部相对，指某一范围之外、事物的外面，是这一义项的反义词。"}, {"text": "医院", "is_correct": false, "explanation": "医院是机构场所名词，与“内部”没有反义关系。"}, {"text": "花园", "is_correct": false, "explanation": "花园是具体场所，与“内部”的范围义没有反义关系。"}, {"text": "报纸", "is_correct": false, "explanation": "报纸是具体事物，与“内部”没有反义关系。"}], "correct_answer": "外部", "explanations": {"外部": "外部与内部相对，指某一范围之外、事物的外面，是这一义项的反义词。", "医院": "医院是机构场所名词，与“内部”没有反义关系。", "花园": "花园是具体场所，与“内部”的范围义没有反义关系。", "报纸": "报纸是具体事物，与“内部”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87070, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某个组织、团体或范围以内（与“外部”相对）。", "primary_collocate": null, "pronunciation": "nèi bù", "ipa": "nei˥˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "这个问题只在公司内部讨论。", "target_word": "内部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "团队内部有一些小问题。", "target_word": "内部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是工厂内部的消息，别告诉外人。", "target_word": "内部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行内部的人先知道了这个消息。", "target_word": "内部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个会议只让公司内部的人参加。", "target_word": "内部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校内部的规定，大家都要看。", "target_word": "内部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家族内部发生了很大的变化。", "target_word": "内部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事不要说出去，只在我们内部说。", "target_word": "内部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队内部很团结，所以比赛赢了。", "target_word": "内部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内部的事情我们自己解决，不用外人帮忙。", "target_word": "内部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "內部", "label": "繁体"}, {"form": "内部消息", "label": "复合"}], "register": "中性", "sense_fingerprint": "组织、团体、范围的内部，与外部相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62420910-ffdd-4a2d-9c1d-95797acdc4fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87070, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内部", "is_correct": true, "explanation": "正确：“只在公司内部讨论”指问题只限于公司范围之内，与句意相符。"}, {"text": "草原", "is_correct": false, "explanation": "语义：公司不在草原上，“只在公司草原讨论”与句意不合。"}, {"text": "海边", "is_correct": false, "explanation": "语义：海边与公司无关，“只在公司海边讨论”不能说明问题的讨论范围。"}, {"text": "贵处", "is_correct": false, "explanation": "语域：“贵处”是敬称，用来指对方的地方，在这里语域不合，也与“公司”搭配不当。"}], "explanations": {"内部": "正确：“只在公司内部讨论”指问题只限于公司范围之内，与句意相符。", "草原": "语义：公司不在草原上，“只在公司草原讨论”与句意不合。", "海边": "语义：海边与公司无关，“只在公司海边讨论”不能说明问题的讨论范围。", "贵处": "语域：“贵处”是敬称，用来指对方的地方，在这里语域不合，也与“公司”搭配不当。"}, "sentence_index": 0, "correct_answer": "内部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事让我的内部很难过。", "explanation": "这里应该用〈内心〉。内部指组织或事物的里面，不用来指人的心理感受。"}, {"text": "这篇小说的内部很精彩。", "explanation": "这里应该用〈内容〉。内部指范围之内，评价作品的好坏要说内容。"}, {"text": "这次会议的内部很长。", "explanation": "这里应该用〈时间〉。内部指空间范围，不能用来说事情持续的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87070, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内部", "is_correct": true, "explanation": "正确：“家族内部”指家族成员之间，与“发生很大的变化”搭配自然。"}, {"text": "天气", "is_correct": false, "explanation": "语义：家族不会有“天气”发生变化，句子说的是家族内部的变化。"}, {"text": "寒舍", "is_correct": false, "explanation": "语域：“寒舍”是谦辞，指自己的住所，用在这种中性叙述中语域不合。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星与家族无关，“家族星星发生了很大的变化”不成立。"}], "explanations": {"内部": "正确：“家族内部”指家族成员之间，与“发生很大的变化”搭配自然。", "天气": "语义：家族不会有“天气”发生变化，句子说的是家族内部的变化。", "寒舍": "语域：“寒舍”是谦辞，指自己的住所，用在这种中性叙述中语域不合。", "星星": "语义：星星与家族无关，“家族星星发生了很大的变化”不成立。"}, "sentence_index": 6, "correct_answer": "内部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的内部很聪明。", "explanation": "这里应该用〈脑子〉。内部指组织或范围之内，不用来形容人的智力。"}, {"text": "他的内部很英俊。", "explanation": "这里应该用〈外表〉。内部指里面，形貌和外形要说外表，不用内部。"}, {"text": "他的内部很高。", "explanation": "这里应该用〈身高〉。内部不用来描述人的身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事已经公司内部解决了。", "corrected_sentence": "这件事已经在公司内部解决了。", "error_description": "漏掉介词“在”。“公司内部”作地点状语要用“在”，应为“在公司内部解决”；去掉“在”后句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87070, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个决定只在内部的公布过。", "corrected_sentence": "这个决定只在内部公布过。", "error_description": "“公布”前多加“的”。“在内部”作状语修饰“公布”，中间不能加“的”；“在内部的公布过”结构不成立，应为“在内部公布过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
