INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87071, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "简直是说一件事情特别特别厉害，差不多就是那样。", "primary_collocate": null, "pronunciation": "jiǎn zhí", "ipa": "tɕjɛn˨˩˦ ʈʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "这里的风景简直太美了。", "target_word": "简直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他跑得简直像风一样快。", "target_word": "简直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天热得简直不能出门。", "target_word": "简直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道菜简直好吃极了。", "target_word": "简直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她唱歌简直跟歌星一样好。", "target_word": "简直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的字简直像打印出来的。", "target_word": "简直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子简直是个小天才。", "target_word": "简直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店人多得简直走不动路。", "target_word": "简直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的汉语说得简直和中国人一样。", "target_word": "简直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到这么大的蛋糕，我简直不敢相信。", "target_word": "简直", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "簡直", "label": "繁体"}], "register": "中性", "sense_fingerprint": "强调程度极高，几乎等于某种情况（多用于赞叹或比喻）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdba5b8c-a597-4c90-bcad-019807f38244') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87071, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "简直", "is_correct": true, "explanation": "正确答案。简直表示程度极深，几乎如此。"}, {"text": "剪纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是剪纸艺术。"}, {"text": "剪枝", "is_correct": false, "explanation": "zhī（第一声）与 zhí（第二声）声调不同，意思是修剪树枝。"}, {"text": "减持", "is_correct": false, "explanation": "chí 与 zhí 声母不同（ch 与 zh），意思是减少持有（股份）。"}], "explanations": {"简直": "正确答案。简直表示程度极深，几乎如此。", "剪纸": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是剪纸艺术。", "剪枝": "zhī（第一声）与 zhí（第二声）声调不同，意思是修剪树枝。", "减持": "chí 与 zhí 声母不同（ch 与 zh），意思是减少持有（股份）。"}, "sentence_index": null, "correct_answer": "简直"}, "level_3": {"options": [{"text": "简直", "is_correct": true, "explanation": "正确答案。简直表示夸张的程度，与“太美了”相符。"}, {"text": "突然", "is_correct": false, "explanation": "语义：突然表示事情忽然发生，与“太美了”所描述的程度不协调。"}, {"text": "根本", "is_correct": false, "explanation": "语义：根本强调彻底或本质，放在“太美了”前语义不通。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：偶尔表示次数少，不能修饰“太美了”这种程度评价。"}], "explanations": {"简直": "正确答案。简直表示夸张的程度，与“太美了”相符。", "突然": "语义：突然表示事情忽然发生，与“太美了”所描述的程度不协调。", "根本": "语义：根本强调彻底或本质，放在“太美了”前语义不通。", "偶尔": "搭配：偶尔表示次数少，不能修饰“太美了”这种程度评价。"}, "sentence_index": 0, "correct_answer": "简直"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天简直去了一趟北京。", "explanation": "这里应该用〈确实〉。确实说明事情属实；简直强调程度夸张，用来说昨天去北京这件实际发生的事不合适。"}, {"text": "这次考试我简直及格了。", "explanation": "这里应该用〈居然〉。居然表示出乎意料；简直强调程度夸张，用来说这次考试及格不合适。"}, {"text": "我每天简直去学校上课。", "explanation": "这里应该用〈几乎〉。几乎只说程度接近，不带夸张；简直带夸张语气，用来描述每天去学校这样的日常安排不合适。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87071, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "简直", "is_correct": true, "explanation": "正确答案。简直表示程度极深，几乎如此。"}, {"text": "兼职", "is_correct": false, "explanation": "jiān（第一声）与 jiǎn（第三声）声调不同，意思是同时做另一份工作。"}, {"text": "检字", "is_correct": false, "explanation": "zì 与 zhí 声母不同（z 与 zh），意思是查找汉字。"}, {"text": "剪纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是剪纸艺术。"}], "explanations": {"简直": "正确答案。简直表示程度极深，几乎如此。", "兼职": "jiān（第一声）与 jiǎn（第三声）声调不同，意思是同时做另一份工作。", "检字": "zì 与 zhí 声母不同（z 与 zh），意思是查找汉字。", "剪纸": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是剪纸艺术。"}, "sentence_index": null, "correct_answer": "简直"}, "level_3": {"options": [{"text": "简直", "is_correct": true, "explanation": "正确答案。简直表示夸张的判断，与“是个小天才”相符。"}, {"text": "正在", "is_correct": false, "explanation": "语法：“正在”表示动作进行，“是”是判断动词，两者不能搭配，不能说“正在是个小天才”。"}, {"text": "赶快", "is_correct": false, "explanation": "语义：赶快表示迅速行动，修饰的是动作，不能修饰“是个小天才”这样的判断。"}, {"text": "差点", "is_correct": false, "explanation": "搭配：差点用于险些发生的事，不能接“是个小天才”这样的判断。"}], "explanations": {"简直": "正确答案。简直表示夸张的判断，与“是个小天才”相符。", "正在": "语法：“正在”表示动作进行，“是”是判断动词，两者不能搭配，不能说“正在是个小天才”。", "赶快": "语义：赶快表示迅速行动，修饰的是动作，不能修饰“是个小天才”这样的判断。", "差点": "搭配：差点用于险些发生的事，不能接“是个小天才”这样的判断。"}, "sentence_index": 6, "correct_answer": "简直"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我没想到他简直会来。", "explanation": "这里应该用〈竟然〉。竟然表示出乎意料；简直强调程度夸张，不用于表示意外的事实。"}, {"text": "他的工资简直涨了三块钱。", "explanation": "这里应该用〈只〉。只表示数量少；简直强调程度夸张，用来形容三块钱的小幅变化不合适。"}, {"text": "你简直把门关上吧。", "explanation": "这里应该用〈快〉。快用于催促；简直表示程度夸张，不能用在请求或命令里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87071, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个蛋糕太简直好吃极了。", "corrected_sentence": "这个蛋糕简直好吃极了。", "error_description": "“简直”与“太”都表示程度，“太简直”的语序不通；“简直太”则是常见说法（如“这里的风景简直太美了”）。应删去前面的“太”，说“这个蛋糕简直好吃极了”，不能说“这个蛋糕太简直好吃极了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87071, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天简直的冷死了。", "corrected_sentence": "今天简直冷死了。", "error_description": "“简直”是副词，后面不能加“的”。应说“今天简直冷死了”，不能说“今天简直的冷死了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
