INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87072, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示几乎完全如此，带有夸张的语气。", "primary_collocate": null, "pronunciation": "jiǎn zhí", "ipa": "tɕjɛn˨˩˦ ʈʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "这件事简直让人生气。", "target_word": "简直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的房间乱得简直没法住。", "target_word": "简直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到这个消息，我简直高兴坏了。", "target_word": "简直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题简直太难了。", "target_word": "简直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外面的雨简直像倒水一样。", "target_word": "简直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你这样做简直是胡闹。", "target_word": "简直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的作业多得简直写不完。", "target_word": "简直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她简直把我当成了小孩子。", "target_word": "简直", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里冬天冷得简直像冰箱。", "target_word": "简直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他简直一分钟也不想等。", "target_word": "简直", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "簡直", "label": "繁体"}], "register": "中性", "sense_fingerprint": "夸张语气，表示几乎完全是这样（多用于抱怨或惊讶）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdba5b8c-a597-4c90-bcad-019807f38244') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87072, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "简直", "is_correct": true, "explanation": "正确答案。简直表示夸张的语气，几乎完全如此。"}, {"text": "剪纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是剪纸艺术。"}, {"text": "减持", "is_correct": false, "explanation": "chí 与 zhí 声母不同（ch 与 zh），意思是减少持有（股份）。"}, {"text": "剪枝", "is_correct": false, "explanation": "zhī（第一声）与 zhí（第二声）声调不同，意思是修剪树枝。"}], "explanations": {"简直": "正确答案。简直表示夸张的语气，几乎完全如此。", "剪纸": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是剪纸艺术。", "减持": "chí 与 zhí 声母不同（ch 与 zh），意思是减少持有（股份）。", "剪枝": "zhī（第一声）与 zhí（第二声）声调不同，意思是修剪树枝。"}, "sentence_index": null, "correct_answer": "简直"}, "level_3": {"options": [{"text": "简直", "is_correct": true, "explanation": "正确答案。简直表示夸张的抱怨语气，与“让人生气”相符。"}, {"text": "赶紧", "is_correct": false, "explanation": "搭配：赶紧多接动作，不能直接接“让人生气”这类结果。"}, {"text": "好不容易", "is_correct": false, "explanation": "语义：好不容易表示费了很大力气才达成，与“让人生气”的语义不协调。"}, {"text": "根本", "is_correct": false, "explanation": "语义：根本强调彻底或本质，与“让人生气”的夸张语气不通。"}], "explanations": {"简直": "正确答案。简直表示夸张的抱怨语气，与“让人生气”相符。", "赶紧": "搭配：赶紧多接动作，不能直接接“让人生气”这类结果。", "好不容易": "语义：好不容易表示费了很大力气才达成，与“让人生气”的语义不协调。", "根本": "语义：根本强调彻底或本质，与“让人生气”的夸张语气不通。"}, "sentence_index": 0, "correct_answer": "简直"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我早上简直吃了两个包子。", "explanation": "这里应该用〈确实〉。确实说明事情属实；简直强调程度夸张，用来说早上吃两个包子这种实际事件不合适。"}, {"text": "我没想到他简直考了第一名。", "explanation": "这里应该用〈竟然〉。竟然表示出乎意料；简直强调程度夸张，不用于表示意外的事实。"}, {"text": "请您简直坐下。", "explanation": "这里应该用〈先〉。先表示先后次序；简直表示夸张语气，用在礼貌的请求里不合适，应说“请您先坐下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87072, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "简直", "is_correct": true, "explanation": "正确答案。简直表示夸张的语气，几乎完全如此。"}, {"text": "兼职", "is_correct": false, "explanation": "jiān（第一声）与 jiǎn（第三声）声调不同，意思是同时做另一份工作。"}, {"text": "检字", "is_correct": false, "explanation": "zì 与 zhí 声母不同（z 与 zh），意思是查找汉字。"}, {"text": "剪纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是剪纸艺术。"}], "explanations": {"简直": "正确答案。简直表示夸张的语气，几乎完全如此。", "兼职": "jiān（第一声）与 jiǎn（第三声）声调不同，意思是同时做另一份工作。", "检字": "zì 与 zhí 声母不同（z 与 zh），意思是查找汉字。", "剪纸": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是剪纸艺术。"}, "sentence_index": null, "correct_answer": "简直"}, "level_3": {"options": [{"text": "简直", "is_correct": true, "explanation": "正确答案。简直表示夸张的程度，与“多得写不完”相符。"}, {"text": "未必", "is_correct": false, "explanation": "语义：未必表示不一定，与“多得写不完”的夸张程度不协调，且不能接在“多得”后面。"}, {"text": "稍微", "is_correct": false, "explanation": "语义：稍微表示程度轻，与夸张的“写不完”语义相反。"}, {"text": "不太", "is_correct": false, "explanation": "搭配：“不太”通常修饰形容词，不能直接接在“多得”这样的补语结构前。"}], "explanations": {"简直": "正确答案。简直表示夸张的程度，与“多得写不完”相符。", "未必": "语义：未必表示不一定，与“多得写不完”的夸张程度不协调，且不能接在“多得”后面。", "稍微": "语义：稍微表示程度轻，与夸张的“写不完”语义相反。", "不太": "搭配：“不太”通常修饰形容词，不能直接接在“多得”这样的补语结构前。"}, "sentence_index": 6, "correct_answer": "简直"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的工资简直涨了三块钱。", "explanation": "这里应该用〈只〉。只表示数量少；简直强调夸张程度，用来形容三块钱的小幅变化不合适。"}, {"text": "我借了他的书，简直还给他了。", "explanation": "这里应该用〈已经〉。已经表示事情已完成；简直表示夸张程度，用来说还书这件事不合适。"}, {"text": "请你简直过来一下。", "explanation": "这里应该用〈快〉。快用于催促；简直表示夸张语气，不能用在请求里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4618090-e62b-423a-93c9-a1cb770131ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, v