INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87073, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "女同是喜欢女生的女生。这是“女同性恋者”的简单说法。", "primary_collocate": null, "pronunciation": "nǚ tóng", "ipa": "ny˨˩˦ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我的同事是女同，她和女朋友住在一起。", "target_word": "女同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说自己是女同，和女朋友已经在一起五年了。", "target_word": "女同", "complexity_tier": "T3", "furigana": "tā shuō zìjǐ shì nǚtóng, hé nǚpéngyou yǐjīng zài yìqǐ wǔ nián le.", "sentence_source": "generated"}, {"text": "小林是女同，她的女朋友很温柔。", "target_word": "女同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友告诉我，她是女同。", "target_word": "女同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位女同今天带女朋友来我家了。", "target_word": "女同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是女同，和女朋友打算明年一起去日本旅游。", "target_word": "女同", "complexity_tier": "T3", "furigana": "tā shì nǚtóng, hé nǚpéngyou dǎsuan míngnián yìqǐ qù Rìběn lǚyóu.", "sentence_source": "generated"}, {"text": "女同喜欢的是女生，不是男生。", "target_word": "女同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我认识一对女同，她们结婚三年了。", "target_word": "女同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很早就知道自己是女同。", "target_word": "女同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家咖啡店的老板是女同，她的爱人也是女生。", "target_word": "女同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "女同性恋者", "label": "全称"}], "register": "口语", "sense_fingerprint": "女同：喜欢女生的女生，口语里对女同性恋者的简单说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5557fc-539b-4cb6-b9b1-8d2660c41b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87073, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女同", "is_correct": true, "explanation": "正确：女同指爱恋女性的女性，与后句「她和女朋友住在一起」相符。"}, {"text": "男朋友", "is_correct": false, "explanation": "语义：「男朋友」指男性恋人，与后句「她和女朋友」矛盾。"}, {"text": "男同", "is_correct": false, "explanation": "语义：「男同」指爱恋男性的男性，与句中的「她」和「女朋友」矛盾。"}, {"text": "女朋友", "is_correct": false, "explanation": "搭配：「女朋友」指恋爱对象，不能用来介绍同事的身份。"}], "explanations": {"女同": "正确：女同指爱恋女性的女性，与后句「她和女朋友住在一起」相符。", "男朋友": "语义：「男朋友」指男性恋人，与后句「她和女朋友」矛盾。", "男同": "语义：「男同」指爱恋男性的男性，与句中的「她」和「女朋友」矛盾。", "女朋友": "搭配：「女朋友」指恋爱对象，不能用来介绍同事的身份。"}, "sentence_index": 0, "correct_answer": "女同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她说自己是女同，却一直在和男朋友约会。", "explanation": "「女同」指爱恋女性的女性，与“一直和男朋友约会”自相矛盾。若指喜欢男性，应说「异性恋」，不能用「女同」。"}, {"text": "我认识一只女同，她很开朗。", "explanation": "这里应该用「位」。「只」多用于动物，指人应说「一位」或「一个」。"}, {"text": "我们在女同见面，再一起去吃饭吧。", "explanation": "「女同」是指人的名词，不能单独作见面的场所。表示地点应说「女同酒吧」之类的具体场所名称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87073, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女同", "is_correct": true, "explanation": "正确：女同指爱恋女性的女性，与后句「喜欢的是女生」相符。"}, {"text": "男同", "is_correct": false, "explanation": "语义：「男同」指爱恋男性的男性，与「喜欢的是女生」矛盾。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是无生命的物品，不能有喜欢的对象。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不能喜欢人，与「喜欢的是女生」冲突。"}], "explanations": {"女同": "正确：女同指爱恋女性的女性，与后句「喜欢的是女生」相符。", "男同": "语义：「男同」指爱恋男性的男性，与「喜欢的是女生」矛盾。", "手机": "语义：手机是无生命的物品，不能有喜欢的对象。", "椅子": "语义：椅子不能喜欢人，与「喜欢的是女生」冲突。"}, "sentence_index": 6, "correct_answer": "女同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们请了一位女同来演讲，她说自己从来不喜欢女生。", "explanation": "「女同」指爱恋女性的女性，与“从来不喜欢女生”自相矛盾。若只想说女性演讲者，应说「女士」或「女性」，不能用「女同」。"}, {"text": "我遇到一条女同，她很友好。", "explanation": "这里应该用「位」。「条」用于长条形事物，指人应说「一位」或「一个」。"}, {"text": "我的弟弟是女同，喜欢踢足球。", "explanation": "这里应该用「男生」。「男生」指男性；「女同」只指爱恋女性的女性，不能指男性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87073, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的同事是一只女同，她很开朗。", "corrected_sentence": "我的同事是一位女同，她很开朗。", "error_description": "量词错误：「女同」指人，应用「位」，不能用「只」（「只」多用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87073, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几位女同们都去参加了那场讲座。", "corrected_sentence": "几位女同都去参加了那场讲座。", "error_description": "词缀错误：「女同」前有数词和量词「几位」时，不能再加「们」，应去掉「们」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
