INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87074, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "“女同性恋者”的简称，指爱恋同性女性的女性。", "primary_collocate": null, "pronunciation": "nǚ tóng", "ipa": "ny˨˩˦ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "女同是女同性恋者的简称。", "target_word": "女同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一位女同，爱的是另一位女性。", "target_word": "女同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个社区里有很多女同。", "target_word": "女同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女同和男同都希望得到尊重。", "target_word": "女同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影讲了两位女同的爱情故事。", "target_word": "女同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在会上说，自己是女同。", "target_word": "女同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个活动是为女同办的。", "target_word": "女同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多女同希望能像别人一样结婚。", "target_word": "女同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位女同作家写了这本书。", "target_word": "女同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们两个都是女同，爱上了对方。", "target_word": "女同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "女同性恋者", "label": "全称"}, {"form": "女同性恋", "label": "复合"}], "register": "中性", "sense_fingerprint": "女同：“女同性恋者”的简称，指爱恋同性女性的女性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5557fc-539b-4cb6-b9b1-8d2660c41b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87074, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女同", "is_correct": true, "explanation": "正确：女同是「女同性恋者」的简称。"}, {"text": "女同性恋者", "is_correct": false, "explanation": "语义：「女同性恋者」本身是全称，不能是它自己的简称。"}, {"text": "同性恋", "is_correct": false, "explanation": "搭配：「同性恋」不限定性别，不能作「女同性恋者」的简称。"}, {"text": "女朋友", "is_correct": false, "explanation": "语义：「女朋友」指恋爱对象，不是性取向称谓，也不是「女同性恋者」的简称。"}], "explanations": {"女同": "正确：女同是「女同性恋者」的简称。", "女同性恋者": "语义：「女同性恋者」本身是全称，不能是它自己的简称。", "同性恋": "搭配：「同性恋」不限定性别，不能作「女同性恋者」的简称。", "女朋友": "语义：「女朋友」指恋爱对象，不是性取向称谓，也不是「女同性恋者」的简称。"}, "sentence_index": 0, "correct_answer": "女同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在会上说，自己是女同，却一直在追求男生。", "explanation": "「女同」指爱恋女性的女性，与“一直在追求男生”自相矛盾。这里说的是喜欢男性，应说「异性恋」，不能用「女同」。"}, {"text": "我认识一只女同，她在医院工作。", "explanation": "这里应该用「位」。「只」多用于动物，指人应说「一位」或「一个」。"}, {"text": "我们约好在女同碰面，再一起去吃饭。", "explanation": "「女同」是指人的名词，不能单独作碰面的地点。表示场所应说「女同酒吧」之类的具体名称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87074, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女同", "is_correct": true, "explanation": "正确：女同指爱恋女性的女性，可以作活动的服务对象。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是人，不能作为活动的服务对象。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能成为活动的服务对象。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：「为……办」的对象应是人或组织，「冰箱」不能作服务对象。"}], "explanations": {"女同": "正确：女同指爱恋女性的女性，可以作活动的服务对象。", "空气": "语义：空气不是人，不能作为活动的服务对象。", "桌子": "语义：桌子不能成为活动的服务对象。", "冰箱": "搭配：「为……办」的对象应是人或组织，「冰箱」不能作服务对象。"}, "sentence_index": 6, "correct_answer": "女同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位女同一直说自己喜欢男生。", "explanation": "「女同」指爱恋女性的女性，与“一直说自己喜欢男生”自相矛盾。若指喜欢男性，应说「异性恋」，不能用「女同」。"}, {"text": "我遇到一条女同，她住在隔壁。", "explanation": "这里应该用「位」。「条」用于长条形事物，指人应说「一位」或「一个」。"}, {"text": "我的哥哥是女同，今年二十岁。", "explanation": "这里应该用「男生」或「男人」。「女同」只指爱恋女性的女性，不能指男性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87074, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的姐姐是一只女同，她住在上海。", "corrected_sentence": "我的姐姐是一位女同，她住在上海。", "error_description": "量词错误：「女同」指人，应用「位」，不能用「只」（「只」多用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87074, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几位女同们都来到了会场。", "corrected_sentence": "几位女同都来到了会场。", "error_description": "词缀错误：「女同」前有数词和量词「几位」时，不能再加「们」，应去掉「们」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87076, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "全称", "is_correct": true, "explanation": "正确选项。全称与简称是反义词：全称指完整的名称，简称指省略后的名称。"}, {"text": "地址", "is_correct": false, "explanation": "与“简称”没有反义关系。“地址”指所在位置。"}, {"text": "年龄", "is_correct": false, "explanation": "与“简称”没有反义关系。“年龄”指人或动物活了多久。"}, {"text": "颜色", "is_correct": false, "explanation": "与“简称”没有反义关系。“颜色”指色彩，与名称无关。"}], "correct_answer": "全称", "explanations": {"全称": "正确选项。全称与简称是反义词：全称指完整的名称，简称指省略后的名称。", "地址": "与“简称”没有反义关系。“地址”指所在位置。", "年龄": "与“简称”没有反义关系。“年龄”指人或动物活了多久。", "颜色": "与“简称”没有反义关系。“颜色”指色彩，与名称无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87076, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "全称", "is_correct": true, "explanation": "正确选项。全称与简称是反义词：全称指完整的名称，简称指省略后的名称。"}, {"text": "价格", "is_correct": false, "explanation": "与“简称”没有反义关系。“价格”指商品的价值。"}, {"text": "天气", "is_correct": false, "explanation": "与“简称”没有反义关系。“天气”指冷热阴晴，与名称无关。"}, {"text": "重量", "is_correct": false, "explanation": "与“简称”没有反义关系。“重量”指物体的轻重。"}], "correct_answer": "全称", "explanations": {"全称": "正确选项。全称与简称是反义词：全称指完整的名称，简称指省略后的名称。", "价格": "与“简称”没有反义关系。“价格”指商品的价值。", "天气": "与“简称”没有反义关系。“天气”指冷热阴晴，与名称无关。", "重量": "与“简称”没有反义关系。“重量”指物体的轻重。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87076, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "较长的名称经过省略后的简短称呼。", "primary_collocate": null, "pronunciation": "jiǎn chēng", "ipa": "tɕjɛn˨˩˦ ʈʂʰɤŋ˥", "syllable_count": 2, "sentences": [{"text": "北京大学的简称是北大。", "target_word": "简称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的全称很长，大家常用简称。", "target_word": "简称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“中国”是“中华人民共和国”的简称。", "target_word": "简称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广东的简称是粤。", "target_word": "简称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告里第一次要写全称，后面可以用简称。", "target_word": "简称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道联合国的简称是什么吗？", "target_word": "简称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机构的简称很好记。", "target_word": "简称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上海的简称是沪。", "target_word": "简称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在表格里写学校的简称。", "target_word": "简称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不知道这个名字有没有简称。", "target_word": "简称", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "簡稱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "机构、地区等较长名称省略后的简短称呼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa28d71a-cd8b-403b-8f08-c583f9f3d70d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87076, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "简称", "is_correct": true, "explanation": "正确选项。简称 jiǎn chēng，意思是较长名称省略后的简短叫法。"}, {"text": "建成", "is_correct": false, "explanation": "两个音节声调都不同：jiàn 为第四声，chéng 为第二声。建成意思是建造完成。"}, {"text": "剪成", "is_correct": false, "explanation": "第二音节声调不同：chéng 与 chēng。剪成意思是剪出某种形状。"}, {"text": "减轻", "is_correct": false, "explanation": "第二音节声母与声调不同：qīng 与 chēng。减轻意思是降低负担或程度。"}], "explanations": {"简称": "正确选项。简称 jiǎn chēng，意思是较长名称省略后的简短叫法。", "建成": "两个音节声调都不同：jiàn 为第四声，chéng 为第二声。建成意思是建造完成。", "剪成": "第二音节声调不同：chéng 与 chēng。剪成意思是剪出某种形状。", "减轻": "第二音节声母与声调不同：qīng 与 chēng。减轻意思是降低负担或程度。"}, "sentence_index": null, "correct_answer": "简称"}, "level_3": {"options": [{"text": "简称", "is_correct": true, "explanation": "正确选项。“简称”指省略后的短称，与“北京大学的……是北大”相符。"}, {"text": "全称", "is_correct": false, "explanation": "语义：“全称”是完整名称，与后面的短称“北大”矛盾。"}, {"text": "地址", "is_correct": false, "explanation": "语义：“地址”指所在位置，“是北大”不能说明地址。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”只用于人或动物，不能说学校的年龄。"}], "explanations": {"简称": "正确选项。“简称”指省略后的短称，与“北京大学的……是北大”相符。", "全称": "语义：“全称”是完整名称，与后面的短称“北大”矛盾。", "地址": "语义：“地址”指所在位置，“是北大”不能说明地址。", "年龄": "搭配：“年龄”只用于人或动物，不能说学校的年龄。"}, "sentence_index": 0, "correct_answer": "简称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所学校的简称是北京大学。", "explanation": "这里应该用〈全称〉。北京大学是完整名称，简称应该是“北大”这样的短称。"}, {"text": "这家公司的简称在北京路十号。", "explanation": "这里应该用〈地址〉。简称是省略后的名称，说公司所在的位置要用地址。"}, {"text": "汉字的简称很多。", "explanation": "这里应该用〈简写〉。汉字字形的简化说简写，简称只用于名称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87076, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "简称", "is_correct": true, "explanation": "正确选项。“简称”指省略后的短称，与“很好记”相符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或口味，不能用来形容机构名称是否好记。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”只用于人或动物的高度，不能用于机构。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”只用于人或动物的重量，不能用于机构。"}], "explanations": {"简称": "正确选项。“简称”指省略后的短称，与“很好记”相符。", "味道": "语义：“味道”指气味或口味，不能用来形容机构名称是否好记。", "身高": "搭配：“身高”只用于人或动物的高度，不能用于机构。", "体重": "搭配：“体重”只用于人或动物的重量，不能用于机构。"}, "sentence_index": 6, "correct_answer": "简称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种草的简称是狗尾草。", "explanation": "这里应该用〈俗称〉。狗尾草是俗称，不是由全名省略而来，不能说简称。"}, {"text": "同学们给他起了个简称，叫小胖。", "explanation": "这里应该用〈外号〉。简称是把长名字省略得来的，“小胖”是同学起的外号，与名字无关，要说外号。"}, {"text": "他的简称叫王小明。", "explanation": "这里应该用〈全名〉。王小明是完整的名字，不是省略后的短称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87076, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司有两把简称。", "corrected_sentence": "这家公司有两个简称。", "error_description": "错误：“两把简称”，正确：“两个简称”。简称按“个”计量，“把”用于有柄的器物，不能用于简称。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87076, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个机构有两条简称，很好记。", "corrected_sentence": "这个机构有两个简称，很好记。", "error_description": "错误：「两条简称」；正确：「两个简称」。简称按“个”计量，“条”用于长条形的事物，不能用于简称。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87077, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难办", "is_correct": true, "explanation": "正确。“难办”与“好办”意思相反，指事情不容易做。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“好办”没有反义关系，“漂亮”形容外表好看。"}, {"text": "安静", "is_correct": false, "explanation": "与“好办”没有反义关系，“安静”形容环境或声音的状态。"}, {"text": "明亮", "is_correct": false, "explanation": "与“好办”没有反义关系，“明亮”形容光线充足。"}], "correct_answer": "难办", "explanations": {"难办": "正确。“难办”与“好办”意思相反，指事情不容易做。", "漂亮": "与“好办”没有反义关系，“漂亮”形容外表好看。", "安静": "与“好办”没有反义关系，“安静”形容环境或声音的状态。", "明亮": "与“好办”没有反义关系，“明亮”形容光线充足。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87077, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难办", "is_correct": true, "explanation": "正确。“难办”与“好办”意思相反，指事情不容易做。"}, {"text": "干净", "is_correct": false, "explanation": "与“好办”没有反义关系，“干净”形容清洁。"}, {"text": "严肃", "is_correct": false, "explanation": "与“好办”没有反义关系，“严肃”形容态度或气氛。"}, {"text": "整齐", "is_correct": false, "explanation": "与“好办”没有反义关系，“整齐”形容排列或外观。"}], "correct_answer": "难办", "explanations": {"难办": "正确。“难办”与“好办”意思相反，指事情不容易做。", "干净": "与“好办”没有反义关系，“干净”形容清洁。", "严肃": "与“好办”没有反义关系，“严肃”形容态度或气氛。", "整齐": "与“好办”没有反义关系，“整齐”形容排列或外观。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87077, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "好办是很容易做，不难。", "primary_collocate": null, "pronunciation": "hǎo bàn", "ipa": "xɑʊ˨˩ pan˥˩", "syllable_count": 2, "sentences": [{"text": "这件事很好办。", "target_word": "好办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了钱，事情就好办了。", "target_word": "好办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你放心，这个问题好办。", "target_word": "好办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买火车票好办，订酒店难。", "target_word": "好办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事不好办。", "target_word": "好办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说请假的事好办，写张条子就行。", "target_word": "好办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "换手机号码好办，去店里就行。", "target_word": "好办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找人帮忙就好办了。", "target_word": "好办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你早说就好办了。", "target_word": "好办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修自行车好办，我来试试。", "target_word": "好办", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不好办", "label": "否定式"}, {"form": "很好办", "label": "程度式"}], "register": "口语", "sense_fingerprint": "事情容易做，不难", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e417de8-3307-410a-8543-b657809a61d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87077, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好办", "is_correct": true, "explanation": "正确。“好办”指事情容易做、不难，填入“这件事很___”语义通顺。"}, {"text": "蓝", "is_correct": false, "explanation": "语义：“蓝”是颜色词，与事情的难易无关，句子说不通。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”形容人或物的体型、规模，不能用来说事情“高大”。"}, {"text": "红", "is_correct": false, "explanation": "语义：“红”是颜色词，与事情的难易无关，句子说不通。"}], "explanations": {"好办": "正确。“好办”指事情容易做、不难，填入“这件事很___”语义通顺。", "蓝": "语义：“蓝”是颜色词，与事情的难易无关，句子说不通。", "高大": "语义：“高大”形容人或物的体型、规模，不能用来说事情“高大”。", "红": "语义：“红”是颜色词，与事情的难易无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "好办"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的天气很好办，我们去公园吧。", "explanation": "这里应该用〈好〉。“好办”指事情容易做、不难，天气的好坏要说“好”。"}, {"text": "这儿离地铁站很好办。", "explanation": "这里应该用〈方便〉。“好办”说事情容易处理，地点近、交通便利要说“方便”。"}, {"text": "这轮月亮很好办，又圆又亮。", "explanation": "这里应该用〈好看〉。“好办”指事情容易做，月亮的样子要说“好看”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87077, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好办", "is_correct": true, "explanation": "正确。“好办”指事情容易做，填入“换手机号码___”后，与“去店里就行”的语境一致。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或动物的身材，不能用来形容号码。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”形容形状，与换号码的难易无关，句子说不通。"}, {"text": "深", "is_correct": false, "explanation": "语义：“深”形容深浅，与事情的难易无关，句子说不通。"}], "explanations": {"好办": "正确。“好办”指事情容易做，填入“换手机号码___”后，与“去店里就行”的语境一致。", "瘦": "体貌：“瘦”形容人或动物的身材，不能用来形容号码。", "圆": "语义：“圆”形容形状，与换号码的难易无关，句子说不通。", "深": "语义：“深”形容深浅，与事情的难易无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "好办"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个嗓音很好办，又尖又响。", "explanation": "这里应该用〈刺耳〉。“好办”指事情容易做，嗓音的效果要说“刺耳”。"}, {"text": "这朵花很好办，颜色又红又艳。", "explanation": "这里应该用〈好看〉。“好办”指事情容易做，花的样子要说“好看”。"}, {"text": "这股味道很好办，又香又甜。", "explanation": "这里应该用〈好闻〉。“好办”指事情容易做，气味要说“好闻”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87077, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事情很好办过，你不用担心。", "corrected_sentence": "这件事情很好办，你不用担心。", "error_description": "错误形式：“很好办过”；正确形式：“很好办”。“过”表示经历，只能接在动词后面，形容词“好办”后不能加“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87077, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事情没好办，只能再等几天。", "corrected_sentence": "这件事情不好办，只能再等几天。", "error_description": "错误形式：“没好办”；正确形式：“不好办”。否定形容词“好办”要用“不”；“没”用于否定已经发生的动作或结果，这里是描述事情的性质。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
