INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87078, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "容易处理；容易解决。", "primary_collocate": null, "pronunciation": "hǎo bàn", "ipa": "xɑʊ˨˩ pan˥˩", "syllable_count": 2, "sentences": [{"text": "小问题好办，大问题难办。", "target_word": "好办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了地址，找人就好办了。", "target_word": "好办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事交给我，好办。", "target_word": "好办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车坏了不好办，只能等人来修。", "target_word": "好办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我朋友，事情好办多了。", "target_word": "好办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要说清楚，误会就好办。", "target_word": "好办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钥匙丢了好办，再配一把。", "target_word": "好办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种手续不好办，要跑好几次。", "target_word": "好办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的学校问题好办了。", "target_word": "好办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把材料准备好，后面的事就好办。", "target_word": "好办", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不好办", "label": "否定式"}, {"form": "很好办", "label": "程度式"}], "register": "口语", "sense_fingerprint": "问题或麻烦容易处理、容易解决", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e417de8-3307-410a-8543-b657809a61d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87078, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好办", "is_correct": true, "explanation": "正确。“好办”指问题容易处理，填入“小问题___”后与“大问题难办”形成对比。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外表好看，不能用来说问题的难易。"}, {"text": "深", "is_correct": false, "explanation": "语义：“深”形容深浅，与问题容易处理与否无关，句子说不通。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”形容形状，与问题的难易无关，句子说不通。"}], "explanations": {"好办": "正确。“好办”指问题容易处理，填入“小问题___”后与“大问题难办”形成对比。", "漂亮": "体貌：“漂亮”形容外表好看，不能用来说问题的难易。", "深": "语义：“深”形容深浅，与问题容易处理与否无关，句子说不通。", "圆": "语义：“圆”形容形状，与问题的难易无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "好办"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑得很好办。", "explanation": "这里应该用〈快〉。“好办”指问题容易处理，不能描写跑步的速度。"}, {"text": "这家商场离我家很好办。", "explanation": "这里应该用〈方便〉。“好办”说事情容易处理，地点远近、交通便利要说“方便”。"}, {"text": "他的想法很好办。", "explanation": "这里应该用〈简单〉。“好办”指事情容易处理，形容人的想法要用“简单”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87078, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好办", "is_correct": true, "explanation": "正确。“好办”指事情容易解决，填入“钥匙丢了___，再配一把”后语义通顺。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或动物的身材，不能用来形容钥匙丢失的情况。"}, {"text": "红", "is_correct": false, "explanation": "语义：“红”是颜色词，与钥匙丢失后的处理难易无关，句子说不通。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”形容味道，与事情的难易无关，句子说不通。"}], "explanations": {"好办": "正确。“好办”指事情容易解决，填入“钥匙丢了___，再配一把”后语义通顺。", "瘦": "体貌：“瘦”形容人或动物的身材，不能用来形容钥匙丢失的情况。", "红": "语义：“红”是颜色词，与钥匙丢失后的处理难易无关，句子说不通。", "甜": "语义：“甜”形容味道，与事情的难易无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "好办"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个西瓜很好办，又甜又脆。", "explanation": "这里应该用〈好吃〉。“好办”指问题容易处理、容易解决，西瓜的味道要说“好吃”。"}, {"text": "这条裙子很好办，颜色又漂亮。", "explanation": "这里应该用〈好看〉。“好办”指问题容易解决，衣服的样子要说“好看”。"}, {"text": "这首歌很好办，大家都爱听。", "explanation": "这里应该用〈好听〉。“好办”指问题容易解决，歌的声音要说“好听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个问题没好办，要多跑几趟。", "corrected_sentence": "这个问题不好办，要多跑几趟。", "error_description": "错误形式：“没好办”；正确形式：“不好办”。否定形容词“好办”要用“不”；“没”用于否定已经发生的动作或结果。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个麻烦很好办过，你别担心。", "corrected_sentence": "这个麻烦很好办，你别担心。", "error_description": "错误形式：“很好办过”；正确形式：“很好办”。“过”表示经历，只能接在动词后面，形容词“好办”后不能加“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87079, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87079, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87079, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "总结是做完一件事以后，想一想做得怎么样，把重要的话说出来。", "primary_collocate": null, "pronunciation": "zǒng jié", "ipa": "tsʊŋ˨˩˦ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "比赛结束后，老师让我们总结一下经验。", "target_word": "总结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上都总结当天的学习情况。", "target_word": "总结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把今天的会议内容总结一下。", "target_word": "总结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她总结了这次旅行的经验。", "target_word": "总结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试以后，我总结了自己的错误。", "target_word": "总结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们开完会，经理开始总结大家的发言。", "target_word": "总结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王总结得很好，大家都点头。", "target_word": "总结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做完这件事，你应该好好总结总结。", "target_word": "总结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“请大家总结这一课的重点。”", "target_word": "总结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天在日记里总结自己的得失。", "target_word": "总结", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "总结了", "label": "体标"}, {"form": "总结过", "label": "体标"}, {"form": "总结总结", "label": "重叠"}, {"form": "總結", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做完事后回想做得如何，并说出要点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa2e5afa-4320-49bb-ab63-b0ef2a0774da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87079, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总结", "is_correct": true, "explanation": "总结：做完事后回想并归纳要点，与“比赛结束后”和“经验”相符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物等，不能与“经验”搭配。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”用于火、灯等，不能与“经验”搭配。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”是不再记得，与“老师让我们……一下经验”要求回顾归纳的意思相反。"}], "explanations": {"总结": "总结：做完事后回想并归纳要点，与“比赛结束后”和“经验”相符。", "修理": "搭配：“修理”的对象是器物等，不能与“经验”搭配。", "点燃": "搭配：“点燃”用于火、灯等，不能与“经验”搭配。", "忘记": "语义：“忘记”是不再记得，与“老师让我们……一下经验”要求回顾归纳的意思相反。"}, "sentence_index": 0, "correct_answer": "总结"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他总结了一碗面条。", "explanation": "这里应该用〈吃〉。总结指回顾并归纳要点，不能用于食物。"}, {"text": "他总结了房间。", "explanation": "这里应该用〈收拾〉。总结指回顾并归纳要点，不指整理具体的物品。"}, {"text": "她总结了三件礼物。", "explanation": "这里应该用〈挑选〉。总结用于回顾和归纳，不能用于挑选具体物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87079, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总结", "is_correct": true, "explanation": "总结：做完事后回想并归纳要点，用“得很好”评价归纳的水平，与“大家都点头”的赞许相符。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”指流泪，与“做得很好，大家都点头”的赞许语境不符。"}, {"text": "吵", "is_correct": false, "explanation": "搭配：“吵”不能用“吵得很好”来评价做事的水平，搭配不成立。"}, {"text": "发抖", "is_correct": false, "explanation": "语义：“发抖”指身体颤动，与“得很好”的评价以及“大家都点头”的语境不符。"}], "explanations": {"总结": "总结：做完事后回想并归纳要点，用“得很好”评价归纳的水平，与“大家都点头”的赞许相符。", "哭": "语义：“哭”指流泪，与“做得很好，大家都点头”的赞许语境不符。", "吵": "搭配：“吵”不能用“吵得很好”来评价做事的水平，搭配不成立。", "发抖": "语义：“发抖”指身体颤动，与“得很好”的评价以及“大家都点头”的语境不符。"}, "sentence_index": 6, "correct_answer": "总结"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护士耐心地总结了他的伤口。", "explanation": "这里应该用〈包扎〉。总结指回顾和归纳，不用于处理伤口。"}, {"text": "工人把那箱书总结进了仓库。", "explanation": "这里应该用〈搬〉。总结指回顾归纳，不能表示把物体搬进某处。"}, {"text": "妈妈总结了蔬菜。", "explanation": "这里应该用〈清洗〉。总结不用于对蔬菜这类实物做清洁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87079, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把这次活动总结了一个。", "corrected_sentence": "她把这次活动总结了一下。", "error_description": "动量词错误：“总结”表示做的次数应用动量词“一下”，不能用名量词“一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87079, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次培训后，他总结了很清楚。", "corrected_sentence": "这次培训后，他总结得很清楚。", "error_description": "“了”不能直接接程度补语“很清楚”；动词后接程度补语要用结构助词“得”，应为“总结得很清楚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
