INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87080, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对一段时间内的工作、学习等进行回顾和分析，得出结论。", "primary_collocate": null, "pronunciation": "zǒng jié", "ipa": "tsʊŋ˨˩˦ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "年底了，公司要总结这一年的工作。", "target_word": "总结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学期结束时，同学们要总结本学期的学习。", "target_word": "总结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理总结了上半年的销售情况。", "target_word": "总结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把三年的研究成果总结了一下。", "target_word": "总结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认真总结了过去五年的工作经验，写成报告。", "target_word": "总结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院总结去年的工作，发现了不少问题。", "target_word": "总结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年终会议上，主任总结了全年的工作。", "target_word": "总结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你总结这个月的学习，再定下个月的计划。", "target_word": "总结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带着学生总结期中考试的结果。", "target_word": "总结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每个季度都要总结一次工作。", "target_word": "总结", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "总结了", "label": "体标"}, {"form": "总结过", "label": "体标"}, {"form": "总结总结", "label": "重叠"}, {"form": "總結", "label": "繁体"}], "register": "书面", "sense_fingerprint": "对一段时间的工作学习回顾分析并得出结论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa2e5afa-4320-49bb-ab63-b0ef2a0774da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87080, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总结", "is_correct": true, "explanation": "总结：对这一年的工作回顾分析并得出结论，与“年底”的语境相符。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”用于枝叶等，不能与“这一年的工作”搭配。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”针对表面的污渍或器物，不能与“工作”搭配。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”指出售，与“年底”回顾工作的语境不符。"}], "explanations": {"总结": "总结：对这一年的工作回顾分析并得出结论，与“年底”的语境相符。", "修剪": "搭配：“修剪”用于枝叶等，不能与“这一年的工作”搭配。", "擦": "搭配：“擦”针对表面的污渍或器物，不能与“工作”搭配。", "卖": "语义：“卖”指出售，与“年底”回顾工作的语境不符。"}, "sentence_index": 0, "correct_answer": "总结"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们总结了一座桥。", "explanation": "这里应该用〈修建〉。总结指回顾分析并得出结论，不指建造工程。"}, {"text": "妈妈总结了那件衣服。", "explanation": "这里应该用〈缝补〉。总结用于工作、学习等的回顾，不用于修补衣物。"}, {"text": "他总结了两张机票。", "explanation": "这里应该用〈订购〉。总结不用于购买或预订物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87080, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总结", "is_correct": true, "explanation": "总结：对全年的工作回顾分析并得出结论，与“年终会议”的语境相符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对器物，不能与“全年的工作”搭配。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：“浇灌”用于植物或田地，不能与“工作”搭配。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”指流泪，与“年终会议上”汇报工作的语境不符。"}], "explanations": {"总结": "总结：对全年的工作回顾分析并得出结论，与“年终会议”的语境相符。", "修理": "搭配：“修理”针对器物，不能与“全年的工作”搭配。", "浇灌": "搭配：“浇灌”用于植物或田地，不能与“工作”搭配。", "哭": "语义：“哭”指流泪，与“年终会议上”汇报工作的语境不符。"}, "sentence_index": 6, "correct_answer": "总结"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护士总结了那位病人。", "explanation": "这里应该用〈照料〉。总结指回顾和归纳，不能用于照顾人。"}, {"text": "这家工厂每天总结五百台机器。", "explanation": "这里应该用〈生产〉。总结指回顾和归纳，不指制造产品。"}, {"text": "农民在田里总结了很多草莓。", "explanation": "这里应该用〈采摘〉。总结用于回顾和归纳，不用于采收果实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87080, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们总结了出一个结论。", "corrected_sentence": "他们总结出了一个结论。", "error_description": "“出”是结果补语，应紧贴动词：应为“总结出了一个结论”；“总结了出”的语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87080, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他总结了很到位。", "corrected_sentence": "他总结得很到位。", "error_description": "“了”不能直接接程度补语“很到位”；动词后接程度补语要用结构助词“得”，应为“总结得很到位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
