INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87081, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "妻是结了婚的女人，是丈夫的伴儿。", "primary_collocate": null, "pronunciation": "qī", "ipa": "tɕʰi˥", "syllable_count": 1, "sentences": [{"text": "他的妻是一位老师。", "target_word": "妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和妻昨天去看电影了。", "target_word": "妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爱妻，也爱孩子。", "target_word": "妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王去年娶了妻。", "target_word": "妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妻在家做饭，等他回来。", "target_word": "妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给妻买了一件新衣服。", "target_word": "妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带着妻去北京旅行。", "target_word": "妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妻比他小三岁。", "target_word": "妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有妻有子，生活很幸福。", "target_word": "妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天给妻打电话。", "target_word": "妻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "妻子", "label": "复合词"}, {"form": "夫妻", "label": "复合词"}, {"form": "前妻", "label": "复合词"}], "register": "书面", "sense_fingerprint": "结了婚的女人，丈夫的伴侣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e417de8-3307-410a-8543-b657809a61d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87081, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "妻", "is_correct": true, "explanation": "正确。妻 qī（第一声）指结了婚的女人，是丈夫的配偶。"}, {"text": "齐", "is_correct": false, "explanation": "qí（第二声）与 qī（第一声）声调不同，意思是整齐。"}, {"text": "气", "is_correct": false, "explanation": "qì（第四声）与 qī（第一声）声调不同，意思是空气、脾气。"}, {"text": "西", "is_correct": false, "explanation": "xī 与 qī 声母不同（x／q），意思是西方。"}, {"text": "鸡", "is_correct": false, "explanation": "jī 与 qī 声母不同（j／q），意思是鸡。"}, {"text": "起", "is_correct": false, "explanation": "qǐ（第三声）与 qī（第一声）声调不同，意思是起来。"}], "explanations": {"妻": "正确。妻 qī（第一声）指结了婚的女人，是丈夫的配偶。", "齐": "qí（第二声）与 qī（第一声）声调不同，意思是整齐。", "气": "qì（第四声）与 qī（第一声）声调不同，意思是空气、脾气。", "西": "xī 与 qī 声母不同（x／q），意思是西方。", "鸡": "jī 与 qī 声母不同（j／q），意思是鸡。", "起": "qǐ（第三声）与 qī（第一声）声调不同，意思是起来。"}, "sentence_index": null, "correct_answer": "妻"}, "level_3": {"options": [{"text": "妻", "is_correct": true, "explanation": "正确。“妻”指丈夫的配偶，可以是一位老师。"}, {"text": "狗", "is_correct": false, "explanation": "语义：狗不能当老师，“他的狗是一位老师”说不通。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不能当老师，句子说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能当老师，“他的桌子是一位老师”说不通。"}], "explanations": {"妻": "正确。“妻”指丈夫的配偶，可以是一位老师。", "狗": "语义：狗不能当老师，“他的狗是一位老师”说不通。", "房子": "语义：房子不能当老师，句子说不通。", "桌子": "语义：桌子不能当老师，“他的桌子是一位老师”说不通。"}, "sentence_index": 0, "correct_answer": "妻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他下个月要和妻结婚。", "explanation": "这里应该用〈女朋友〉。“妻”指已经结婚的配偶，还没结婚的恋人要说“女朋友”。"}, {"text": "他的妻今年才十岁。", "explanation": "这里应该用〈女儿〉。“妻”指已婚的成年配偶，十岁的孩子只能说“女儿”。"}, {"text": "他和妻昨天才认识，还在谈恋爱。", "explanation": "这里应该用〈对象〉。“妻”指已结婚的配偶，刚认识、还在恋爱中的人要说“对象”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87081, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "妻", "is_correct": true, "explanation": "正确。妻 qī（第一声）指结了婚的女人，是丈夫的配偶。"}, {"text": "棋", "is_correct": false, "explanation": "qí（第二声）与 qī（第一声）声调不同，意思是棋。"}, {"text": "汽", "is_correct": false, "explanation": "qì（第四声）与 qī（第一声）声调不同，意思是汽车、蒸汽。"}, {"text": "吸", "is_correct": false, "explanation": "xī 与 qī 声母不同（x／q），意思是吸入。"}, {"text": "机", "is_correct": false, "explanation": "jī 与 qī 声母不同（j／q），意思是机器。"}, {"text": "骑", "is_correct": false, "explanation": "qí（第二声）与 qī（第一声）声调不同，意思是骑乘。"}], "explanations": {"妻": "正确。妻 qī（第一声）指结了婚的女人，是丈夫的配偶。", "棋": "qí（第二声）与 qī（第一声）声调不同，意思是棋。", "汽": "qì（第四声）与 qī（第一声）声调不同，意思是汽车、蒸汽。", "吸": "xī 与 qī 声母不同（x／q），意思是吸入。", "机": "jī 与 qī 声母不同（j／q），意思是机器。", "骑": "qí（第二声）与 qī（第一声）声调不同，意思是骑乘。"}, "sentence_index": null, "correct_answer": "妻"}, "level_3": {"options": [{"text": "妻", "is_correct": true, "explanation": "正确。“妻”指丈夫的配偶，可以随丈夫一起去北京旅行。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海无法被人带着去旅行，句子说不通。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳无法被人带着去旅行，句子说不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“带着……去”的宾语要能随人携带，冰箱不能随身去北京旅行。"}], "explanations": {"妻": "正确。“妻”指丈夫的配偶，可以随丈夫一起去北京旅行。", "大海": "语义：大海无法被人带着去旅行，句子说不通。", "太阳": "语义：太阳无法被人带着去旅行，句子说不通。", "冰箱": "搭配：“带着……去”的宾语要能随人携带，冰箱不能随身去北京旅行。"}, "sentence_index": 6, "correct_answer": "妻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他还没结婚，妻常常来看他。", "explanation": "这里应该用〈女朋友〉。“妻”指已经结婚的配偶，没结婚的人没有妻，恋人要说“女朋友”。"}, {"text": "她的妻是一位医生，每天很忙。", "explanation": "这里应该用〈丈夫〉。“妻”是丈夫一方对女性配偶的称呼，女子的配偶要说“丈夫”。"}, {"text": "他的妻刚上幼儿园，每天哭着要妈妈。", "explanation": "这里应该用〈女儿〉。“妻”指已婚的成年女子，上幼儿园的孩子只能是“女儿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87081, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他年轻时就娶了一只妻，两人感情很好。", "corrected_sentence": "他年轻时就娶了一位妻，两人感情很好。", "error_description": "错误形式：“一只妻”；正确形式：“一位妻”。“只”多用于动物或成对事物中的一个，指人要用“位”或“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87081, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位聪明妻的常常帮他做决定。", "corrected_sentence": "那位聪明的妻常常帮他做决定。", "error_description": "错误形式：“聪明妻的”；正确形式：“聪明的妻”。修饰语“聪明”后要加“的”，“的”紧跟修饰语，修饰语应放在中心词“妻”的前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87082, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87082, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87082, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "已婚女子，是丈夫的配偶。", "primary_collocate": null, "pronunciation": "qī", "ipa": "tɕʰi˥", "syllable_count": 1, "sentences": [{"text": "这位先生的妻很漂亮。", "target_word": "妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他要娶妻，所以在存钱。", "target_word": "妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妻做饭，他洗碗。", "target_word": "妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕妻生气，就早点回家了。", "target_word": "妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的妻在医院工作。", "target_word": "妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的妻生了一个女儿。", "target_word": "妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李结婚了，他的妻是同事。", "target_word": "妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带妻去过很多国家。", "target_word": "妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妻听了他的话，笑了。", "target_word": "妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生给妻写了一封信。", "target_word": "妻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "妻子", "label": "复合词"}, {"form": "夫妻", "label": "复合词"}, {"form": "前妻", "label": "复合词"}], "register": "书面", "sense_fingerprint": "已婚女子，丈夫的配偶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e417de8-3307-410a-8543-b657809a61d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87082, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "妻", "is_correct": true, "explanation": "妻（第一声）指已婚女子，是丈夫的配偶。"}, {"text": "起", "is_correct": false, "explanation": "qǐ（第三声）与 qī（第一声）声调不同，意思是起来、站起。"}, {"text": "气", "is_correct": false, "explanation": "qì（第四声）与 qī（第一声）声调不同，意思是空气、脾气。"}, {"text": "其", "is_correct": false, "explanation": "qí（第二声）与 qī（第一声）声调不同，意思是他的、它的。"}, {"text": "西", "is_correct": false, "explanation": "xī 与 qī 声母不同（x 与 q），意思是西方。"}, {"text": "齐", "is_correct": false, "explanation": "qí（第二声）与 qī（第一声）声调不同，意思是整齐。"}], "explanations": {"妻": "妻（第一声）指已婚女子，是丈夫的配偶。", "起": "qǐ（第三声）与 qī（第一声）声调不同，意思是起来、站起。", "气": "qì（第四声）与 qī（第一声）声调不同，意思是空气、脾气。", "其": "qí（第二声）与 qī（第一声）声调不同，意思是他的、它的。", "西": "xī 与 qī 声母不同（x 与 q），意思是西方。", "齐": "qí（第二声）与 qī（第一声）声调不同，意思是整齐。"}, "sentence_index": null, "correct_answer": "妻"}, "level_3": {"options": [{"text": "妻", "is_correct": true, "explanation": "正确：“这位先生的妻”指先生的配偶，与“很漂亮”的描述相符。"}, {"text": "丈夫", "is_correct": false, "explanation": "语义：“丈夫”指女子的配偶，与句中的“先生”（男子）相冲突。"}, {"text": "女士", "is_correct": false, "explanation": "搭配：“女士”是对女子的称呼，不表示家属关系，不能说“先生的女士”。"}, {"text": "绅士", "is_correct": false, "explanation": "搭配：“绅士”是称赞男子的词，不表示家属关系，不能说“先生的绅士”。"}], "explanations": {"妻": "正确：“这位先生的妻”指先生的配偶，与“很漂亮”的描述相符。", "丈夫": "语义：“丈夫”指女子的配偶，与句中的“先生”（男子）相冲突。", "女士": "搭配：“女士”是对女子的称呼，不表示家属关系，不能说“先生的女士”。", "绅士": "搭配：“绅士”是称赞男子的词，不表示家属关系，不能说“先生的绅士”。"}, "sentence_index": 0, "correct_answer": "妻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的妻今年十八岁，还在读高中。", "explanation": "这里应该用〈女朋友〉。“妻”指已婚女子，十八岁的在读学生还未结婚，应说女朋友。"}, {"text": "我的妻是一位男士。", "explanation": "这里应该用〈丈夫〉。“妻”只指女性配偶，指男性配偶要用丈夫。"}, {"text": "她的妻每天开车送她上班。", "explanation": "这里应该用〈丈夫〉。“妻”是男子的女性配偶，女子的配偶要说“丈夫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87082, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "妻", "is_correct": true, "explanation": "妻（第一声）指已婚女子，是丈夫的配偶。"}, {"text": "旗", "is_correct": false, "explanation": "qí（第二声）与 qī（第一声）声调不同，意思是旗子。"}, {"text": "弃", "is_correct": false, "explanation": "qì（第四声）与 qī（第一声）声调不同，意思是放弃、丢弃。"}, {"text": "吸", "is_correct": false, "explanation": "xī 与 qī 声母不同（x 与 q），意思是吸入、呼吸。"}, {"text": "骑", "is_correct": false, "explanation": "qí（第二声）与 qī（第一声）声调不同，意思是骑乘。"}], "explanations": {"妻": "妻（第一声）指已婚女子，是丈夫的配偶。", "旗": "qí（第二声）与 qī（第一声）声调不同，意思是旗子。", "弃": "qì（第四声）与 qī（第一声）声调不同，意思是放弃、丢弃。", "吸": "xī 与 qī 声母不同（x 与 q），意思是吸入、呼吸。", "骑": "qí（第二声）与 qī（第一声）声调不同，意思是骑乘。"}, "sentence_index": null, "correct_answer": "妻"}, "level_3": {"options": [{"text": "妻", "is_correct": true, "explanation": "正确：小李已婚，“他的妻”指其配偶，与“结婚了”相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”不是人，不能是同事。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：“小狗”是动物，不能是同事。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不是人，不能指人际关系中的角色，“他的天气”搭配不当。"}], "explanations": {"妻": "正确：小李已婚，“他的妻”指其配偶，与“结婚了”相符。", "桌子": "语义：“桌子”不是人，不能是同事。", "小狗": "语义：“小狗”是动物，不能是同事。", "天气": "搭配：“天气”不是人，不能指人际关系中的角色，“他的天气”搭配不当。"}, "sentence_index": 6, "correct_answer": "妻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的妻下个月就要结婚了，我们都很期待。", "explanation": "这里应该用〈未婚妻〉。“妻”指已婚女子，还未结婚的人要用未婚妻。"}, {"text": "他的妻已经再婚了。", "explanation": "这里应该用〈前妻〉。“妻”指现在的配偶，已离婚的人要用前妻，二者不能混用。"}, {"text": "我妻八岁了，正在上小学。", "explanation": "这里应该用〈女儿〉。“妻”指已婚女子，八岁的孩子不能称妻，应说女儿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87082, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一只妻，在银行工作。", "corrected_sentence": "他有一位妻，在银行工作。", "error_description": "量词错误：“妻”指人，量词应用“位”或“个”，不用“只”（“只”多用于动物）。应为：他有一位妻，在银行工作。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87082, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "王先生地妻在银行工作。", "corrected_sentence": "王先生的妻在银行工作。", "error_description": "错误形式：“王先生地妻”；正确形式：“王先生的妻”。“妻”是名词，表示领属关系要用“的”，不用“地”（“地”用在动词前）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a9f9b6c-16bc-4d1e-ac88-dd8454c33efd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
