INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87084, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用粗野或恶意的话侮辱、责备别人。", "primary_collocate": null, "pronunciation": "mà", "ipa": "ma˥˩", "syllable_count": 1, "sentences": [{"text": "他生气了，大声骂了那个人。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别骂孩子，他已经知道错了。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板骂了他一个小时。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们吵架时互相骂对方。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈从来不骂我，只是慢慢说。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个司机很生气，下车就开始骂。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把弟弟骂哭了。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在网上骂别人是不对的。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么骂他？他没做错什么。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很难过，因为同学骂过她。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "骂了", "label": "体标"}, {"form": "骂过", "label": "体标"}, {"form": "骂人", "label": "复合"}, {"form": "罵", "label": "繁体"}], "register": "口语", "sense_fingerprint": "用粗野或恶意的话侮辱、责备别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa28d71a-cd8b-403b-8f08-c583f9f3d70d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87084, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "骂", "is_correct": true, "explanation": "mà（第四声）指用粗野或恶意的话责备别人。"}, {"text": "妈", "is_correct": false, "explanation": "mā（第一声）与 mà（第四声）声调不同，意思是妈妈。"}, {"text": "马", "is_correct": false, "explanation": "mǎ（第三声）与 mà（第四声）声调不同，意思是马。"}, {"text": "麻", "is_correct": false, "explanation": "má（第二声）与 mà（第四声）声调不同，意思是麻。"}, {"text": "慢", "is_correct": false, "explanation": "màn 与 mà 韵母不同，多了鼻音 n，意思是慢。"}, {"text": "爸", "is_correct": false, "explanation": "bà 与 mà 声母不同（b 与 m），意思是爸爸。"}], "explanations": {"骂": "mà（第四声）指用粗野或恶意的话责备别人。", "妈": "mā（第一声）与 mà（第四声）声调不同，意思是妈妈。", "马": "mǎ（第三声）与 mà（第四声）声调不同，意思是马。", "麻": "má（第二声）与 mà（第四声）声调不同，意思是麻。", "慢": "màn 与 mà 韵母不同，多了鼻音 n，意思是慢。", "爸": "bà 与 mà 声母不同（b 与 m），意思是爸爸。"}, "sentence_index": null, "correct_answer": "骂"}, "level_3": {"options": [{"text": "骂", "is_correct": true, "explanation": "正确。骂是用粗野的话责备别人，与“生气”和“大声”的语境相符。"}, {"text": "夸", "is_correct": false, "explanation": "语义：“夸”是称赞，与句中“生气”的语境矛盾。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞，与句中“生气”的语境矛盾。"}, {"text": "亲", "is_correct": false, "explanation": "搭配：“亲”是亲吻，不能与“大声”搭配，也不能用来责备别人。"}], "explanations": {"骂": "正确。骂是用粗野的话责备别人，与“生气”和“大声”的语境相符。", "夸": "语义：“夸”是称赞，与句中“生气”的语境矛盾。", "表扬": "语义：“表扬”是称赞，与句中“生气”的语境矛盾。", "亲": "搭配：“亲”是亲吻，不能与“大声”搭配，也不能用来责备别人。"}, "sentence_index": 0, "correct_answer": "骂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师骂了他的努力，还说他进步很大。", "explanation": "这里应该用〈表扬〉。骂是用粗野或恶意的话责备，不能用来褒扬别人的努力。"}, {"text": "我骂大家的帮助，真的很感谢。", "explanation": "这里应该用〈感谢〉。骂表示恶意责备，不能用来对别人的帮助表示谢意。"}, {"text": "老师骂了她的字写得好。", "explanation": "这里应该用〈称赞〉。骂用于责备，不能用来称赞别人字写得好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87084, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "骂", "is_correct": true, "explanation": "mà（第四声）指用粗野或恶意的话责备别人。"}, {"text": "那", "is_correct": false, "explanation": "nà 与 mà 声母不同（n 与 m），意思是那。"}, {"text": "怕", "is_correct": false, "explanation": "pà 与 mà 声母不同（p 与 m），意思是害怕。"}, {"text": "码", "is_correct": false, "explanation": "mǎ（第三声）与 mà（第四声）声调不同，意思是数码或号码。"}, {"text": "麦", "is_correct": false, "explanation": "mài 与 mà 韵母不同，多了 i，意思是小麦。"}], "explanations": {"骂": "mà（第四声）指用粗野或恶意的话责备别人。", "那": "nà 与 mà 声母不同（n 与 m），意思是那。", "怕": "pà 与 mà 声母不同（p 与 m），意思是害怕。", "码": "mǎ（第三声）与 mà（第四声）声调不同，意思是数码或号码。", "麦": "mài 与 mà 韵母不同，多了 i，意思是小麦。"}, "sentence_index": null, "correct_answer": "骂"}, "level_3": {"options": [{"text": "骂", "is_correct": true, "explanation": "正确。“骂哭”表示责骂使弟弟哭，是常见的结果补语结构。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能使人哭，“吃哭”没有这种说法。"}, {"text": "借", "is_correct": false, "explanation": "语义：“借”指借入或借出，不会使人哭，“借哭”不成立。"}, {"text": "扶", "is_correct": false, "explanation": "搭配：“扶”不能与“哭”构成结果关系，“扶哭”不合理。"}], "explanations": {"骂": "正确。“骂哭”表示责骂使弟弟哭，是常见的结果补语结构。", "吃": "搭配：“吃”不能使人哭，“吃哭”没有这种说法。", "借": "语义：“借”指借入或借出，不会使人哭，“借哭”不成立。", "扶": "搭配：“扶”不能与“哭”构成结果关系，“扶哭”不合理。"}, "sentence_index": 6, "correct_answer": "骂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天骂了一张火车票。", "explanation": "这里应该用〈订〉。骂是用粗野或恶意的话责备，不能用来表示预订车票。"}, {"text": "他每个月骂了一笔钱。", "explanation": "这里应该用〈存〉。骂是用粗野或恶意的话责备，不能用来表示把钱存起来。"}, {"text": "他在厨房骂了一锅饭。", "explanation": "这里应该用〈煮〉。骂是用粗野或恶意的话责备，不能用来表示加热做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他骂很厉害。", "corrected_sentence": "他骂得很厉害。", "error_description": "“骂很厉害”应为“骂得很厉害”。“骂”后面带程度补语时要用“得”连接，漏掉“得”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他骂了我一个。", "corrected_sentence": "他骂了我一顿。", "error_description": "“骂了我一个”应为“骂了我一顿”。“骂”这一动作的数量要用“顿”来计算，不能用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebe4df0-deea-49ac-80a5-64074ed8d248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
