INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87086, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "女性月经周期中不易受孕的时期。", "primary_collocate": null, "pronunciation": "ān quán qī", "ipa": "an˥ t͡ɕʰɥɛn˧˥ t͡ɕʰi˥", "syllable_count": 3, "sentences": [{"text": "医生解释了什么是安全期。", "target_word": "安全期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用日历算自己的安全期。", "target_word": "安全期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "安全期并不是百分之百安全的。", "target_word": "安全期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，安全期在月经周期的某几天。", "target_word": "安全期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多女性不太清楚自己的安全期。", "target_word": "安全期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，不能只靠安全期来避孕。", "target_word": "安全期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的月经不准，安全期很难算。", "target_word": "安全期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本健康书讲了安全期是什么。", "target_word": "安全期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "安全期的算法对每个人不一样。", "target_word": "安全期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在课上介绍了安全期的知识。", "target_word": "安全期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "安全期：月经周期中不易受孕的时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e2e0b30-a3a1-4ae4-9be1-ab2c143552df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87086, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安全期", "is_correct": true, "explanation": "正确：“安全期”是指月经周期中不易受孕的时段，符合“什么是”所要求的概念名词。"}, {"text": "北京", "is_correct": false, "explanation": "语义：“什么是北京”问的是地名，不是需要解释的生理概念，与“解释”的对象不合。"}, {"text": "张三", "is_correct": false, "explanation": "语义：“张三”是人名，不能作为医生需要解释的概念。"}, {"text": "十二点", "is_correct": false, "explanation": "搭配：“十二点”是时间点，不能与“什么是”构成可解释的概念，句意不通。"}], "explanations": {"安全期": "正确：“安全期”是指月经周期中不易受孕的时段，符合“什么是”所要求的概念名词。", "北京": "语义：“什么是北京”问的是地名，不是需要解释的生理概念，与“解释”的对象不合。", "张三": "语义：“张三”是人名，不能作为医生需要解释的概念。", "十二点": "搭配：“十二点”是时间点，不能与“什么是”构成可解释的概念，句意不通。"}, "sentence_index": 0, "correct_answer": "安全期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的家给她很大的安全期。", "explanation": "这里应该用〈安全感〉。安全感指心理上的踏实，安全期是月经周期中的时段，不能用来表示心理感受。"}, {"text": "这份保险的安全期是十年。", "explanation": "这里应该用〈保险期〉。保险期指保障的有效时间，安全期只指月经周期中不易受孕的几天，不能说保险期限。"}, {"text": "她的病情终于度过了安全期。", "explanation": "这里应该用〈危险期〉。“度过危险期”指病情等渡过最危险的阶段；安全期只指女性月经周期中不易受孕的时期，不能用于病情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87086, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安全期", "is_correct": true, "explanation": "正确：“安全期”是时段名词，可以作为“很难算”的对象，与前半句“月经不准”呼应。"}, {"text": "上海", "is_correct": false, "explanation": "语义：“上海”是地名，不能作为需要计算的对象，与“月经不准”的语境无关。"}, {"text": "李四", "is_correct": false, "explanation": "语义：“李四”是人名，不能被“算”，句意不通。"}, {"text": "七点半", "is_correct": false, "explanation": "语义：「七点半」是一个固定的时间点，不需要计算，与「月经不准」造成的难算无关。"}], "explanations": {"安全期": "正确：“安全期”是时段名词，可以作为“很难算”的对象，与前半句“月经不准”呼应。", "上海": "语义：“上海”是地名，不能作为需要计算的对象，与“月经不准”的语境无关。", "李四": "语义：“李四”是人名，不能被“算”，句意不通。", "七点半": "语义：「七点半」是一个固定的时间点，不需要计算，与「月经不准」造成的难算无关。"}, "sentence_index": 6, "correct_answer": "安全期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "司机出发前要系好安全期。", "explanation": "这里应该用〈安全带〉。安全带是可以系的物品，安全期是时段，不能系。"}, {"text": "我们暑假有一个长安全期。", "explanation": "这里应该用〈假期〉。假期指放假的一段时间，安全期只指月经周期中的几天，不能指假期。"}, {"text": "工地四周挂着安全期，防止工人坠落。", "explanation": "这里应该用〈安全网〉。安全网是挂在高处防止坠落的装置，安全期只指女性月经周期中不易受孕的时期，不能挂在工地上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87086, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们这次算出了一只安全期。", "corrected_sentence": "我们这次算出了一个安全期。", "error_description": "量词错误：“安全期”是时段，应该用量词“个”，写作“一个安全期”；“一只安全期”中的“只”只用于动物等，不能修饰时段。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87086, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她每个月都会算很安全期。", "corrected_sentence": "她每个月都会算安全期。", "error_description": "错误在于「很安全期」。「安全期」是名词，前面不能加程度副词「很」，应说「算安全期」；「很安全期」会被误解为“很安全的时期”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87087, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "喜欢", "is_correct": true, "explanation": "“讨厌”与“喜欢”是反义词，表示对人或事物的好恶相反。"}, {"text": "担心", "is_correct": false, "explanation": "无关：“担心”表示忧虑，与“讨厌”不构成反义关系。"}, {"text": "害怕", "is_correct": false, "explanation": "无关：“害怕”表示恐惧，不是对人或事物的反感，与“讨厌”不构成反义。"}, {"text": "尊敬", "is_correct": false, "explanation": "无关：“尊敬”表示敬重，与“讨厌”不构成反义关系。"}], "correct_answer": "喜欢", "explanations": {"喜欢": "“讨厌”与“喜欢”是反义词，表示对人或事物的好恶相反。", "担心": "无关：“担心”表示忧虑，与“讨厌”不构成反义关系。", "害怕": "无关：“害怕”表示恐惧，不是对人或事物的反感，与“讨厌”不构成反义。", "尊敬": "无关：“尊敬”表示敬重，与“讨厌”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87087, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "喜欢", "is_correct": true, "explanation": "“讨厌”与“喜欢”是反义词，表示对人或事物的好恶相反。"}, {"text": "信任", "is_correct": false, "explanation": "无关：“信任”表示相信、托付，与“讨厌”不构成反义关系。"}, {"text": "怀念", "is_correct": false, "explanation": "无关：“怀念”表示思念过去的人或事，与“讨厌”不构成反义。"}, {"text": "佩服", "is_correct": false, "explanation": "无关：“佩服”表示钦佩，与“讨厌”不构成反义关系。"}], "correct_answer": "喜欢", "explanations": {"喜欢": "“讨厌”与“喜欢”是反义词，表示对人或事物的好恶相反。", "信任": "无关：“信任”表示相信、托付，与“讨厌”不构成反义关系。", "怀念": "无关：“怀念”表示思念过去的人或事，与“讨厌”不构成反义。", "佩服": "无关：“佩服”表示钦佩，与“讨厌”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87087, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "讨厌是不喜欢某个人或某件事，不想接近。", "primary_collocate": null, "pronunciation": "tǎo yàn", "ipa": "tʰɑʊ˨˩˦ jɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我很讨厌说谎的人。", "target_word": "讨厌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他讨厌早上起床。", "target_word": "讨厌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妹妹讨厌吃青菜，一吃就哭。", "target_word": "讨厌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不讨厌他，只是不太熟。", "target_word": "讨厌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她讨厌别人大声说话。", "target_word": "讨厌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟最讨厌洗澡。", "target_word": "讨厌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师讨厌学生迟到。", "target_word": "讨厌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我真讨厌那个爱骗人的同事。", "target_word": "讨厌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸讨厌抽烟的人，所以不去那家饭馆。", "target_word": "讨厌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你为什么这么讨厌他？", "target_word": "讨厌", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "讨厌了", "label": "体标（了）"}, {"form": "讨厌过", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "不喜欢某个人或某种行为，不想接近", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa572e2a-b4ac-45be-a597-2cd926dc15a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87087, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讨厌", "is_correct": true, "explanation": "“讨厌”表示不喜欢，与句中对说谎者的反感相符。"}, {"text": "赞同", "is_correct": false, "explanation": "搭配：“赞同”的宾语应是观点或做法，不能说“赞同说谎的人”。"}, {"text": "尊敬", "is_correct": false, "explanation": "语义：“尊敬”表示敬重，与“说谎的人”的品行相反。"}, {"text": "佩服", "is_correct": false, "explanation": "语义：“佩服”针对值得钦佩的人或事，说谎的人不值得钦佩。"}], "explanations": {"讨厌": "“讨厌”表示不喜欢，与句中对说谎者的反感相符。", "赞同": "搭配：“赞同”的宾语应是观点或做法，不能说“赞同说谎的人”。", "尊敬": "语义：“尊敬”表示敬重，与“说谎的人”的品行相反。", "佩服": "语义：“佩服”针对值得钦佩的人或事，说谎的人不值得钦佩。"}, "sentence_index": 0, "correct_answer": "讨厌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题真讨厌，我怎么也做不出来。", "explanation": "这里的“讨厌”是形容词，表示“令人烦恼”，不是动词“不喜欢某人或某事”的意思。"}, {"text": "你真讨厌，又把我的笔拿走了！", "explanation": "这里的“讨厌”是形容词，表示“让人烦、惹人嫌”（常带嗔怪语气），不是动词“不喜欢某人或某事”的意思。"}, {"text": "他是个很讨厌的邻居，总是吵个不停。", "explanation": "这里的“讨厌”是形容词“令人厌烦”的意思，不是动词“不喜欢某人”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87087, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讨厌", "is_correct": true, "explanation": "“讨厌”表示不喜欢，与老师对学生迟到的态度相符。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示乐于接待，与“学生迟到”的评价不合。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”针对值得称赞的行为，迟到不值得表扬。"}, {"text": "感激", "is_correct": false, "explanation": "搭配：“感激”的宾语应是他人的帮助或恩惠，不能说“感激学生迟到”。"}], "explanations": {"讨厌": "“讨厌”表示不喜欢，与老师对学生迟到的态度相符。", "欢迎": "语义：“欢迎”表示乐于接待，与“学生迟到”的评价不合。", "表扬": "语义：“表扬”针对值得称赞的行为，迟到不值得表扬。", "感激": "搭配：“感激”的宾语应是他人的帮助或恩惠，不能说“感激学生迟到”。"}, "sentence_index": 6, "correct_answer": "讨厌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个天气真讨厌，一直在下雨。", "explanation": "这里的“讨厌”是形容词“令人烦恼”的意思，不是动词“不喜欢”的意思。"}, {"text": "这些蚊子真讨厌，咬得我睡不着。", "explanation": "这里的“讨厌”是形容词，表示“令人厌烦”，不是动词“不喜欢”的意思。"}, {"text": "这件事真讨厌，我不想再提。", "explanation": "这里的“讨厌”是形容词，表示“令人厌烦”，不是动词“不喜欢某人”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87087, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很讨厌讨厌吃香菜。", "corrected_sentence": "我很讨厌吃香菜。", "error_description": "错误形式是“我很讨厌讨厌吃香菜”，正确形式是“我很讨厌吃香菜”。“讨厌”只能出现一次，多写的“讨厌”是重复成分。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87087, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直很讨厌得夏天。", "corrected_sentence": "他一直很讨厌夏天。", "error_description": "错误形式是“讨厌得夏天”，正确形式是“讨厌夏天”。“得”是补语标记，不能插在动词“讨厌”和宾语“夏天”之间，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
