INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87089, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "害死是做了坏事，让别人死了。", "primary_collocate": null, "pronunciation": "hài sǐ", "ipa": "xaɪ˥˩ sɹ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "坏人用毒药害死了他的朋友。", "target_word": "害死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个医生乱开药，害死了一个病人。", "target_word": "害死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他开车喝酒，害死了两个路人。", "target_word": "害死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个老板偷工减料，害死了好几个工人。", "target_word": "害死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国王听了坏人的话，害死了忠臣。", "target_word": "害死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他怕证人说出真话，就害死了证人。", "target_word": "害死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他为了钱害死了自己的亲哥哥。", "target_word": "害死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂乱排脏水，害死了附近的村民。", "target_word": "害死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察说，他从没害死过人。", "target_word": "害死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁害死了老王？警察还在查这件事。", "target_word": "害死", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "害死了", "label": "体标"}, {"form": "害死过", "label": "体标"}], "register": "口语", "sense_fingerprint": "害死：因为做了坏事或错事，使别人失去生命", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157c64-73c7-4e54-9585-b5a2f818129e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87089, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "救活", "is_correct": false, "explanation": "语义：“救活”是救人，与“用毒药”的加害行为相反，不合句意。"}, {"text": "害死", "is_correct": true, "explanation": "害死：做了坏事，使别人失去生命，与“用毒药”相合。"}, {"text": "治好", "is_correct": false, "explanation": "语义：“治好”指治病，用毒药不能治好人，与句意不合。"}, {"text": "陪伴", "is_correct": false, "explanation": "搭配：“用毒药”后不能接“陪伴”，二者搭配不通。"}], "explanations": {"救活": "语义：“救活”是救人，与“用毒药”的加害行为相反，不合句意。", "害死": "害死：做了坏事，使别人失去生命，与“用毒药”相合。", "治好": "语义：“治好”指治病，用毒药不能治好人，与句意不合。", "陪伴": "搭配：“用毒药”后不能接“陪伴”，二者搭配不通。"}, "sentence_index": 0, "correct_answer": "害死"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的粗心害死了孩子的手。", "explanation": "这里应该用〈伤〉。害死指使人失去生命，不能用于身体部位。"}, {"text": "这次事故害死了一辆车。", "explanation": "这里应该用〈损坏〉。害死只用于使生物失去生命，不用于车辆。"}, {"text": "他的粗心害死了那根绳子。", "explanation": "这里应该用〈弄断〉。害死指使生命失去，不用于绳子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87089, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”是感激，与“为了钱”的动机不合，句意说不通。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“为了钱”后不能接“欢迎”，“欢迎了亲哥哥”搭配不通。"}, {"text": "害死", "is_correct": true, "explanation": "害死：做了坏事，使别人失去生命，与“为了钱”的加害动机相合。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”是称赞，与“为了钱”的动机不合。"}], "explanations": {"感谢": "语义：“感谢”是感激，与“为了钱”的动机不合，句意说不通。", "欢迎": "搭配：“为了钱”后不能接“欢迎”，“欢迎了亲哥哥”搭配不通。", "害死": "害死：做了坏事，使别人失去生命，与“为了钱”的加害动机相合。", "赞美": "语义：“赞美”是称赞，与“为了钱”的动机不合。"}, "sentence_index": 6, "correct_answer": "害死"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小偷把我的手机害死了。", "explanation": "这里应该用〈偷走〉。害死指使生命失去，不指偷东西。"}, {"text": "弟弟不小心害死了我的电脑。", "explanation": "这里应该用〈弄坏〉。害死指使人失去生命，不用于电脑等物品。"}, {"text": "他把皮鞋害死了。", "explanation": "这里的意思是〈弄坏〉。害死指使人丧命，不指把物品弄坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87089, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个司机喝醉了，害死着一个骑车的人。", "corrected_sentence": "那个司机喝醉了，害死了一个骑车的人。", "error_description": "体标错误：“害死”表示动作已完成，应用“了”，不能用“着”。“着”表示持续的状态。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87089, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他为了钱，害死着亲弟弟。", "corrected_sentence": "他为了钱，害死了亲弟弟。", "error_description": "体标错误：“害死”表示动作已完成，应用“了”，不能用“着”。“着”表示持续的状态。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
