INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87090, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使人丧命；使人遭受严重损害而死亡。", "primary_collocate": null, "pronunciation": "hài sǐ", "ipa": "xaɪ˥˩ sɹ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的坏习惯最后害死了他自己。", "target_word": "害死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种假药会害死很多病人。", "target_word": "害死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "疲劳驾驶不但伤自己，还会害死别人。", "target_word": "害死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你这样骗老人，迟早会害死他。", "target_word": "害死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场大火害死了三个孩子。", "target_word": "害死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一次小小的错误害死了整个车队的人。", "target_word": "害死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的粗心害死了一个无辜的孩子。", "target_word": "害死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院的一个小错，害死了她的母亲。", "target_word": "害死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一句谣言害死了一位老人。", "target_word": "害死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上的坑没人管，已经害死过好几个人了。", "target_word": "害死", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "害死了", "label": "体标"}, {"form": "害死过", "label": "体标"}], "register": "口语", "sense_fingerprint": "害死：因某种行为、错误或东西，使人受到严重损害而死亡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157c64-73c7-4e54-9585-b5a2f818129e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87090, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扶持", "is_correct": false, "explanation": "语义：“扶持”是帮助、支持，坏习惯不会扶持人，与句意不合。"}, {"text": "治愈", "is_correct": false, "explanation": "语义：“治愈”指治好病，坏习惯不能治愈人，与句意相反。"}, {"text": "害死", "is_correct": true, "explanation": "害死：因某种行为或东西，使人受到严重损害而死亡，与“坏习惯”相合。"}, {"text": "照顾", "is_correct": false, "explanation": "搭配：“坏习惯”不能“照顾”人，二者搭配不通。"}], "explanations": {"扶持": "语义：“扶持”是帮助、支持，坏习惯不会扶持人，与句意不合。", "治愈": "语义：“治愈”指治好病，坏习惯不能治愈人，与句意相反。", "害死": "害死：因某种行为或东西，使人受到严重损害而死亡，与“坏习惯”相合。", "照顾": "搭配：“坏习惯”不能“照顾”人，二者搭配不通。"}, "sentence_index": 0, "correct_answer": "害死"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "药物害死了他的病。", "explanation": "这里应该用〈治好〉。害死指使人死亡，不能用于疾病。"}, {"text": "他开车不小心，害死了自己的新车。", "explanation": "这里应该用〈撞坏〉。害死指使人死亡，不用于车辆。"}, {"text": "他害死了一个杯子。", "explanation": "这里应该用〈打碎〉。害死不用于易碎的器物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87090, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拯救", "is_correct": false, "explanation": "语义：“拯救”是救人，与“粗心”导致的过失相反，不合句意。"}, {"text": "照料", "is_correct": false, "explanation": "搭配：“粗心”不能与“照料”搭配，句中说的是过失，不是照顾。"}, {"text": "害死", "is_correct": true, "explanation": "害死：因某种错误使人受到严重损害而死亡，与“粗心”的过失相合。"}, {"text": "迎接", "is_correct": false, "explanation": "语义：“迎接”是欢迎到来，与“粗心”造成的伤害不合。"}], "explanations": {"拯救": "语义：“拯救”是救人，与“粗心”导致的过失相反，不合句意。", "照料": "搭配：“粗心”不能与“照料”搭配，句中说的是过失，不是照顾。", "害死": "害死：因某种错误使人受到严重损害而死亡，与“粗心”的过失相合。", "迎接": "语义：“迎接”是欢迎到来，与“粗心”造成的伤害不合。"}, "sentence_index": 6, "correct_answer": "害死"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他害死了眼泪。", "explanation": "这里应该用〈擦干〉。害死指使人死亡，不能用于眼泪。"}, {"text": "他害死了那封信。", "explanation": "这里应该用〈撕破〉。害死不用于纸张等物品。"}, {"text": "他把衣服害死了。", "explanation": "这里的意思是〈弄坏〉。害死指使人丧命或严重受害，不指把衣服弄坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87090, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那场洪水害死着一位农民。", "corrected_sentence": "那场洪水害死了一位农民。", "error_description": "体标错误：“害死”表示动作已完成，应用“了”，不用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87090, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场车祸害死着一个年轻人。", "corrected_sentence": "这场车祸害死了一个年轻人。", "error_description": "体标错误：“害死”表示动作已完成，应用“了”，不用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
