INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87091, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "请求是很有礼貌地对别人说，希望他帮忙。", "primary_collocate": null, "pronunciation": "qǐng qiú", "ipa": "tɕʰiŋ˨˩˦ tɕʰiou̯˧˥", "syllable_count": 2, "sentences": [{"text": "他请求同学帮他搬桌子。", "target_word": "请求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我请求老师再讲一遍。", "target_word": "请求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩请求妈妈带他去公园。", "target_word": "请求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她请求邻居帮忙看一下孩子。", "target_word": "请求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请求朋友明天陪他去医院。", "target_word": "请求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我请求你帮我拿一下行李。", "target_word": "请求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们请求老师给他们更多时间。", "target_word": "请求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不好意思地请求同事帮他换班。", "target_word": "请求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们请求经理帮我们换一个房间。", "target_word": "请求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人请求路人帮他叫一辆出租车。", "target_word": "请求", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "请求了", "label": "完成体"}, {"form": "请求过", "label": "经历体"}, {"form": "請求", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有礼貌地对人开口，希望对方帮忙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '679c1d60-cd18-4bd7-984c-952bf355ca55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87091, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "请求", "is_correct": true, "explanation": "“请求”表示客气地请同学帮忙，符合句意。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”指出过错，而同学帮忙搬桌子是好事，句意不通。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”含讥讽之意，与同学乐于帮忙的善意相矛盾。"}, {"text": "痛斥", "is_correct": false, "explanation": "语域：“痛斥”语气激烈，与这种平常的求助场景不协调。"}], "explanations": {"请求": "“请求”表示客气地请同学帮忙，符合句意。", "批评": "语义：“批评”指出过错，而同学帮忙搬桌子是好事，句意不通。", "嘲笑": "语义：“嘲笑”含讥讽之意，与同学乐于帮忙的善意相矛盾。", "痛斥": "语域：“痛斥”语气激烈，与这种平常的求助场景不协调。"}, "sentence_index": 0, "correct_answer": "请求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司请求员工每天准时上班。", "explanation": "这里应该用〈要求〉。请求是客气地提出希望，上级对下属的规定要用“要求”。"}, {"text": "这条校规请求全体师生遵守纪律。", "explanation": "这里应该用〈规定〉。校规是对师生的硬性约束，不能“请求”，应说“规定”。"}, {"text": "他粗暴地请求我帮忙。", "explanation": "这里应该用〈命令〉。“请求”是客气地提出希望，不能用于强硬的态度；强硬的指示应说〈命令〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87091, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "请求", "is_correct": true, "explanation": "“请求”体现学生对老师的客气提问，符合句意。"}, {"text": "命令", "is_correct": false, "explanation": "语义：学生不能对老师用“命令”，这样说与师生之间的语境相矛盾。"}, {"text": "喝令", "is_correct": false, "explanation": "语域：“喝令”语气粗暴严厉，与学生向老师提出合理请求的语境不协调。"}, {"text": "责怪", "is_correct": false, "explanation": "语义：“责怪”含指责之意，与老师给学生更多时间这件好事相矛盾。"}], "explanations": {"请求": "“请求”体现学生对老师的客气提问，符合句意。", "命令": "语义：学生不能对老师用“命令”，这样说与师生之间的语境相矛盾。", "喝令": "语域：“喝令”语气粗暴严厉，与学生向老师提出合理请求的语境不协调。", "责怪": "语义：“责怪”含指责之意，与老师给学生更多时间这件好事相矛盾。"}, "sentence_index": 6, "correct_answer": "请求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他站在台上，请求大家的掌声。", "explanation": "这里应该用〈期待〉。“请求”是客气地向人提出帮助或许可，掌声是观众自然给予的，应说〈期待〉。"}, {"text": "学生向老师请求数学题。", "explanation": "这里应该用〈请教〉。请教是向人求教，“请求”不能指向知识或题目。"}, {"text": "这张通知请求大家明天八点到校。", "explanation": "这里应该用〈要求〉。通知是事物，不能“请求”别人；它规定大家做什么，应说“要求”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87091, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天请求过老师帮忙。", "corrected_sentence": "我明天请求老师帮忙。", "error_description": "错误：“请求过”的“过”表示已经发生的经历，但“明天”指将来，应去掉“过”，说“我明天请求老师帮忙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87091, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天请求着老师帮忙。", "corrected_sentence": "我昨天请求了老师帮忙。", "error_description": "错误：“请求着”的“着”表示持续的状态，与“昨天”已完成的动作矛盾，应把“着”改为“了”，说“我昨天请求了老师帮忙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
