INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87092, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "客气地向人提出要求，希望得到答应或帮助。", "primary_collocate": null, "pronunciation": "qǐng qiú", "ipa": "tɕʰiŋ˨˩˦ tɕʰiou̯˧˥", "syllable_count": 2, "sentences": [{"text": "他请求经理让他提前回家。", "target_word": "请求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她请求老师允许她明天请假。", "target_word": "请求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机请求警察放他过去。", "target_word": "请求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我请求公司给我一个机会。", "target_word": "请求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生请求校长同意他们办晚会。", "target_word": "请求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向领导请求帮助。", "target_word": "请求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人请求医生让他早点出院。", "target_word": "请求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们请求政府修一条新路。", "target_word": "请求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我请求你别告诉妈妈。", "target_word": "请求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子请求爸爸再玩十分钟。", "target_word": "请求", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "请求了", "label": "完成体"}, {"form": "请求过", "label": "经历体"}, {"form": "請求", "label": "繁体"}], "register": "中性", "sense_fingerprint": "客气地向人提出要求，希望对方答应或帮助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '679c1d60-cd18-4bd7-984c-952bf355ca55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87092, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "请求", "is_correct": true, "explanation": "“请求”表示客气地向经理提出希望，符合句意。"}, {"text": "命令", "is_correct": false, "explanation": "语义：下属不能对经理用“命令”，与客气请求的语境相矛盾。"}, {"text": "训斥", "is_correct": false, "explanation": "语域：“训斥”口气严厉，下属对经理这样说不合语境。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场地或房间，不能说打扫“经理”，句意不通。"}], "explanations": {"请求": "“请求”表示客气地向经理提出希望，符合句意。", "命令": "语义：下属不能对经理用“命令”，与客气请求的语境相矛盾。", "训斥": "语域：“训斥”口气严厉，下属对经理这样说不合语境。", "打扫": "搭配：“打扫”的对象是场地或房间，不能说打扫“经理”，句意不通。"}, "sentence_index": 0, "correct_answer": "请求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "军官请求士兵立刻出发。", "explanation": "这里应该用〈命令〉。军队中的指令是强制性的，不能用客气的“请求”。"}, {"text": "这份合同请求双方一周内签字。", "explanation": "这里应该用〈要求〉。合同这类事物不能“请求”，此处应说“要求”。"}, {"text": "他怒气冲冲地请求我帮忙。", "explanation": "这里应该用〈要求〉。“请求”是客气地提出希望，不能用于发怒时的强硬语气；此时应说〈要求〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87092, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "请求", "is_correct": true, "explanation": "“请求”表示病人客气地请医生帮忙，符合句意。"}, {"text": "吩咐", "is_correct": false, "explanation": "语义：病人不能对医生“吩咐”，这样说与医患之间的语境相矛盾。"}, {"text": "挖苦", "is_correct": false, "explanation": "语义：“挖苦”含讽刺之意，与病人向医生恳求出院的语境不符。"}, {"text": "斥责", "is_correct": false, "explanation": "语域：“斥责”语气严厉，病人对医生这样说不合语境。"}], "explanations": {"请求": "“请求”表示病人客气地请医生帮忙，符合句意。", "吩咐": "语义：病人不能对医生“吩咐”，这样说与医患之间的语境相矛盾。", "挖苦": "语义：“挖苦”含讽刺之意，与病人向医生恳求出院的语境不符。", "斥责": "语域：“斥责”语气严厉，病人对医生这样说不合语境。"}, "sentence_index": 6, "correct_answer": "请求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校请求学生晚上十点前回宿舍。", "explanation": "这里应该用〈规定〉。学校对学生的纪律要求用“规定”，“请求”带有商量的语气。"}, {"text": "这篇文章请求大家的关注。", "explanation": "这里应该用〈引起〉。文章是事物，不能“请求”关注，应说“引起”大家的关注。"}, {"text": "他向医生请求病情。", "explanation": "这里应该用〈询问〉。“请求”是客气地向人提出希望，询问病情应说〈询问〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87092, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天请求着经理延期交报告。", "corrected_sentence": "我昨天请求了经理延期交报告。", "error_description": "错误：“请求着”的“着”表示持续的状态，与“昨天”已完成的动作矛盾，应把“着”改为“了”，说“我昨天请求了经理延期交报告”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87092, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹请求得妈妈多给她一块蛋糕。", "corrected_sentence": "妹妹请求妈妈多给她一块蛋糕。", "error_description": "错误：“请求”后面直接接兼语“妈妈”，中间的“得”多余，应去掉，说“妹妹请求妈妈多给她一块蛋糕”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
