INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87093, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对策是遇到难事时想出来的办法。", "primary_collocate": null, "pronunciation": "duì cè", "ipa": "tweɪ˥˩ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "遇到难题时，我们要想一个好对策。", "target_word": "对策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对堵车问题，市政府想出了新对策。", "target_word": "对策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个对策很简单，大家都能做到。", "target_word": "对策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一时想不出什么对策。", "target_word": "对策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气突然变冷，我们要马上想对策。", "target_word": "对策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，先别急，慢慢找对策。", "target_word": "对策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司已经有了应付危机的对策。", "target_word": "对策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有没有更好的对策？", "target_word": "对策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对大雨，大家提出了几个对策。", "target_word": "对策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个对策真的有用吗？", "target_word": "对策", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "对策研究", "label": "复合"}], "register": "中性", "sense_fingerprint": "遇到难事时想出来的应对办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046a46c1-f6ab-4b59-a727-080c82d4af4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87093, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脾气", "is_correct": false, "explanation": "语义：脾气是性格上的情绪特点，不是可以“想”出来用来解决难题的东西，“想一个好脾气”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“想”可以接办法、计划之类，不能接天气这种自然现象。"}, {"text": "对策", "is_correct": true, "explanation": "正确。对策指应付难题的办法，与“想一个好”搭配自然。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是食物，不能用来应付难题，“想一个好水果”不成立。"}], "explanations": {"脾气": "语义：脾气是性格上的情绪特点，不是可以“想”出来用来解决难题的东西，“想一个好脾气”说不通。", "天气": "搭配：“想”可以接办法、计划之类，不能接天气这种自然现象。", "对策": "正确。对策指应付难题的办法，与“想一个好”搭配自然。", "水果": "语义：水果是食物，不能用来应付难题，“想一个好水果”不成立。"}, "sentence_index": 0, "correct_answer": "对策"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的对策很简单。", "explanation": "这里应该用〈做法〉。对策指应付困难或问题的办法，做菜没有需要应付的问题，所以要用“做法”。"}, {"text": "我忘了邮箱的对策。", "explanation": "这里应该用〈密码〉。对策指应付难事的办法，登录邮箱的秘密字符要用“密码”。"}, {"text": "他用了一个小对策，把我的钱骗走了。", "explanation": "这里应该用〈计策〉。对策是应付问题的办法，没有欺骗别人的意思；骗人的手段要用“计策”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87093, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食物", "is_correct": false, "explanation": "语义：食物不是用来应付危机的办法，“应付危机的食物”说不通。"}, {"text": "宿舍", "is_correct": false, "explanation": "搭配：“应付”的对象是危机、问题等，不能接宿舍这类建筑。"}, {"text": "对策", "is_correct": true, "explanation": "正确。对策指应付问题的办法，与“应付危机的”搭配自然。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是办法，不能用来应付危机。"}], "explanations": {"食物": "语义：食物不是用来应付危机的办法，“应付危机的食物”说不通。", "宿舍": "搭配：“应付”的对象是危机、问题等，不能接宿舍这类建筑。", "对策": "正确。对策指应付问题的办法，与“应付危机的”搭配自然。", "颜色": "语义：颜色不是办法，不能用来应付危机。"}, "sentence_index": 6, "correct_answer": "对策"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子的对策很结实。", "explanation": "这里应该用〈做工〉。对策指应付难事的办法，说椅子做得结实要用“做工”。"}, {"text": "这张照片的对策很好看。", "explanation": "这里应该用〈颜色〉。对策指应付难事的办法，照片好看的是颜色，不是对策。"}, {"text": "这首歌的对策很好听。", "explanation": "这里应该用〈旋律〉。对策指应付难事的办法，歌好听的是旋律，不是对策。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87093, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府还没想出一本对策。", "corrected_sentence": "政府还没想出一个对策。", "error_description": "量词错误：“对策”的量词应是“个”，“本”用于书籍等。正确说法是“一个对策”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87093, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在会上讨论出一次对策。", "corrected_sentence": "他们在会上讨论出一个对策。", "error_description": "量词错误：“对策”应用“个”，“次”表示动作的次数，不能用来数对策。正确说法是“一个对策”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
