INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87094, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "应付困难或问题的办法。", "primary_collocate": null, "pronunciation": "duì cè", "ipa": "tweɪ˥˩ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "政府正在研究解决污染的对策。", "target_word": "对策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对付作弊，学校提出了新的对策。", "target_word": "对策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家们讨论了很久，终于找到对策。", "target_word": "对策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到价格上涨，商店老板马上想出了对策。", "target_word": "对策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告写了三条对策。", "target_word": "对策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对竞争，公司必须有自己的对策。", "target_word": "对策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减少交通事故的对策有很多。", "target_word": "对策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这个问题没有任何对策。", "target_word": "对策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起想对策，问题就好解决。", "target_word": "对策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的对策一点也不管用。", "target_word": "对策", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "对策研究", "label": "复合"}], "register": "中性", "sense_fingerprint": "应付困难或问题的办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046a46c1-f6ab-4b59-a727-080c82d4af4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
